    private static void ga_init(S_growarray gap) {
        gap.ga_data = null;
        gap.ga_maxlen = 0;
        gap.ga_len = 0;
    }

    private static void ga_init2(S_growarray gap, long itemsize, int growsize) {
        ga_init(gap);
        gap.ga_itemsize = (int) itemsize;
        gap.ga_growsize = growsize;
    }

    private boolean ga_grow(S_growarray gap, int n) {
        if (gap.ga_maxlen - gap.ga_len < n) {
            return ga_grow_inner(gap, n);
        }
        return true;
    }

    private boolean ga_grow_inner(S_growarray gap, int n) {
        if (n < gap.ga_growsize) {
            n = gap.ga_growsize;
        }
        if (n < gap.ga_len / 2) {
            n = gap.ga_len / 2;
        }
        if (n > 0
                && Long.compareUnsigned((long) (gap.ga_len + n),
                Long.divideUnsigned(-1L, (long) gap.ga_itemsize)) > 0) {
            return false;
        }
        // C allocates, copies and clears the storage here; Ga does it at the
        // next typed access, in elements of the storage's type.
        gap.ga_maxlen = gap.ga_len + n;
        return true;
    }

    private void ga_concat(S_growarray gap, BytePtr s) {
        int len;
        if (s == null || s.get() == NUL) {
            return;
        }
        len = (int) musl_strlen(s);
        if (ga_grow(gap, len)) {
            Rt.memmove(GA_BytePtr(gap).add(gap.ga_len), s, (long) len);
            gap.ga_len += len;
        }
    }

    private void ga_concat_len(S_growarray gap, BytePtr s, long len) {
        if (s == null || s.get() == NUL || len == 0L) {
            return;
        }
        if (ga_grow(gap, (int) len)) {
            Rt.memmove(GA_BytePtr(gap).add(gap.ga_len), s, len);
            gap.ga_len += (int) len;
        }
    }

    private boolean ga_append(S_growarray gap, int c) {
        if (!ga_grow(gap, 1)) {
            return false;
        }
        GA_BytePtr(gap).add(gap.ga_len).put((byte) c);
        gap.ga_len++;
        return true;
    }

