    private boolean open_buffer() {
        boolean retval = true;
        T_bufref_T old_curbuf = new T_bufref_T();
        if (!ml_open(curbuf)) {
            close_buffer(curwin, curbuf, 0, false, false, false);
            emsg(new BytePtr(e_cannot_allocate_any_buffer_exiting, 0));
            v_dying = 2;
            getout(2);
        }
        set_bufref(old_curbuf, curbuf);
        curbuf.b_modified_was_set = false;
        curwin.w_valid = 0;
        if ((curbuf.b_flags & BF_NEVERLOADED) != 0) {
            buf_init_chartab(curbuf, false);
        }
        if ((got_int != 0 && vim_strchr(p_cpo[0], CPO_INTMOD) != null) || curbuf.b_modified_was_set) {
            changed();
        } else if ((retval ? 1 : 0) == OK) {
            unchanged(curbuf, false, true);
        }
        curbuf.b_last_changedtick = curbuf.b_changedtick;
        curbuf.b_last_changedtick_i = curbuf.b_changedtick;
        curbuf.b_last_changedtick_pum = curbuf.b_changedtick;
        if (got_int != 0) {
            curbuf.b_flags |= BF_READERR;
        }
        if ((curwin.w_valid & VALID_TOPLINE) == 0) {
            curwin.w_topline = 1L;
        }
        if ((retval ? 1 : 0) != OK) {
            return retval;
        }
        if (bufref_valid(old_curbuf) && old_curbuf.br_buf.b_ml.ml_root != null) {
            curbuf.b_flags &= ~(BF_CHECK_RO | BF_NEVERLOADED);
        }
        return retval;
    }

    private void set_bufref(T_bufref_T bufref, S_file_buffer buf) {
        bufref.br_buf = buf;
        bufref.br_fnum = buf == null ? 0 : buf.b_fnum;
        bufref.br_buf_free_count = buf_free_count;
    }

    private boolean bufref_valid(T_bufref_T bufref) {
        return (bufref.br_buf_free_count == buf_free_count ? TRUE : (buf_valid(bufref.br_buf)
                && bufref.br_fnum == bufref.br_buf.b_fnum ? 1 : 0)) != 0;
    }

    private boolean buf_valid(S_file_buffer buf) {
        return buf == curbuf;
    }

    private boolean can_unload_buffer(S_file_buffer buf) {
        boolean can_unload = buf.b_locked == 0;
        if (can_unload && updating_screen != 0) {
            if (curwin.w_buffer == buf) {
                can_unload = false;
            }
        }
        if (can_unload && buf.b_saving) {
            can_unload = false;
        }
        if (!can_unload) {
            vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_attempt_to_delete_buffer_that_is_in_use_str, 0),
                    BytePtr.lit("[No Name]"));
            emsg(iobuff_or(new BytePtr(e_attempt_to_delete_buffer_that_is_in_use_str, 0)));
        }
        return can_unload;
    }

    private boolean close_buffer(S_window_S win, S_file_buffer buf, int action, boolean abort_if_last,
            boolean ignore_abort, boolean set_context) {
        boolean hiding_buf;
        T_bufref_T bufref = new T_bufref_T();
        boolean unload_buf = action != 0;
        boolean wipe_buf = action == DOBUF_WIPE || action == DOBUF_WIPE_REUSE;
        boolean del_buf = action == DOBUF_DEL || wipe_buf;
        boolean win_valid = win_valid_any_tab(win);
        boolean closed_popup = win != null && !win_valid && false;
        if ((del_buf || wipe_buf) && !can_unload_buffer(buf)) {
            return false;
        }
        if (set_context && win_valid && win.w_buffer == buf) {
            if (buf.b_nwindows == 1) {
                set_last_cursor(win);
            }
            buflist_setfpos(buf, win, win.w_cursor.lnum == 1L ? 0L : win.w_cursor.lnum, win.w_cursor.col, true);
        }
        set_bufref(bufref, buf);
        if ((win_valid || closed_popup) && win.w_buffer == buf && buf.b_nwindows == 1) {
            if (abort_if_last) {
                emsg(new BytePtr(e_autocommands_caused_command_to_abort, 0));
                return false;
            }
            win_valid = win_valid && win_valid_any_tab(win);
        }
        hiding_buf = buf.b_nwindows <= 0 || ((win_valid || closed_popup) && win.w_buffer == buf && buf.b_nwindows == 1);
        if (!hiding_buf || !unload_buf) {
            return false;
        }
        del_buf = true;
        if (!buf_freeall(buf,
                (del_buf ? BFA_DEL : 0) + (wipe_buf ? BFA_WIPE : 0) + (ignore_abort ? BFA_IGNORE_ABORT : 0))) {
            return false;
        }
        win_valid = win_valid && win_valid_any_tab(win);
        if ((win_valid || closed_popup) && win.w_buffer == buf) {
            buf.b_nwindows--;
            win.w_buffer = null;
        }
        if (del_buf) {
            free_buffer_stuff(buf, true);
            buf.b_flags = BF_CHECK_RO | BF_NEVERLOADED;
            buf.b_p_initialized = false;
        }
        buf_clear_file(buf);
        return true;
    }

    private void buf_clear_file(S_file_buffer buf) {
        buf.b_ml.ml_line_count = 1L;
        unchanged(buf, true, true);
        buf.b_shortname = false;
        buf.b_ml.ml_root = null;
        buf.b_ml.ml_flags = ML_EMPTY;
    }

    private boolean buf_freeall(S_file_buffer buf, int flags) {
        boolean is_curbuf = buf == curbuf;
        T_bufref_T bufref = new T_bufref_T();
        buf.b_locked++;
        buf.b_locked_split++;
        set_bufref(bufref, buf);
        buf.b_locked--;
        buf.b_locked_split--;
        if (buf == curbuf && !is_curbuf) {
            return false;
        }
        if (buf == curbuf && VIsual_active) {
            end_visual_mode();
        }
        ml_close(buf, true);
        buf.b_ml.ml_line_count = 0L;
        if ((flags & BFA_KEEP_UNDO) == 0) {
            u_clearallandblockfree(buf);
        }
        buf.b_flags &= ~BF_READERR;
        return true;
    }

    private static void init_changedtick(S_file_buffer buf) {
        buf.b_changedtick = 0L;
    }

    private void clear_wininfo(S_file_buffer buf) {
        S_wininfo_S wip = null;
        while (buf.b_wininfo != null) {
            wip = buf.b_wininfo;
            buf.b_wininfo = wip.wi_next;
            free_wininfo(wip);
        }
    }

    private void free_buffer_stuff(S_file_buffer buf, boolean free_options) {
        if (free_options) {
            clear_wininfo(buf);
            free_buf_options(buf, true);
        }
        map_clear_mode(buf, MAP_ALL_MODES, true, false);
        map_clear_mode(buf, MAP_ALL_MODES, true, true);
    }

    private void free_wininfo(S_wininfo_S wip) {
        if (wip.wi_optset) {
            clear_winopt(wip.wi_opt);
        }
    }

    private boolean curbuf_reusable() {
        return curbuf != null && curbuf.b_nwindows <= 1
                && (curbuf.b_ml.ml_root == null || (curbuf.b_ml.ml_line_count == 1L && ml_get(1L).get() == NUL))
                && curbufIsChanged() == 0;
    }

    private S_file_buffer buflist_new(long lnum, int flags) {
        S_file_buffer buf = null;
        if ((flags & BLN_CURBUF) != 0 && curbuf_reusable()) {
            T_bufref_T bufref = new T_bufref_T();
            buf = curbuf;
            set_bufref(bufref, buf);
            buf_freeall(buf, BFA_WIPE | BFA_DEL);
            if (!bufref_valid(bufref)) {
                buf = null;
            }
        }
        if (buf != curbuf || curbuf == null) {
            buf = new S_file_buffer();
            init_changedtick(buf);
        }
        clear_wininfo(buf);
        buf.b_wininfo = new S_wininfo_S();
        if (buf == curbuf) {
            free_buffer_stuff(buf, false);
            buf.b_p_initialized = false;
            buf_copy_options(buf, BCO_ENTER);
        } else {
            buf.b_fnum = top_file_num++;
            if (top_file_num < 0) {
                emsg(BytePtr.lit("W14: Warning: List of file names overflow"));
                if (emsg_silent == 0 && !in_assert_fails) {
                    out_flush();
                    ui_delay(3001L, true);
                }
                top_file_num = 1;
            }
            buf_copy_options(buf, BCO_ALWAYS);
        }
        buf.b_wininfo.wi_fpos.lnum = lnum;
        buf.b_wininfo.wi_win = curwin;
        buf.b_u_synced = true;
        buf.b_flags = BF_CHECK_RO | BF_NEVERLOADED;
        if ((flags & BLN_DUMMY) != 0) {
            buf.b_flags |= BF_DUMMY;
        }
        buf_clear_file(buf);
        clrallmarks(buf);
        if ((flags & BLN_DUMMY) == 0) {
            T_bufref_T bufref_2 = new T_bufref_T();
            set_bufref(bufref_2, buf);
        }
        return buf;
    }

    private void free_buf_options(S_file_buffer buf, boolean free_p_ff) {
        clear_string_option(new Ptr<BytePtr>(buf.b_p_mps, 0));
        clear_string_option(new Ptr<BytePtr>(buf.b_p_isk, 0));
        clear_string_option(new Ptr<BytePtr>(buf.b_p_nf, 0));
        clear_string_option(new Ptr<BytePtr>(buf.b_p_qe, 0));
        buf.b_p_ul[0] = -123456L;
    }

    private S_file_buffer buflist_findnr(int nr) {
        if (curbuf != null && curbuf.b_fnum == nr) {
            return curbuf;
        }
        return null;
    }

    private void buflist_setfpos(S_file_buffer buf, S_window_S win, long lnum, int col, boolean copy_options) {
        S_wininfo_S wip = null;
        for (wip = buf.b_wininfo; wip != null; wip = wip.wi_next) {
            if (wip.wi_win == win) {
                break;
            }
        }
        if (wip == null) {
            wip = new S_wininfo_S();
            wip.wi_win = win;
            if (lnum == 0L) {
                lnum = 1L;
            }
        } else {
            if (wip.wi_prev != null) {
                wip.wi_prev.wi_next = wip.wi_next;
            } else {
                buf.b_wininfo = wip.wi_next;
            }
            if (wip.wi_next != null) {
                wip.wi_next.wi_prev = wip.wi_prev;
            }
            if (copy_options && wip.wi_optset) {
                clear_winopt(wip.wi_opt);
            }
        }
        if (lnum != 0L) {
            wip.wi_fpos.lnum = lnum;
            wip.wi_fpos.col = col;
        }
        if (copy_options && win != null) {
            copy_winopt(win.w_onebuf_opt, wip.wi_opt);
            wip.wi_optset = true;
        }
        wip.wi_next = buf.b_wininfo;
        buf.b_wininfo = wip;
        wip.wi_prev = null;
        if (wip.wi_next != null) {
            wip.wi_next.wi_prev = wip;
        }
    }

    private BytePtr getaltfname(boolean errmsg) {
        if (errmsg) {
            emsg(new BytePtr(e_no_alternate_file, 0));
        }
        return null;
    }

    private void fileinfo(int fullname, boolean shorthelp, boolean dont_truncate) {
        BytePtr name;
        long bufferlen = 0L;
        BytePtr buffer = BytePtr.alloc(1025L);
        if (fullname > 1) {
            bufferlen = safelen_result(buffer, 1025L,
                    vim_snprintf(buffer, 1025L, BytePtr.lit("buf %d: "), curbuf.b_fnum));
        }
        buffer.set((int) bufferlen++, (byte) '"');
        name = buf_spname(curbuf);
        bufferlen += safelen_result(buffer.add((int) bufferlen), 1025L - bufferlen,
                vim_snprintf(buffer.add((int) bufferlen), 1025L - bufferlen, BytePtr.lit("%s"), name));
        BytePtr new_msg = (curbuf.b_flags & BF_NEW) != 0 ? new_file_message() : BytePtr.lit("");
        bufferlen += safelen_result(buffer.add((int) bufferlen), 1025L - bufferlen,
                vim_snprintf(buffer.add((int) bufferlen), 1025L - bufferlen, BytePtr.lit("\"%s%s%s%s%s"),
                curbufIsChanged() != 0 ? (shortmess(SHM_MOD) ? BytePtr.lit(" [+]") : BytePtr.lit(" [Modified]")) : BytePtr.lit(" "), (curbuf.b_flags & BF_NOTEDITED) != 0 ? BytePtr.lit("[Not edited]") : BytePtr.lit(""), new_msg, (curbuf.b_flags & BF_READERR) != 0 ? BytePtr.lit("[Read errors]") : BytePtr.lit(""), curbufIsChanged() != 0 || (curbuf.b_flags & (BF_NOTEDITED + BF_NEW + BF_READERR)) != 0 ? BytePtr.lit(" ") : BytePtr.lit("")));
        if ((curbuf.b_ml.ml_flags & ML_EMPTY) != 0) {
            bufferlen += safelen_result(buffer.add((int) bufferlen), 1025L - bufferlen,
                    vim_snprintf(buffer.add((int) bufferlen), 1025L - bufferlen, BytePtr.lit("%s"),
                    new BytePtr(no_lines_msg, 0)));
        } else if (p_ru[0] != 0) {
            bufferlen += safelen_result(buffer.add((int) bufferlen), 1025L - bufferlen,
                    vim_snprintf(buffer.add((int) bufferlen), 1025L - bufferlen,
                    NGETTEXT(BytePtr.lit("%ld line --%d%%--"), BytePtr.lit("%ld lines --%d%%--"),
                    curbuf.b_ml.ml_line_count), curbuf.b_ml.ml_line_count,
                    calc_percentage(curwin.w_cursor.lnum, curbuf.b_ml.ml_line_count)));
        } else {
            bufferlen += safelen_result(buffer.add((int) bufferlen), 1025L - bufferlen,
                    vim_snprintf(buffer.add((int) bufferlen), 1025L - bufferlen,
                    BytePtr.lit("line %ld of %ld --%d%%-- col "), curwin.w_cursor.lnum, curbuf.b_ml.ml_line_count,
                    calc_percentage(curwin.w_cursor.lnum, curbuf.b_ml.ml_line_count)));
            validate_virtcol();
            bufferlen += (long) col_print(buffer.add((int) bufferlen), 1025L - bufferlen, curwin.w_cursor.col + 1,
                    curwin.w_virtcol[0] + 1);
        }
        if (dont_truncate) {
            int n;
            msg_start();
            n = msg_scroll;
            msg_scroll = TRUE;
            msg(buffer);
            msg_scroll = n;
        } else {
            BytePtr p = msg_trunc_attr(buffer, false, 0);
            if (restart_edit != 0 || (msg_scrolled != 0 && need_wait_return == 0)) {
                set_keep_msg(p, 0);
            }
        }
    }

    private int col_print(BytePtr buf, long buflen, int col, int vcol) {
        if (col == vcol) {
            return (int) safelen_result(buf, buflen, vim_snprintf(buf, buflen, BytePtr.lit("%d"), col));
        }
        return (int) safelen_result(buf, buflen, vim_snprintf(buf, buflen, BytePtr.lit("%d-%d"), col, vcol));
    }

    private int get_rel_pos(S_window_S wp, BytePtr buf, int buflen) {
        long above;
        long below;
        if (buflen < 3) {
            return 0;
        }
        above = wp.w_topline - 1L;
        below = wp.w_buffer.b_ml.ml_line_count - wp.w_botline + 1L;
        if (below <= 0L) {
            return (int) safelen_result(buf, (long) buflen,
                    vim_snprintf(buf, (long) buflen, BytePtr.lit("%s"),
                    above == 0L ? BytePtr.lit("All") : BytePtr.lit("Bot")));
        }
        if (above <= 0L) {
            return (int) safelen_result(buf, (long) buflen,
                    vim_snprintf(buf, (long) buflen, BytePtr.lit("%s"), BytePtr.lit("Top")));
        }
        int perc = calc_percentage(above, above + below);
        byte[] tmp = new byte[8];
        vim_snprintf(new BytePtr(tmp, 0), 8L, BytePtr.lit("%d%%"), perc);
        return (int) safelen_result(buf, (long) buflen,
                vim_snprintf(buf, (long) buflen, BytePtr.lit("%3s"), new BytePtr(tmp, 0)));
    }

    private static boolean bt_help(S_file_buffer buf) {
        return buf != null && buf.b_help;
    }

    private static BytePtr buf_spname(S_file_buffer buf) {
        return buf_get_fname(buf);
    }

    private static BytePtr buf_get_fname(S_file_buffer buf) {
        return BytePtr.lit("[No Name]");
    }

    private BytePtr new_file_message() {
        return shortmess(SHM_NEW) ? BytePtr.lit("[New]") : BytePtr.lit("[New File]");
    }

    private void changed() {
        if (curbuf.b_changed[0] == 0) {
            changed_internal();
        }
        curbuf.b_changedtick++;
        highlight_match = false;
    }

    private void changed_internal() {
        curbuf.b_changed[0] = TRUE;
        check_status(curbuf);
        redraw_tabline = true;
    }

    private void changed_common(long lnum, int col, long lnume, long xtra) {
        S_window_S wp;
        int i = 0;
        int cols;
        T_pos_T p;
        boolean add;
        changed();
        if ((cmdmod.cmod_flags & CMOD_KEEPJUMPS) == 0) {
            curbuf.b_last_change.lnum = lnum;
            curbuf.b_last_change.col = col;
            if (curbuf.b_new_change || curbuf.b_changelistlen == 0) {
                if (curbuf.b_changelistlen == 0) {
                    add = true;
                } else {
                    p = curbuf.b_changelist[curbuf.b_changelistlen - 1];
                    if (p.lnum != lnum) {
                        add = true;
                    } else {
                        cols = comp_textwidth();
                        if (cols == 0) {
                            cols = 79;
                        }
                        add = p.col + cols < col || col + cols < p.col;
                    }
                }
                if (add) {
                    curbuf.b_new_change = false;
                    if (curbuf.b_changelistlen == JUMPLISTSIZE) {
                        curbuf.b_changelistlen = JUMPLISTSIZE - 1;
                        Rt.moveStructs(new Ptr<T_pos_T>(curbuf.b_changelist, 0),
                                new Ptr<T_pos_T>(curbuf.b_changelist, 0).add(1), 99);
                        wp = curwin;
                        if (wp.w_buffer == curbuf && wp.w_changelistidx > 0) {
                            wp.w_changelistidx--;
                        }
                    }
                    wp = curwin;
                    if (wp.w_buffer == curbuf && wp.w_changelistidx == curbuf.b_changelistlen) {
                        wp.w_changelistidx++;
                    }
                    curbuf.b_changelistlen++;
                }
            }
            curbuf.b_changelist[curbuf.b_changelistlen - 1].set(curbuf.b_last_change);
            curwin.w_changelistidx = curbuf.b_changelistlen;
        }
        if (VIsual_active) {
            check_visual_pos();
        }
        wp = curwin;
        if (wp.w_buffer == curbuf) {
            long last = lnume + xtra - 1L;
            if (!redraw_not_allowed && wp.w_redr_type < UPD_VALID) {
                wp.w_redr_type = UPD_VALID;
            }
            if (xtra != 0L && wp.w_redraw_top != 0L) {
                redraw_win_later(wp, UPD_NOT_VALID);
            }
            if (wp.w_skipcol > 0
                    && (last < wp.w_topline
                    || (wp.w_topline >= lnum && wp.w_topline < lnume
                    && linetabsize_eol(wp, wp.w_topline) <= wp.w_skipcol + sms_marker_overlap(wp, -1)))) {
                wp.w_skipcol = 0;
            }
            if (wp.w_cursor.lnum > lnum) {
                changed_line_abv_curs_win(wp);
            } else if (wp.w_cursor.lnum == lnum && wp.w_cursor.col >= col) {
                changed_cline_bef_curs_win(wp);
            }
            if (wp.w_botline >= lnum) {
                if (xtra < 0L) {
                    invalidate_botline_win(wp);
                } else {
                    approximate_botline_win(wp);
                }
            }
            for (i = 0; i < wp.w_lines_valid; i++) {
                if (wp.w_lines.at(i).wl_valid != 0) {
                    if (wp.w_lines.at(i).wl_lnum >= lnum) {
                        if (wp.w_lines.at(i).wl_lnum < lnume || i == 0) {
                            wp.w_lines.at(i).wl_valid = FALSE;
                        } else if (xtra != 0L) {
                            wp.w_lines.at(i).wl_lnum += xtra;
                        }
                    }
                }
            }
            if (wp.w_onebuf_opt.wo_rnu[0] != 0 && xtra != 0L) {
                wp.w_last_cursor_lnum_rnu = 0L;
            }
        }
        if (wp == curwin && xtra != 0L && search_hl_has_cursor_lnum >= lnum) {
            search_hl_has_cursor_lnum += xtra;
        }
        set_must_redraw(UPD_VALID);
        if (lnum <= curwin.w_cursor.lnum && lnume + (xtra < 0L ? -xtra : xtra) > curwin.w_cursor.lnum) {
            last_cursormoved.lnum = 0L;
        }
    }

    private static void changedOneline(S_file_buffer buf, long lnum) {
        if (buf.b_mod_set) {
            if (lnum < buf.b_mod_top) {
                buf.b_mod_top = lnum;
            } else if (lnum >= buf.b_mod_bot) {
                buf.b_mod_bot = lnum + 1L;
            }
        } else {
            buf.b_mod_set = true;
            buf.b_mod_top = lnum;
            buf.b_mod_bot = lnum + 1L;
            buf.b_mod_xlines = 0L;
        }
    }

    private void changed_bytes(long lnum, int col) {
        changedOneline(curbuf, lnum);
        changed_common(lnum, col, lnum + 1L, 0L);
    }

    private void inserted_bytes(long lnum, int col, int added) {
        changed_bytes(lnum, col);
    }

    private void appended_lines(long lnum, long count) {
        changed_lines(lnum + 1L, 0, lnum + 1L, count);
    }

    private void appended_lines_mark(long lnum, long count) {
        mark_adjust(lnum + 1L, LONG_MAX, count, 0L);
        changed_lines(lnum + 1L, 0, lnum + 1L, count);
    }

    private void deleted_lines(long lnum, long count) {
        changed_lines(lnum, 0, lnum + count, -count);
    }

    private void deleted_lines_mark(long lnum, long count) {
        mark_adjust(lnum, lnum + count - 1L, LONG_MAX, -count);
        changed_lines(lnum, 0, lnum + count, -count);
    }

    private static void changed_lines_buf(S_file_buffer buf, long lnum, long lnume, long xtra) {
        if (buf.b_mod_set) {
            if (lnum < buf.b_mod_top) {
                buf.b_mod_top = lnum;
            }
            if (lnum < buf.b_mod_bot) {
                buf.b_mod_bot += xtra;
                if (buf.b_mod_bot < lnum) {
                    buf.b_mod_bot = lnum;
                }
            }
            if (lnume + xtra > buf.b_mod_bot) {
                buf.b_mod_bot = lnume + xtra;
            }
            buf.b_mod_xlines += xtra;
        } else {
            buf.b_mod_set = true;
            buf.b_mod_top = lnum;
            buf.b_mod_bot = lnume + xtra;
            buf.b_mod_xlines = xtra;
        }
    }

    private void changed_lines(long lnum, int col, long lnume, long xtra) {
        changed_lines_buf(curbuf, lnum, lnume, xtra);
        changed_common(lnum, col, lnume, xtra);
    }

    private void unchanged(S_file_buffer buf, boolean ff, boolean always_inc_changedtick) {
        if (buf.b_changed[0] != 0) {
            buf.b_changed[0] = 0;
            check_status(buf);
            redraw_tabline = true;
            buf.b_changedtick++;
        } else if (always_inc_changedtick) {
            buf.b_changedtick++;
        }
    }

    private void ins_bytes(BytePtr p) {
        ins_bytes_len(p, (int) musl_strlen(p));
    }

    private void ins_bytes_len(BytePtr p, int len) {
        int i = 0;
        int n = 0;
        for (i = 0; i < len; i += n) {
            n = utfc_ptr2len_len(p.add(i), len - i);
            ins_char_bytes(p.add(i), n);
        }
    }

    private void ins_char(int c) {
        byte[] buf = new byte[22];
        int n = utf_char2bytes(c, new BytePtr(buf, 0));
        if (buf[0] == 0) {
            buf[0] = '\n';
        }
        ins_char_bytes(new BytePtr(buf, 0), n);
    }

    private void ins_char_bytes(BytePtr buf, int charlen) {
        int newlen;
        int oldlen;
        BytePtr p;
        BytePtr newp;
        BytePtr oldp;
        int linelen;
        int col;
        long lnum = curwin.w_cursor.lnum;
        int i = 0;
        if (virtual_active() != 0 && curwin.w_cursor.coladd > 0) {
            coladvance_force(getviscol());
        }
        col = curwin.w_cursor.col;
        oldp = ml_get(lnum);
        linelen = ml_get_len(lnum) + 1;
        oldlen = 0;
        newlen = charlen;
        if ((State & REPLACE_FLAG) != 0) {
            if ((State & VREPLACE_FLAG) != 0) {
                int new_vcol = 0;
                int[] vcol = new int[1];
                int old_list = curwin.w_onebuf_opt.wo_list[0];
                if (old_list != 0 && vim_strchr(p_cpo[0], CPO_LISTWM) == null) {
                    curwin.w_onebuf_opt.wo_list[0] = FALSE;
                }
                getvcol(curwin, curwin.w_cursor, null, new IntPtr(vcol, 0), null, 0);
                new_vcol = vcol[0] + chartabsize(buf, vcol[0]);
                while (oldp.at(col + oldlen) != NUL && vcol[0] < new_vcol) {
                    vcol[0] += chartabsize(oldp.add(col).add(oldlen), vcol[0]);
                    if (vcol[0] > new_vcol && oldp.at(col + oldlen) == TAB) {
                        break;
                    }
                    oldlen += utfc_ptr2len(oldp.add(col).add(oldlen));
                    if (vcol[0] > new_vcol) {
                        newlen += vcol[0] - new_vcol;
                    }
                }
                curwin.w_onebuf_opt.wo_list[0] = old_list;
            } else if (oldp.at(col) != NUL) {
                oldlen = utfc_ptr2len(oldp.add(col));
            }
            replace_push(NUL);
            for (i = 0; i < oldlen; i++) {
                i += replace_push_mb(oldp.add(col).add(i)) - 1;
            }
        }
        newp = BytePtr.alloc((long) (linelen + newlen - oldlen));
        if (col > 0) {
            Rt.memmove(newp, oldp, (long) col);
        }
        p = newp.add(col);
        if (linelen > (col + oldlen)) {
            Rt.memmove(p.add(newlen), oldp.add(col).add(oldlen), (long) (linelen - col - oldlen));
        }
        Rt.memmove(p, buf, (long) charlen);
        i = charlen;
        while (i < newlen) {
            p.set(i++, (byte) ' ');
        }
        ml_replace(lnum, newp, false);
        changed_bytes(lnum, col);
        if (p_sm[0] != 0 && (State & MODE_INSERT) != 0 && msg_silent == 0) {
            showmatch(utf_ptr2char(buf));
        }
        curwin.w_cursor.col += charlen;
    }

    private void ins_str(BytePtr s, long slen) {
        BytePtr oldp;
        BytePtr newp;
        int oldlen;
        int col;
        long lnum = curwin.w_cursor.lnum;
        if (virtual_active() != 0 && curwin.w_cursor.coladd > 0) {
            coladvance_force(getviscol());
        }
        col = curwin.w_cursor.col;
        oldp = ml_get(lnum);
        oldlen = ml_get_len(lnum);
        newp = BytePtr.alloc((long) oldlen + slen + 1L);
        if (col > 0) {
            Rt.memmove(newp, oldp, (long) col);
        }
        Rt.memmove(newp.add(col), s, slen);
        Rt.memmove(newp.add(col).add((int) slen), oldp.add(col), (long) (oldlen - col + 1));
        ml_replace(lnum, newp, false);
        inserted_bytes(lnum, col, (int) slen);
        curwin.w_cursor.col += (int) slen;
    }

    private boolean del_char(boolean fixpos) {
        mb_adjust_cursor();
        if (ml_get_cursor().get() == NUL) {
            return false;
        }
        return del_chars(1L, fixpos);
    }

    private boolean del_chars(long count, boolean fixpos) {
        long bytes = 0L;
        long i = 0;
        int l = 0;
        BytePtr p = ml_get_cursor();
        for (i = 0L; i < count && p.get() != NUL; i++) {
            l = utfc_ptr2len(p);
            bytes += (long) l;
            p = p.add(l);
        }
        return del_bytes(bytes, fixpos, true);
    }

    private boolean del_bytes(long count, boolean fixpos_arg, boolean use_delcombine) {
        BytePtr newp;
        int newlen;
        long lnum = curwin.w_cursor.lnum;
        int col = curwin.w_cursor.col;
        boolean alloc_newp;
        long movelen;
        int fixpos = fixpos_arg ? 1 : 0;
        BytePtr oldp = ml_get(lnum);
        int oldlen = ml_get_len(lnum);
        if (col >= oldlen) {
            return false;
        }
        if (count == 0L) {
            return true;
        }
        if (count < 1L) {
            vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_invalid_count_for_del_bytes_nr, 0), count);
            iemsg(iobuff_or(new BytePtr(e_invalid_count_for_del_bytes_nr, 0)));
            return false;
        }
        if (p_deco[0] != 0 && use_delcombine && (long) utfc_ptr2len(oldp.add(col)) >= count) {
            int[] cc = new int[6];
            int n;
            utfc_ptr2char(oldp.add(col), new IntPtr(cc, 0));
            if (cc[0] != NUL) {
                n = col;
                do {
                    col = n;
                    count = (long) utf_ptr2len(oldp.add(n));
                    n += (int) count;
                } while (utf_iscomposing(utf_ptr2char(oldp.add(n))));
                fixpos = 0;
            }
        }
        movelen = (long) oldlen - (long) col - count + 1L;
        if (movelen <= 1L) {
            if (col > 0 && fixpos != 0 && restart_edit == 0 && (get_ve_flags() & VE_ONEMORE) == 0) {
                curwin.w_cursor.col--;
                curwin.w_cursor.coladd = 0;
                curwin.w_cursor.col -= utf_head_off(oldp, oldp.add(curwin.w_cursor.col));
            }
            count = (long) (oldlen - col);
            movelen = 1L;
        }
        newlen = (int) ((long) oldlen - count);
        alloc_newp = ml_line_alloced() == 0;
        if (!alloc_newp) {
            newp = oldp;
        } else {
            newp = BytePtr.alloc((long) (newlen + 1));
            Rt.memmove(newp, oldp, (long) col);
        }
        Rt.memmove(newp.add(col), oldp.add(col).add((int) count), movelen);
        if (alloc_newp) {
            ml_replace(lnum, newp, false);
        } else {
            curbuf.b_ml.ml_line_len -= (int) count;
            curbuf.b_ml.ml_line_textlen = 0;
        }
        inserted_bytes(lnum, col, (int) -count);
        return true;
    }

    private boolean open_line(int dir, int flags, int second_line_indent, IntPtr did_do_comment) {
        BytePtr saved_line;
        BytePtr next_line = null;
        BytePtr p_extra = null;
        int less_cols = 0;
        int less_cols_off = 0;
        long old_cursor_lnum;
        int old_cursor_col;
        int old_cursor_coladd;
        int newcol = 0;
        int newindent = 0;
        int n = 0;
        boolean trunc_line = false;
        boolean retval = false;
        BytePtr p;
        int saved_char = NUL;
        T_pos_T pos = null;
        boolean do_si = may_do_si();
        boolean no_si = false;
        int first_char = NUL;
        int vreplace_mode;
        boolean did_append;
        int saved_pi = curbuf.b_p_pi[0];
        int len = ml_get_curline_len();
        saved_line = vim_strnsave(ml_get_curline(), (long) len);
        if ((State & VREPLACE_FLAG) != 0) {
            if (curwin.w_cursor.lnum < (long) orig_line_count) {
                int len_2 = ml_get_len(curwin.w_cursor.lnum + 1L);
                next_line = vim_strnsave(ml_get(curwin.w_cursor.lnum + 1L), (long) len_2);
            } else {
                next_line = vim_strsave(BytePtr.lit(""));
            }
            if (next_line == null) {
                curbuf.b_p_pi[0] = saved_pi;
                return retval;
            }
            replace_push(NUL);
            replace_push(NUL);
            p = saved_line.add(curwin.w_cursor.col);
            while (p.get() != NUL) {
                p = p.add(replace_push_mb(p));
            }
            saved_line.set(curwin.w_cursor.col, (byte) NUL);
        }
        if ((State & MODE_INSERT) != 0 && (State & VREPLACE_FLAG) == 0) {
            p_extra = saved_line.add(curwin.w_cursor.col);
            if (do_si) {
                p = skipwhite(p_extra);
                first_char = p.u();
            }
            saved_char = p_extra.u();
            p_extra.put((byte) NUL);
        }
        u_clearline();
        did_si = false;
        ai_col = 0;
        if (dir == FORWARD && did_ai) {
            trunc_line = true;
        }
        if ((flags & OPENLINE_FORCE_INDENT) != 0 && second_line_indent >= 0) {
            newindent = second_line_indent;
        } else if (curbuf.b_p_ai[0] != 0 || do_si) {
            newindent = get_indent_str(saved_line, (int) curbuf.b_p_ts[0], false);
            if (newindent == 0) {
                newindent = second_line_indent;
            }
            if (!trunc_line && do_si && saved_line.get() != NUL && (p_extra == null || first_char != '{')) {
                BytePtr ptr;
                byte last_char;
                old_cursor_lnum = curwin.w_cursor.lnum;
                old_cursor_col = curwin.w_cursor.col;
                old_cursor_coladd = curwin.w_cursor.coladd;
                ptr = saved_line;
                if (dir == FORWARD) {
                    if (ptr.at(0) == '#') {
                        while (ptr.at(0) == '#' && curwin.w_cursor.lnum > 1L) {
                            curwin.w_cursor.lnum--;
                            ptr = ml_get(curwin.w_cursor.lnum);
                        }
                        newindent = get_indent();
                    }
                    p = ptr.add((int) musl_strlen(ptr)).add(-1);
                    while (p.gt(ptr) && (p.get() == ' ' || p.get() == '\t')) {
                        p = p.add(-1);
                    }
                    last_char = p.get();
                    if (last_char == '{' || last_char == ';') {
                        if (p.gt(ptr)) {
                            p = p.add(-1);
                        }
                        while (p.gt(ptr) && (p.get() == ' ' || p.get() == '\t')) {
                            p = p.add(-1);
                        }
                    }
                    if (p.get() == ')') {
                        curwin.w_cursor.col = (int) p.sub(ptr);
                        if ((pos = findmatch(null, '(')) != null) {
                            curwin.w_cursor.lnum = pos.lnum;
                            newindent = get_indent();
                        }
                    }
                    if (last_char == '{') {
                        did_si = true;
                        no_si = true;
                    }
                } else {
                    if (ptr.at(0) == '#') {
                        boolean was_backslashed = false;
                        while ((ptr.at(0) == '#' || was_backslashed)
                                && curwin.w_cursor.lnum < curbuf.b_ml.ml_line_count) {
                            if (ptr.get() != 0 && ptr.at((int) (musl_strlen(ptr) - 1L)) == '\\') {
                                was_backslashed = true;
                            } else {
                                was_backslashed = false;
                            }
                            curwin.w_cursor.lnum++;
                            ptr = ml_get(curwin.w_cursor.lnum);
                        }
                        if (was_backslashed) {
                            newindent = 0;
                        } else {
                            newindent = get_indent();
                        }
                    }
                    p = skipwhite(ptr);
                    if (p.get() == '}') {
                        did_si = true;
                    } else {
                        can_si_back = true;
                    }
                }
                curwin.w_cursor.lnum = old_cursor_lnum;
                curwin.w_cursor.col = old_cursor_col;
                curwin.w_cursor.coladd = old_cursor_coladd;
            }
            if (do_si) {
                can_si = TRUE;
            }
            did_ai = true;
        }
        if (p_extra != null) {
            p_extra.put((byte) saved_char);
            if ((State & REPLACE_FLAG) != 0 && (State & VREPLACE_FLAG) == 0) {
                replace_push(NUL);
            }
            if (curbuf.b_p_ai[0] != 0 || (flags & OPENLINE_DELSPACES) != 0) {
                while ((p_extra.get() == ' ' || p_extra.get() == '\t')
                        && !utf_iscomposing(utf_ptr2char(p_extra.add(1)))) {
                    if ((State & REPLACE_FLAG) != 0 && (State & VREPLACE_FLAG) == 0) {
                        replace_push(p_extra.u());
                    }
                    p_extra = p_extra.add(1);
                    less_cols_off++;
                }
            }
            less_cols = (int) p_extra.sub(saved_line);
        }
        if (p_extra == null) {
            p_extra = BytePtr.lit("");
        }
        old_cursor_lnum = curwin.w_cursor.lnum;
        old_cursor_col = curwin.w_cursor.col;
        old_cursor_coladd = curwin.w_cursor.coladd;
        if (dir == -1) {
            curwin.w_cursor.lnum--;
        }
        if ((State & VREPLACE_FLAG) == 0 || old_cursor_lnum >= (long) orig_line_count) {
            if (!ml_append(curwin.w_cursor.lnum, p_extra, 0)) {
                curbuf.b_p_pi[0] = saved_pi;
                return retval;
            }
            mark_adjust(curwin.w_cursor.lnum + 1L, LONG_MAX, 1L, 0L);
            did_append = true;
        } else {
            curwin.w_cursor.lnum++;
            if (curwin.w_cursor.lnum >= Insstart.lnum + (long) vr_lines_changed) {
                u_save_cursor();
                vr_lines_changed++;
            }
            ml_replace(curwin.w_cursor.lnum, p_extra, true);
            changed_bytes(curwin.w_cursor.lnum, 0);
            curwin.w_cursor.lnum--;
            did_append = false;
        }
        if (newindent != 0 || did_si) {
            curwin.w_cursor.lnum++;
            if (did_si) {
                int sw = (int) get_sw_value(curbuf);
                if (p_sr[0] != 0) {
                    newindent -= newindent % sw;
                }
                newindent += sw;
            }
            if (curbuf.b_p_ci[0] != 0) {
                copy_indent(newindent, saved_line);
                curbuf.b_p_pi[0] = TRUE;
            } else {
                set_indent(newindent, SIN_INSERT);
            }
            less_cols -= curwin.w_cursor.col;
            ai_col = curwin.w_cursor.col;
            if ((State & REPLACE_FLAG) != 0 && (State & VREPLACE_FLAG) == 0) {
                for (n = 0; n < curwin.w_cursor.col; n++) {
                    replace_push(NUL);
                }
            }
            newcol += curwin.w_cursor.col;
            if (no_si) {
                did_si = false;
            }
        }
        curwin.w_cursor.lnum = old_cursor_lnum;
        curwin.w_cursor.col = old_cursor_col;
        curwin.w_cursor.coladd = old_cursor_coladd;
        if (dir == FORWARD) {
            if (trunc_line || (State & MODE_INSERT) != 0) {
                saved_line.set(curwin.w_cursor.col, (byte) NUL);
                if (trunc_line) {
                    truncate_spaces(saved_line, (long) curwin.w_cursor.col);
                }
                ml_replace(curwin.w_cursor.lnum, saved_line, false);
                saved_line = null;
                if (did_append) {
                    changed_lines(curwin.w_cursor.lnum, curwin.w_cursor.col, curwin.w_cursor.lnum + 1L, 1L);
                    did_append = false;
                    if ((flags & OPENLINE_MARKFIX) != 0) {
                        mark_col_adjust(curwin.w_cursor.lnum, curwin.w_cursor.col + less_cols_off, 1L,
                                (long) -less_cols, 0);
                    }
                } else {
                    changed_bytes(curwin.w_cursor.lnum, curwin.w_cursor.col);
                }
            }
            curwin.w_cursor.lnum = old_cursor_lnum + 1L;
        }
        if (did_append) {
            changed_lines(curwin.w_cursor.lnum, 0, curwin.w_cursor.lnum, 1L);
        }
        curwin.w_cursor.col = newcol;
        curwin.w_cursor.coladd = 0;
        if ((State & VREPLACE_FLAG) != 0) {
            vreplace_mode = State;
            State = MODE_INSERT;
        } else {
            vreplace_mode = 0;
        }
        if (vreplace_mode != 0) {
            State = vreplace_mode;
        }
        if ((State & VREPLACE_FLAG) != 0) {
            int len_3 = ml_get_curline_len();
            p_extra = vim_strnsave(ml_get_curline(), (long) len_3);
            ml_replace(curwin.w_cursor.lnum, next_line, false);
            curwin.w_cursor.col = 0;
            curwin.w_cursor.coladd = 0;
            ins_bytes(p_extra);
            next_line = null;
        }
        retval = true;
        curbuf.b_p_pi[0] = saved_pi;
        return retval;
    }

    private boolean truncate_line(boolean fixpos) {
        BytePtr newp;
        long lnum = curwin.w_cursor.lnum;
        int col = curwin.w_cursor.col;
        int deleted;
        BytePtr old_line = ml_get(lnum);
        if (col == 0) {
            newp = vim_strsave(BytePtr.lit(""));
        } else {
            newp = vim_strnsave(old_line, (long) col);
        }
        deleted = ml_get_len(lnum) - col;
        if (newp == null) {
            return false;
        }
        ml_replace(lnum, newp, false);
        inserted_bytes(lnum, curwin.w_cursor.col, -deleted);
        if (fixpos && curwin.w_cursor.col > 0) {
            curwin.w_cursor.col--;
        }
        return true;
    }

    private void del_lines(long nlines, boolean undo) {
        long n = 0;
        long first = curwin.w_cursor.lnum;
        if (nlines <= 0L) {
            return;
        }
        if (undo && !u_savedel(first, nlines)) {
            return;
        }
        for (n = 0L; n < nlines; ) {
            if ((curbuf.b_ml.ml_flags & ML_EMPTY) != 0) {
                break;
            }
            ml_delete_flags(first, ML_DEL_MESSAGE);
            n++;
            if (first > curbuf.b_ml.ml_line_count) {
                break;
            }
        }
        curwin.w_cursor.col = 0;
        check_cursor_lnum();
        deleted_lines_mark(first, n);
    }

    private boolean init_chartab() {
        return buf_init_chartab(curbuf, true);
    }

    private boolean buf_init_chartab(S_file_buffer buf, boolean global) {
        int c;
        BytePtr p = null;
        int i = 0;
        if (global) {
            c = 0;
            while (c < ' ') {
                g_chartab[c++] = (byte) ((dy_flags[0] & DY_UHEX) != 0 ? 4 : 2);
            }
            while (c <= '~') {
                g_chartab[c++] = 1 + CT_PRINT_CHAR;
            }
            while (c < 256) {
                if (c >= 160) {
                    g_chartab[c++] = CT_PRINT_CHAR + 1;
                } else {
                    g_chartab[c++] = (byte) ((dy_flags[0] & DY_UHEX) != 0 ? 4 : 2);
                }
            }
            for (c = 1; c < 256; c++) {
                if (c >= 160) {
                    g_chartab[c] |= (byte) CT_FNAME_CHAR;
                }
            }
        }
        Rt.memset(new BytePtr(buf.b_chartab, 0), 0, 32L);
        for (i = global ? 0 : 3; i <= 3; i++) {
            if (i == 0) {
                p = p_isi[0];
            } else if (i == 1) {
                p = p_isp[0];
            } else if (i == 2) {
                p = p_isf[0];
            } else {
                p = buf.b_p_isk[0];
            }
            if (!parse_isopt(p, buf, false)) {
                return false;
            }
        }
        chartab_initialized = true;
        return true;
    }

    private boolean check_isopt(BytePtr var_) {
        return parse_isopt(var_, null, true);
    }

    private boolean parse_isopt(BytePtr var_, S_file_buffer buf, boolean only_check) {
        BytePtr[] p = new BytePtr[1];
        p[0] = var_;
        int c = 0;
        int c2 = 0;
        boolean tilde = false;
        boolean do_isalpha = false;
        boolean trail_comma = false;
        while (p[0].get() != 0) {
            tilde = false;
            do_isalpha = false;
            if (p[0].get() == '^' && p[0].at(1) != NUL) {
                tilde = true;
                p[0] = p[0].add(1);
            }
            if (ascii_isdigit(p[0].u())) {
                c = (int) getdigits(new Ptr<BytePtr>(p, 0));
            } else {
                c = mb_ptr2char_adv(new Ptr<BytePtr>(p, 0));
            }
            c2 = -1;
            if (p[0].get() == '-' && p[0].at(1) != NUL) {
                p[0] = p[0].add(1);
                if (ascii_isdigit(p[0].u())) {
                    c2 = (int) getdigits(new Ptr<BytePtr>(p, 0));
                } else {
                    c2 = mb_ptr2char_adv(new Ptr<BytePtr>(p, 0));
                }
            }
            if (c <= 0 || c >= 256 || (c2 < c && c2 != -1) || c2 >= 256 || !(p[0].get() == NUL || p[0].get() == ',')) {
                return false;
            }
            trail_comma = p[0].get() == ',';
            p[0] = skip_to_option_part(p[0]);
            if (trail_comma && p[0].get() == NUL) {
                return false;
            }
            if (only_check) {
                continue;
            }
            if (c2 == -1) {
                if (c == '@') {
                    do_isalpha = true;
                    c = 1;
                    c2 = 255;
                } else {
                    c2 = c;
                }
            }
            while (c <= c2) {
                if (!do_isalpha || vim_islower(c) || vim_isupper(c)) {
                    if (BytePtr.eq(var_, p_isi[0])) {
                        if (tilde) {
                            g_chartab[c] &= (byte) ~CT_ID_CHAR;
                        } else {
                            g_chartab[c] |= (byte) CT_ID_CHAR;
                        }
                    } else if (BytePtr.eq(var_, p_isp[0])) {
                        if (c < ' ' || c > '~') {
                            if (tilde) {
                                g_chartab[c] = (byte) ((g_chartab[c] & 0xff & ~CT_CELL_MASK) + ((dy_flags[0] & DY_UHEX) != 0 ? 4 : 2));
                                g_chartab[c] &= (byte) ~CT_PRINT_CHAR;
                            } else {
                                g_chartab[c] = (byte) ((g_chartab[c] & 0xff & ~CT_CELL_MASK) + 1);
                                g_chartab[c] |= (byte) CT_PRINT_CHAR;
                            }
                        }
                    } else if (BytePtr.eq(var_, p_isf[0])) {
                        if (tilde) {
                            g_chartab[c] &= (byte) ~CT_FNAME_CHAR;
                        } else {
                            g_chartab[c] |= (byte) CT_FNAME_CHAR;
                        }
                    } else {
                        if (tilde) {
                            buf.b_chartab[c >>> 3] &= (byte) ~(1 << (c & 7));
                        } else {
                            buf.b_chartab[c >>> 3] |= (byte) (1 << (c & 7));
                        }
                    }
                }
                c++;
            }
        }
        return true;
    }

    private void trans_characters(BytePtr buf, int bufsize) {
        BytePtr trs = null;
        int trs_len = 0;
        int len = (int) musl_strlen(buf);
        int room = bufsize - len;
        while (buf.get() != 0) {
            if ((trs_len = utfc_ptr2len(buf)) > 1) {
                len -= trs_len;
            } else {
                trs = transchar_byte(buf.u());
                trs_len = (int) musl_strlen(trs);
                if (trs_len > 1) {
                    room -= trs_len - 1;
                    if (room <= 0) {
                        return;
                    }
                    Rt.memmove(buf.add(trs_len), buf.add(1), (long) len);
                }
                Rt.memmove(buf, trs, (long) trs_len);
                len--;
            }
            buf = buf.add(trs_len);
        }
    }

    private BytePtr transchar(int c) {
        return transchar_buf(curbuf, c);
    }

    private BytePtr transchar_buf(S_file_buffer buf, int c) {
        int i = 0;
        if (c < 0) {
            transchar_charbuf[0] = '~';
            transchar_charbuf[1] = '@';
            i = 2;
            c = c == 128 ? KS_SPECIAL : (c == NUL ? KS_ZERO : -c & 255);
        }
        if ((!chartab_initialized && (c >= ' ' && c <= '~')) || (c < 256 && vim_isprintc_strict(c))) {
            transchar_charbuf[i] = (byte) c;
            transchar_charbuf[i + 1] = NUL;
        } else {
            transchar_nonprint(buf, new BytePtr(transchar_charbuf, 0).add(i), c);
        }
        return new BytePtr(transchar_charbuf, 0);
    }

    private BytePtr transchar_byte(int c) {
        return transchar_byte_buf(curbuf, c);
    }

    private BytePtr transchar_byte_buf(S_file_buffer buf, int c) {
        if (c >= 128) {
            transchar_nonprint(buf, new BytePtr(transchar_charbuf, 0), c);
            return new BytePtr(transchar_charbuf, 0);
        }
        return transchar_buf(buf, c);
    }

    private void transchar_nonprint(S_file_buffer buf, BytePtr charbuf, int c) {
        if (c == NL) {
            c = NUL;
        }
        if ((dy_flags[0] & DY_UHEX) != 0) {
            transchar_hex(charbuf, c);
        } else if (c <= 127) {
            charbuf.set(0, (byte) '^');
            charbuf.set(1, (byte) (c ^ 64));
            charbuf.set(2, (byte) NUL);
        } else {
            transchar_hex(charbuf, c);
        }
    }

    private static void transchar_hex(BytePtr buf, int c) {
        int i = 0;
        buf.set(0, (byte) '<');
        if (c > 255) {
            buf.set(++i, (byte) nr2hex(c >>> 12));
            buf.set(++i, (byte) nr2hex(c >>> 8));
        }
        buf.set(++i, (byte) nr2hex(c >>> 4));
        buf.set(++i, (byte) nr2hex(c));
        buf.set(++i, (byte) '>');
        buf.set(++i, (byte) NUL);
    }

    private static int nr2hex(int c) {
        if (Integer.compareUnsigned(c & 15, 9) <= 0) {
            return (c & 15) + '0';
        }
        return (c & 15) - 10 + 'a';
    }

    private int byte2cells(int b) {
        if (b >= 128) {
            return 0;
        }
        return g_chartab[b] & 0xff & CT_CELL_MASK;
    }

    private int char2cells(int c) {
        if (c < 0) {
            return char2cells(c == 128 ? KS_SPECIAL : (c == NUL ? KS_ZERO : -c & 255)) + 2;
        }
        if (c >= 128) {
            return utf_char2cells(c);
        }
        return g_chartab[c & 255] & 0xff & CT_CELL_MASK;
    }

    private int ptr2cells(BytePtr p) {
        if (p.u() >= 128) {
            return utf_ptr2cells(p);
        }
        return g_chartab[p.u()] & 0xff & CT_CELL_MASK;
    }

    private int vim_strsize(BytePtr s) {
        return vim_strnsize(s, MAXCOL);
    }

    private int vim_strnsize(BytePtr s, int len) {
        int size = 0;
        while (s.get() != NUL && --len >= 0) {
            int l = utfc_ptr2len(s);
            size += ptr2cells(s);
            s = s.add(l);
            len -= l - 1;
        }
        return size;
    }

    private int chartabsize(BytePtr p, int col) {
        if (p.get() == TAB && (curwin.w_onebuf_opt.wo_list[0] == 0 || curwin.w_lcs_chars.tab1 != 0)) {
            int ts = (int) curbuf.b_p_ts[0];
            return ts - col % ts;
        } else {
            return ptr2cells(p);
        }
    }

    private int linetabsize_str(BytePtr s) {
        return linetabsize_col(0, s);
    }

    private int linetabsize_col(int startcol, BytePtr s) {
        T_chartabsize_T cts = new T_chartabsize_T();
        long vcol;
        init_chartabsize_arg(cts, curwin, 0L, startcol, s, s);
        vcol = (long) cts.cts_vcol;
        while (cts.cts_ptr.get() != NUL) {
            vcol += (long) lbr_chartabsize_adv(cts);
            if (vcol > MAXCOL) {
                cts.cts_vcol = MAXCOL;
                break;
            } else {
                cts.cts_vcol = (int) vcol;
            }
        }
        return cts.cts_vcol;
    }

    private int win_linetabsize(S_window_S wp, long lnum, BytePtr line, int len) {
        T_chartabsize_T cts = new T_chartabsize_T();
        init_chartabsize_arg(cts, wp, lnum, 0, line, line);
        win_linetabsize_cts(cts, len);
        return cts.cts_vcol;
    }

    private int linetabsize(S_window_S wp, long lnum) {
        return win_linetabsize(wp, lnum, ml_get_buf(wp.w_buffer, lnum, false), MAXCOL);
    }

    private int linetabsize_eol(S_window_S wp, long lnum) {
        return linetabsize(wp, lnum) + (wp.w_onebuf_opt.wo_list[0] != 0 && wp.w_lcs_chars.eol[0] != NUL ? 1 : 0);
    }

    private int linetabsize_no_outer(S_window_S wp, long lnum) {
        return linetabsize(wp, lnum);
    }

    private void win_linetabsize_cts(T_chartabsize_T cts, int len) {
        long vcol = (long) cts.cts_vcol;
        for (; cts.cts_ptr.get() != NUL
                && (len == MAXCOL
                || cts.cts_ptr.lt(cts.cts_line.add(len))); cts.cts_ptr = cts.cts_ptr.add(utfc_ptr2len(cts.cts_ptr))) {
            vcol += (long) win_lbr_chartabsize(cts, null, null);
            if (vcol > MAXCOL) {
                cts.cts_vcol = MAXCOL;
                break;
            } else {
                cts.cts_vcol = (int) vcol;
            }
        }
    }

    private boolean vim_isIDc(int c) {
        return c > 0 && c < 256 && (g_chartab[c] & 0xff & CT_ID_CHAR) != 0;
    }

    private static boolean vim_isNormalIDc(int c) {
        return ascii_isupper(c) || ascii_islower(c) || ascii_isdigit(c) || c == '_';
    }

    private boolean vim_iswordc(int c) {
        return vim_iswordc_buf(c, curbuf);
    }

    private boolean vim_iswordc_buf(int c, S_file_buffer buf) {
        if (c >= 256) {
            return utf_class_buf(c, buf) >= 2;
        }
        return c > 0 && (buf.b_chartab[c >>> 3] & 0xff & (1 << (c & 7))) != 0;
    }

    private boolean vim_iswordp(BytePtr p) {
        return vim_iswordp_buf(p, curbuf);
    }

    private boolean vim_iswordp_buf(BytePtr p, S_file_buffer buf) {
        int c = p.u();
        if ((int) mb_bytelen_tab[c] > 1) {
            c = utf_ptr2char(p);
        }
        return vim_iswordc_buf(c, buf);
    }

    private boolean vim_isfilec(int c) {
        return c >= 256 || (c > 0 && (g_chartab[c] & 0xff & CT_FNAME_CHAR) != 0);
    }

    private boolean vim_isprintc(int c) {
        if (c >= 256) {
            return utf_printable(c);
        }
        return c >= 256 || (c > 0 && (g_chartab[c] & 0xff & CT_PRINT_CHAR) != 0);
    }

    private boolean vim_isprintc_strict(int c) {
        if (c >= 256) {
            return utf_printable(c);
        }
        return c >= 256 || (c > 0 && (g_chartab[c] & 0xff & CT_PRINT_CHAR) != 0);
    }

    private static void init_chartabsize_arg(T_chartabsize_T cts, S_window_S wp, long lnum, int col, BytePtr line,
            BytePtr ptr) {
        cts.zero();
        cts.cts_win = wp;
        cts.cts_vcol = col;
        cts.cts_line = line;
        cts.cts_ptr = ptr;
    }

    private int lbr_chartabsize(T_chartabsize_T cts) {
        if (curwin.w_onebuf_opt.wo_wrap[0] != 0) {
            return win_nolbr_chartabsize(cts, null);
        }
        if (cts.cts_ptr.get() == TAB && (curwin.w_onebuf_opt.wo_list[0] == 0 || curwin.w_lcs_chars.tab1 != 0)) {
            int ts = (int) curbuf.b_p_ts[0];
            return ts - cts.cts_vcol % ts;
        } else {
            return ptr2cells(cts.cts_ptr);
        }
    }

    private int lbr_chartabsize_adv(T_chartabsize_T cts) {
        int retval = lbr_chartabsize(cts);
        cts.cts_ptr = cts.cts_ptr.add(utfc_ptr2len(cts.cts_ptr));
        return retval;
    }

    private int win_lbr_chartabsize(T_chartabsize_T cts, IntPtr headp, IntPtr tailp) {
        S_window_S wp = cts.cts_win;
        BytePtr s = cts.cts_ptr;
        int vcol = cts.cts_vcol;
        if (wp.w_onebuf_opt.wo_wrap[0] != 0) {
            return win_nolbr_chartabsize(cts, headp);
        }
        if (s.get() == TAB && (wp.w_onebuf_opt.wo_list[0] == 0 || wp.w_lcs_chars.tab1 != 0)) {
            int ts = (int) wp.w_buffer.b_p_ts[0];
            return ts - vcol % ts;
        } else {
            return ptr2cells(s);
        }
    }

    private int win_nolbr_chartabsize(T_chartabsize_T cts, IntPtr headp) {
        S_window_S wp = cts.cts_win;
        BytePtr s = cts.cts_ptr;
        int col = cts.cts_vcol;
        int n;
        if (s.get() == TAB && (wp.w_onebuf_opt.wo_list[0] == 0 || wp.w_lcs_chars.tab1 != 0)) {
            n = (int) wp.w_buffer.b_p_ts[0];
            return n - col % n;
        }
        n = ptr2cells(s);
        if (n == 2 && (int) mb_bytelen_tab[s.u()] > 1 && in_win_border(wp, col)) {
            if (headp != null) {
                headp.put(1);
            }
            return 3;
        }
        return n;
    }

    private boolean in_win_border(S_window_S wp, int vcol) {
        int width1;
        int width2;
        if (wp.w_width == 0) {
            return false;
        }
        width1 = wp.w_width - win_col_off(wp);
        if (vcol < width1 - 1) {
            return false;
        }
        if (vcol == width1 - 1) {
            return true;
        }
        width2 = width1 + win_col_off2(wp);
        if (width2 <= 0) {
            return false;
        }
        return (vcol - width1) % width2 == width2 - 1;
    }

    private void getvcol(S_window_S wp, T_pos_T pos, IntPtr start, IntPtr cursor, IntPtr end, int flags) {
        BytePtr ptr = null;
        int incr = 0;
        int[] head = new int[1];
        int[] tail = new int[1];
        int ts = (int) wp.w_buffer.b_p_ts[0];
        int c = 0;
        T_chartabsize_T cts = new T_chartabsize_T();
        int vcol = 0;
        BytePtr line = ptr = ml_get_buf(wp.w_buffer, pos.lnum, false);
        init_chartabsize_arg(cts, wp, pos.lnum, 0, line, line);
        cts.cts_max_head_vcol = -1;
        if (wp.w_onebuf_opt.wo_list[0] == 0 || wp.w_lcs_chars.tab1 != NUL) {
            for (;;) {
                head[0] = 0;
                c = ptr.u();
                if (c == NUL) {
                    incr = 1;
                    break;
                }
                if (c == TAB) {
                    incr = ts - vcol % ts;
                } else {
                    if (c >= 128) {
                        incr = utf_ptr2cells(ptr);
                    } else {
                        incr = g_chartab[c] & 0xff & CT_CELL_MASK;
                    }
                    if (incr == 2 && wp.w_onebuf_opt.wo_wrap[0] != 0 && (int) mb_bytelen_tab[ptr.u()] > 1
                            && in_win_border(wp, vcol)) {
                        incr++;
                        head[0] = 1;
                    }
                }
                BytePtr next_ptr = ptr.add(utfc_ptr2len(ptr));
                if (next_ptr.sub(line) > ((long) pos.col)) {
                    break;
                }
                vcol += incr;
                ptr = next_ptr;
            }
            tail[0] = 0;
        } else {
            for (;;) {
                head[0] = 0;
                tail[0] = 0;
                incr = win_lbr_chartabsize(cts, new IntPtr(head, 0), new IntPtr(tail, 0));
                if (cts.cts_ptr.get() == NUL) {
                    incr = 1;
                    break;
                }
                BytePtr next_ptr_2 = cts.cts_ptr.add(utfc_ptr2len(cts.cts_ptr));
                if (next_ptr_2.sub(line) > ((long) pos.col)) {
                    break;
                }
                cts.cts_vcol += incr;
                cts.cts_ptr = next_ptr_2;
            }
            vcol = cts.cts_vcol;
            ptr = cts.cts_ptr;
        }
        if (ptr.get() == NUL && pos.col < MAXCOL && (long) pos.col > ptr.sub(line)) {
            pos.col = (int) ptr.sub(line);
        }
        if (start != null) {
            start.put(vcol + head[0]);
        }
        if (end != null) {
            end.put(vcol + incr - ((flags & GETVCOL_END_EXCL_LBR) != 0 ? tail[0] : 0) - 1);
        }
        if (cursor != null) {
            if (ptr.get() == TAB && (State & MODE_NORMAL) != 0 && wp.w_onebuf_opt.wo_list[0] == 0
                    && virtual_active() == 0
                    && !(VIsual_active
                    && (p_sel[0].get() == 'e'
                    || ((pos.lnum != VIsual.lnum ? pos.lnum < VIsual.lnum : (pos.col != VIsual.col ? pos.col < VIsual.col : pos.coladd < VIsual.coladd)) || (pos.lnum == VIsual.lnum && pos.col == VIsual.col && pos.coladd == VIsual.coladd))))) {
                cursor.put(vcol + incr - 1);
            } else {
                cursor.put(vcol + head[0]);
            }
        }
    }

    private int getvcol_nolist(T_pos_T posp) {
        int list_save = curwin.w_onebuf_opt.wo_list[0];
        int[] vcol = new int[1];
        curwin.w_onebuf_opt.wo_list[0] = FALSE;
        if (posp.coladd != 0) {
            getvvcol(curwin, posp, null, new IntPtr(vcol, 0), null, 0);
        } else {
            getvcol(curwin, posp, null, new IntPtr(vcol, 0), null, 0);
        }
        curwin.w_onebuf_opt.wo_list[0] = list_save;
        return vcol[0];
    }

    private void getvvcol(S_window_S wp, T_pos_T pos, IntPtr start, IntPtr cursor, IntPtr end, int flags) {
        int[] col = new int[1];
        int coladd;
        int endadd;
        BytePtr ptr;
        if (virtual_active() != 0) {
            getvcol(wp, pos, new IntPtr(col, 0), null, null, flags);
            coladd = pos.coladd;
            endadd = 0;
            ptr = ml_get_buf(wp.w_buffer, pos.lnum, false);
            if (pos.col < ml_get_buf_len(wp.w_buffer, pos.lnum)) {
                int c = utf_ptr2char(ptr.add(pos.col));
                if (c != TAB && vim_isprintc(c)) {
                    endadd = char2cells(c) - 1;
                    if (coladd > endadd) {
                        endadd = 0;
                    } else {
                        coladd = 0;
                    }
                }
            }
            col[0] += coladd;
            if (start != null) {
                start.put(col[0]);
            }
            if (cursor != null) {
                cursor.put(col[0]);
            }
            if (end != null) {
                end.put(col[0] + endadd);
            }
        } else {
            getvcol(wp, pos, start, cursor, end, flags);
        }
    }

    private void getvcols(S_window_S wp, T_pos_T pos1, T_pos_T pos2, IntPtr left, IntPtr right, int flags) {
        int[] from1 = new int[1];
        int[] from2 = new int[1];
        int[] to1 = new int[1];
        int[] to2 = new int[1];
        if (pos1.lnum != pos2.lnum ? pos1.lnum < pos2.lnum : (pos1.col != pos2.col ? pos1.col < pos2.col : pos1.coladd < pos2.coladd)) {
            getvvcol(wp, pos1, new IntPtr(from1, 0), null, new IntPtr(to1, 0), flags);
            getvvcol(wp, pos2, new IntPtr(from2, 0), null, new IntPtr(to2, 0), flags);
        } else {
            getvvcol(wp, pos2, new IntPtr(from1, 0), null, new IntPtr(to1, 0), flags);
            getvvcol(wp, pos1, new IntPtr(from2, 0), null, new IntPtr(to2, 0), flags);
        }
        if (from2[0] < from1[0]) {
            left.put(from2[0]);
        } else {
            left.put(from1[0]);
        }
        if (to2[0] > to1[0]) {
            if (p_sel[0].get() == 'e' && from2[0] - 1 >= to1[0]) {
                right.put(from2[0] - 1);
            } else {
                right.put(to2[0]);
            }
        } else {
            right.put(to1[0]);
        }
    }

    private static BytePtr skipwhite(BytePtr q) {
        BytePtr p = q;
        while (p.get() == ' ' || p.get() == '\t') {
            p = p.add(1);
        }
        return p;
    }

    private int getwhitecols_curline() {
        return getwhitecols(ml_get_curline());
    }

    private static int getwhitecols(BytePtr p) {
        return (int) skipwhite(p).sub(p);
    }

    private static BytePtr skipdigits(BytePtr q) {
        BytePtr p = q;
        while (ascii_isdigit(p.u())) {
            p = p.add(1);
        }
        return p;
    }

    private static boolean vim_isdigit(int c) {
        return c >= '0' && c <= '9';
    }

    private static boolean vim_isxdigit(int c) {
        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
    }

    private static boolean vim_isbdigit(int c) {
        return c == '0' || c == '1';
    }

    private static boolean vim_isodigit(int c) {
        return c >= '0' && c <= '7';
    }

    private boolean vim_islower(int c) {
        if (c <= '@') {
            return false;
        }
        if (c >= 128) {
            return utf_islower(c);
        }
        return musl_islower((byte) c & 0xff);
    }

    private boolean vim_isupper(int c) {
        if (c <= '@') {
            return false;
        }
        if (c >= 128) {
            return utf_isupper(c);
        }
        return musl_isupper((byte) c & 0xff);
    }

    private int vim_toupper(int c) {
        if (c <= '@') {
            return c;
        }
        if (c >= 128 || (cmp_flags[0] & CMP_KEEPASCII) == 0) {
            return utf_toupper(c);
        }
        if (c < 128 && (cmp_flags[0] & CMP_KEEPASCII) != 0) {
            return c < 'a' || c > 'z' ? c : c - ('a' - 'A');
        }
        return musl_toupper((byte) c & 0xff);
    }

    private int vim_tolower(int c) {
        if (c <= '@') {
            return c;
        }
        if (c >= 128 || (cmp_flags[0] & CMP_KEEPASCII) == 0) {
            return utf_tolower(c);
        }
        if (c < 128 && (cmp_flags[0] & CMP_KEEPASCII) != 0) {
            return c < 'A' || c > 'Z' ? c : c + ('a' - 'A');
        }
        return musl_tolower((byte) c & 0xff);
    }

    private static BytePtr skiptowhite(BytePtr p) {
        while (p.get() != ' ' && p.get() != '\t' && p.get() != NUL) {
            p = p.add(1);
        }
        return p;
    }

    private static long getdigits(Ptr<BytePtr> pp) {
        BytePtr p = pp.get();
        long retval = musl_strtol(p, null, 10);
        if (p.get() == '-') {
            p = p.add(1);
        }
        p = skipdigits(p);
        pp.put(p);
        return retval;
    }

    private static long getdigits_quoted(Ptr<BytePtr> pp) {
        BytePtr p = pp.get();
        long retval = 0L;
        if (p.get() == '-') {
            p = p.add(1);
        }
        while (ascii_isdigit(p.u())) {
            if (retval >= LONG_MAX / 10L - 10L) {
                retval = LONG_MAX;
            } else {
                retval = retval * 10L - '0' + (p.get() & 0xffL);
            }
            p = p.add(1);
        }
        if (pp.get().get() == '-') {
            if (retval == LONG_MAX) {
                retval = LONG_MIN;
            } else {
                retval = -retval;
            }
        }
        pp.put(p);
        return retval;
    }

    private static int vim_str2nr(BytePtr start, IntPtr prep, int len, int what, LongPtr nptr, LongPtr unptr,
            int maxlen, boolean strict, IntPtr overflow) {
        BytePtr ptr = start;
        int pre = 0;
        boolean negative = false;
        long un = 0L;
        int n = 0;
        len = 0;
        if (ptr.at(0) == '-') {
            negative = true;
            ptr = ptr.add(1);
        }
        if (ptr.at(0) == '0' && ptr.at(1) != '8' && ptr.at(1) != '9' && (maxlen == 0 || maxlen > 1)) {
            pre = ptr.u(1);
            if ((what & STR2NR_HEX) != 0 && (pre == 'X' || pre == 'x') && vim_isxdigit(ptr.u(2))
                    && (maxlen == 0 || maxlen > 2)) {
                ptr = ptr.add(2);
            } else if ((what & STR2NR_BIN) != 0 && (pre == 'B' || pre == 'b') && vim_isbdigit(ptr.u(2))
                    && (maxlen == 0 || maxlen > 2)) {
                ptr = ptr.add(2);
            } else if ((what & STR2NR_OOCT) != 0 && (pre == 'O' || pre == 'o') && vim_isodigit(ptr.u(2))
                    && (maxlen == 0 || maxlen > 2)) {
                ptr = ptr.add(2);
            } else {
                pre = 0;
                if ((what & STR2NR_OCT) != 0) {
                    for (n = 1; n != maxlen && ascii_isdigit(ptr.u(n)); n++) {
                        if (ptr.u(n) > '7') {
                            pre = 0;
                            break;
                        }
                        pre = '0';
                    }
                }
            }
        }
        n = 1;
        if (pre == 'B' || pre == 'b' || ((what & STR2NR_BIN) != 0 && (what & STR2NR_FORCE) != 0)) {
            if (pre != 0) {
                n += 2;
            }
            while ('0' <= ptr.u() && ptr.u() <= '1') {
                if (Long.compareUnsigned(un, 9223372036854775807L) <= 0) {
                    un = 2L * un + (long) (ptr.u() - '0');
                } else {
                    un = ULLONG_MAX;
                    if (overflow != null) {
                        overflow.put(TRUE);
                    }
                }
                ptr = ptr.add(1);
                if (n++ == maxlen) {
                    break;
                }
                if ((what & STR2NR_QUOTE) != 0 && ptr.get() == '\'' && '0' <= ptr.u(1) && ptr.u(1) <= '1') {
                    ptr = ptr.add(1);
                    if (n++ == maxlen) {
                        break;
                    }
                }
            }
        } else if (pre == 'O' || pre == 'o' || pre == '0' || ((what & STR2NR_OCT) != 0 && (what & STR2NR_FORCE) != 0)) {
            if (pre != 0 && pre != '0') {
                n += 2;
            }
            while ('0' <= ptr.u() && ptr.u() <= '7') {
                if (Long.compareUnsigned(un, 2305843009213693951L) <= 0) {
                    un = 8L * un + (long) (ptr.u() - '0');
                } else {
                    un = ULLONG_MAX;
                    if (overflow != null) {
                        overflow.put(TRUE);
                    }
                }
                ptr = ptr.add(1);
                if (n++ == maxlen) {
                    break;
                }
                if ((what & STR2NR_QUOTE) != 0 && ptr.get() == '\'' && '0' <= ptr.u(1) && ptr.u(1) <= '7') {
                    ptr = ptr.add(1);
                    if (n++ == maxlen) {
                        break;
                    }
                }
            }
        } else if (pre != 0 || ((what & STR2NR_HEX) != 0 && (what & STR2NR_FORCE) != 0)) {
            if (pre != 0) {
                n += 2;
            }
            while (vim_isxdigit(ptr.u())) {
                if (Long.compareUnsigned(un, 1152921504606846975L) <= 0) {
                    un = 16L * un + (long) hex2nr(ptr.u());
                } else {
                    un = ULLONG_MAX;
                    if (overflow != null) {
                        overflow.put(TRUE);
                    }
                }
                ptr = ptr.add(1);
                if (n++ == maxlen) {
                    break;
                }
                if ((what & STR2NR_QUOTE) != 0 && ptr.get() == '\'' && vim_isxdigit(ptr.u(1))) {
                    ptr = ptr.add(1);
                    if (n++ == maxlen) {
                        break;
                    }
                }
            }
        } else {
            while (ascii_isdigit(ptr.u())) {
                long digit = (long) (ptr.u() - '0');
                if (Long.compareUnsigned(un, 1844674407370955161L) < 0
                        || (un == 1844674407370955161L && Long.compareUnsigned(digit, 5L) <= 0)) {
                    un = 10L * un + digit;
                } else {
                    un = ULLONG_MAX;
                    if (overflow != null) {
                        overflow.put(TRUE);
                    }
                }
                ptr = ptr.add(1);
                if (n++ == maxlen) {
                    break;
                }
                if ((what & STR2NR_QUOTE) != 0 && ptr.get() == '\'' && ascii_isdigit(ptr.u(1))) {
                    ptr = ptr.add(1);
                    if (n++ == maxlen) {
                        break;
                    }
                }
            }
        }
        if (strict && n - 1 != maxlen && (ascii_isupper(ptr.u()) || ascii_islower(ptr.u()) || ascii_isdigit(ptr.u()))) {
            return len;
        }
        if (prep != null) {
            prep.put(pre);
        }
        len = (int) ptr.sub(start);
        if (nptr != null) {
            if (negative) {
                if (Long.compareUnsigned(un, LLONG_MAX) > 0) {
                    nptr.put(LLONG_MIN);
                    if (overflow != null) {
                        overflow.put(TRUE);
                    }
                } else {
                    nptr.put(-un);
                }
            } else {
                if (Long.compareUnsigned(un, LLONG_MAX) > 0) {
                    un = LLONG_MAX;
                    if (overflow != null) {
                        overflow.put(TRUE);
                    }
                }
                nptr.put(un);
            }
        }
        if (unptr != null) {
            unptr.put(un);
        }
        return len;
    }

    private static int hex2nr(int c) {
        if (c >= 'a' && c <= 'f') {
            return c - 'a' + 10;
        }
        if (c >= 'A' && c <= 'F') {
            return c - 'A' + 10;
        }
        return c - '0';
    }

    private static int hexhex2nr(BytePtr p) {
        if (!vim_isxdigit(p.u(0)) || !vim_isxdigit(p.u(1))) {
            return -1;
        }
        return (hex2nr(p.u(0)) << 4) + hex2nr(p.u(1));
    }

    private static boolean rem_backslash(BytePtr str) {
        return str.at(0) == '\\' && str.at(1) != NUL;
    }

    private BytePtr skip_string(BytePtr p) {
        int i = 0;
        for (; ; p = p.add(1)) {
            if (p.at(0) == '\'') {
                if (p.at(1) == NUL) {
                    break;
                }
                i = 2;
                if (p.at(1) == '\\' && p.at(2) != NUL) {
                    i++;
                    while (vim_isdigit(p.u(i - 1))) {
                        i++;
                    }
                }
                if (p.at(i - 1) != NUL && p.at(i) == '\'') {
                    p = p.add(i);
                    continue;
                }
            } else if (p.at(0) == '"') {
                for (p = p.add(1); p.at(0) != 0; p = p.add(1)) {
                    if (p.at(0) == '\\' && p.at(1) != NUL) {
                        p = p.add(1);
                    } else if (p.at(0) == '"') {
                        break;
                    }
                }
                if (p.at(0) == '"') {
                    continue;
                }
            } else if (p.at(0) == 'R' && p.at(1) == '"') {
                BytePtr delim = p.add(2);
                BytePtr paren = vim_strchr(delim, '(');
                if (paren != null) {
                    long delim_len = paren.sub(delim);
                    for (p = p.add(3); p.get() != 0; p = p.add(1)) {
                        if (p.at(0) == ')' && musl_strncmp(p.add(1), delim, delim_len) == 0
                                && p.at((int) (delim_len + 1L)) == '"') {
                            p = p.add((int) (delim_len + 1L));
                            break;
                        }
                    }
                    if (p.at(0) == '"') {
                        continue;
                    }
                }
            }
            break;
        }
        if (p.get() == 0) {
            p = p.add(-1);
        }
        return p;
    }

    private int check_linecomment(BytePtr line) {
        BytePtr p = line;
        for (; p.get() != NUL; p = p.add(1)) {
            p = skip_string(p);
            if (p.get() == NUL) {
                break;
            }
            if (p.at(0) == '/' && p.at(1) == '/' && (BytePtr.eq(p, line) || p.at(-1) != '*' || p.at(2) != '*')) {
                break;
            }
        }
        if (p.get() == NUL) {
            p = null;
        }
        if (p == null) {
            return MAXCOL;
        }
        return (int) p.sub(line);
    }

    private static void free_xp_files_extra(S_expand xp, int numfiles) {
        if (xp.xp_files_abbr != null) {
            FreeWild(numfiles, xp.xp_files_abbr);
            xp.xp_files_abbr = null;
        }
        if (xp.xp_files_kind != null) {
            FreeWild(numfiles, xp.xp_files_kind);
            xp.xp_files_kind = null;
        }
        if (xp.xp_files_menu != null) {
            FreeWild(numfiles, xp.xp_files_menu);
            xp.xp_files_menu = null;
        }
        if (xp.xp_files_info != null) {
            FreeWild(numfiles, xp.xp_files_info);
            xp.xp_files_info = null;
        }
    }

    private static void ExpandInit(S_expand xp) {
        xp.zero();
        xp.xp_backslash = XP_BS_NONE;
        xp.xp_prefix = XP_PREFIX_NONE;
        xp.xp_numfiles = -1;
    }

    private static void ExpandCleanup(S_expand xp) {
        if (xp.xp_numfiles >= 0) {
            free_xp_files_extra(xp, xp.xp_numfiles);
            FreeWild(xp.xp_numfiles, xp.xp_files);
            xp.xp_numfiles = -1;
        }
        xp.xp_orig = null;
    }

