    private void ex_join(S_exarg eap) {
        curwin.w_cursor.lnum = eap.line1;
        if (eap.line1 == eap.line2) {
            if (eap.addr_count >= 2) {
                return;
            }
            if (eap.line2 == curbuf.b_ml.ml_line_count) {
                beep_flush();
                return;
            }
            eap.line2++;
        }
        do_join(eap.line2 - eap.line1 + 1L, !eap.forceit, true, true, true);
        beginline(BL_WHITE | BL_FIX);
        ex_may_print(eap);
    }

    private void ex_at(S_exarg eap) {
        int c;
        int prev_len = typebuf.tb_len;
        curwin.w_cursor.lnum = eap.line2;
        check_cursor_col();
        c = eap.arg[0].u();
        if (c == NUL || (c == '*' && eap.cmd[0].get() == '*')) {
            c = '@';
        }
        if (!do_execreg(c, true, vim_strchr(p_cpo[0], CPO_EXECBUF) != null, true)) {
            beep_flush();
            return;
        }
        int save_efr = exec_from_reg;
        exec_from_reg = TRUE;
        while (!stuff_empty() || typebuf.tb_len > prev_len) {
            do_cmdline(null, fp_getexline, DOCMD_NOWAIT | DOCMD_VERBOSE | DOCMD_GETEXLINE);
        }
        exec_from_reg = save_efr;
    }

