    private void ex_later(S_exarg eap) {
        long count = 0L;
        boolean sec = false;
        boolean file = false;
        BytePtr[] p = new BytePtr[1];
        p[0] = eap.arg[0];
        if (p[0].get() == NUL) {
            count = 1L;
        } else if (musl_isdigit(p[0].u())) {
            count = getdigits(new Ptr<BytePtr>(p, 0));
            switch (p[0].u()) {
                case 's' -> {
                    p[0] = p[0].add(1);
                    sec = true;
                }
                case 'm' -> {
                    p[0] = p[0].add(1);
                    sec = true;
                    count *= 60L;
                }
                case 'h' -> {
                    p[0] = p[0].add(1);
                    sec = true;
                    count *= 3600L;
                }
                case 'd' -> {
                    p[0] = p[0].add(1);
                    sec = true;
                    count *= 86400L;
                }
                case 'f' -> {
                    p[0] = p[0].add(1);
                    file = true;
                }
            }
        }
        if (p[0].get() != NUL) {
            vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_invalid_argument_str, 0), eap.arg[0]);
            emsg(iobuff_or(new BytePtr(e_invalid_argument_str, 0)));
        } else {
            undo_time(eap.cmdidx == CMD_earlier ? -count : count, sec, file, false);
        }
    }

