    private void ex_mark(S_exarg eap) {
        long pos_lnum;
        int pos_col_;
        int pos_coladd;
        if (eap.arg[0].get() == NUL) {
            emsg(new BytePtr(e_argument_required, 0));
            return;
        }
        if (eap.arg[0].at(1) != NUL) {
            vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_trailing_characters_str, 0), eap.arg[0]);
            emsg(iobuff_or(new BytePtr(e_trailing_characters_str, 0)));
            return;
        }
        pos_lnum = curwin.w_cursor.lnum;
        pos_col_ = curwin.w_cursor.col;
        pos_coladd = curwin.w_cursor.coladd;
        curwin.w_cursor.lnum = eap.line2;
        beginline(BL_WHITE | BL_FIX);
        if (setmark(eap.arg[0].u()) == FAIL) {
            emsg(new BytePtr(e_argument_must_be_letter_or_forward_backward_quote, 0));
        }
        curwin.w_cursor.lnum = pos_lnum;
        curwin.w_cursor.col = pos_col_;
        curwin.w_cursor.coladd = pos_coladd;
    }

