    private boolean save_current_state(T_save_state_T sst) {
        sst.save_msg_scroll = msg_scroll;
        sst.save_restart_edit = restart_edit;
        sst.save_msg_didout = msg_didout;
        sst.save_State = State;
        sst.save_insertmode = p_im[0];
        sst.save_finish_op = finish_op;
        sst.save_opcount = (int) opcount;
        sst.save_reg_executing = reg_executing;
        sst.save_pending_end_reg_executing = pending_end_reg_executing;
        msg_scroll = FALSE;
        restart_edit = 0;
        p_im[0] = FALSE;
        sst.save_script_version = current_sctx.sc_version;
        current_sctx.sc_version = 1;
        save_typeahead(sst.tabuf);
        return sst.tabuf.typebuf_valid;
    }

    private void restore_current_state(T_save_state_T sst) {
        restore_typeahead(sst.tabuf, false);
        msg_scroll = sst.save_msg_scroll;
        restart_edit = sst.save_restart_edit;
        p_im[0] = sst.save_insertmode;
        finish_op = sst.save_finish_op;
        opcount = (long) sst.save_opcount;
        reg_executing = sst.save_reg_executing;
        pending_end_reg_executing = sst.save_pending_end_reg_executing;
        msg_didout |= sst.save_msg_didout;
        current_sctx.sc_version = sst.save_script_version;
        State = sst.save_State;
    }

    private void ex_normal(S_exarg eap) {
        long t1 = 0;
        T_save_state_T save_state = new T_save_state_T();
        BytePtr arg = null;
        int l = 0;
        BytePtr p = null;
        if (ex_normal_lock > 0) {
            emsg(new BytePtr(e_not_allowed_here, 0));
            return;
        }
        if ((long) ex_normal_busy >= p_mmd[0]) {
            emsg(new BytePtr(e_recursive_use_of_normal_too_deep, 0));
            return;
        }
        int len = 0;
        for (p = eap.arg[0]; p.get() != NUL; p = p.add(1)) {
            for (l = utfc_ptr2len(p) - 1; l > 0; l--) {
                p = p.add(1);
                if (p.u() == 128) {
                    len += 2;
                }
            }
        }
        if (len > 0) {
            arg = BytePtr.alloc(musl_strlen(eap.arg[0]) + (long) len + 1L);
            len = 0;
            for (p = eap.arg[0]; p.get() != NUL; p = p.add(1)) {
                arg.set(len++, p.get());
                for (l = utfc_ptr2len(p) - 1; l > 0; l--) {
                    p = p.add(1);
                    arg.set(len++, p.get());
                    if (p.u() == 128) {
                        arg.set(len++, (byte) KS_SPECIAL);
                        arg.set(len++, (byte) 'X');
                    }
                }
                arg.set(len, (byte) NUL);
            }
        }
        ex_normal_busy++;
        if (save_current_state(save_state)) {
            do {
                if (eap.addr_count != 0) {
                    t1 = eap.line1;
                    eap.line1++;
                    curwin.w_cursor.lnum = t1;
                    curwin.w_cursor.col = 0;
                    check_cursor_moved(curwin);
                }
                exec_normal_cmd(arg != null ? arg : eap.arg[0], eap.forceit ? -1 : REMAP_YES, false);
            } while (eap.addr_count > 0 && eap.line1 <= eap.line2 && got_int == 0);
        }
        update_topline_cursor();
        restore_current_state(save_state);
        ex_normal_busy--;
    }

    private void exec_normal_cmd(BytePtr cmd, int remap, boolean silent) {
        ins_typebuf(cmd, remap, 0, true, silent ? 1 : 0);
        exec_normal(false, false, false);
    }

    private void exec_normal(boolean was_typed, boolean use_vpeekc, boolean may_use_terminal_loop) {
        S_oparg_S oa = new S_oparg_S();
        int c = 0;
        clear_oparg(oa);
        finish_op = FALSE;
        while ((!stuff_empty() || ((was_typed || !typebuf_typed()) && typebuf.tb_len > 0)
                || (use_vpeekc && (c = vpeekc()) != NUL && c != Ctrl_C)) && got_int == 0) {
            update_topline_cursor();
            normal_cmd(oa, true);
        }
    }

