    private boolean parse_pattern_and_range(T_pos_T incsearch_start, IntPtr search_delim, IntPtr skiplen,
            IntPtr patlen) {
        BytePtr t1 = null;
        int t2 = 0;
        BytePtr cmd;
        BytePtr p = null;
        BytePtr end;
        T_cmdmod_T dummy_cmdmod = new T_cmdmod_T();
        S_exarg ea = new S_exarg();
        long save_cursor_lnum;
        int save_cursor_col;
        int save_cursor_coladd;
        boolean delim_optional = false;
        int delim;
        boolean use_last_pat;
        int[] magic = new int[1];
        magic[0] = 0;
        BytePtr[] dummy = new BytePtr[1];
        skiplen.put(0);
        patlen.put(ccline.cmdlen);
        search_first_line = 0L;
        search_last_line = LONG_MAX;
        ea.zero();
        ea.line1 = 1L;
        ea.line2 = 1L;
        ea.cmd[0] = ccline.cmdbuff;
        ea.addr_type = ADDR_LINES;
        parse_command_modifiers(ea, new Ptr<BytePtr>(dummy, 0), dummy_cmdmod, true);
        cmd = skip_range(ea.cmd[0], true, null);
        if (vim_strchr(BytePtr.lit("sgvlu"), cmd.u()) == null) {
            return false;
        }
        for (p = cmd; ascii_isupper(p.u()) || ascii_islower(p.u()); p = p.add(1)) {
        }
        if (skipwhite(p).get() == NUL) {
            return false;
        }
        if (musl_strncmp(cmd, BytePtr.lit("substitute"), p.sub(cmd)) == 0
                || musl_strncmp(cmd, BytePtr.lit("smagic"), p.sub(cmd)) == 0
                || musl_strncmp(cmd, BytePtr.lit("snomagic"), p.sub(cmd) > 3L ? p.sub(cmd) : 3L) == 0
                || musl_strncmp(cmd, BytePtr.lit("vglobal"), p.sub(cmd)) == 0) {
            if (cmd.get() == 's' && cmd.at(1) == 'm') {
                magic_overruled = OPTION_MAGIC_ON;
            } else if (cmd.get() == 's' && cmd.at(1) == 'n') {
                magic_overruled = OPTION_MAGIC_OFF;
            }
        } else if (musl_strncmp(cmd, BytePtr.lit("sort"), p.sub(cmd) > 3L ? p.sub(cmd) : 3L) == 0
                || musl_strncmp(cmd, BytePtr.lit("uniq"), p.sub(cmd) > 3L ? p.sub(cmd) : 3L) == 0) {
            if (p.get() == '!') {
                p = skipwhite(p.add(1));
            }
            while (ascii_isupper((p = skipwhite(p)).u()) || ascii_islower((p = skipwhite(p)).u())) {
                p = p.add(1);
            }
            if (p.get() == NUL) {
                return false;
            }
        } else if (musl_strncmp(cmd, BytePtr.lit("vimgrep"), p.sub(cmd) > 3L ? p.sub(cmd) : 3L) == 0
                || musl_strncmp(cmd, BytePtr.lit("vimgrepadd"), p.sub(cmd) > 8L ? p.sub(cmd) : 8L) == 0
                || musl_strncmp(cmd, BytePtr.lit("lvimgrep"), p.sub(cmd) > 2L ? p.sub(cmd) : 2L) == 0
                || musl_strncmp(cmd, BytePtr.lit("lvimgrepadd"), p.sub(cmd) > 9L ? p.sub(cmd) : 9L) == 0
                || musl_strncmp(cmd, BytePtr.lit("global"), p.sub(cmd)) == 0) {
            if (p.get() == '!') {
                p = p.add(1);
                if (skipwhite(p).get() == NUL) {
                    return false;
                }
            }
            if (cmd.get() != 'g') {
                delim_optional = true;
            }
        } else {
            return false;
        }
        p = skipwhite(p);
        if (delim_optional && vim_isIDc(p.u())) {
            t2 = ' ';
        } else {
            t1 = p;
            p = p.add(1);
            t2 = t1.u();
        }
        delim = t2;
        search_delim.put(delim);
        end = skip_regexp_ex(p, delim, magic_isset(), null, null, new IntPtr(magic, 0));
        use_last_pat = BytePtr.eq(end, p) && end.u() == delim;
        if (BytePtr.eq(end, p) && !use_last_pat) {
            return false;
        }
        if (!use_last_pat) {
            byte c = end.get();
            boolean empty;
            end.put((byte) NUL);
            empty = empty_pattern_magic(p, end.sub(p), magic[0]);
            end.put(c);
            if (empty) {
                return false;
            }
        }
        skiplen.put((int) p.sub(ccline.cmdbuff));
        patlen.put((int) end.sub(p));
        save_cursor_lnum = curwin.w_cursor.lnum;
        save_cursor_col = curwin.w_cursor.col;
        save_cursor_coladd = curwin.w_cursor.coladd;
        curwin.w_cursor.set(incsearch_start);
        parse_cmd_address(ea, new Ptr<BytePtr>(dummy, 0), true);
        if (ea.addr_count > 0) {
            boolean reverse_match = ea.line2 < ea.line1;
            search_first_line = reverse_match ? ea.line2 : ea.line1;
            search_last_line = reverse_match ? ea.line1 : ea.line2;
        } else if (cmd.at(0) == 's' && cmd.at(1) != 'o') {
            search_first_line = search_last_line = curwin.w_cursor.lnum;
        }
        curwin.w_cursor.lnum = save_cursor_lnum;
        curwin.w_cursor.col = save_cursor_col;
        curwin.w_cursor.coladd = save_cursor_coladd;
        return true;
    }

    private boolean do_incsearch_highlighting(int firstc, IntPtr search_delim, T_incsearch_state_T is_state,
            IntPtr skiplen, IntPtr patlen) {
        boolean retval = false;
        skiplen.put(0);
        patlen.put(ccline.cmdlen);
        if (p_is[0] == 0 || cmd_silent) {
            return false;
        }
        search_first_line = 0L;
        search_last_line = LONG_MAX;
        if (firstc == '/' || firstc == '?') {
            search_delim.put(firstc);
            return true;
        }
        if (firstc != ':') {
            return false;
        }
        emsg_off++;
        retval = parse_pattern_and_range(is_state.search_start, search_delim, skiplen, patlen);
        emsg_off--;
        return retval;
    }

    private void finish_incsearch_highlighting(int gotesc, T_incsearch_state_T is_state, boolean call_update_screen) {
        if (!is_state.did_incsearch) {
            return;
        }
        is_state.did_incsearch = false;
        if (gotesc != 0) {
            curwin.w_cursor.set(is_state.save_cursor);
        } else {
            if (!(is_state.save_cursor.lnum == is_state.search_start.lnum
                    && is_state.save_cursor.col == is_state.search_start.col
                    && is_state.save_cursor.coladd == is_state.search_start.coladd)) {
                curwin.w_cursor.set(is_state.save_cursor);
                setpcmark();
            }
            curwin.w_cursor.set(is_state.search_start);
        }
        restore_viewstate(is_state.old_viewstate);
        highlight_match = false;
        search_first_line = 0L;
        search_last_line = LONG_MAX;
        magic_overruled = is_state.magic_overruled_save;
        validate_cursor();
        status_redraw_all();
        redraw_all_later(UPD_SOME_VALID);
        if (call_update_screen) {
            update_screen(UPD_SOME_VALID);
        }
    }

    private void may_do_incsearch_highlighting(int firstc, long count, T_incsearch_state_T is_state) {
        int[] skiplen = new int[1];
        int[] patlen = new int[1];
        int found;
        long end_pos_lnum;
        int end_pos_col;
        int end_pos_coladd;
        int next_char;
        boolean use_last_pat;
        boolean did_do_incsearch = is_state.did_incsearch;
        int[] search_delim = new int[1];
        save_last_search_pattern();
        if (!do_incsearch_highlighting(firstc, new IntPtr(search_delim, 0), is_state, new IntPtr(skiplen, 0),
                new IntPtr(patlen, 0))) {
            restore_last_search_pattern();
            finish_incsearch_highlighting(FALSE, is_state, true);
            if (did_do_incsearch && vpeekc() == NUL) {
                redrawcmd();
            }
            return;
        }
        if (char_avail()) {
            restore_last_search_pattern();
            is_state.incsearch_postponed = true;
            return;
        }
        is_state.incsearch_postponed = false;
        if (search_first_line == 0L) {
            curwin.w_cursor.set(is_state.search_start);
        } else if (search_first_line > curbuf.b_ml.ml_line_count) {
            curwin.w_cursor.lnum = curbuf.b_ml.ml_line_count;
            curwin.w_cursor.col = MAXCOL;
        } else {
            curwin.w_cursor.lnum = search_first_line;
            curwin.w_cursor.col = 0;
        }
        next_char = ccline.cmdbuff.u(skiplen[0] + patlen[0]);
        use_last_pat = patlen[0] == 0 && skiplen[0] > 0 && ccline.cmdbuff.u(skiplen[0] - 1) == next_char;
        if (patlen[0] == 0 && !use_last_pat) {
            found = 0;
            set_no_hlsearch(TRUE);
            redraw_all_later(UPD_SOME_VALID);
        } else {
            int search_flags = SEARCH_OPT + SEARCH_NOOF + SEARCH_PEEK;
            cursor_off();
            out_flush();
            emsg_off++;
            if (p_hls[0] == 0) {
                search_flags += SEARCH_KEEP;
            }
            if (search_first_line != 0L) {
                search_flags += SEARCH_START;
            }
            ccline.cmdbuff.set(skiplen[0] + patlen[0], (byte) NUL);
            found = do_search(null, firstc == ':' ? '/' : firstc, search_delim[0], ccline.cmdbuff.add(skiplen[0]),
                    (long) patlen[0], count, search_flags, null);
            ccline.cmdbuff.set(skiplen[0] + patlen[0], (byte) next_char);
            emsg_off--;
            if (curwin.w_cursor.lnum < search_first_line || curwin.w_cursor.lnum > search_last_line) {
                found = 0;
                curwin.w_cursor.set(is_state.search_start);
            }
            if (got_int != 0) {
                vpeekc();
                got_int = FALSE;
                found = 0;
            } else if (char_avail()) {
                is_state.incsearch_postponed = true;
            }
        }
        if (found != 0) {
            highlight_match = true;
        } else {
            highlight_match = false;
        }
        restore_viewstate(is_state.old_viewstate);
        changed_cline_bef_curs();
        update_topline();
        if (found != 0) {
            long save_pos_lnum = curwin.w_cursor.lnum;
            int save_pos_col = curwin.w_cursor.col;
            int save_pos_coladd = curwin.w_cursor.coladd;
            is_state.match_start.set(curwin.w_cursor);
            set_search_match(curwin.w_cursor);
            validate_cursor();
            end_pos_lnum = curwin.w_cursor.lnum;
            end_pos_col = curwin.w_cursor.col;
            end_pos_coladd = curwin.w_cursor.coladd;
            is_state.match_end.lnum = end_pos_lnum;
            is_state.match_end.col = end_pos_col;
            is_state.match_end.coladd = end_pos_coladd;
            curwin.w_cursor.lnum = save_pos_lnum;
            curwin.w_cursor.col = save_pos_col;
            curwin.w_cursor.coladd = save_pos_coladd;
        } else {
            end_pos_lnum = curwin.w_cursor.lnum;
            end_pos_col = curwin.w_cursor.col;
            end_pos_coladd = curwin.w_cursor.coladd;
        }
        if (!use_last_pat) {
            next_char = ccline.cmdbuff.u(skiplen[0] + patlen[0]);
            ccline.cmdbuff.set(skiplen[0] + patlen[0], (byte) NUL);
            if (empty_pattern(ccline.cmdbuff.add(skiplen[0]), (long) patlen[0], search_delim[0]) && no_hlsearch == 0) {
                redraw_all_later(UPD_SOME_VALID);
                set_no_hlsearch(TRUE);
            }
            ccline.cmdbuff.set(skiplen[0] + patlen[0], (byte) next_char);
        }
        validate_cursor();
        if (p_ru[0] != 0 && curwin.w_status_height > 0) {
            curwin.w_redr_status = true;
        }
        update_screen(UPD_SOME_VALID);
        highlight_match = false;
        restore_last_search_pattern();
        if (ccline.cmdbuff.at(skiplen[0] + patlen[0]) != NUL) {
            curwin.w_cursor.set(is_state.search_start);
        } else if (found != 0) {
            curwin.w_cursor.lnum = end_pos_lnum;
            curwin.w_cursor.col = end_pos_col;
            curwin.w_cursor.coladd = end_pos_coladd;
        }
        msg_starthere();
        redrawcmdline();
        is_state.did_incsearch = true;
    }

    private boolean may_adjust_incsearch_highlighting(int firstc, long count, T_incsearch_state_T is_state, int c) {
        T_parse_search_pattern_offset__out_T parse_search_pattern_offset__o = new T_parse_search_pattern_offset__out_T();
        int[] skiplen = new int[1];
        int[] patlen = new int[1];
        T_pos_T t = new T_pos_T();
        BytePtr pat;
        BytePtr dircp = null;
        BytePtr searchstr;
        BytePtr[] strcopy = new BytePtr[1];
        strcopy[0] = null;
        long searchstrlen;
        long patlen_s;
        S_soffset offset = new S_soffset();
        int search_flags = SEARCH_NOOF;
        int i;
        int[] search_delim = new int[1];
        save_last_search_pattern();
        if (!do_incsearch_highlighting(firstc, new IntPtr(search_delim, 0), is_state, new IntPtr(skiplen, 0),
                new IntPtr(patlen, 0))) {
            restore_last_search_pattern();
            return true;
        }
        if (patlen[0] == 0 && ccline.cmdbuff.at(skiplen[0]) == NUL) {
            restore_last_search_pattern();
            return false;
        }
        pat = ccline.cmdbuff.add(skiplen[0]);
        searchstr = pat;
        searchstrlen = (long) patlen[0];
        patlen_s = (long) (ccline.cmdlen - skiplen[0]);
        parse_search_pattern_offset__o = parse_search_pattern_offset(pat, patlen_s, search_delim[0], SEARCH_OPT,
                new Ptr<BytePtr>(strcopy, 0), searchstr, searchstrlen, dircp, offset);
        searchstr = parse_search_pattern_offset__o.searchstr;
        searchstrlen = parse_search_pattern_offset__o.searchstrlen;
        dircp = parse_search_pattern_offset__o.dircp;
        cursor_off();
        out_flush();
        if (c == Ctrl_G) {
            t.set(is_state.match_end);
            if (is_state.match_start.lnum != is_state.match_end.lnum ? is_state.match_start.lnum < is_state.match_end.lnum : (is_state.match_start.col != is_state.match_end.col ? is_state.match_start.col < is_state.match_end.col : is_state.match_start.coladd < is_state.match_end.coladd)) {
                decl(t);
            }
            search_flags += SEARCH_COL;
        } else {
            t.set(is_state.match_start);
        }
        if (p_hls[0] == 0) {
            search_flags += SEARCH_KEEP;
        }
        emsg_off++;
        i = searchit(curwin, curbuf, t, null, c == Ctrl_G ? FORWARD : -1, searchstr, searchstrlen, count, search_flags,
                RE_SEARCH, null);
        emsg_off--;
        if (dircp != null) {
            dircp.put((byte) search_delim[0]);
        }
        if (i != 0) {
            long match_start_lnum = is_state.match_start.lnum;
            int match_start_col = is_state.match_start.col;
            int match_start_coladd = is_state.match_start.coladd;
            long match_end_lnum = is_state.match_end.lnum;
            int match_end_col = is_state.match_end.col;
            int match_end_coladd = is_state.match_end.coladd;
            long off = offset.off;
            is_state.search_start.lnum = match_start_lnum;
            is_state.search_start.col = match_start_col;
            is_state.search_start.coladd = match_start_coladd;
            if (offset.line == 0 && (offset.end != 0 || off != 0L)) {
                if (offset.end != 0) {
                    is_state.search_start.lnum = match_end_lnum;
                    is_state.search_start.col = match_end_col;
                    is_state.search_start.coladd = match_end_coladd;
                    decl(is_state.search_start);
                }
                while (off > 0L) {
                    if (incl(is_state.search_start) == -1) {
                        break;
                    }
                    off--;
                }
                while (off < 0L) {
                    if (decl(is_state.search_start) == -1) {
                        break;
                    }
                    off++;
                }
            }
            is_state.match_end.set(t);
            is_state.match_start.set(t);
            if (c == Ctrl_T && firstc != '?') {
                is_state.search_start.set(t);
                decl(is_state.search_start);
            } else if (c == Ctrl_G && firstc == '?') {
                is_state.search_start.set(t);
                incl(is_state.search_start);
            }
            if ((t.lnum != is_state.search_start.lnum ? t.lnum < is_state.search_start.lnum : (t.col != is_state.search_start.col ? t.col < is_state.search_start.col : t.coladd < is_state.search_start.coladd)) && c == Ctrl_G) {
                is_state.search_start.set(t);
                if (firstc == '?') {
                    incl(is_state.search_start);
                } else {
                    decl(is_state.search_start);
                }
            }
            set_search_match(is_state.match_end);
            curwin.w_cursor.set(is_state.match_start);
            changed_cline_bef_curs();
            update_topline();
            validate_cursor();
            highlight_match = true;
            save_viewstate(is_state.old_viewstate);
            update_screen(UPD_NOT_VALID);
            highlight_match = false;
            redrawcmdline();
            curwin.w_cursor.set(is_state.match_end);
        } else {
            vim_beep(BO_ERROR);
        }
        restore_last_search_pattern();
        return false;
    }

    private T_may_add_char_to_search__out_T may_add_char_to_search(int firstc, int c, T_incsearch_state_T is_state) {
        T_may_add_char_to_search__out_T out__ = new T_may_add_char_to_search__out_T();
        int[] skiplen = new int[1];
        int[] patlen = new int[1];
        int[] search_delim = new int[1];
        save_last_search_pattern();
        if (!do_incsearch_highlighting(firstc, new IntPtr(search_delim, 0), is_state, new IntPtr(skiplen, 0),
                new IntPtr(patlen, 0))) {
            restore_last_search_pattern();
            out__.r__ = false;
            out__.c = c;
            return out__;
        }
        restore_last_search_pattern();
        if (is_state.did_incsearch) {
            curwin.w_cursor.set(is_state.match_end);
            c = gchar_cursor();
            if (c != NUL) {
                if (p_ic[0] != 0 && p_scs[0] != 0 && !pat_has_uppercase(ccline.cmdbuff.add(skiplen[0]))) {
                    c = vim_tolower(c);
                }
                if (c == search_delim[0]
                        || vim_strchr(magic_isset() != 0 ? BytePtr.lit("\\~^$.*[") : BytePtr.lit("\\^$"), c) != null) {
                    stuffcharReadbuff(c);
                    c = '\\';
                }
                if (utf_char2len(c) != utfc_ptr2len(ml_get_cursor())) {
                    int save_c = c;
                    while (utf_char2len(c) != utfc_ptr2len(ml_get_cursor())) {
                        curwin.w_cursor.col += utf_char2len(c);
                        c = gchar_cursor();
                        stuffcharReadbuff(c);
                    }
                    c = save_c;
                }
                out__.r__ = false;
                out__.c = c;
                return out__;
            }
        }
        out__.r__ = true;
        out__.c = c;
        return out__;
    }

    private void cmdline_init() {
        ccline.zero();
    }

    private int cmdline_handle_ctrl_bsl(IntPtr gotesc) {
        int c;
        no_mapping++;
        allow_keys++;
        c = plain_vgetc();
        no_mapping--;
        allow_keys--;
        if (c != Ctrl_N && c != Ctrl_G && (c != 'e' || (ccline.cmdfirstc == '=' && KeyTyped))) {
            vungetc(c);
            return PROCESS_NEXT_KEY;
        }
        if (c == Ctrl_G && p_im[0] != 0 && restart_edit == 0) {
            restart_edit = 'a';
        }
        gotesc.put(TRUE);
        return GOTO_NORMAL_MODE;
    }

    private int cmdline_erase_chars(int c, int indent, T_incsearch_state_T isp) {
        int i;
        int j;
        if (c == K_KDEL) {
            c = K_DEL;
        }
        if (c == K_DEL && ccline.cmdpos != ccline.cmdlen) {
            ccline.cmdpos++;
        }
        if (c == K_DEL) {
            ccline.cmdpos += mb_off_next(ccline.cmdbuff, ccline.cmdbuff.add(ccline.cmdpos));
        }
        if (ccline.cmdpos > 0) {
            BytePtr p;
            j = ccline.cmdpos;
            p = ccline.cmdbuff.add(j);
            p = mb_prevptr(ccline.cmdbuff, p);
            if (c == Ctrl_W) {
                while (p.gt(ccline.cmdbuff) && vim_isspace(p.u())) {
                    p = mb_prevptr(ccline.cmdbuff, p);
                }
                i = mb_get_class(p);
                while (p.gt(ccline.cmdbuff) && mb_get_class(p) == i) {
                    p = mb_prevptr(ccline.cmdbuff, p);
                }
                if (mb_get_class(p) != i) {
                    p = p.add(utfc_ptr2len(p));
                }
            }
            ccline.cmdpos = (int) p.sub(ccline.cmdbuff);
            ccline.cmdlen -= j - ccline.cmdpos;
            i = ccline.cmdpos;
            while (i < ccline.cmdlen) {
                ccline.cmdbuff.set(i++, ccline.cmdbuff.at(j++));
            }
            ccline.cmdbuff.set(ccline.cmdlen, (byte) NUL);
            if (ccline.cmdlen == 0) {
                isp.search_start.set(isp.save_cursor);
                isp.old_viewstate.set(isp.init_viewstate);
            }
            redrawcmd();
        } else if (ccline.cmdlen == 0 && c != Ctrl_W && ccline.cmdprompt == null && indent == 0) {
            dealloc_cmdbuff();
            if (!cmd_silent) {
                msg_col = 0;
                msg_putchar(' ');
            }
            isp.search_start.set(isp.save_cursor);
            redraw_cmdline = TRUE;
            return GOTO_NORMAL_MODE;
        }
        return CMDLINE_CHANGED;
    }

    private int cmdline_insert_reg(IntPtr gotesc) {
        int i;
        int c = 0;
        boolean literally = false;
        putcmdline('"', TRUE);
        no_mapping++;
        allow_keys++;
        i = c = plain_vgetc();
        if (i == Ctrl_O) {
            i = Ctrl_R;
        }
        if (i == Ctrl_R) {
            c = plain_vgetc();
        }
        extra_char = NUL;
        no_mapping--;
        allow_keys--;
        if (c != ESC) {
            literally = i == Ctrl_R;
            cmdline_paste(c, literally, false);
            KeyTyped = false;
        }
        redrawcmd();
        return literally ? CMDLINE_CHANGED : CMDLINE_NOT_CHANGED;
    }

    private T_cmdline_browse_history__out_T cmdline_browse_history(int c, int firstc, BytePtr curcmdstr,
            long curcmdstrlen, int histype, int hiscnt_p, S_expand xp) {
        T_cmdline_browse_history__out_T out__ = new T_cmdline_browse_history__out_T();
        int orig_hiscnt = 0;
        int hiscnt = orig_hiscnt = hiscnt_p;
        BytePtr lookfor = curcmdstr;
        long lookforlen = curcmdstrlen;
        int res = 0;
        if (get_hislen() == 0 || firstc == NUL) {
            out__.r__ = CMDLINE_NOT_CHANGED;
            out__.curcmdstr = curcmdstr;
            out__.curcmdstrlen = curcmdstrlen;
            out__.hiscnt_p = hiscnt_p;
            return out__;
        }
        if (lookfor == null) {
            lookfor = vim_strnsave(ccline.cmdbuff, (long) ccline.cmdlen);
            lookfor.set(ccline.cmdpos, (byte) NUL);
            lookforlen = (long) ccline.cmdpos;
        }
        for (;;) {
            if (c == K_UP || c == K_S_UP || c == Ctrl_P || c == K_PAGEUP || c == K_KPAGEUP) {
                if (hiscnt == get_hislen()) {
                    hiscnt = get_hisidx(histype).get();
                } else if (hiscnt == 0 && get_hisidx(histype).get() != get_hislen() - 1) {
                    hiscnt = get_hislen() - 1;
                } else if (hiscnt != get_hisidx(histype).get() + 1) {
                    hiscnt--;
                } else {
                    hiscnt = orig_hiscnt;
                    break;
                }
            } else {
                if (hiscnt == get_hisidx(histype).get()) {
                    hiscnt = get_hislen();
                    break;
                }
                if (hiscnt == get_hislen()) {
                    break;
                }
                if (hiscnt == get_hislen() - 1) {
                    hiscnt = 0;
                } else {
                    hiscnt++;
                }
            }
            if (hiscnt < 0 || get_histentry(histype).at(hiscnt).hisstr == null) {
                hiscnt = orig_hiscnt;
                break;
            }
            if ((c != K_UP && c != K_DOWN) || hiscnt == orig_hiscnt
                    || musl_strncmp(get_histentry(histype).at(hiscnt).hisstr, lookfor, lookforlen) == 0) {
                break;
            }
        }
        if (hiscnt != orig_hiscnt) {
            BytePtr p;
            long plen;
            int old_firstc = 0;
            dealloc_cmdbuff();
            xp.xp_context = EXPAND_NOTHING;
            if (hiscnt == get_hislen()) {
                p = lookfor;
                plen = lookforlen;
            } else {
                p = get_histentry(histype).at(hiscnt).hisstr;
                plen = get_histentry(histype).at(hiscnt).hisstrlen;
            }
            if (histype == HIST_SEARCH && !BytePtr.eq(p, lookfor) && (old_firstc = p.u((int) (plen + 1L))) != firstc) {
                int i = 0;
                int j = 0;
                long len = 0;
                for (i = 0; i <= 1; i++) {
                    len = 0L;
                    for (j = 0; p.at(j) != NUL; j++) {
                        if (p.u(j) == old_firstc && (j == 0 || p.at(j - 1) != '\\')) {
                            if (i > 0) {
                                ccline.cmdbuff.set((int) len, (byte) firstc);
                            }
                        } else {
                            if (p.u(j) == firstc && (j == 0 || p.at(j - 1) != '\\')) {
                                if (i > 0) {
                                    ccline.cmdbuff.set((int) len, (byte) '\\');
                                }
                                len++;
                            }
                            if (i > 0) {
                                ccline.cmdbuff.set((int) len, p.at(j));
                            }
                        }
                        len++;
                    }
                    if (i == 0) {
                        alloc_cmdbuff(len);
                        if (ccline.cmdbuff == null) {
                            res = GOTO_NORMAL_MODE;
                            curcmdstr = lookfor;
                            curcmdstrlen = lookforlen;
                            hiscnt_p = hiscnt;
                            out__.r__ = res;
                            out__.curcmdstr = curcmdstr;
                            out__.curcmdstrlen = curcmdstrlen;
                            out__.hiscnt_p = hiscnt_p;
                            return out__;
                        }
                    }
                }
                ccline.cmdbuff.set((int) len, (byte) NUL);
                ccline.cmdlen = (int) len;
                ccline.cmdpos = ccline.cmdlen;
            } else {
                alloc_cmdbuff(plen);
                if (ccline.cmdbuff == null) {
                    res = GOTO_NORMAL_MODE;
                    curcmdstr = lookfor;
                    curcmdstrlen = lookforlen;
                    hiscnt_p = hiscnt;
                    out__.r__ = res;
                    out__.curcmdstr = curcmdstr;
                    out__.curcmdstrlen = curcmdstrlen;
                    out__.hiscnt_p = hiscnt_p;
                    return out__;
                }
                musl_strcpy(ccline.cmdbuff, p);
                ccline.cmdlen = (int) plen;
                ccline.cmdpos = ccline.cmdlen;
            }
            redrawcmd();
            res = CMDLINE_CHANGED;
            curcmdstr = lookfor;
            curcmdstrlen = lookforlen;
            hiscnt_p = hiscnt;
            out__.r__ = res;
            out__.curcmdstr = curcmdstr;
            out__.curcmdstrlen = curcmdstrlen;
            out__.hiscnt_p = hiscnt_p;
            return out__;
        }
        beep_flush();
        res = CMDLINE_NOT_CHANGED;
        curcmdstr = lookfor;
        curcmdstrlen = lookforlen;
        hiscnt_p = hiscnt;
        out__.r__ = res;
        out__.curcmdstr = curcmdstr;
        out__.curcmdstrlen = curcmdstrlen;
        out__.hiscnt_p = hiscnt_p;
        return out__;
    }

    private boolean init_ccline(int firstc, int indent) {
        ccline.overstrike = false;
        ccline.cmdfirstc = firstc == '@' ? 0 : firstc;
        ccline.cmdindent = firstc > 0 ? indent : 0;
        alloc_cmdbuff((long) (indent + 50));
        ccline.cmdpos = 0;
        ccline.cmdlen = ccline.cmdpos;
        if (ccline.cmdbuff == null) {
            ccline.cmdbufflen = 0;
            return false;
        }
        ccline.cmdbuff.set(0, (byte) NUL);
        sb_text_start_cmdline();
        if (firstc <= 0) {
            Rt.memset(ccline.cmdbuff, ' ', (long) indent);
            ccline.cmdbuff.set(indent, (byte) NUL);
            ccline.cmdpos = indent;
            ccline.cmdspos = indent;
            ccline.cmdlen = indent;
        }
        return true;
    }

    private BytePtr getcmdline(int firstc, long count, int indent, int do_concat) {
        return getcmdline_int(firstc, count, indent, true);
    }

    @SuppressWarnings("fallthrough")
    private BytePtr getcmdline_int(int firstc, long count, int indent, boolean clear_ccline) {
        T_cmdline_browse_history__out_T cmdline_browse_history__o = new T_cmdline_browse_history__out_T();
        T_may_add_char_to_search__out_T may_add_char_to_search__o = new T_may_add_char_to_search__out_T();
        int c = 0;
        int i = 0;
        int j = 0;
        int[] gotesc = new int[1];
        boolean do_abbr = false;
        BytePtr lookfor = null;
        long lookforlen = 0;
        int hiscnt = 0;
        int histype = 0;
        T_incsearch_state_T is_state = new T_incsearch_state_T();
        int res = 0;
        int save_msg_scroll = 0;
        int save_State = 0;
        boolean some_key_typed = false;
        S_expand xpc = new S_expand();
        T_cmdline_info_T save_ccline = new T_cmdline_info_T();
        boolean did_save_ccline = false;
        int wild_type = 0;
        BytePtr prev_cmdbuff = null;
        boolean trigger_cmdlinechanged = false;
        int prev_cmdpos = 0;
        int clen = 0;
        int cc_count = 0;
        BytePtr p = null;
        c = 0;
        gotesc[0] = FALSE;
        lookfor = null;
        lookforlen = 0L;
        save_msg_scroll = msg_scroll;
        save_State = State;
        some_key_typed = false;
        did_save_ccline = false;
        wild_type = 0;
        prev_cmdbuff = null;
        getcmdline_int_depth++;
        if (ccline.cmdbuff != null) {
            save_cmdline(save_ccline);
            did_save_ccline = true;
        }
        if (clear_ccline) {
            ccline.zero();
        }
        init_incsearch_state(is_state);
        c1: {
            if (!init_ccline(firstc, indent)) {
                break c1;
            }
            if (getcmdline_int_depth == 50) {
                emsg(new BytePtr(e_command_too_recursive, 0));
                break c1;
            }
            ExpandInit(xpc);
            ccline.xpc = xpc;
            clear_cmdline_orig();
            if (!cmd_silent) {
                i = msg_scrolled;
                msg_scrolled = 0;
                gotocmdline(true);
                msg_scrolled += i;
                redrawcmdprompt();
                set_cmdspos();
            }
            xpc.xp_context = EXPAND_NOTHING;
            xpc.xp_backslash = XP_BS_NONE;
            xpc.xp_shell = false;
            msg_scroll = FALSE;
            State = MODE_CMDLINE;
            term_enter();
            init_history();
            hiscnt = get_hislen();
            histype = hist_char2type(firstc);
            if (did_emsg != 0) {
                redrawcmd();
            }
            did_emsg = FALSE;
            got_int = FALSE;
            L_returncmd: {
                for (;;) {
                    trigger_cmdlinechanged = true;
                    prev_cmdpos = ccline.cmdpos;
                    prev_cmdbuff = null;
                    quit_more = false;
                    did_emsg = FALSE;
                    if (ex_normal_busy == 0 && stuff_empty() && typebuf.tb_len == 0) {
                        some_key_typed = true;
                    }
                    may_trigger_safestate(true);
                    if (ccline.cmdbuff != null) {
                        prev_cmdbuff = vim_strsave(ccline.cmdbuff);
                    }
                    do {
                        cursorcmd();
                        c = safe_vgetc();
                    } while (c == K_IGNORE || c == K_NOP);
                    ccline.cmdbuff_replaced = false;
                    L_cmdline_changed: {
                        if (c == K_COMMAND || c == K_SCRIPT_COMMAND) {
                            clen = ccline.cmdlen;
                            cc_count = aucmd_cmdline_changed_count;
                            if (do_cmdkey_command(c, DOCMD_NOWAIT)) {
                                if (clen == ccline.cmdlen || cc_count != aucmd_cmdline_changed_count) {
                                    trigger_cmdlinechanged = false;
                                }
                                break L_cmdline_changed;
                            }
                        }
                        if (KeyTyped) {
                            some_key_typed = true;
                        }
                        if ((c == Ctrl_C || c == intr_char) && global_busy == 0) {
                            got_int = FALSE;
                        }
                        if (lookfor != null && c != K_S_DOWN && c != K_S_UP && c != K_DOWN && c != K_UP
                                && c != K_PAGEDOWN && c != K_PAGEUP && c != K_KPAGEDOWN && c != K_KPAGEUP
                                && c != K_LEFT && c != K_RIGHT
                                && (xpc.xp_numfiles > 0 || (c != Ctrl_P && c != Ctrl_N))) {
                            lookfor = null;
                            lookforlen = 0L;
                        }
                        L_cmdline_not_changed: {
                            if (c == Ctrl_BSL) {
                                res = cmdline_handle_ctrl_bsl(new IntPtr(gotesc, 0));
                                if (res == CMDLINE_CHANGED) {
                                    break L_cmdline_changed;
                                } else if (res == CMDLINE_NOT_CHANGED) {
                                    break L_cmdline_not_changed;
                                } else if (res == GOTO_NORMAL_MODE) {
                                    break;
                                }
                                c = Ctrl_BSL;
                            }
                            if (c == '\n' || c == '\r' || c == K_KENTER
                                    || (c == ESC && (!KeyTyped || vim_strchr(p_cpo[0], CPO_ESC) != null))) {
                                gotesc[0] = FALSE;
                                if (!cmd_silent) {
                                    windgoto(msg_row, cmdline_col_off);
                                    out_flush();
                                }
                                break;
                            }
                            gotesc[0] = FALSE;
                            if (c == NUL || c == -(KS_ZERO + ('X' << 8))) {
                                c = NL;
                            }
                            do_abbr = true;
                            if (wild_type == WILD_CANCEL || wild_type == WILD_APPLY) {
                                if (KeyTyped || vpeekc() == NUL) {
                                    may_do_incsearch_highlighting(firstc, count, is_state);
                                }
                                wild_type = 0;
                                break L_cmdline_not_changed;
                            }
                            switch (c) {
                                case K_BS:
                                case Ctrl_H:
                                case K_DEL:
                                case K_KDEL:
                                case Ctrl_W:
                                    res = cmdline_erase_chars(c, indent, is_state);
                                    if (res == CMDLINE_NOT_CHANGED) {
                                        break L_cmdline_not_changed;
                                    } else if (res == GOTO_NORMAL_MODE) {
                                        break L_returncmd;
                                    }
                                    break L_cmdline_changed;
                                case K_INS:
                                case K_KINS:
                                    ccline.overstrike = !ccline.overstrike;
                                    status_redraw_curbuf();
                                    redraw_statuslines();
                                    break L_cmdline_not_changed;
                                case Ctrl_HAT:
                                    break L_cmdline_not_changed;
                                case Ctrl_U:
                                    j = ccline.cmdpos;
                                    ccline.cmdlen -= j;
                                    ccline.cmdpos = 0;
                                    i = ccline.cmdpos;
                                    while (i < ccline.cmdlen) {
                                        ccline.cmdbuff.set(i++, ccline.cmdbuff.at(j++));
                                    }
                                    ccline.cmdbuff.set(ccline.cmdlen, (byte) NUL);
                                    if (ccline.cmdlen == 0) {
                                        is_state.search_start.set(is_state.save_cursor);
                                    }
                                    redrawcmd();
                                    break L_cmdline_changed;
                                case ESC:
                                case Ctrl_C:
                                    gotesc[0] = TRUE;
                                    break L_returncmd;
                                case Ctrl_R:
                                    res = cmdline_insert_reg(new IntPtr(gotesc, 0));
                                    if (res == GOTO_NORMAL_MODE) {
                                        break L_returncmd;
                                    }
                                    if (res == CMDLINE_CHANGED) {
                                        break L_cmdline_changed;
                                    }
                                    break L_cmdline_not_changed;
                                case K_RIGHT:
                                case K_TC_PCT_i:
                                case K_C_RIGHT:
                                    do {
                                        if (ccline.cmdpos >= ccline.cmdlen) {
                                            break;
                                        }
                                        i = cmdline_charsize(ccline.cmdpos);
                                        if (KeyTyped && (long) (ccline.cmdspos + i) >= (long) cmdline_width * Rows[0]) {
                                            break;
                                        }
                                        ccline.cmdspos += i;
                                        ccline.cmdpos += utfc_ptr2len(ccline.cmdbuff.add(ccline.cmdpos));
                                    } while ((c == K_TC_PCT_i || c == K_C_RIGHT
                                            || (mod_mask[0] & (MOD_MASK_SHIFT | MOD_MASK_CTRL)) != 0)
                                            && ccline.cmdbuff.at(ccline.cmdpos) != ' ');
                                    set_cmdspos_cursor();
                                    break L_cmdline_not_changed;
                                case K_LEFT:
                                case K_TC_HASH_4:
                                case K_C_LEFT:
                                    if (ccline.cmdpos == 0) {
                                        break L_cmdline_not_changed;
                                    }
                                    do {
                                        ccline.cmdpos--;
                                        ccline.cmdpos -= utf_head_off(ccline.cmdbuff,
                                                ccline.cmdbuff.add(ccline.cmdpos));
                                        ccline.cmdspos -= cmdline_charsize(ccline.cmdpos);
                                    } while (ccline.cmdpos > 0
                                            && (c == K_TC_HASH_4 || c == K_C_LEFT
                                            || (mod_mask[0] & (MOD_MASK_SHIFT | MOD_MASK_CTRL)) != 0)
                                            && ccline.cmdbuff.at(ccline.cmdpos - 1) != ' ');
                                    set_cmdspos_cursor();
                                    break L_cmdline_not_changed;
                                case K_IGNORE:
                                    break L_cmdline_not_changed;
                                case -(KS_SELECT + ('X' << 8)):
                                    break L_cmdline_not_changed;
                                case Ctrl_B:
                                case K_HOME:
                                case K_KHOME:
                                case K_TC_HASH_2:
                                case K_C_HOME:
                                    ccline.cmdpos = 0;
                                    set_cmdspos();
                                    break L_cmdline_not_changed;
                                case Ctrl_E:
                                case K_END:
                                case K_KEND:
                                case K_TC_STAR_7:
                                case K_C_END:
                                    ccline.cmdpos = ccline.cmdlen;
                                    set_cmdspos_cursor();
                                    break L_cmdline_not_changed;
                                case Ctrl_L:
                                    may_add_char_to_search__o = may_add_char_to_search(firstc, c, is_state);
                                    c = may_add_char_to_search__o.c;
                                    if (may_add_char_to_search__o.r__) {
                                        break L_cmdline_not_changed;
                                    }
                                    break;
                                case Ctrl_N:
                                case Ctrl_P:
                                // fall through
                                case K_UP:
                                case K_DOWN:
                                case K_S_UP:
                                case K_S_DOWN:
                                case K_PAGEUP:
                                case K_KPAGEUP:
                                case K_PAGEDOWN:
                                case K_KPAGEDOWN:
                                    cmdline_browse_history__o = cmdline_browse_history(c, firstc, lookfor, lookforlen,
                                            histype, hiscnt, xpc);
                                    lookfor = cmdline_browse_history__o.curcmdstr;
                                    res = cmdline_browse_history__o.r__;
                                    if (res == CMDLINE_CHANGED) {
                                        break L_cmdline_changed;
                                    } else if (res == GOTO_NORMAL_MODE) {
                                        break L_returncmd;
                                    }
                                    break L_cmdline_not_changed;
                                case Ctrl_G:
                                case Ctrl_T:
                                    if (!may_adjust_incsearch_highlighting(firstc, count, is_state, c)) {
                                        break L_cmdline_not_changed;
                                    }
                                    break;
                                case Ctrl_V:
                                case Ctrl_Q:
                                    putcmdline('^', TRUE);
                                    c = get_literal(mod_mask[0] & MOD_MASK_SHIFT);
                                    do_abbr = false;
                                    extra_char = NUL;
                                    if (utf_iscomposing(c) && !cmd_silent) {
                                        draw_cmdline(ccline.cmdpos, ccline.cmdlen - ccline.cmdpos);
                                        msg_putchar(' ');
                                        cursorcmd();
                                    }
                                    break;
                                case K_PASTESTART:
                                    bracketed_paste(PASTE_CMDLINE, false, null);
                                    break L_cmdline_changed;
                                default:
                                    if (c == intr_char) {
                                        gotesc[0] = TRUE;
                                        break L_returncmd;
                                    }
                                    if (!(c < 0)) {
                                        mod_mask[0] = 0;
                                    }
                                    break;
                            }
                            if (do_abbr && (c < 0 || !vim_iswordc(c)) && c == Ctrl_RSB) {
                                break L_cmdline_changed;
                            }
                            if (c < 0 || mod_mask[0] != 0) {
                                put_on_cmdline(get_special_key_name(c, mod_mask[0]), -1, true);
                            } else {
                                j = utf_char2bytes(c, IObuff);
                                IObuff.set(j, (byte) NUL);
                                put_on_cmdline(IObuff, j, true);
                            }
                            break L_cmdline_changed;
                        }
                        if (ccline.cmdpos != prev_cmdpos) {
                            prev_cmdpos = ccline.cmdpos;
                        }
                        if (!is_state.incsearch_postponed) {
                            continue;
                        }
                    }
                    if (KeyTyped || vpeekc() == NUL) {
                        may_do_incsearch_highlighting(firstc, count, is_state);
                    }
                    if (trigger_cmdlinechanged
                            && (ccline.cmdpos != prev_cmdpos
                            || (prev_cmdbuff != null && musl_strcmp(prev_cmdbuff, ccline.cmdbuff) != 0))) {
                    }
                }
            }
            ExpandCleanup(xpc);
            ccline.xpc = null;
            clear_cmdline_orig();
            finish_incsearch_highlighting(gotesc[0], is_state, false);
            if (ccline.cmdbuff != null) {
                if (ccline.cmdlen != 0 && firstc != NUL && (some_key_typed || histype == HIST_SEARCH)) {
                    add_to_history(histype, ccline.cmdbuff, (long) ccline.cmdlen, true,
                            histype == HIST_SEARCH ? firstc : NUL);
                    if (firstc == ':') {
                        new_last_cmdline = vim_strnsave(ccline.cmdbuff, (long) ccline.cmdlen);
                    }
                }
                if (gotesc[0] != 0) {
                    abandon_cmdline();
                }
            }
            msg_check();
            msg_scroll = save_msg_scroll;
            if (some_key_typed) {
                need_wait_return = FALSE;
            }
            State = save_State;
            sb_text_end_cmdline();
        }
        p = ccline.cmdbuff;
        getcmdline_int_depth--;
        if (did_save_ccline) {
            restore_cmdline(save_ccline);
        } else {
            ccline.cmdbuff = null;
        }
        return p;
    }

    private boolean text_locked() {
        return textlock != 0;
    }

    private void text_locked_msg() {
        emsg(get_text_locked_msg());
    }

    private BytePtr get_text_locked_msg() {
        return new BytePtr(e_not_allowed_to_change_text_or_change_window, 0);
    }

    private boolean curbuf_locked() {
        if (curbuf_lock > 0) {
            emsg(new BytePtr(e_not_allowed_to_edit_another_buffer_now, 0));
            return true;
        }
        return allbuf_locked();
    }

    private boolean allbuf_locked() {
        if (allbuf_lock > 0) {
            emsg(new BytePtr(e_not_allowed_to_change_buffer_information_now, 0));
            return true;
        }
        return false;
    }

    private int cmdline_charsize(int idx) {
        return ptr2cells(ccline.cmdbuff.add(idx));
    }

    private void set_cmdspos() {
        if (ccline.cmdfirstc != NUL) {
            ccline.cmdspos = 1 + ccline.cmdindent;
        } else {
            ccline.cmdspos = 0 + ccline.cmdindent;
        }
    }

    private void set_cmdspos_cursor() {
        int i = 0;
        int m;
        int c = 0;
        set_cmdspos();
        if (KeyTyped) {
            m = (int) ((long) cmdline_width * Rows[0]);
            if (m < 0) {
                m = MAXCOL;
            }
        } else {
            m = MAXCOL;
        }
        for (i = 0; i < ccline.cmdlen && i < ccline.cmdpos; i++) {
            c = cmdline_charsize(i);
            correct_cmdspos(i, c);
            ccline.cmdspos += c;
            if (ccline.cmdspos >= m) {
                ccline.cmdspos -= c;
                break;
            }
            i += utfc_ptr2len(ccline.cmdbuff.add(i)) - 1;
        }
    }

    private void correct_cmdspos(int idx, int cells) {
        if (utfc_ptr2len(ccline.cmdbuff.add(idx)) > 1 && utf_ptr2cells(ccline.cmdbuff.add(idx)) > 1
                && ccline.cmdspos % cmdline_width + cells > cmdline_width) {
            ccline.cmdspos++;
        }
    }

    private BytePtr getexline(int c, int indent, int options) {
        if (exec_from_reg != 0 && vpeekc() == ':') {
            vgetc();
        }
        return getcmdline(c, 1L, indent, options);
    }

    private void dealloc_cmdbuff() {
        ccline.cmdbuff = null;
        ccline.cmdbufflen = 0;
        ccline.cmdlen = ccline.cmdbufflen;
    }

    private void alloc_cmdbuff(long len) {
        if (Long.compareUnsigned(len, 80L) < 0) {
            len = 100L;
        } else {
            len += 20L;
        }
        ccline.cmdbuff = BytePtr.alloc(len);
        ccline.cmdbufflen = (int) len;
    }

    private boolean realloc_cmdbuff(int len) {
        BytePtr p;
        int plen;
        if (len < ccline.cmdbufflen) {
            return true;
        }
        p = ccline.cmdbuff;
        plen = ccline.cmdbufflen;
        alloc_cmdbuff((long) len);
        if (ccline.cmdbuff == null) {
            ccline.cmdbuff = p;
            ccline.cmdbufflen = plen;
            return false;
        }
        Rt.memmove(ccline.cmdbuff, p, (long) ccline.cmdlen);
        ccline.cmdbuff.set(ccline.cmdlen, (byte) NUL);
        if (ccline.xpc != null && ccline.xpc.xp_pattern != null && ccline.xpc.xp_context != EXPAND_NOTHING
                && ccline.xpc.xp_context != -2) {
            int i = (int) ccline.xpc.xp_pattern.sub(p);
            if (i >= 0 && i <= ccline.cmdlen) {
                ccline.xpc.xp_pattern = ccline.cmdbuff.add(i);
            }
        }
        return true;
    }

    private void draw_cmdline(int start, int len) {
        msg_outtrans_len(ccline.cmdbuff.add(start), len);
    }

    private void putcmdline(int c, int shift) {
        if (cmd_silent) {
            return;
        }
        msg_no_more = true;
        msg_putchar(c);
        if (shift != 0) {
            draw_cmdline(ccline.cmdpos, ccline.cmdlen - ccline.cmdpos);
        }
        msg_no_more = false;
        cursorcmd();
        extra_char = c;
        extra_char_shift = shift;
    }

    private void unputcmdline() {
        if (cmd_silent) {
            return;
        }
        msg_no_more = true;
        if (ccline.cmdlen == ccline.cmdpos) {
            msg_putchar(' ');
        } else {
            draw_cmdline(ccline.cmdpos, utfc_ptr2len(ccline.cmdbuff.add(ccline.cmdpos)));
        }
        msg_no_more = false;
        cursorcmd();
        extra_char = NUL;
    }

    private boolean put_on_cmdline(BytePtr str, int len, boolean redraw) {
        boolean retval;
        int i = 0;
        int m;
        int c;
        if (len < 0) {
            len = (int) musl_strlen(str);
        }
        if (ccline.cmdlen + len + 1 >= ccline.cmdbufflen) {
            retval = realloc_cmdbuff(ccline.cmdlen + len + 1);
        } else {
            retval = true;
        }
        if ((retval ? 1 : 0) == OK) {
            if (!ccline.overstrike) {
                Rt.memmove(ccline.cmdbuff.add(ccline.cmdpos).add(len), ccline.cmdbuff.add(ccline.cmdpos),
                        (long) (ccline.cmdlen - ccline.cmdpos));
                ccline.cmdlen += len;
            } else {
                m = 0;
                for (i = 0; i < len; i += utfc_ptr2len(str.add(i))) {
                    m++;
                }
                for (i = ccline.cmdpos; i < ccline.cmdlen && m > 0; i += utfc_ptr2len(ccline.cmdbuff.add(i))) {
                    m--;
                }
                if (i < ccline.cmdlen) {
                    Rt.memmove(ccline.cmdbuff.add(ccline.cmdpos).add(len), ccline.cmdbuff.add(i),
                            (long) (ccline.cmdlen - i));
                    ccline.cmdlen += ccline.cmdpos + len - i;
                } else {
                    ccline.cmdlen = ccline.cmdpos + len;
                }
            }
            Rt.memmove(ccline.cmdbuff.add(ccline.cmdpos), str, (long) len);
            ccline.cmdbuff.set(ccline.cmdlen, (byte) NUL);
            i = 0;
            c = utf_ptr2char(ccline.cmdbuff.add(ccline.cmdpos));
            while (ccline.cmdpos > 0 && utf_iscomposing(c)) {
                i = utf_head_off(ccline.cmdbuff, ccline.cmdbuff.add(ccline.cmdpos).add(-1)) + 1;
                ccline.cmdpos -= i;
                len += i;
                c = utf_ptr2char(ccline.cmdbuff.add(ccline.cmdpos));
            }
            if (i != 0) {
                i = ptr2cells(ccline.cmdbuff.add(ccline.cmdpos));
                ccline.cmdspos -= i;
                msg_col -= i;
                if (msg_col < 0) {
                    msg_col += cmdline_width;
                    msg_row--;
                }
            }
            if (redraw && !cmd_silent) {
                msg_no_more = true;
                i = cmdline_row;
                cursorcmd();
                draw_cmdline(ccline.cmdpos, ccline.cmdlen - ccline.cmdpos);
                if (cmdline_row != i || ccline.overstrike) {
                    msg_clr_eos();
                }
                msg_no_more = false;
            }
            if (KeyTyped) {
                m = (int) ((long) cmdline_width * Rows[0]);
                if (m < 0) {
                    m = MAXCOL;
                }
            } else {
                m = MAXCOL;
            }
            for (i = 0; i < len; i++) {
                c = cmdline_charsize(ccline.cmdpos);
                correct_cmdspos(ccline.cmdpos, c);
                if (ccline.cmdspos + c < m) {
                    ccline.cmdspos += c;
                }
                c = utfc_ptr2len(ccline.cmdbuff.add(ccline.cmdpos)) - 1;
                if (c > (len - i - 1)) {
                    c = len - i - 1;
                }
                ccline.cmdpos += c;
                i += c;
                ccline.cmdpos++;
            }
        }
        if (redraw) {
            msg_check();
        }
        return retval;
    }

    private void save_cmdline(T_cmdline_info_T ccp) {
        if (!prev_ccline_used) {
            prev_ccline.zero();
            prev_ccline_used = true;
        }
        ccp.set(prev_ccline);
        prev_ccline.set(ccline);
        ccline.cmdbuff = null;
    }

    private void restore_cmdline(T_cmdline_info_T ccp) {
        ccline.set(prev_ccline);
        prev_ccline.set(ccp);
    }

    private boolean cmdline_paste(int regname, boolean literally, boolean remcr) {
        T_get_spec_reg__out_T get_spec_reg__o = new T_get_spec_reg__out_T();
        long i;
        BytePtr[] arg = new BytePtr[1];
        BytePtr p;
        if (regname != Ctrl_F && regname != Ctrl_P && regname != Ctrl_W && regname != Ctrl_A && regname != Ctrl_L
                && !valid_yank_reg(regname, false)) {
            return false;
        }
        line_breakcheck();
        if (got_int != 0) {
            return false;
        }
        textlock++;
        get_spec_reg__o = get_spec_reg(regname, new Ptr<BytePtr>(arg, 0), true);
        i = (long) (get_spec_reg__o.r__ ? 1 : 0);
        textlock--;
        if (i != 0) {
            if (arg[0] == null) {
                return false;
            }
            p = arg[0];
            if (p_is[0] != 0 && regname == Ctrl_W) {
                BytePtr w = null;
                int len = 0;
                for (w = ccline.cmdbuff.add(ccline.cmdpos); w.gt(ccline.cmdbuff); ) {
                    len = utf_head_off(ccline.cmdbuff, w.add(-1)) + 1;
                    if (!vim_iswordc(utf_ptr2char(w.add(-len)))) {
                        break;
                    }
                    w = w.add(-len);
                }
                len = (int) ccline.cmdbuff.add(ccline.cmdpos).sub(w);
                if (p_ic[0] != 0 ? musl_strncasecmp(w, arg[0], (long) len) == 0 : musl_strncmp(w, arg[0],
                        (long) len) == 0) {
                    p = p.add(len);
                }
            }
            cmdline_paste_str(p, literally);
            return true;
        }
        return cmdline_paste_reg(regname, literally, remcr);
    }

    private void cmdline_paste_str(BytePtr s, boolean literally) {
        T_mb_cptr2char_adv__out_T mb_cptr2char_adv__o = new T_mb_cptr2char_adv__out_T();
        int c = 0;
        int cv = 0;
        if (literally) {
            put_on_cmdline(s, -1, true);
        } else {
            while (s.get() != NUL) {
                cv = s.u();
                if (cv == Ctrl_V && s.at(1) != 0) {
                    s = s.add(1);
                }
                mb_cptr2char_adv__o = mb_cptr2char_adv(s);
                s = mb_cptr2char_adv__o.pp;
                c = mb_cptr2char_adv__o.r__;
                if (cv == Ctrl_V || c == ESC || c == Ctrl_C || c == CAR || c == NL || c == Ctrl_L || c == intr_char
                        || (c == Ctrl_BSL && s.get() == Ctrl_N)) {
                    stuffcharReadbuff(Ctrl_V);
                }
                stuffcharReadbuff(c);
            }
        }
    }

    private void redrawcmdline() {
        redrawcmdline_ex(true);
    }

    private void redrawcmdline_ex(boolean do_compute_cmdrow) {
        if (cmd_silent) {
            return;
        }
        need_wait_return = FALSE;
        if (do_compute_cmdrow) {
            compute_cmdrow();
        }
        redrawcmd();
        cursorcmd();
    }

    private void redrawcmdprompt() {
        int i = 0;
        if (cmd_silent) {
            return;
        }
        if (ccline.cmdfirstc != NUL) {
            msg_putchar(ccline.cmdfirstc);
        }
        if (ccline.cmdprompt != null) {
            msg_puts_attr(ccline.cmdprompt, ccline.cmdattr);
            ccline.cmdindent = msg_col + (msg_row - cmdline_row) * cmdline_width;
            if (ccline.cmdfirstc != NUL) {
                ccline.cmdindent--;
            }
        } else {
            for (i = ccline.cmdindent; i > 0; i--) {
                msg_putchar(' ');
            }
        }
    }

    private void redrawcmd() {
        int save_in_echowindow = in_echowindow;
        if (cmd_silent) {
            return;
        }
        if (ccline.cmdbuff == null) {
            windgoto(cmdline_row, cmdline_col_off);
            msg_clr_eos();
            return;
        }
        in_echowindow = FALSE;
        sb_text_restart_cmdline();
        msg_start();
        msg_starthere();
        redrawcmdprompt();
        msg_no_more = true;
        draw_cmdline(0, ccline.cmdlen);
        msg_clr_eos();
        msg_no_more = false;
        set_cmdspos_cursor();
        if (extra_char != NUL) {
            putcmdline(extra_char, extra_char_shift);
        }
        msg_scroll = FALSE;
        skip_redraw = false;
        in_echowindow = save_in_echowindow;
    }

    private void compute_cmdrow() {
        if (msg_scrolled != 0 && updating_screen == 0) {
            cmdline_row = (int) (Rows[0] - 1L);
        } else {
            cmdline_row = curwin.w_winrow + curwin.w_height + curwin.w_status_height;
        }
    }

    private void cursorcmd() {
        if (cmd_silent) {
            return;
        }
        msg_row = cmdline_row + ccline.cmdspos / cmdline_width;
        msg_col = ccline.cmdspos % cmdline_width;
        if ((long) msg_row >= Rows[0]) {
            msg_row = (int) (Rows[0] - 1L);
        }
        windgoto(msg_row, cmdline_col_off + msg_col);
    }

    private void gotocmdline(boolean clr) {
        msg_start();
        msg_col = 0;
        if (clr) {
            msg_clr_eos();
        }
        windgoto(cmdline_row, cmdline_col_off);
    }

