    private static T_get_list_range__out_T get_list_range(BytePtr str, int num1, int num2) {
        T_get_list_range__out_T out__ = new T_get_list_range__out_T();
        int len = 0;
        boolean first = false;
        long[] num = new long[1];
        str = skipwhite(str);
        if (str.get() == '-' || vim_isdigit(str.u())) {
            len = vim_str2nr(str, null, len, 0, new LongPtr(num, 0), null, 0, false, null);
            str = str.add(len);
            if (num[0] > INT_MAX) {
                out__.r__ = false;
                out__.str = str;
                out__.num1 = num1;
                out__.num2 = num2;
                return out__;
            }
            num1 = (int) num[0];
            first = true;
        }
        str = skipwhite(str);
        if (str.get() == ',') {
            str = skipwhite(str.add(1));
            len = vim_str2nr(str, null, len, 0, new LongPtr(num, 0), null, 0, false, null);
            if (len > 0) {
                str = skipwhite(str.add(len));
                if (num[0] > INT_MAX) {
                    out__.r__ = false;
                    out__.str = str;
                    out__.num1 = num1;
                    out__.num2 = num2;
                    return out__;
                }
                num2 = (int) num[0];
            } else if (!first) {
                out__.r__ = false;
                out__.str = str;
                out__.num1 = num1;
                out__.num2 = num2;
                return out__;
            }
        } else if (first) {
            num2 = num1;
        }
        out__.r__ = true;
        out__.str = str;
        out__.num1 = num1;
        out__.num2 = num2;
        return out__;
    }

