    private void shorten_dir_len(BytePtr str, int trim_len) {
        BytePtr t1 = null;
        BytePtr t2 = null;
        BytePtr t3 = null;
        BytePtr t4 = null;
        BytePtr s = null;
        boolean skip = false;
        int dirchunk_len = 0;
        BytePtr tail = gettail(str);
        BytePtr d = str;
        for (s = str; ; s = s.add(1)) {
            if (s.ge(tail)) {
                t1 = d;
                d = d.add(1);
                t1.put(s.get());
                if (s.get() == NUL) {
                    break;
                }
            } else if (vim_ispathsep(s.u())) {
                t2 = d;
                d = d.add(1);
                t2.put(s.get());
                skip = false;
                dirchunk_len = 0;
            } else if (!skip) {
                t3 = d;
                d = d.add(1);
                t3.put(s.get());
                if (s.get() != '~' && s.get() != '.') {
                    dirchunk_len++;
                    if (dirchunk_len >= trim_len) {
                        skip = true;
                    }
                }
                int l = utfc_ptr2len(s);
                while (--l > 0) {
                    t4 = d;
                    d = d.add(1);
                    s = s.add(1);
                    t4.put(s.get());
                }
            }
        }
    }

    private void shorten_dir(BytePtr str) {
        shorten_dir_len(str, 1);
    }

    private long home_replace(S_file_buffer buf, BytePtr src, BytePtr dst, int dstlen, boolean one) {
        long len;
        if (src == null) {
            dst.put((byte) NUL);
            return 0L;
        }
        len = musl_strlen(src);
        if (Long.compareUnsigned(len, (long) dstlen) >= 0) {
            len = (long) dstlen - 1L;
        }
        Rt.memmove(dst, src, len);
        dst.set((int) len, (byte) NUL);
        return len;
    }

    private BytePtr gettail(BytePtr fname) {
        BytePtr p1 = null;
        BytePtr p2 = null;
        if (fname == null) {
            return BytePtr.lit("");
        }
        for (p1 = p2 = get_past_head(fname); p2.get() != 0; ) {
            if (vim_ispathsep_nocolon(p2.u())) {
                p1 = p2.add(1);
            }
            p2 = p2.add(utfc_ptr2len(p2));
        }
        return p1;
    }

    private static BytePtr get_past_head(BytePtr path) {
        BytePtr retval = path;
        while (vim_ispathsep(retval.u())) {
            retval = retval.add(1);
        }
        return retval;
    }

    private static boolean vim_ispathsep(int c) {
        return c == '/';
    }

    private static boolean vim_ispathsep_nocolon(int c) {
        return vim_ispathsep(c);
    }

