    private BytePtr file_name_at_cursor(int options, long count, LongPtr file_lnum) {
        return file_name_in_line(ml_get_curline(), curwin.w_cursor.col, options, count, null, file_lnum);
    }

    private BytePtr file_name_in_line(BytePtr line, int col, int options, long count, BytePtr rel_fname,
            LongPtr file_lnum) {
        int len = 0;
        boolean in_type = true;
        boolean is_url = false;
        BytePtr ptr = line.add(col);
        while (ptr.get() != NUL && !vim_isfilec(ptr.u())) {
            ptr = ptr.add(utfc_ptr2len(ptr));
        }
        if (ptr.get() == NUL) {
            if ((options & FNAME_MESS) != 0) {
                emsg(new BytePtr(e_no_file_name_under_cursor, 0));
            }
            return null;
        }
        while (ptr.gt(line)) {
            if ((len = utf_head_off(line, ptr.add(-1))) > 0) {
                ptr = ptr.add(-(len + 1));
            } else if (vim_isfilec(ptr.u(-1)) || ((options & FNAME_HYP) != 0 && path_is_url(ptr.add(-1)) != 0)) {
                ptr = ptr.add(-1);
            } else {
                break;
            }
        }
        len = 0;
        while (vim_isfilec(ptr.u(len)) || (ptr.at(len) == '\\' && ptr.at(len + 1) == ' ')
                || ((options & FNAME_HYP) != 0 && path_is_url(ptr.add(len)) != 0)
                || (is_url && vim_strchr(BytePtr.lit(":?&="), ptr.u(len)) != null)) {
            if ((ptr.u(len) >= 'A' && ptr.u(len) <= 'Z') || (ptr.u(len) >= 'a' && ptr.u(len) <= 'z')) {
                if (in_type && path_is_url(ptr.add(len).add(1)) != 0) {
                    is_url = true;
                }
            } else {
                in_type = false;
            }
            if (ptr.at(len) == '\\') {
                len++;
            }
            len += utfc_ptr2len(ptr.add(len));
        }
        if (len > 2 && vim_strchr(BytePtr.lit(".,:;!"), ptr.u(len - 1)) != null && ptr.at(len - 2) != '.') {
            len--;
        }
        if (file_lnum != null) {
            BytePtr[] p = new BytePtr[1];
            BytePtr match_text = BytePtr.lit(" line ");
            long match_textlen = 6L;
            p[0] = ptr.add(len);
            if (musl_strncmp(p[0], match_text, match_textlen) == 0) {
                p[0] = p[0].add((int) match_textlen);
            } else {
                match_text = new BytePtr(line_msg, 0);
                match_textlen = musl_strlen(match_text);
                if (musl_strncmp(p[0], match_text, match_textlen) == 0) {
                    p[0] = p[0].add((int) match_textlen);
                } else {
                    p[0] = skipwhite(p[0]);
                }
            }
            if (p[0].get() != NUL) {
                if (!musl_isdigit(p[0].u())) {
                    p[0] = p[0].add(1);
                }
                p[0] = skipwhite(p[0]);
                if (musl_isdigit(p[0].u())) {
                    file_lnum.put((long) (int) getdigits(new Ptr<BytePtr>(p, 0)));
                }
            }
        }
        return find_file_name_in_path(ptr, len, options, count, rel_fname);
    }

    private BytePtr find_file_name_in_path(BytePtr ptr, int len, int options, long count, BytePtr rel_fname) {
        BytePtr file_name;
        if (len == 0) {
            return null;
        }
        file_name = vim_strnsave(ptr, (long) len);
        return file_name;
    }

    private static void free_buff(S_buffheader buf) {
        S_buffblock p = null;
        S_buffblock np = null;
        for (p = buf.bh_first.b_next; p != null; p = np) {
            np = p.b_next;
        }
        buf.bh_first.b_next = null;
        buf.bh_curr = null;
    }

    private static T_get_buffcont__out_T get_buffcont(S_buffheader buffer, boolean dozero, long len) {
        BytePtr t1 = null;
        BytePtr t2 = null;
        T_get_buffcont__out_T out__ = new T_get_buffcont__out_T();
        long count = 0L;
        BytePtr p = null;
        BytePtr p2;
        BytePtr str = null;
        S_buffblock bp = null;
        long i = 0L;
        for (bp = buffer.bh_first.b_next; bp != null; bp = bp.b_next) {
            count += bp.b_strlen;
        }
        if ((Long.compareUnsigned(count, 0L) > 0 || dozero) && (p = BytePtr.alloc(count + 1L)) != null) {
            p2 = p;
            for (bp = buffer.bh_first.b_next; bp != null; bp = bp.b_next) {
                for (str = bp.b_str; str.get() != 0; ) {
                    t1 = p2;
                    p2 = p2.add(1);
                    t2 = str;
                    str = str.add(1);
                    t1.put(t2.get());
                }
            }
            p2.put((byte) NUL);
            i = p2.sub(p);
        }
        len = i;
        out__.r__ = p;
        out__.len = len;
        return out__;
    }

    private BytePtr get_recorded() {
        T_get_buffcont__out_T get_buffcont__o = new T_get_buffcont__out_T();
        BytePtr p;
        long len = 0;
        get_buffcont__o = get_buffcont(recordbuff, true, len);
        len = get_buffcont__o.len;
        p = get_buffcont__o.r__;
        if (p == null) {
            return null;
        }
        free_buff(recordbuff);
        if (Long.compareUnsigned(len, last_recorded_len) >= 0) {
            len -= last_recorded_len;
            p.set((int) len, (byte) NUL);
        }
        if (Long.compareUnsigned(len, 0L) > 0 && restart_edit != 0 && p.at((int) (len - 1L)) == Ctrl_O) {
            p.set((int) (len - 1L), (byte) NUL);
        }
        return p;
    }

    private T_string_T get_inserted() {
        T_get_buffcont__out_T get_buffcont__o = new T_get_buffcont__out_T();
        long len = 0L;
        get_buffcont__o = get_buffcont(redobuff, false, len);
        len = get_buffcont__o.len;
        BytePtr str = get_buffcont__o.r__;
        T_string_T ret = new T_string_T();
        ret.string[0] = str;
        ret.length = len;
        return ret;
    }

    private void add_buff(S_buffheader buf, BytePtr s, long slen) {
        if (slen < 0L) {
            slen = musl_strlen(s);
        }
        if (slen == 0L) {
            return;
        }
        if (buf.bh_first.b_next == null) {
            buf.bh_curr = buf.bh_first;
            buf.bh_create_newblock = TRUE;
        } else if (buf.bh_curr == null) {
            iemsg(new BytePtr(e_add_to_internal_buffer_that_was_already_read_from, 0));
            return;
        } else if (buf.bh_index != 0) {
            Rt.memmove(buf.bh_first.b_next.b_str, buf.bh_first.b_next.b_str.add(buf.bh_index),
                    buf.bh_first.b_next.b_strlen - (long) buf.bh_index + 1L);
            buf.bh_first.b_next.b_strlen -= (long) buf.bh_index;
            buf.bh_space += buf.bh_index;
        }
        buf.bh_index = 0;
        if (buf.bh_create_newblock == 0 && buf.bh_space >= (int) slen) {
            vim_strncpy(buf.bh_curr.b_str.add((int) buf.bh_curr.b_strlen), s, slen);
            buf.bh_curr.b_strlen += slen;
            buf.bh_space -= (int) slen;
        } else {
            long len;
            S_buffblock p;
            if (slen < MINIMAL_SIZE) {
                len = MINIMAL_SIZE;
            } else {
                len = slen;
            }
            p = new S_buffblock();
            p.b_str = BytePtr.alloc(len + 1L);
            vim_strncpy(p.b_str, s, slen);
            p.b_strlen = slen;
            buf.bh_space = (int) (len - slen);
            buf.bh_create_newblock = FALSE;
            p.b_next = buf.bh_curr.b_next;
            buf.bh_curr.b_next = p;
            buf.bh_curr = p;
        }
    }

    private static void delete_buff_tail(S_buffheader buf, int slen) {
        if (buf.bh_curr == null) {
            return;
        }
        if (Long.compareUnsigned(buf.bh_curr.b_strlen, (long) slen) < 0) {
            return;
        }
        buf.bh_curr.b_str.set((int) (buf.bh_curr.b_strlen - (long) slen), (byte) NUL);
        buf.bh_curr.b_strlen -= (long) slen;
        buf.bh_space += slen;
    }

    private void add_num_buff(S_buffheader buf, long n) {
        byte[] number = new byte[32];
        int numberlen = vim_snprintf(new BytePtr(number, 0), 32L, BytePtr.lit("%ld"), n);
        add_buff(buf, new BytePtr(number, 0), (long) numberlen);
    }

    private void add_char_buff(S_buffheader buf, int c) {
        byte[] bytes = new byte[22];
        int len;
        int i = 0;
        byte[] temp = new byte[4];
        long templen = 0;
        if (c < 0) {
            len = 1;
        } else {
            len = utf_char2bytes(c, new BytePtr(bytes, 0));
        }
        for (i = 0; i < len; i++) {
            if (!(c < 0)) {
                c = bytes[i] & 0xff;
            }
            if (c < 0 || c == 128 || c == NUL) {
                temp[0] = -128;
                temp[1] = (byte) (c == 128 ? KS_SPECIAL : (c == NUL ? KS_ZERO : -c & 255));
                temp[2] = (byte) (c == 128 || c == NUL ? 'X' : (-c >>> 8) & 255);
                temp[3] = NUL;
                templen = 3L;
            } else {
                temp[0] = (byte) c;
                temp[1] = NUL;
                templen = 1L;
            }
            add_buff(buf, new BytePtr(temp, 0), templen);
        }
    }

    private int read_readbuffers(boolean advance) {
        int c = read_readbuf(readbuf1, advance);
        if (c == NUL) {
            c = read_readbuf(readbuf2, advance);
        }
        return c;
    }

    private static int read_readbuf(S_buffheader buf, boolean advance) {
        byte c;
        S_buffblock curr;
        if (buf.bh_first.b_next == null) {
            return NUL;
        }
        curr = buf.bh_first.b_next;
        c = curr.b_str.at(buf.bh_index);
        if (advance) {
            buf.bh_index++;
            if (curr.b_str.at(buf.bh_index) == NUL) {
                buf.bh_first.b_next = curr.b_next;
                buf.bh_index = 0;
            }
        }
        return c & 0xff;
    }

    private void start_stuff() {
        if (readbuf1.bh_first.b_next != null) {
            readbuf1.bh_curr = readbuf1.bh_first;
            readbuf1.bh_create_newblock = TRUE;
        }
        if (readbuf2.bh_first.b_next != null) {
            readbuf2.bh_curr = readbuf2.bh_first;
            readbuf2.bh_create_newblock = TRUE;
        }
    }

    private boolean stuff_empty() {
        return readbuf1.bh_first.b_next == null && readbuf2.bh_first.b_next == null;
    }

    private void typeahead_noflush(int c) {
        typeahead_char = c;
    }

    private void flush_buffers(int flush_typeahead) {
        init_typebuf();
        start_stuff();
        while (read_readbuffers(true) != NUL) {
        }
        if (flush_typeahead == FLUSH_MINIMAL) {
            if (typebuf.tb_off + typebuf.tb_maplen >= typebuf.tb_buflen) {
                typebuf.tb_off = MAXMAPLEN;
                typebuf.tb_len = 0;
            } else {
                typebuf.tb_off += typebuf.tb_maplen;
                typebuf.tb_len -= typebuf.tb_maplen;
            }
        } else {
            if (flush_typeahead == FLUSH_INPUT) {
                while (inchar(typebuf.tb_buf, typebuf.tb_buflen - 1, 10L) != 0) {
                }
            }
            typebuf.tb_off = MAXMAPLEN;
            typebuf.tb_len = 0;
        }
        typebuf.tb_maplen = 0;
        typebuf.tb_silent = 0;
        cmd_silent = false;
        typebuf.tb_no_abbr_cnt = 0;
        typebuf.tb_change_cnt++;
        if (typebuf.tb_change_cnt == 0) {
            typebuf.tb_change_cnt = 1;
        }
    }

