    private void AppendToRedobuff(BytePtr s) {
        if (!block_redo) {
            add_buff(redobuff, s, -1L);
        }
    }

    private void AppendToRedobuffLit(BytePtr str, int len) {
        T_mb_cptr2char_adv__out_T mb_cptr2char_adv__o = new T_mb_cptr2char_adv__out_T();
        BytePtr s = str;
        int c = 0;
        BytePtr start = null;
        if (block_redo) {
            return;
        }
        while (len < 0 ? s.get() != NUL : s.sub(str) < (long) len) {
            start = s;
            while (s.u() >= ' ' && s.u() < DEL && (len < 0 || s.sub(str) < (long) len)) {
                s = s.add(1);
            }
            if (s.get() == NUL && (s.at(-1) == '0' || s.at(-1) == '^')) {
                s = s.add(-1);
            }
            if (s.gt(start)) {
                add_buff(redobuff, start, s.sub(start));
            }
            if (s.get() == NUL || (len >= 0 && s.sub(str) >= (long) len)) {
                break;
            }
            mb_cptr2char_adv__o = mb_cptr2char_adv(s);
            s = mb_cptr2char_adv__o.pp;
            c = mb_cptr2char_adv__o.r__;
            if (c < ' ' || c == DEL || (s.get() == NUL && (c == '0' || c == '^'))) {
                add_char_buff(redobuff, Ctrl_V);
            }
            if (s.get() == NUL && c == '0') {
                add_buff(redobuff, BytePtr.lit("048"), 3L);
            } else {
                add_char_buff(redobuff, c);
            }
        }
    }

    private void AppendToRedobuffSpec(BytePtr s) {
        T_mb_cptr2char_adv__out_T mb_cptr2char_adv__o = new T_mb_cptr2char_adv__out_T();
        if (block_redo) {
            return;
        }
        while (s.get() != NUL) {
            if (s.u() == 128 && s.at(1) != NUL && s.at(2) != NUL) {
                add_buff(redobuff, s, 3L);
                s = s.add(3);
            } else {
                mb_cptr2char_adv__o = mb_cptr2char_adv(s);
                s = mb_cptr2char_adv__o.pp;
                add_char_buff(redobuff, mb_cptr2char_adv__o.r__);
            }
        }
    }

