    private void stuffescaped(BytePtr arg, int literally) {
        T_mb_cptr2char_adv__out_T mb_cptr2char_adv__o = new T_mb_cptr2char_adv__out_T();
        int c = 0;
        BytePtr start = null;
        while (arg.get() != NUL) {
            start = arg;
            while ((arg.u() >= ' ' && arg.u() < DEL) || (arg.u() == 128 && literally == 0)) {
                arg = arg.add(1);
            }
            if (arg.gt(start)) {
                stuffReadbuffLen(start, arg.sub(start));
            }
            if (arg.get() != NUL) {
                mb_cptr2char_adv__o = mb_cptr2char_adv(arg);
                arg = mb_cptr2char_adv__o.pp;
                c = mb_cptr2char_adv__o.r__;
                if (literally != 0 && ((c < ' ' && c != TAB) || c == DEL)) {
                    stuffcharReadbuff(Ctrl_V);
                }
                stuffcharReadbuff(c);
            }
        }
    }

    private int read_redo(boolean init, boolean old_redo) {
        int c = 0;
        int n;
        byte[] buf = new byte[22];
        int i = 0;
        if (init) {
            if (old_redo) {
                read_redo_bp = old_redobuff.bh_first.b_next;
            } else {
                read_redo_bp = redobuff.bh_first.b_next;
            }
            if (read_redo_bp == null) {
                return FAIL;
            }
            read_redo_p = read_redo_bp.b_str;
            return OK;
        }
        if ((c = read_redo_p.u()) != NUL) {
            if (c != 128 || read_redo_p.u(1) == KS_SPECIAL) {
                n = c < 0 || c > 255 ? 1 : (int) mb_bytelen_tab[c];
            } else {
                n = 1;
            }
            for (i = 0; ; i++) {
                if (c == 128) {
                    c = read_redo_p.u(1) == KS_SPECIAL ? 128 : (read_redo_p.u(1) == KS_ZERO ? -(KS_ZERO + ('X' << 8)) : -(read_redo_p.u(1) + (read_redo_p.u(2) << 8)));
                    read_redo_p = read_redo_p.add(2);
                }
                read_redo_p = read_redo_p.add(1);
                if (read_redo_p.get() == NUL && read_redo_bp.b_next != null) {
                    read_redo_bp = read_redo_bp.b_next;
                    read_redo_p = read_redo_bp.b_str;
                }
                buf[i] = (byte) c;
                if (i == n - 1) {
                    if (n != 1) {
                        c = utf_ptr2char(new BytePtr(buf, 0));
                    }
                    break;
                }
                c = read_redo_p.u();
                if (c == NUL) {
                    break;
                }
            }
        }
        return c;
    }

    private void copy_redo(boolean old_redo) {
        int c = 0;
        while ((c = read_redo(false, old_redo)) != NUL) {
            add_char_buff(readbuf2, c);
        }
    }

    private boolean start_redo(long count, boolean old_redo) {
        int c;
        if (read_redo(true, old_redo) == FAIL) {
            return false;
        }
        c = read_redo(false, old_redo);
        if (c == '"') {
            add_buff(readbuf2, BytePtr.lit("\""), 1L);
            c = read_redo(false, old_redo);
            if (c >= '1' && c < '9') {
                c++;
            }
            add_char_buff(readbuf2, c);
            if (c == '=') {
                add_char_buff(readbuf2, CAR);
                cmd_silent = true;
            }
            c = read_redo(false, old_redo);
        }
        if (c == 'v') {
            VIsual.set(curwin.w_cursor);
            VIsual_active = true;
            VIsual_select = FALSE;
            VIsual_reselect = true;
            redo_VIsual_busy = true;
            c = read_redo(false, old_redo);
        }
        if (count != 0) {
            while (ascii_isdigit(c)) {
                c = read_redo(false, old_redo);
            }
            add_num_buff(readbuf2, count);
        }
        add_char_buff(readbuf2, c);
        copy_redo(old_redo);
        return true;
    }

    private boolean start_redo_ins() {
        int c = 0;
        if (read_redo(true, false) == FAIL) {
            return false;
        }
        start_stuff();
        while ((c = read_redo(false, false)) != NUL) {
            if (vim_strchr(BytePtr.lit("AaIiRrOo"), c) != null) {
                if (c == 'O' || c == 'o') {
                    add_buff(readbuf2, BytePtr.lit("\n"), -1L);
                }
                break;
            }
        }
        copy_redo(false);
        block_redo = true;
        return true;
    }

    private void stop_redo_ins() {
        block_redo = false;
    }

    private void init_typebuf() {
        if (typebuf.tb_buf != null) {
            return;
        }
        typebuf.tb_buf = new BytePtr(typebuf_init, 0);
        typebuf.tb_noremap = new BytePtr(noremapbuf_init, 0);
        typebuf.tb_buflen = 5 * (MAXMAPLEN + 3);
        typebuf.tb_len = 0;
        typebuf.tb_off = MAXMAPLEN + 4;
        typebuf.tb_change_cnt = 1;
    }

    private boolean ins_typebuf(BytePtr str, int noremap, int offset, boolean nottyped, int silent) {
        BytePtr s1;
        BytePtr s2;
        int newlen;
        int addlen;
        int i = 0;
        int newoff;
        int val;
        int nrm;
        init_typebuf();
        typebuf.tb_change_cnt++;
        if (typebuf.tb_change_cnt == 0) {
            typebuf.tb_change_cnt = 1;
        }
        addlen = (int) musl_strlen(str);
        if (offset == 0 && addlen <= typebuf.tb_off) {
            typebuf.tb_off -= addlen;
            Rt.memmove(typebuf.tb_buf.add(typebuf.tb_off), str, (long) addlen);
        } else if (typebuf.tb_len == 0 && typebuf.tb_buflen >= addlen + 3 * (MAXMAPLEN + 4)) {
            typebuf.tb_off = (typebuf.tb_buflen - addlen - 3 * (MAXMAPLEN + 4)) / 2;
            Rt.memmove(typebuf.tb_buf.add(typebuf.tb_off), str, (long) addlen);
        } else {
            int extra;
            newoff = MAXMAPLEN + 4;
            extra = addlen + newoff + 4 * (MAXMAPLEN + 4);
            if (typebuf.tb_len > (2147483647 - extra)) {
                emsg(new BytePtr(e_command_too_complex, 0));
                setcursor();
                return false;
            }
            newlen = typebuf.tb_len + extra;
            s1 = BytePtr.alloc((long) newlen);
            s2 = BytePtr.alloc((long) newlen);
            typebuf.tb_buflen = newlen;
            Rt.memmove(s1.add(newoff), typebuf.tb_buf.add(typebuf.tb_off), (long) offset);
            Rt.memmove(s1.add(newoff).add(offset), str, (long) addlen);
            Rt.memmove(s1.add(newoff).add(offset).add(addlen), typebuf.tb_buf.add(typebuf.tb_off).add(offset),
                    (long) (typebuf.tb_len - offset + 1));
            typebuf.tb_buf = s1;
            Rt.memmove(s2.add(newoff), typebuf.tb_noremap.add(typebuf.tb_off), (long) offset);
            Rt.memmove(s2.add(newoff).add(offset).add(addlen), typebuf.tb_noremap.add(typebuf.tb_off).add(offset),
                    (long) (typebuf.tb_len - offset));
            typebuf.tb_noremap = s2;
            typebuf.tb_off = newoff;
        }
        typebuf.tb_len += addlen;
        if (noremap == -2) {
            val = RM_SCRIPT;
        } else if (noremap == -3) {
            val = RM_ABBR;
        } else {
            val = RM_NONE;
        }
        if (noremap == -3) {
            nrm = 1;
        } else if (noremap < 0) {
            nrm = addlen;
        } else {
            nrm = noremap;
        }
        for (i = 0; i < addlen; i++) {
            typebuf.tb_noremap.set(typebuf.tb_off + i + offset, (byte) (--nrm >= 0 ? val : RM_YES));
        }
        if (nottyped || typebuf.tb_maplen > offset) {
            typebuf.tb_maplen += addlen;
        }
        if (silent != 0 || typebuf.tb_silent > offset) {
            typebuf.tb_silent += addlen;
            cmd_silent = true;
        }
        if (typebuf.tb_no_abbr_cnt != 0 && offset == 0) {
            typebuf.tb_no_abbr_cnt += addlen;
        }
        return true;
    }

    private int ins_char_typebuf(int c, int modifiers) {
        byte[] buf = new byte[67];
        int len = special_to_buf(c, modifiers, true, new BytePtr(buf, 0));
        buf[len] = NUL;
        ins_typebuf(new BytePtr(buf, 0), KeyNoremap, 0, !KeyTyped, cmd_silent ? 1 : 0);
        return len;
    }

    private boolean typebuf_changed(int tb_change_cnt) {
        return tb_change_cnt != 0 && typebuf.tb_change_cnt != tb_change_cnt;
    }

    private boolean typebuf_typed() {
        return typebuf.tb_maplen == 0;
    }

    private int typebuf_maplen() {
        return typebuf.tb_maplen;
    }

    private void del_typebuf(int len, int offset) {
        int i;
        if (len == 0) {
            return;
        }
        typebuf.tb_len -= len;
        if (offset == 0 && typebuf.tb_buflen - (typebuf.tb_off + len) >= 3 * MAXMAPLEN + 3) {
            typebuf.tb_off += len;
        } else {
            i = typebuf.tb_off + offset;
            if (typebuf.tb_off > MAXMAPLEN) {
                Rt.memmove(typebuf.tb_buf.add(MAXMAPLEN), typebuf.tb_buf.add(typebuf.tb_off), (long) offset);
                Rt.memmove(typebuf.tb_noremap.add(MAXMAPLEN), typebuf.tb_noremap.add(typebuf.tb_off), (long) offset);
                typebuf.tb_off = MAXMAPLEN;
            }
            Rt.memmove(typebuf.tb_buf.add(typebuf.tb_off).add(offset), typebuf.tb_buf.add(i).add(len),
                    (long) (typebuf.tb_len - offset + 1));
            Rt.memmove(typebuf.tb_noremap.add(typebuf.tb_off).add(offset), typebuf.tb_noremap.add(i).add(len),
                    (long) (typebuf.tb_len - offset));
        }
        if (typebuf.tb_maplen > offset) {
            if (typebuf.tb_maplen < offset + len) {
                typebuf.tb_maplen = offset;
            } else {
                typebuf.tb_maplen -= len;
            }
        }
        if (typebuf.tb_silent > offset) {
            if (typebuf.tb_silent < offset + len) {
                typebuf.tb_silent = offset;
            } else {
                typebuf.tb_silent -= len;
            }
        }
        if (typebuf.tb_no_abbr_cnt > offset) {
            if (typebuf.tb_no_abbr_cnt < offset + len) {
                typebuf.tb_no_abbr_cnt = offset;
            } else {
                typebuf.tb_no_abbr_cnt -= len;
            }
        }
        typebuf.tb_change_cnt++;
        if (typebuf.tb_change_cnt == 0) {
            typebuf.tb_change_cnt = 1;
        }
    }

    private boolean gotchars_add_byte(T_gotchars_state_T state, byte byte_) {
        long t1 = 0;
        t1 = state.buflen;
        state.buflen++;
        state.buf[(int) t1] = byte_;
        int c = state.buf[(int) t1] & 0xff;
        boolean retval = false;
        boolean in_special = Integer.compareUnsigned(state.pending_special, 0) > 0;
        boolean in_mbyte = Integer.compareUnsigned(state.pending_mbyte, 0) > 0;
        if (in_special) {
            state.pending_special--;
        } else if (c == 128) {
            state.pending_special = 2;
        }
        if (Integer.compareUnsigned(state.pending_special, 0) > 0) {
            state.prev_c = c;
            return retval;
        }
        if (in_mbyte) {
            state.pending_mbyte--;
        } else {
            if (in_special) {
                if (state.prev_c == KS_MODIFIER) {
                    state.prev_c = c;
                    return retval;
                }
                c = state.prev_c == KS_SPECIAL ? 128 : (state.prev_c == KS_ZERO ? -(KS_ZERO + ('X' << 8)) : -(state.prev_c + (c << 8)));
                if (c == K_FOCUSGAINED || c == K_FOCUSLOST || c == K_COMPLETE_DELAY) {
                    state.buflen = 0L;
                }
            }
            state.pending_mbyte = (c < 0 || c > 255 ? 1 : (int) mb_bytelen_tab[c]) - 1;
        }
        if (Integer.compareUnsigned(state.pending_mbyte, 0) > 0) {
            state.prev_c = c;
            return retval;
        }
        retval = true;
        state.prev_c = c;
        return retval;
    }

    private void gotchars(BytePtr chars, int len) {
        BytePtr t1 = null;
        BytePtr s = chars;
        int todo = len;
        while (todo-- > 0) {
            t1 = s;
            s = s.add(1);
            if (!gotchars_add_byte(gotchars_state, t1.get())) {
                continue;
            }
            if (reg_recording != 0) {
                gotchars_state.buf[(int) gotchars_state.buflen] = NUL;
                add_buff(recordbuff, new BytePtr(gotchars_state.buf, 0), gotchars_state.buflen);
                last_recorded_len += gotchars_state.buflen;
            }
            gotchars_state.buflen = 0L;
        }
        may_sync_undo();
        maptick++;
    }

    private void gotchars_ignore() {
        byte[] nop_buf = new byte[3];
        nop_buf[0] = -128;
        nop_buf[1] = (byte) KS_EXTRA;
        nop_buf[2] = KE_IGNORE;
        gotchars(new BytePtr(nop_buf, 0), 3);
    }

    private void ungetchars(int len) {
        if (reg_recording == 0) {
            return;
        }
        delete_buff_tail(recordbuff, len);
        last_recorded_len -= (long) len;
    }

    private void may_sync_undo() {
        if ((State & (MODE_INSERT | MODE_CMDLINE)) == 0 || arrow_used) {
            u_sync(false);
        }
    }

    private boolean alloc_typebuf() {
        typebuf.tb_buf = BytePtr.alloc(5 * (MAXMAPLEN + 3));
        typebuf.tb_noremap = BytePtr.alloc(5 * (MAXMAPLEN + 3));
        if (typebuf.tb_buf == null || typebuf.tb_noremap == null) {
            free_typebuf();
            return false;
        }
        typebuf.tb_buflen = 5 * (MAXMAPLEN + 3);
        typebuf.tb_off = MAXMAPLEN + 4;
        typebuf.tb_len = 0;
        typebuf.tb_maplen = 0;
        typebuf.tb_silent = 0;
        typebuf.tb_no_abbr_cnt = 0;
        typebuf.tb_change_cnt++;
        if (typebuf.tb_change_cnt == 0) {
            typebuf.tb_change_cnt = 1;
        }
        return true;
    }

    private void free_typebuf() {
        if (BytePtr.eq(typebuf.tb_buf, new BytePtr(typebuf_init, 0))) {
            internal_error(BytePtr.lit("Free typebuf 1"));
        } else {
            typebuf.tb_buf = null;
        }
        if (BytePtr.eq(typebuf.tb_noremap, new BytePtr(noremapbuf_init, 0))) {
            internal_error(BytePtr.lit("Free typebuf 2"));
        } else {
            typebuf.tb_noremap = null;
        }
    }

    private boolean can_get_old_char() {
        return old_char != -1 && (old_KeyStuffed || stuff_empty());
    }

    private void save_typeahead(T_tasave_T tp) {
        tp.save_typebuf.set(typebuf);
        tp.typebuf_valid = alloc_typebuf();
        if (!tp.typebuf_valid) {
            typebuf.set(tp.save_typebuf);
        }
        tp.old_char = old_char;
        tp.old_mod_mask = old_mod_mask;
        old_char = -1;
        tp.save_readbuf1.set(readbuf1);
        readbuf1.bh_first.b_next = null;
        tp.save_readbuf2.set(readbuf2);
        readbuf2.bh_first.b_next = null;
        tp.save_inputbuf = get_input_buf();
    }

    private void restore_typeahead(T_tasave_T tp, boolean overwrite) {
        if (tp.typebuf_valid) {
            free_typebuf();
            typebuf.set(tp.save_typebuf);
        }
        old_char = tp.old_char;
        old_mod_mask = tp.old_mod_mask;
        free_buff(readbuf1);
        readbuf1.set(tp.save_readbuf1);
        free_buff(readbuf2);
        readbuf2.set(tp.save_readbuf2);
        set_input_buf(tp.save_inputbuf, overwrite);
    }

    private static int merge_modifyOtherKeys(int c_arg, IntPtr modifiers) {
        int c = c_arg;
        if ((modifiers.get() & MOD_MASK_CTRL) != 0) {
            if ((c >= '`' && c <= 127) || (c >= '@' && c <= '_')) {
                c &= 31;
                if (c == NUL) {
                    c = -(KS_ZERO + ('X' << 8));
                }
            } else if (c == '6') {
                c = 30;
            }
            if (c != c_arg) {
                modifiers.put(modifiers.get() & ~MOD_MASK_CTRL);
            }
        }
        if ((modifiers.get() & (MOD_MASK_META | MOD_MASK_ALT)) != 0 && c >= 0 && c <= 127) {
            if ((modifiers.get() & MOD_MASK_SHIFT) != 0 && c >= 'a' && c <= 'z') {
                c += 'a' - 'A';
                modifiers.put(modifiers.get() & ~MOD_MASK_SHIFT);
            }
            c += 128;
            modifiers.put(modifiers.get() & ~(MOD_MASK_META | MOD_MASK_ALT));
        }
        return c;
    }

    private void add_byte_to_showcmd(byte byte_) {
        BytePtr t1 = null;
        int t2 = 0;
        BytePtr t3 = null;
        BytePtr[] ptr = new BytePtr[1];
        int modifiers = 0;
        int c = NUL;
        if (p_sc[0] == 0 || msg_silent != 0) {
            return;
        }
        if (!gotchars_add_byte(add_byte_to_showcmd_state, byte_)) {
            return;
        }
        add_byte_to_showcmd_state.buf[(int) add_byte_to_showcmd_state.buflen] = NUL;
        add_byte_to_showcmd_state.buflen = 0L;
        ptr[0] = new BytePtr(add_byte_to_showcmd_state.buf, 0);
        if (ptr[0].u(0) == 128 && ptr[0].u(1) == KS_MODIFIER && ptr[0].at(2) != NUL) {
            modifiers = ptr[0].u(2);
            ptr[0] = ptr[0].add(3);
        }
        if (ptr[0].get() != NUL) {
            BytePtr mb_ptr = mb_unescape(new Ptr<BytePtr>(ptr, 0));
            if (mb_ptr != null) {
                t2 = utf_ptr2char(mb_ptr);
            } else {
                t1 = ptr[0];
                ptr[0] = ptr[0].add(1);
                t2 = t1.u();
            }
            c = t2;
            if (c <= 127) {
                int[] modifiers_after = new int[1];
                modifiers_after[0] = modifiers;
                int mod_c = merge_modifyOtherKeys(c, new IntPtr(modifiers_after, 0));
                if (modifiers_after[0] == 0) {
                    modifiers = 0;
                    c = mod_c;
                }
            }
        }
        if (modifiers != 0) {
            add_to_showcmd(128);
            add_to_showcmd(KS_MODIFIER);
            add_to_showcmd(modifiers);
        }
        if (c != NUL) {
            add_to_showcmd(c);
        }
        while (ptr[0].get() != NUL) {
            t3 = ptr[0];
            ptr[0] = ptr[0].add(1);
            add_to_showcmd(t3.u());
        }
    }

    private int vgetc() {
        int c = 0;
        int c2 = 0;
        int n = 0;
        byte[] buf = new byte[22];
        int i = 0;
        if (can_get_old_char()) {
            c = old_char;
            old_char = -1;
            mod_mask[0] = old_mod_mask;
        } else {
            mod_mask[0] = 0;
            vgetc_mod_mask = 0;
            vgetc_char = 0;
            last_recorded_len -= vgetc_last_vgetc_recorded_len;
            for (;;) {
                boolean did_inc = false;
                if (mod_mask[0] != 0) {
                    no_mapping++;
                    allow_keys++;
                    did_inc = true;
                }
                c = vgetorpeek(true);
                if (did_inc) {
                    no_mapping--;
                    allow_keys--;
                }
                if (c == 128) {
                    int save_allow_keys = allow_keys;
                    no_mapping++;
                    allow_keys = 0;
                    c2 = vgetorpeek(true);
                    c = vgetorpeek(true);
                    no_mapping--;
                    allow_keys = save_allow_keys;
                    if (c2 == KS_MODIFIER) {
                        mod_mask[0] = c;
                        continue;
                    }
                    c = c2 == KS_SPECIAL ? 128 : (c2 == KS_ZERO ? -(KS_ZERO + ('X' << 8)) : -(c2 + (c << 8)));
                    if (allow_osc_key == 0 && c == K_OSC) {
                        continue;
                    }
                    if (c == K_ESC) {
                        c = ESC;
                    }
                }
                if ((n = c < 0 || c > 255 ? 1 : (int) mb_bytelen_tab[c]) > 1) {
                    no_mapping++;
                    buf[0] = (byte) c;
                    for (i = 1; i < n; i++) {
                        buf[i] = (byte) vgetorpeek(true);
                        if ((buf[i] & 0xff) == 128) {
                            c = vgetorpeek(true);
                            if (vgetorpeek(true) == KE_CSI && c == KS_EXTRA) {
                                buf[i] = (byte) CSI;
                            }
                        }
                    }
                    no_mapping--;
                    c = utf_ptr2char(new BytePtr(buf, 0));
                }
                if (vgetc_char == 0) {
                    vgetc_mod_mask = mod_mask[0];
                    vgetc_char = c;
                }
                switch (c) {
                    case K_KPLUS -> c = '+';
                    case K_KMINUS -> c = '-';
                    case K_KDIVIDE -> c = '/';
                    case K_KMULTIPLY -> c = '*';
                    case K_KENTER -> c = CAR;
                    case K_KPOINT -> c = '.';
                    case K_K0 -> c = '0';
                    case K_K1 -> c = '1';
                    case K_K2 -> c = '2';
                    case K_K3 -> c = '3';
                    case K_K4 -> c = '4';
                    case K_K5 -> c = '5';
                    case K_K6 -> c = '6';
                    case K_K7 -> c = '7';
                    case K_K8 -> c = '8';
                    case K_K9 -> c = '9';
                    case K_XHOME, K_ZHOME -> {
                        if (mod_mask[0] == MOD_MASK_SHIFT) {
                            c = K_TC_HASH_2;
                            mod_mask[0] = 0;
                        } else if (mod_mask[0] == MOD_MASK_CTRL) {
                            c = K_C_HOME;
                            mod_mask[0] = 0;
                        } else {
                            c = K_HOME;
                        }
                    }
                    case K_XEND, K_ZEND -> {
                        if (mod_mask[0] == MOD_MASK_SHIFT) {
                            c = K_TC_STAR_7;
                            mod_mask[0] = 0;
                        } else if (mod_mask[0] == MOD_MASK_CTRL) {
                            c = K_C_END;
                            mod_mask[0] = 0;
                        } else {
                            c = K_END;
                        }
                    }
                    case K_XUP -> c = K_UP;
                    case K_XDOWN -> c = K_DOWN;
                    case K_XLEFT -> c = K_LEFT;
                    case K_XRIGHT -> c = K_RIGHT;
                }
                break;
            }
            vgetc_last_vgetc_recorded_len = last_recorded_len;
        }
        return c;
    }

    private int safe_vgetc() {
        int c = vgetc();
        if (c == NUL) {
            c = get_keystroke();
        }
        return c;
    }

    private int plain_vgetc_nopaste() {
        int c = 0;
        do {
            c = safe_vgetc();
        } while (c == K_IGNORE || c == -(KS_VER_SCROLLBAR + ('X' << 8)) || c == -(KS_HOR_SCROLLBAR + ('X' << 8))
                || c == K_MOUSEMOVE);
        return c;
    }

    private int plain_vgetc() {
        int c = plain_vgetc_nopaste();
        if (c == K_PASTESTART) {
            c = bracketed_paste(PASTE_ONE_CHAR, false, null);
        }
        return c;
    }

    private int vpeekc() {
        if (can_get_old_char()) {
            return old_char;
        }
        return vgetorpeek(false);
    }

    private boolean char_avail() {
        int retval;
        no_mapping++;
        retval = vpeekc();
        no_mapping--;
        return retval != NUL;
    }

    private int check_simplify_modifier(int max_offset) {
        byte[] new_string = new byte[21];
        int len = 0;
        int offset = 0;
        BytePtr tp = null;
        for (offset = 0; offset < max_offset; offset++) {
            if (offset + 3 >= typebuf.tb_len) {
                break;
            }
            tp = typebuf.tb_buf.add(typebuf.tb_off).add(offset);
            if ((tp.u(0) == 128 || tp.u(0) == CSI) && tp.u(1) == KS_MODIFIER) {
                int[] modifier = new int[1];
                modifier[0] = tp.u(2);
                int c = tp.u(3);
                int new_c = merge_modifyOtherKeys(c, new IntPtr(modifier, 0));
                if (new_c != c) {
                    int key_offset = offset;
                    if (offset == 0) {
                        vgetc_char = c;
                        vgetc_mod_mask = tp.u(2);
                    }
                    if (new_c < 0) {
                        new_string[0] = -128;
                        new_string[1] = (byte) (new_c == 128 ? KS_SPECIAL : (new_c == NUL ? KS_ZERO : -new_c & 255));
                        new_string[2] = (byte) (new_c == 128 || new_c == NUL ? 'X' : (-new_c >>> 8) & 255);
                        len = 3;
                    } else {
                        len = utf_char2bytes(new_c, new BytePtr(new_string, 0));
                    }
                    if (modifier[0] == 0) {
                        if (!put_string_in_typebuf(offset, 4, new BytePtr(new_string, 0), len, null, 0, null)) {
                            return -1;
                        }
                    } else {
                        tp.set(2, (byte) modifier[0]);
                        key_offset = offset + 3;
                        if (!put_string_in_typebuf(key_offset, 1, new BytePtr(new_string, 0), len, null, 0, null)) {
                            return -1;
                        }
                    }
                    for (int i = 0; i < len; i++) {
                        typebuf.tb_noremap.set(typebuf.tb_off + key_offset + i,
                                (byte) (typebuf.tb_noremap.u(typebuf.tb_off + key_offset + i) | RM_SIMPLIFIED));
                    }
                    return len;
                }
            }
        }
        return 0;
    }

    private boolean key_protocol_enabled() {
        boolean using_mok = modify_otherkeys_state != MOKS_INITIAL ? modify_otherkeys_state == MOKS_ENABLED : seenModifyOtherKeys;
        return using_mok || kitty_protocol_state == KKPS_ENABLED;
    }

    private T_handle_mapping__out_T handle_mapping(int keylenp, int timedout, int mapdepth) {
        BytePtr s = null;
        int n = 0;
        BytePtr t2 = null;
        T_handle_mapping__out_T out__ = new T_handle_mapping__out_T();
        S_mapblock mp = null;
        S_mapblock mp2;
        S_mapblock mp_match;
        int mp_match_len = 0;
        int max_mlen = 0;
        int want_termcode = 0;
        int tb_c1;
        int mlen = 0;
        int keylen = keylenp;
        boolean i;
        int local_State = get_real_state();
        boolean is_plug_map = false;
        boolean in_osc = in_osc_sequence();
        if (!in_osc && typebuf.tb_len >= 3 && typebuf.tb_buf.u(typebuf.tb_off) == 128
                && typebuf.tb_buf.u(typebuf.tb_off + 1) == KS_EXTRA
                && typebuf.tb_buf.at(typebuf.tb_off + 2) == KE_PLUG) {
            is_plug_map = true;
        }
        tb_c1 = typebuf.tb_buf.u(typebuf.tb_off);
        if (!in_osc && no_mapping == 0 && is_maphash_valid() && (no_zero_mapping == 0 || tb_c1 != '0')
                && (typebuf.tb_maplen == 0 || is_plug_map
                || (p_remap[0] != 0 && (typebuf.tb_noremap.u(typebuf.tb_off) & (RM_NONE | RM_ABBR)) == 0))
                && !(p_paste[0] != 0 && (State & (MODE_INSERT | MODE_CMDLINE)) != 0)
                && !(State == (8192 | MODE_NORMAL) && (tb_c1 == CAR || tb_c1 == ' ')) && State != MODE_ASKMORE
                && State != MODE_CONFIRM) {
            mp = get_buf_maphash_list(local_State, tb_c1);
            mp2 = get_maphash_list(local_State, tb_c1);
            if (mp == null) {
                mp = mp2;
                mp2 = null;
            }
            mp_match = null;
            mp_match_len = 0;
            for (;;) {
                if (mp == null) {
                    break;
                }
                c1: {
                    if (mp.m_keys.u(0) == tb_c1 && (mp.m_mode & local_State) != 0
                            && !(mp.m_simplified && key_protocol_enabled() && typebuf.tb_maplen == 0
                            && (typebuf.tb_noremap.u(typebuf.tb_off) & RM_SIMPLIFIED) == 0)) {
                        for (mlen = 1; mlen < typebuf.tb_len; mlen++) {
                            int c2 = typebuf.tb_buf.u(typebuf.tb_off + mlen);
                            if (mp.m_keys.u(mlen) != c2) {
                                break;
                            }
                        }
                        BytePtr[] p1 = new BytePtr[1];
                        p1[0] = mp.m_keys;
                        BytePtr p2 = mb_unescape(new Ptr<BytePtr>(p1, 0));
                        if (p2 != null && (int) mb_bytelen_tab[tb_c1] > utfc_ptr2len(p2)) {
                            mlen = 0;
                        }
                        keylen = mp.m_keylen;
                        if (mlen == keylen || (mlen == typebuf.tb_len && typebuf.tb_len < keylen)) {
                            s = typebuf.tb_noremap.add(typebuf.tb_off);
                            if ((s.u() & ~RM_SIMPLIFIED) == RM_SCRIPT
                                    && (mp.m_keys.u(0) != 128 || mp.m_keys.u(1) != KS_EXTRA
                                    || mp.m_keys.at(2) != KE_SNR)) {
                                break c1;
                            }
                            for (n = mlen; --n >= 0; ) {
                                t2 = s;
                                s = s.add(1);
                                if ((t2.u() & (RM_NONE | RM_ABBR)) != 0) {
                                    break;
                                }
                            }
                            if (!is_plug_map && n >= 0) {
                                break c1;
                            }
                            if (keylen > typebuf.tb_len) {
                                if (timedout == 0 && !(mp_match != null && mp_match.m_nowait != 0)) {
                                    keylen = -2;
                                    break;
                                }
                            } else if (keylen > mp_match_len) {
                                mp_match = mp;
                                mp_match_len = keylen;
                            }
                        } else {
                            if (max_mlen < mlen) {
                                max_mlen = mlen;
                                want_termcode = mp.m_keys.u(mlen) == 128 ? 1 : 0;
                            } else if (max_mlen == mlen && mp.m_keys.u(mlen) == 128) {
                                want_termcode = 1;
                            }
                            if (ascii_isupper(mp.m_keys.u(mlen))) {
                                want_termcode = 1;
                            }
                        }
                    }
                }
                if (mp.m_next[0] == null) {
                    mp = mp2;
                    mp2 = null;
                } else {
                    mp = mp.m_next[0];
                }
            }
            if (keylen != -2 && mp_match != null) {
                mp = mp_match;
                keylen = mp_match_len;
            }
        }
        if (!in_osc && p_pt[0].get() != NUL && mp == null && (State & (MODE_INSERT | MODE_NORMAL)) != 0) {
            for (mlen = 0; mlen < typebuf.tb_len && p_pt[0].at(mlen) != 0; mlen++) {
                if (p_pt[0].u(mlen) != typebuf.tb_buf.u(typebuf.tb_off + mlen)) {
                    break;
                }
            }
            if (p_pt[0].at(mlen) == NUL) {
                if (mlen > typebuf.tb_maplen) {
                    gotchars(typebuf.tb_buf.add(typebuf.tb_off).add(typebuf.tb_maplen), mlen - typebuf.tb_maplen);
                }
                del_typebuf(mlen, 0);
                set_option_value_give_err(BytePtr.lit("paste"), (long) (p_paste[0] == 0 ? 1 : 0), null, 0);
                if ((State & MODE_INSERT) == 0) {
                    msg_col = 0;
                    msg_row = (int) (Rows[0] - 1L);
                    msg_clr_eos();
                }
                status_redraw_all();
                redraw_statuslines();
                showmode();
                setcursor();
                keylenp = keylen;
                out__.r__ = map_result_retry;
                out__.keylenp = keylenp;
                out__.timedout = timedout;
                out__.mapdepth = mapdepth;
                return out__;
            }
            if (mlen == typebuf.tb_len) {
                keylen = -1;
            } else if (max_mlen < mlen) {
                max_mlen = mlen + 1;
            }
        }
        if (in_osc
                || ((mp == null || max_mlen + want_termcode > mp_match_len
                || (mp_match_len == 1 && mp.m_keys.get() == ESC && timedout == 0)) && keylen != -2)) {
            int save_keylen = keylen;
            if (in_osc || no_mapping == 0 || allow_keys != 0) {
                if (in_osc
                        || ((typebuf.tb_maplen == 0
                        || (p_remap[0] != 0 && (typebuf.tb_noremap.u(typebuf.tb_off) & ~RM_SIMPLIFIED) == RM_YES))
                        && timedout == 0)) {
                    keylen = check_termcode(max_mlen + 1, null, 0, null);
                } else {
                    keylen = 0;
                }
                if (keylen == 0 && save_keylen == -1 && timedout == 0) {
                    keylen = -1;
                }
                if (keylen == 0 && !no_reduce_keys) {
                    keylen = check_simplify_modifier(max_mlen + 1);
                    if (keylen < 0) {
                        out__.r__ = map_result_fail;
                        out__.keylenp = keylenp;
                        out__.timedout = timedout;
                        out__.mapdepth = mapdepth;
                        return out__;
                    }
                }
                if (keylen < 0 && typebuf.tb_len == typebuf.tb_maplen) {
                    keylen = 0;
                }
            } else {
                keylen = 0;
            }
            if (keylen == 0) {
                if (mp == null) {
                    keylenp = keylen;
                    out__.r__ = map_result_get;
                    out__.keylenp = keylenp;
                    out__.timedout = timedout;
                    out__.mapdepth = mapdepth;
                    return out__;
                }
            }
            if (keylen > 0) {
                keylenp = keylen;
                out__.r__ = map_result_retry;
                out__.keylenp = keylenp;
                out__.timedout = timedout;
                out__.mapdepth = mapdepth;
                return out__;
            }
            if (mp == null || keylen < 0) {
                keylen = -1;
            } else {
                keylen = mp_match_len;
            }
        }
        if (keylen >= 0 && keylen <= typebuf.tb_len) {
            BytePtr map_str;
            if (keylen > typebuf.tb_maplen) {
                gotchars(typebuf.tb_buf.add(typebuf.tb_off).add(typebuf.tb_maplen), keylen - typebuf.tb_maplen);
            }
            cmd_silent = typebuf.tb_silent > 0;
            del_typebuf(keylen, 0);
            if ((long) ++mapdepth >= p_mmd[0]) {
                emsg(new BytePtr(e_recursive_mapping, 0));
                if ((State & MODE_CMDLINE) != 0) {
                    redrawcmdline();
                } else {
                    setcursor();
                }
                flush_buffers(FLUSH_MINIMAL);
                mapdepth = 0;
                keylenp = keylen;
                out__.r__ = map_result_fail;
                out__.keylenp = keylenp;
                out__.timedout = timedout;
                out__.mapdepth = mapdepth;
                return out__;
            }
            if (VIsual_active && VIsual_select != 0 && (mp.m_mode & MODE_VISUAL) != 0) {
                VIsual_select = FALSE;
                ins_typebuf(BytePtr.lit("\200\365X"), -1, 0, true, FALSE);
            }
            map_str = mp.m_str;
            if (map_str == null) {
                i = false;
            } else {
                int noremap;
                if (mp.m_noremap != REMAP_YES) {
                    noremap = mp.m_noremap;
                } else if (musl_strncmp(map_str, mp.m_keys, (long) keylen) == 0
                        || (mp.m_alt != null
                        && musl_strncmp(map_str, mp.m_alt.m_keys, (long) mp.m_alt.m_keylen) == 0)) {
                    noremap = -3;
                } else {
                    noremap = REMAP_YES;
                }
                i = ins_typebuf(map_str, noremap, 0, true, cmd_silent || mp.m_silent != 0 ? 1 : 0);
            }
            keylenp = keylen;
            if ((i ? 1 : 0) == FAIL) {
                out__.r__ = map_result_fail;
                out__.keylenp = keylenp;
                out__.timedout = timedout;
                out__.mapdepth = mapdepth;
                return out__;
            }
            out__.r__ = map_result_retry;
            out__.keylenp = keylenp;
            out__.timedout = timedout;
            out__.mapdepth = mapdepth;
            return out__;
        }
        keylenp = keylen;
        out__.r__ = map_result_nomatch;
        out__.keylenp = keylenp;
        out__.timedout = timedout;
        out__.mapdepth = mapdepth;
        return out__;
    }

    private void vungetc(int c) {
        old_char = c;
        old_mod_mask = mod_mask[0];
        old_KeyStuffed = KeyStuffed;
    }

    private void check_end_reg_executing(boolean advance) {
        if (reg_executing != 0 && (typebuf.tb_maplen == 0 || pending_end_reg_executing != 0)) {
            if (advance) {
                reg_executing = 0;
                pending_end_reg_executing = FALSE;
            } else {
                pending_end_reg_executing = TRUE;
            }
        }
    }

    private int vgetorpeek(boolean advance) {
        long wait_time = 0;
        int showcmd_idx = 0;
        BytePtr ptr = null;
        T_chartabsize_T cts = new T_chartabsize_T();
        int t1 = 0;
        T_handle_mapping__out_T handle_mapping__o = new T_handle_mapping__out_T();
        int c = 0;
        int timedout = FALSE;
        int mapdepth = 0;
        boolean mode_deleted = false;
        int new_wcol = 0;
        int new_wrow = 0;
        int n = 0;
        int old_wcol = 0;
        int old_wrow = 0;
        int wait_tb_len = 0;
        if (vgetc_busy > 0 && ex_normal_busy == 0) {
            return NUL;
        }
        vgetc_busy++;
        if (advance) {
            KeyStuffed = false;
        }
        init_typebuf();
        start_stuff();
        check_end_reg_executing(advance);
        do {
            if (typeahead_char != 0) {
                c = typeahead_char;
                if (advance) {
                    typeahead_char = 0;
                }
            } else {
                c = read_readbuffers(advance);
            }
            if (c != NUL && got_int == 0) {
                if (advance) {
                    KeyStuffed = true;
                }
                if (typebuf.tb_no_abbr_cnt == 0) {
                    typebuf.tb_no_abbr_cnt = 1;
                }
            } else {
                for (;;) {
                    int keylen = 0;
                    check_end_reg_executing(advance);
                    if (typebuf.tb_maplen != 0) {
                        line_breakcheck();
                    } else {
                        ui_breakcheck();
                    }
                    if (got_int != 0) {
                        c = inchar(typebuf.tb_buf, typebuf.tb_buflen - 1, 0L);
                        if ((c != 0 || typebuf.tb_maplen != 0) && (State & (MODE_INSERT | MODE_CMDLINE)) != 0) {
                            c = ESC;
                        } else {
                            c = Ctrl_C;
                        }
                        flush_buffers(FLUSH_INPUT);
                        if (advance) {
                            typebuf.tb_buf.put((byte) c);
                            gotchars(typebuf.tb_buf, 1);
                        }
                        cmd_silent = false;
                        break;
                    } else if (typebuf.tb_len > 0) {
                        handle_mapping__o = handle_mapping(keylen, timedout, mapdepth);
                        keylen = handle_mapping__o.keylenp;
                        timedout = handle_mapping__o.timedout;
                        int result = handle_mapping__o.r__;
                        if (result == map_result_retry) {
                            continue;
                        }
                        if (result == map_result_fail) {
                            c = -1;
                            break;
                        }
                        if (result == map_result_get) {
                            c = typebuf.tb_buf.u(typebuf.tb_off);
                            if (advance) {
                                cmd_silent = typebuf.tb_silent > 0;
                                if (typebuf.tb_maplen > 0) {
                                    KeyTyped = false;
                                } else {
                                    KeyTyped = true;
                                    gotchars(typebuf.tb_buf.add(typebuf.tb_off), 1);
                                }
                                KeyNoremap = typebuf.tb_noremap.u(typebuf.tb_off) & ~RM_SIMPLIFIED;
                                del_typebuf(1, 0);
                            }
                            break;
                        }
                    }
                    c = 0;
                    new_wcol = curwin.w_wcol;
                    new_wrow = curwin.w_wrow;
                    if (advance && typebuf.tb_len == 1 && typebuf.tb_buf.at(typebuf.tb_off) == ESC && no_mapping == 0
                            && kitty_protocol_state != KKPS_ENABLED && ex_normal_busy == 0 && typebuf.tb_maplen == 0
                            && (State & MODE_INSERT) != 0
                            && (p_timeout[0] != 0 || (keylen == -1 && p_ttimeout[0] != 0))
                            && (c = inchar(typebuf.tb_buf.add(typebuf.tb_off).add(typebuf.tb_len), 3, 25L)) == 0) {
                        int col = 0;
                        if (mode_displayed) {
                            unshowmode(true);
                            mode_deleted = true;
                        }
                        validate_cursor();
                        old_wcol = curwin.w_wcol;
                        old_wrow = curwin.w_wrow;
                        if (curwin.w_cursor.col != 0) {
                            if (curwin.w_wcol > 0) {
                                if (did_ai && skipwhite(ml_get_curline().add(curwin.w_cursor.col)).get() == NUL) {
                                    curwin.w_wcol = 0;
                                    ptr = ml_get_curline();
                                    init_chartabsize_arg(cts, curwin, curwin.w_cursor.lnum, 0, ptr, ptr);
                                    while (cts.cts_ptr.lt(ptr.add(curwin.w_cursor.col))) {
                                        if (!(cts.cts_ptr.get() == ' ' || cts.cts_ptr.get() == '\t')) {
                                            curwin.w_wcol = cts.cts_vcol;
                                        }
                                        cts.cts_vcol += lbr_chartabsize(cts);
                                        cts.cts_ptr = cts.cts_ptr.add(utfc_ptr2len(cts.cts_ptr));
                                    }
                                    curwin.w_wrow = curwin.w_cline_row + curwin.w_wcol / curwin.w_width;
                                    curwin.w_wcol %= curwin.w_width;
                                    curwin.w_wcol += curwin_col_off();
                                    col = 0;
                                } else {
                                    curwin.w_wcol--;
                                    col = curwin.w_cursor.col - 1;
                                }
                            } else if (curwin.w_onebuf_opt.wo_wrap[0] != 0 && curwin.w_wrow != 0) {
                                curwin.w_wrow--;
                                curwin.w_wcol = curwin.w_width - 1;
                                col = curwin.w_cursor.col - 1;
                            }
                            if (col > 0 && curwin.w_wcol > 0) {
                                ptr = ml_get_curline();
                                col -= utf_head_off(ptr, ptr.add(col));
                                if (utf_ptr2cells(ptr.add(col)) > 1) {
                                    curwin.w_wcol--;
                                }
                            }
                        }
                        setcursor();
                        out_flush();
                        new_wcol = curwin.w_wcol;
                        new_wrow = curwin.w_wrow;
                        curwin.w_wcol = old_wcol;
                        curwin.w_wrow = old_wrow;
                    }
                    if (c < 0) {
                        continue;
                    }
                    for (n = 1; n <= c; n++) {
                        typebuf.tb_noremap.set(typebuf.tb_off + n, (byte) RM_YES);
                    }
                    typebuf.tb_len += c;
                    if (typebuf.tb_len >= typebuf.tb_maplen + MAXMAPLEN) {
                        timedout = TRUE;
                        continue;
                    }
                    if (ex_normal_busy > 0) {
                        if (typebuf.tb_len > 0) {
                            timedout = TRUE;
                            continue;
                        }
                        if (p_im[0] != 0 && (State & MODE_INSERT) != 0) {
                            c = Ctrl_L;
                        } else if ((State & MODE_CMDLINE) != 0) {
                            c = Ctrl_C;
                        } else {
                            c = ESC;
                        }
                        typebuf.tb_no_abbr_cnt = 0;
                        break;
                    }
                    if (((State & MODE_INSERT) != 0 || p_lz[0] != 0) && (State & MODE_CMDLINE) == 0 && advance
                            && must_redraw != 0 && need_wait_return == 0) {
                        update_screen(0);
                        setcursor();
                    }
                    showcmd_idx = 0;
                    boolean showing_partial = false;
                    if (typebuf.tb_len > 0 && advance) {
                        if ((State & (MODE_NORMAL | MODE_INSERT)) != 0 && State != (8192 | MODE_NORMAL)) {
                            if ((State & MODE_INSERT) != 0
                                    && ptr2cells(typebuf.tb_buf.add(typebuf.tb_off).add(typebuf.tb_len).add(-1)) == 1) {
                                edit_putchar(typebuf.tb_buf.u(typebuf.tb_off + typebuf.tb_len - 1), false);
                                setcursor();
                                showing_partial = true;
                            }
                            old_wcol = curwin.w_wcol;
                            old_wrow = curwin.w_wrow;
                            curwin.w_wcol = new_wcol;
                            curwin.w_wrow = new_wrow;
                            push_showcmd();
                            if (typebuf.tb_len > SHOWCMD_COLS) {
                                showcmd_idx = typebuf.tb_len - SHOWCMD_COLS;
                            }
                            while (showcmd_idx < typebuf.tb_len) {
                                add_byte_to_showcmd(typebuf.tb_buf.at(typebuf.tb_off + showcmd_idx++));
                            }
                            curwin.w_wcol = old_wcol;
                            curwin.w_wrow = old_wrow;
                        }
                        if ((State & MODE_CMDLINE) != 0 && get_cmdline_info().cmdbuff != null
                                && ptr2cells(typebuf.tb_buf.add(typebuf.tb_off).add(typebuf.tb_len).add(-1)) == 1) {
                            putcmdline(typebuf.tb_buf.u(typebuf.tb_off + typebuf.tb_len - 1), FALSE);
                            showing_partial = true;
                        }
                    }
                    if (typebuf.tb_len == 0) {
                        timedout = FALSE;
                    }
                    if (advance) {
                        if (typebuf.tb_len == 0 || !(p_timeout[0] != 0 || (p_ttimeout[0] != 0 && keylen == -1))) {
                            wait_time = -1L;
                        } else if (keylen == -1 && p_ttm[0] >= 0L) {
                            wait_time = p_ttm[0];
                        } else {
                            wait_time = p_tm[0];
                        }
                    } else {
                        wait_time = 0L;
                    }
                    wait_tb_len = typebuf.tb_len;
                    c = inchar(typebuf.tb_buf.add(typebuf.tb_off).add(typebuf.tb_len),
                            typebuf.tb_buflen - typebuf.tb_off - typebuf.tb_len - 1, wait_time);
                    if (showcmd_idx != 0) {
                        pop_showcmd();
                    }
                    if (showing_partial) {
                        if ((State & MODE_INSERT) != 0) {
                            edit_unputchar();
                        }
                        if ((State & MODE_CMDLINE) != 0 && get_cmdline_info().cmdbuff != null) {
                            unputcmdline();
                        } else {
                            setcursor();
                        }
                    }
                    if (c < 0) {
                        continue;
                    }
                    if (c == NUL) {
                        if (!advance) {
                            break;
                        }
                        if (wait_tb_len > 0) {
                            timedout = TRUE;
                            continue;
                        }
                    } else {
                        while (typebuf.tb_buf.at(typebuf.tb_off + typebuf.tb_len) != NUL) {
                            t1 = typebuf.tb_len;
                            typebuf.tb_len++;
                            typebuf.tb_noremap.set(typebuf.tb_off + t1, (byte) RM_YES);
                        }
                    }
                }
            }
        } while ((c < 0 && c != K_CANCEL) || (advance && c == NUL));
        if (advance && p_smd[0] != 0 && msg_silent == 0 && (State & MODE_INSERT) != 0) {
            if (c == ESC && !mode_deleted && no_mapping == 0 && mode_displayed) {
                if (typebuf.tb_len != 0 && !KeyTyped) {
                    redraw_cmdline = TRUE;
                } else {
                    unshowmode(false);
                }
            } else if (c != ESC && mode_deleted) {
                if (typebuf.tb_len != 0 && !KeyTyped) {
                    redraw_cmdline = TRUE;
                } else {
                    showmode();
                }
            }
        }
        if (timedout != 0 && c == ESC) {
            gotchars_ignore();
        }
        vgetc_busy--;
        return c;
    }

    private int inchar(BytePtr buf, int maxlen, long wait_time) {
        boolean t1 = false;
        int len = 0;
        int tb_change_cnt = typebuf.tb_change_cnt;
        if (wait_time == -1L || wait_time > 100L) {
            cursor_on();
            out_flush_cursor(false, false);
        }
        if (State != (8192 | MODE_NORMAL)) {
            did_outofmem_msg = false;
        }
        undo_off = false;
        if (got_int != 0) {
            byte[] dum = new byte[154];
            for (;;) {
                len = ui_inchar(new BytePtr(dum, 0), MAXMAPLEN * 3 + 3, 0L, 0);
                if (len == 0 || (len == 1 && dum[0] == Ctrl_C)) {
                    break;
                }
            }
            return FALSE;
        }
        if (wait_time == -1L || wait_time > 10L) {
            out_flush();
        }
        len = ui_inchar(buf, maxlen / 3, wait_time, tb_change_cnt);
        if (typebuf_changed(tb_change_cnt)) {
            return 0;
        }
        t1 = len > 0;
        if (t1) {
            typebuf.tb_change_cnt++;
            t1 = typebuf.tb_change_cnt == 0;
        }
        if (t1) {
            typebuf.tb_change_cnt = 1;
        }
        return fix_input_buffer(buf, len);
    }

    private static int fix_input_buffer(BytePtr buf, int len) {
        int i = 0;
        BytePtr p = buf;
        for (i = len; --i >= 0; p = p.add(1)) {
            if (p.at(0) == NUL
                    || (p.u(0) == 128
                    && (i < 2 || p.u(1) != KS_EXTRA || (p.at(2) != KE_CURSORHOLD && p.at(2) != KE_COMPLETE_DELAY)))) {
                Rt.memmove(p.add(3), p.add(1), (long) i);
                p.set(2, (byte) (p.u(0) == 128 || p.at(0) == NUL ? 'X' : (-p.u(0) >>> 8) & 255));
                p.set(1, (byte) (p.u(0) == 128 ? KS_SPECIAL : (p.at(0) == NUL ? KS_ZERO : -p.u(0) & 255)));
                p.set(0, (byte) -128);
                p = p.add(2);
                len += 2;
            }
        }
        p.put((byte) NUL);
        return len;
    }

    private boolean input_available() {
        return !vim_is_input_buf_empty();
    }

    private BytePtr getcmdkeycmd(int promptc, int indent, int do_concat) {
        S_growarray line_ga = new S_growarray();
        int c1 = -1;
        int c2 = 0;
        int cmod = 0;
        boolean aborted = false;
        ga_init2(line_ga, 1L, 32);
        no_mapping++;
        got_int = FALSE;
        while (c1 != NUL && !aborted) {
            if (!ga_grow(line_ga, 32)) {
                aborted = true;
                break;
            }
            if (vgetorpeek(false) == NUL) {
                emsg(new BytePtr(e_cmd_mapping_must_end_with_cr, 0));
                aborted = true;
                break;
            }
            c1 = vgetorpeek(true);
            if (c1 == 128) {
                c1 = vgetorpeek(true);
                c2 = vgetorpeek(true);
                if (c1 == KS_MODIFIER) {
                    cmod = c2;
                    continue;
                }
                c1 = c1 == KS_SPECIAL ? 128 : (c1 == KS_ZERO ? -(KS_ZERO + ('X' << 8)) : -(c1 + (c2 << 8)));
                if (c1 == K_ESC) {
                    c1 = ESC;
                }
            }
            if (got_int != 0) {
                aborted = true;
            } else if (c1 == '\r' || c1 == '\n') {
                c1 = NUL;
            } else if (c1 == ESC) {
                aborted = true;
            } else if (c1 == K_COMMAND || c1 == K_SCRIPT_COMMAND) {
                emsg(new BytePtr(e_cmd_mapping_must_end_with_cr_before_second_cmd, 0));
                aborted = true;
            } else if (c1 == K_SNR) {
                ga_concat_len(line_ga, BytePtr.lit("<SNR>"), 5L);
            } else {
                if (cmod != 0) {
                    ga_append(line_ga, 128);
                    ga_append(line_ga, KS_MODIFIER);
                    ga_append(line_ga, cmod);
                }
                if (c1 < 0) {
                    ga_append(line_ga, 128);
                    ga_append(line_ga, c1 == 128 ? KS_SPECIAL : (c1 == NUL ? KS_ZERO : -c1 & 255));
                    ga_append(line_ga, c1 == 128 || c1 == NUL ? 'X' : (-c1 >>> 8) & 255);
                } else {
                    ga_append(line_ga, c1);
                }
            }
            cmod = 0;
        }
        no_mapping--;
        if (aborted) {
            ga_clear(line_ga);
        }
        return GA_BytePtr(line_ga);
    }

    private boolean do_cmdkey_command(int key, int flags) {
        boolean res = do_cmdline(null, fp_getcmdkeycmd, flags);
        return res;
    }

    private void init_highlight(boolean both, boolean reset) {
        int i = 0;
        Ptr<BytePtr> pp;
        if (both) {
            init_highlight_had_both = true;
            pp = new Ptr<BytePtr>(highlight_init_both, 0);
            for (i = 0; pp.at(i) != null; i++) {
                do_highlight(pp.at(i), reset, true);
            }
        } else if (!init_highlight_had_both) {
            return;
        }
        if (p_bg[0].get() == 'l') {
            pp = new Ptr<BytePtr>(highlight_init_light, 0);
        } else {
            pp = new Ptr<BytePtr>(highlight_init_dark, 0);
        }
        for (i = 0; pp.at(i) != null; i++) {
            do_highlight(pp.at(i), reset, true);
        }
        if (t_colors < 8) {
            do_highlight(BytePtr.lit("Visual term=reverse cterm=reverse ctermbg=NONE ctermfg=NONE"), false, true);
        }
        if (t_colors <= 8) {
            if (p_bg[0].get() == 'l') {
                do_highlight(BytePtr.lit("Search ctermfg=black"), false, true);
            }
        }
        resolve_fallback_fg_to_rgb();
        resolve_fallback_bg_to_rgb();
    }

    private T_lookup_color__out_T lookup_color(int idx, boolean foreground, int boldp) {
        T_lookup_color__out_T out__ = new T_lookup_color__out_T();
        int color = color_numbers_16[idx];
        BytePtr p;
        if (color < 0) {
            out__.r__ = -1;
            out__.boldp = boldp;
            return out__;
        }
        if (t_colors == 8) {
            color = color_numbers_8[idx];
            if (foreground) {
                if ((color & 8) != 0) {
                    boldp = TRUE;
                } else {
                    boldp = FALSE;
                }
            }
            color &= 7;
        } else if (t_colors == 16 || t_colors == 88 || t_colors >= 256) {
            if (term_strings[KS_CAF].get() != NUL) {
                p = term_strings[KS_CAF];
            } else {
                p = term_strings[KS_CSF];
            }
            if (p.get() != NUL && (t_colors > 256 || p.add((int) musl_strlen(p)).add(-1).get() == 'm')) {
                if (t_colors == 88) {
                    color = color_numbers_88[idx];
                } else if (t_colors >= 256) {
                    color = color_numbers_256[idx];
                } else {
                    color = color_numbers_8[idx];
                }
            }
        }
        out__.r__ = color;
        out__.boldp = boldp;
        return out__;
    }

    private void highlight_group_link(BytePtr from_hg, int from_len, BytePtr to_hg, int to_len, boolean dodefault,
            boolean forceit, boolean init) {
        int to_id;
        T_hl_group_T hlgroup = null;
        int from_id = syn_check_group(from_hg, from_len);
        if (musl_strncmp(to_hg, BytePtr.lit("NONE"), 4L) == 0) {
            to_id = 0;
        } else {
            to_id = syn_check_group(to_hg, to_len);
        }
        if (from_id > 0) {
            hlgroup = GA_Ptr_T_hl_group_T(highlight_ga).at(from_id - 1);
            if (dodefault && (forceit || hlgroup.sg_deflink == 0)) {
                hlgroup.sg_deflink = to_id;
            }
        }
        if (from_id > 0 && (!init || hlgroup.sg_set == 0)) {
            if (to_id > 0 && !forceit && !init && hl_has_settings(from_id - 1, dodefault)) {
                if (GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_name == null && !dodefault) {
                    emsg(new BytePtr(e_group_has_settings_highlight_link_ignored, 0));
                }
            } else if (hlgroup.sg_link != to_id || hlgroup.sg_cleared) {
                if (!init) {
                    hlgroup.sg_set |= SG_LINK;
                }
                hlgroup.sg_link = to_id;
                hlgroup.sg_cleared = false;
                redraw_all_later(UPD_SOME_VALID);
                need_highlight_changed = true;
            }
        }
    }

    private void highlight_reset_all() {
        int idx = 0;
        restore_cterm_colors();
        for (idx = 0; idx < highlight_ga.ga_len; idx++) {
            highlight_clear(idx);
        }
        init_highlight(true, true);
        highlight_changed();
        redraw_later_clear();
    }

    private boolean highlight_set_termgui_attr(int idx, BytePtr key, BytePtr arg, boolean init) {
        T_keyvalue_T target = new T_keyvalue_T();
        Ptr<T_keyvalue_T> entry = null;
        int attr = 0;
        long off = 0L;
        target.key = 0;
        target.value.length = 0L;
        while (arg.at((int) off) != NUL) {
            target.value.string[0] = arg.add((int) off);
            entry = keyvalue_bsearch(target, new Ptr<T_keyvalue_T>(highlight_tab, 0), 13L, fp_cmp_keyvalue_value_ni);
            if (entry == null) {
                vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_illegal_value_str, 0), arg);
                emsg(iobuff_or(new BytePtr(e_illegal_value_str, 0)));
                return false;
            }
            attr |= entry.get().key;
            off += entry.get().value.length;
            if (arg.at((int) off) == ',') {
                off++;
            }
        }
        if (key.get() == 'T') {
            if (!init || (GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set & SG_TERM) == 0) {
                if (!init) {
                    GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set |= SG_TERM;
                }
                GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_term = attr;
            }
        } else if (key.get() == 'C') {
            if (!init || (GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set & SG_CTERM) == 0) {
                if (!init) {
                    GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set |= SG_CTERM;
                }
                GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm = attr;
                GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm_bold = false;
            }
        }
        return true;
    }

