    private boolean highlight_set_cterm_font(int idx, BytePtr arg, boolean init) {
        int font;
        if (init && (GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set & SG_CTERM) != 0) {
            return false;
        }
        if (!init) {
            GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set |= SG_CTERM;
        }
        if (ascii_isdigit(arg.u())) {
            font = musl_atoi(arg);
        } else if (musl_strcasecmp(arg, BytePtr.lit("NONE")) == 0) {
            font = -1;
        } else {
            return false;
        }
        GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm_font = font + 1;
        return true;
    }

    private boolean highlight_set_cterm_color(int idx, BytePtr key, BytePtr key_start, BytePtr arg,
            boolean is_normal_group, boolean init) {
        T_lookup_color__out_T lookup_color__o = new T_lookup_color__out_T();
        int color;
        if (init && (GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set & SG_CTERM) != 0) {
            return false;
        }
        if (!init) {
            GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set |= SG_CTERM;
        }
        if (key.at(5) == 'F' && GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm_bold) {
            GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm &= ~HL_BOLD;
            GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm_bold = false;
        }
        if (ascii_isdigit(arg.u())) {
            color = musl_atoi(arg);
        } else if (musl_strcasecmp(arg, BytePtr.lit("fg")) == 0) {
            if (cterm_normal_fg_color != 0) {
                color = cterm_normal_fg_color - 1;
            } else {
                emsg(new BytePtr(e_fg_color_unknown, 0));
                return false;
            }
        } else if (musl_strcasecmp(arg, BytePtr.lit("bg")) == 0) {
            if (cterm_normal_bg_color > 0) {
                color = cterm_normal_bg_color - 1;
            } else {
                emsg(new BytePtr(e_bg_color_unknown, 0));
                return false;
            }
        } else if (musl_strcasecmp(arg, BytePtr.lit("ul")) == 0) {
            if (cterm_normal_ul_color > 0) {
                color = cterm_normal_ul_color - 1;
            } else {
                emsg(new BytePtr(e_ul_color_unknown, 0));
                return false;
            }
        } else {
            int bold = MAYBE;
            T_keyvalue_T target = new T_keyvalue_T();
            Ptr<T_keyvalue_T> entry;
            target.key = 0;
            target.value.string[0] = arg;
            target.value.length = 0L;
            entry = keyvalue_bsearch(target, new Ptr<T_keyvalue_T>(color_name_tab, 0), 28L, fp_cmp_keyvalue_value_i);
            if (entry == null) {
                vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_color_name_or_number_not_recognized_str, 0),
                        key_start);
                emsg(iobuff_or(new BytePtr(e_color_name_or_number_not_recognized_str, 0)));
                return false;
            }
            lookup_color__o = lookup_color(entry.get().key, key.at(5) == 'F', bold);
            bold = lookup_color__o.boldp;
            color = lookup_color__o.r__;
            if (bold == TRUE) {
                GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm |= HL_BOLD;
                GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm_bold = true;
            } else if (bold == FALSE) {
                GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm &= ~HL_BOLD;
            }
        }
        if (key.at(5) == 'F') {
            highlight_set_ctermfg(idx, color, is_normal_group);
        } else if (key.at(5) == 'B') {
            highlight_set_ctermbg(idx, color, is_normal_group);
        } else {
            highlight_set_ctermul(idx, color, is_normal_group);
        }
        return true;
    }

    private boolean highlight_set_startstop_termcode(int idx, BytePtr key, BytePtr arg, boolean init) {
        BytePtr t1 = null;
        int off = 0;
        byte[] buf = new byte[100];
        int len = 0;
        BytePtr tname = null;
        BytePtr[] p = new BytePtr[1];
        if (!init) {
            GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set |= SG_TERM;
        }
        if (musl_strncmp(arg, BytePtr.lit("t_"), 2L) == 0) {
            off = 0;
            buf[0] = 0;
            while (arg.at(off) != NUL) {
                for (len = 0; arg.at(off + len) != 0 && arg.at(off + len) != ','; len++) {
                }
                tname = vim_strnsave(arg.add(off), (long) len);
                p[0] = get_term_code(tname);
                if (p[0] == null) {
                    p[0] = BytePtr.lit("");
                }
                if ((int) (musl_strlen(new BytePtr(buf, 0)) + musl_strlen(p[0])) >= 99) {
                    vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_terminal_code_too_long_str, 0), arg);
                    emsg(iobuff_or(new BytePtr(e_terminal_code_too_long_str, 0)));
                    return false;
                }
                musl_strcat(new BytePtr(buf, 0), p[0]);
                off += len;
                if (arg.at(off) == ',') {
                    off++;
                }
            }
        } else {
            p[0] = arg;
            for (off = 0; off < 94 && p[0].get() != 0; ) {
                len = trans_special(new Ptr<BytePtr>(p, 0), new BytePtr(buf, 0).add(off), FSK_SIMPLIFY, false, null);
                if (len > 0) {
                    off += len;
                } else {
                    t1 = p[0];
                    p[0] = p[0].add(1);
                    buf[off++] = t1.get();
                }
            }
            buf[off] = NUL;
        }
        if (musl_strcmp(new BytePtr(buf, 0), BytePtr.lit("NONE")) == 0) {
            p[0] = null;
        } else {
            p[0] = vim_strsave(new BytePtr(buf, 0));
        }
        if (key.at(2) == 'A') {
            GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_start = p[0];
        } else {
            GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_stop = p[0];
        }
        return true;
    }

    private void do_highlight(BytePtr line, boolean forceit, boolean init) {
        BytePtr name_end;
        BytePtr linep;
        BytePtr key_start = null;
        BytePtr arg_start = null;
        BytePtr key = null;
        BytePtr arg = null;
        long i = 0;
        int id;
        int idx;
        T_hl_group_T item_before = new T_hl_group_T();
        boolean did_change = false;
        boolean dodefault = false;
        boolean doclear = false;
        boolean dolink = false;
        boolean error = false;
        boolean is_normal_group = false;
        if (!init && ends_excmd2(line.add(-1), line)) {
            for (i = 1L; i <= (long) highlight_ga.ga_len && got_int == 0; i++) {
                highlight_list_one((int) i);
            }
            return;
        }
        name_end = skiptowhite(line);
        linep = skipwhite(name_end);
        if (musl_strncmp(line, BytePtr.lit("default"), name_end.sub(line)) == 0) {
            dodefault = true;
            line = linep;
            name_end = skiptowhite(line);
            linep = skipwhite(name_end);
        }
        if (musl_strncmp(line, BytePtr.lit("clear"), name_end.sub(line)) == 0) {
            doclear = true;
        }
        if (musl_strncmp(line, BytePtr.lit("link"), name_end.sub(line)) == 0) {
            dolink = true;
        }
        if (!doclear && !dolink && ends_excmd2(line, linep)) {
            id = syn_namen2id(line, (int) name_end.sub(line));
            if (id == 0) {
                vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_highlight_group_name_not_found_str, 0), line);
                emsg(iobuff_or(new BytePtr(e_highlight_group_name_not_found_str, 0)));
            } else {
                highlight_list_one(id);
            }
            return;
        }
        if (dolink) {
            BytePtr from_start = linep;
            int from_len;
            int to_len;
            BytePtr from_end = skiptowhite(from_start);
            BytePtr to_start = skipwhite(from_end);
            BytePtr to_end = skiptowhite(to_start);
            if (ends_excmd2(line, from_start) || ends_excmd2(line, to_start)) {
                vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_not_enough_arguments_highlight_link_str, 0),
                        from_start);
                emsg(iobuff_or(new BytePtr(e_not_enough_arguments_highlight_link_str, 0)));
                return;
            }
            if (!ends_excmd2(line, skipwhite(to_end))) {
                vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_too_many_arguments_highlight_link_str, 0),
                        from_start);
                emsg(iobuff_or(new BytePtr(e_too_many_arguments_highlight_link_str, 0)));
                return;
            }
            from_len = (int) from_end.sub(from_start);
            to_len = (int) to_end.sub(to_start);
            highlight_group_link(from_start, from_len, to_start, to_len, dodefault, forceit, init);
            return;
        }
        if (doclear) {
            if (ends_excmd2(line, linep)) {
                highlight_reset_all();
                return;
            }
            line = linep;
            name_end = skiptowhite(line);
            linep = skipwhite(name_end);
        }
        id = syn_check_group(line, (int) name_end.sub(line));
        if (id == 0) {
            return;
        }
        idx = id - 1;
        if (dodefault && hl_has_settings(idx, true)) {
            return;
        }
        item_before.set(GA_Ptr_T_hl_group_T(highlight_ga).at(idx));
        if (musl_strcmp(GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_name_u, BytePtr.lit("NORMAL")) == 0) {
            is_normal_group = true;
        }
        if (doclear || (forceit && init)) {
            highlight_clear(idx);
            if (!doclear) {
                GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set = 0;
            }
        }
        if (!doclear) {
            while (!ends_excmd2(line, linep)) {
                key_start = linep;
                if (linep.get() == '=') {
                    vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_unexpected_equal_sign_str, 0), key_start);
                    emsg(iobuff_or(new BytePtr(e_unexpected_equal_sign_str, 0)));
                    error = true;
                    break;
                }
                while (linep.get() != 0 && !(linep.get() == ' ' || linep.get() == '\t') && linep.get() != '=') {
                    linep = linep.add(1);
                }
                key = vim_strnsave_up(key_start, linep.sub(key_start));
                linep = skipwhite(linep);
                if (musl_strcmp(key, BytePtr.lit("NONE")) == 0) {
                    if (!init || GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set == 0) {
                        if (!init) {
                            GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set |= SG_TERM + SG_CTERM + SG_GUI;
                        }
                        highlight_clear(idx);
                    }
                    continue;
                }
                if (linep.get() != '=') {
                    vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_missing_equal_sign_str_2, 0), key_start);
                    emsg(iobuff_or(new BytePtr(e_missing_equal_sign_str_2, 0)));
                    error = true;
                    break;
                }
                linep = linep.add(1);
                linep = skipwhite(linep);
                if (linep.get() == '\'') {
                    linep = linep.add(1);
                    arg_start = linep;
                    linep = vim_strchr(linep, '\'');
                    if (linep == null) {
                        vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_invalid_argument_str, 0), key_start);
                        emsg(iobuff_or(new BytePtr(e_invalid_argument_str, 0)));
                        error = true;
                        break;
                    }
                } else {
                    arg_start = linep;
                    linep = skiptowhite(linep);
                }
                if (BytePtr.eq(linep, arg_start)) {
                    vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_missing_argument_str, 0), key_start);
                    emsg(iobuff_or(new BytePtr(e_missing_argument_str, 0)));
                    error = true;
                    break;
                }
                arg = vim_strnsave(arg_start, linep.sub(arg_start));
                if (linep.get() == '\'') {
                    linep = linep.add(1);
                }
                if (musl_strcmp(key, BytePtr.lit("TERM")) == 0 || musl_strcmp(key, BytePtr.lit("CTERM")) == 0
                        || musl_strcmp(key, BytePtr.lit("GUI")) == 0) {
                    if (!highlight_set_termgui_attr(idx, key, arg, init)) {
                        error = true;
                        break;
                    }
                } else if (musl_strcmp(key, BytePtr.lit("FONT")) == 0) {
                } else if (musl_strcmp(key, BytePtr.lit("CTERMFG")) == 0
                        || musl_strcmp(key, BytePtr.lit("CTERMBG")) == 0
                        || musl_strcmp(key, BytePtr.lit("CTERMUL")) == 0) {
                    if (!highlight_set_cterm_color(idx, key, key_start, arg, is_normal_group, init)) {
                        error = true;
                        break;
                    }
                } else if (musl_strcmp(key, BytePtr.lit("CTERMFONT")) == 0) {
                    if (!highlight_set_cterm_font(idx, arg, init)) {
                        error = true;
                        break;
                    }
                } else if (musl_strcmp(key, BytePtr.lit("GUIFG")) == 0) {
                } else if (musl_strcmp(key, BytePtr.lit("GUIBG")) == 0) {
                } else if (musl_strcmp(key, BytePtr.lit("GUISP")) == 0) {
                } else if (musl_strcmp(key, BytePtr.lit("START")) == 0 || musl_strcmp(key, BytePtr.lit("STOP")) == 0) {
                    if (!highlight_set_startstop_termcode(idx, key, arg, init)) {
                        error = true;
                        break;
                    }
                } else {
                    vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_illegal_argument_str_3, 0), key_start);
                    emsg(iobuff_or(new BytePtr(e_illegal_argument_str_3, 0)));
                    error = true;
                    break;
                }
                GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cleared = false;
                if (!init || (GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set & SG_LINK) == 0) {
                    GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_link = 0;
                }
                linep = skipwhite(linep);
            }
        }
        if (error && idx == highlight_ga.ga_len) {
            syn_unadd_group();
        } else {
            if (is_normal_group) {
                GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_term_attr = 0;
                GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm_attr = 0;
                resolve_fallback_fg_to_rgb();
                resolve_fallback_bg_to_rgb();
            } else {
                set_hl_attr(idx);
            }
        }
        if (did_change || (GA_Ptr_T_hl_group_T(highlight_ga).at(idx).eq(item_before) ? 0 : 1) != 0) {
            if (updating_screen == 0) {
                redraw_all_later(UPD_NOT_VALID);
            }
            need_highlight_changed = true;
        }
    }

