    private int get_attr_entry(S_growarray table, S_attr_entry aep) {
        int i = 0;
        S_attr_entry taep = null;
        table.ga_itemsize = 24;
        table.ga_growsize = 7;
        for (i = 0; i < table.ga_len; i++) {
            taep = GA_Ptr_S_attr_entry(table).at(i);
            if ((int) aep.ae_attr == (int) taep.ae_attr
                    && ((table == term_attr_table
                    && (aep.ae_u.term.start == null ? 1 : 0) == (taep.ae_u.term.start == null ? 1 : 0)
                    && (aep.ae_u.term.start == null || musl_strcmp(aep.ae_u.term.start, taep.ae_u.term.start) == 0)
                    && (aep.ae_u.term.stop == null ? 1 : 0) == (taep.ae_u.term.stop == null ? 1 : 0)
                    && (aep.ae_u.term.stop == null || musl_strcmp(aep.ae_u.term.stop, taep.ae_u.term.stop) == 0))
                    || (table == cterm_attr_table
                    && (aep.ae_u.cterm.fg_color & 0xffff) == (taep.ae_u.cterm.fg_color & 0xffff)
                    && (aep.ae_u.cterm.bg_color & 0xffff) == (taep.ae_u.cterm.bg_color & 0xffff)
                    && (aep.ae_u.cterm.ul_color & 0xffff) == (taep.ae_u.cterm.ul_color & 0xffff)
                    && (aep.ae_u.cterm.font & 0xffff) == (taep.ae_u.cterm.font & 0xffff)))) {
                return i + (HL_ALL + 1);
            }
        }
        if (table.ga_len + (HL_ALL + 1) > MAX_TYPENR) {
            if (get_attr_entry_recursive) {
                emsg(new BytePtr(e_too_many_different_highlighting_attributes_in_use, 0));
                return 0;
            }
            get_attr_entry_recursive = true;
            clear_hl_tables();
            set_must_redraw(UPD_CLEAR);
            for (i = 0; i < highlight_ga.ga_len; i++) {
                set_hl_attr(i);
            }
            get_attr_entry_recursive = false;
        }
        if (!ga_grow(table, 1)) {
            return 0;
        }
        taep = GA_Ptr_S_attr_entry(table).at(table.ga_len);
        taep.zero();
        taep.ae_attr = aep.ae_attr;
        if (table == term_attr_table) {
            if (aep.ae_u.term.start == null) {
                taep.ae_u.term.start = null;
            } else {
                taep.ae_u.term.start = vim_strsave(aep.ae_u.term.start);
            }
            if (aep.ae_u.term.stop == null) {
                taep.ae_u.term.stop = null;
            } else {
                taep.ae_u.term.stop = vim_strsave(aep.ae_u.term.stop);
            }
        } else if (table == cterm_attr_table) {
            taep.ae_u.cterm.fg_color = aep.ae_u.cterm.fg_color;
            taep.ae_u.cterm.bg_color = aep.ae_u.cterm.bg_color;
            taep.ae_u.cterm.ul_color = aep.ae_u.cterm.ul_color;
            taep.ae_u.cterm.font = aep.ae_u.cterm.font;
        }
        table.ga_len++;
        return table.ga_len - 1 + (HL_ALL + 1);
    }

