    private int get_indent_str(BytePtr ptr, int ts, boolean no_ts) {
        int count = 0;
        for (; ptr.get() != 0; ptr = ptr.add(1)) {
            if (ptr.get() == TAB) {
                if (!no_ts) {
                    count += ts - count % ts;
                } else {
                    count += ptr2cells(ptr);
                }
            } else if (ptr.get() == ' ') {
                count++;
            } else {
                break;
            }
        }
        return count;
    }

