    private void change_indent(int type, int amount, boolean round, int replaced, int call_changed_bytes) {
        int vcol;
        int last_vcol;
        int insstart_less;
        int new_cursor_col;
        int i;
        BytePtr ptr;
        int save_p_list;
        int start_col;
        int vc;
        int orig_col = 0;
        BytePtr new_line;
        BytePtr orig_line = null;
        if ((State & VREPLACE_FLAG) != 0) {
            int len = ml_get_curline_len();
            orig_line = vim_strnsave(ml_get_curline(), (long) len);
            orig_col = curwin.w_cursor.col;
        }
        save_p_list = curwin.w_onebuf_opt.wo_list[0];
        curwin.w_onebuf_opt.wo_list[0] = FALSE;
        vc = getvcol_nolist(curwin.w_cursor);
        vcol = vc;
        start_col = curwin.w_cursor.col;
        new_cursor_col = curwin.w_cursor.col;
        beginline(BL_WHITE);
        new_cursor_col -= curwin.w_cursor.col;
        insstart_less = curwin.w_cursor.col;
        if (new_cursor_col < 0) {
            vcol = get_indent() - vcol;
        }
        if (new_cursor_col > 0) {
            start_col = -1;
        }
        if (type == INDENT_SET) {
            set_indent(amount, call_changed_bytes != 0 ? SIN_CHANGED : 0);
        } else {
            int save_State = State;
            if ((State & VREPLACE_FLAG) != 0) {
                State = MODE_INSERT;
            }
            shift_line(type == INDENT_DEC, round ? 1 : 0, 1, call_changed_bytes);
            State = save_State;
        }
        insstart_less -= curwin.w_cursor.col;
        if (new_cursor_col >= 0) {
            if (new_cursor_col == 0) {
                insstart_less = MAXCOL;
            }
            new_cursor_col += curwin.w_cursor.col;
        } else if ((State & MODE_INSERT) == 0) {
            new_cursor_col = curwin.w_cursor.col;
        } else {
            T_chartabsize_T cts = new T_chartabsize_T();
            vcol = get_indent() - vcol;
            curwin.w_virtcol[0] = vcol < 0 ? 0 : vcol;
            last_vcol = 0;
            ptr = ml_get_curline();
            init_chartabsize_arg(cts, curwin, 0L, 0, ptr, ptr);
            while (cts.cts_vcol <= curwin.w_virtcol[0]) {
                last_vcol = cts.cts_vcol;
                if (cts.cts_vcol > 0) {
                    cts.cts_ptr = cts.cts_ptr.add(utfc_ptr2len(cts.cts_ptr));
                }
                if (cts.cts_ptr.get() == NUL) {
                    break;
                }
                cts.cts_vcol += lbr_chartabsize(cts);
            }
            vcol = last_vcol;
            new_cursor_col = (int) cts.cts_ptr.sub(cts.cts_line);
            if (vcol != curwin.w_virtcol[0]) {
                curwin.w_cursor.col = new_cursor_col;
                i = curwin.w_virtcol[0] - vcol;
                ptr = BytePtr.alloc((long) (i + 1));
                long ptrlen;
                new_cursor_col += i;
                ptr.set(i, (byte) NUL);
                ptrlen = (long) i;
                while (--i >= 0) {
                    ptr.set(i, (byte) ' ');
                }
                ins_str(ptr, ptrlen);
            }
            insstart_less = MAXCOL;
        }
        curwin.w_onebuf_opt.wo_list[0] = save_p_list;
        if (new_cursor_col <= 0) {
            curwin.w_cursor.col = 0;
        } else {
            curwin.w_cursor.col = new_cursor_col;
        }
        curwin.w_set_curswant = true;
        changed_cline_bef_curs();
        if ((State & MODE_INSERT) != 0) {
            if (curwin.w_cursor.lnum == Insstart.lnum && Insstart.col != 0) {
                if (Insstart.col <= insstart_less) {
                    Insstart.col = 0;
                } else {
                    Insstart.col -= insstart_less;
                }
            }
            if (ai_col <= insstart_less) {
                ai_col = 0;
            } else {
                ai_col -= insstart_less;
            }
        }
        if ((State & REPLACE_FLAG) != 0 && (State & VREPLACE_FLAG) == 0 && start_col >= 0) {
            while (start_col > curwin.w_cursor.col) {
                replace_join(0);
                start_col--;
            }
            while (start_col < curwin.w_cursor.col || replaced != 0) {
                replace_push(NUL);
                if (replaced != 0) {
                    replace_push(replaced);
                    replaced = NUL;
                }
                start_col++;
            }
        }
        if ((State & VREPLACE_FLAG) != 0) {
            if (orig_line == null) {
                return;
            }
            int len_2 = ml_get_curline_len();
            new_line = vim_strnsave(ml_get_curline(), (long) len_2);
            new_line.set(curwin.w_cursor.col, (byte) NUL);
            ml_replace(curwin.w_cursor.lnum, orig_line, false);
            curwin.w_cursor.col = orig_col;
            backspace_until_column(0);
            ins_bytes(new_line);
        }
    }

