    private static int utf_char2len(int c) {
        if (c < 128) {
            return 1;
        }
        if (c < 2048) {
            return 2;
        }
        if (c < 65536) {
            return 3;
        }
        if (c < 2097152) {
            return 4;
        }
        if (c < 67108864) {
            return 5;
        }
        return 6;
    }

    private static int utf_char2bytes(int c, BytePtr buf) {
        if (c < 128) {
            buf.set(0, (byte) c);
            return 1;
        }
        if (c < 2048) {
            buf.set(0, (byte) (192 + (c >>> 6)));
            buf.set(1, (byte) (128 + (c & 63)));
            return 2;
        }
        if (c < 65536) {
            buf.set(0, (byte) (224 + (c >>> 12)));
            buf.set(1, (byte) (128 + ((c >>> 6) & 63)));
            buf.set(2, (byte) (128 + (c & 63)));
            return 3;
        }
        if (c < 2097152) {
            buf.set(0, (byte) (240 + (c >>> 18)));
            buf.set(1, (byte) (128 + ((c >>> 12) & 63)));
            buf.set(2, (byte) (128 + ((c >>> 6) & 63)));
            buf.set(3, (byte) (128 + (c & 63)));
            return 4;
        }
        if (c < 67108864) {
            buf.set(0, (byte) (248 + (c >>> 24)));
            buf.set(1, (byte) (128 + ((c >>> 18) & 63)));
            buf.set(2, (byte) (128 + ((c >>> 12) & 63)));
            buf.set(3, (byte) (128 + ((c >>> 6) & 63)));
            buf.set(4, (byte) (128 + (c & 63)));
            return 5;
        }
        buf.set(0, (byte) (252 + (c >>> 30)));
        buf.set(1, (byte) (128 + ((c >>> 24) & 63)));
        buf.set(2, (byte) (128 + ((c >>> 18) & 63)));
        buf.set(3, (byte) (128 + ((c >>> 12) & 63)));
        buf.set(4, (byte) (128 + ((c >>> 6) & 63)));
        buf.set(5, (byte) (128 + (c & 63)));
        return 6;
    }

    private boolean utf_iscomposing(int c) {
        return intable(new Ptr<S_interval>(utf_iscomposing_combining, 0), 5664L, c);
    }

    private boolean utf_printable(int c) {
        return !intable(new Ptr<S_interval>(utf_printable_nonprint, 0), 144L, c);
    }

    private int utf_class(int c) {
        return utf_class_buf(c, curbuf);
    }

    private int utf_class_buf(int c, S_file_buffer buf) {
        int bot = 0;
        int top = 70;
        int mid = 0;
        if (c < 256) {
            if (c == ' ' || c == '\t' || c == NUL || c == 160) {
                return 0;
            }
            if (vim_iswordc_buf(c, buf)) {
                return 2;
            }
            return 1;
        }
        if (intable(new Ptr<S_interval>(emoji_all, 0), 2336L, c)) {
            return 3;
        }
        while (top >= bot) {
            mid = (bot + top) / 2;
            if (Integer.compareUnsigned(utf_class_buf_classes[mid].last, c) < 0) {
                bot = mid + 1;
            } else if (Integer.compareUnsigned(utf_class_buf_classes[mid].first, c) > 0) {
                top = mid - 1;
            } else {
                return utf_class_buf_classes[mid].class_;
            }
        }
        return 2;
    }

    private boolean utf_ambiguous_width(int c) {
        return c >= 128
                && (intable(new Ptr<S_interval>(ambiguous, 0), 2864L, c)
                || intable(new Ptr<S_interval>(emoji_all, 0), 2336L, c));
    }

    private static int utf_convert(int a, Ptr<T_convertStruct> table, int tableSize) {
        int mid = 0;
        int entries = (int) Long.divideUnsigned((long) tableSize, 16L);
        int start = 0;
        int end = entries;
        while (start < end) {
            mid = (end + start) / 2;
            if (table.at(mid).rangeEnd < a) {
                start = mid + 1;
            } else {
                end = mid;
            }
        }
        if (start < entries && table.at(start).rangeStart <= a && a <= table.at(start).rangeEnd
                && (a - table.at(start).rangeStart) % table.at(start).step == 0) {
            return a + table.at(start).offset;
        } else {
            return a;
        }
    }

    private int utf_fold(int a) {
        if (a < 128) {
            return a >= 65 && a <= 90 ? a + 32 : a;
        }
        return utf_convert(a, new Ptr<T_convertStruct>(foldCase, 0), 3296);
    }

    private int musl_towupper(int a) {
        return utf_convert(a, new Ptr<T_convertStruct>(toUpper, 0), 3184);
    }

    private int musl_towlower(int a) {
        return utf_convert(a, new Ptr<T_convertStruct>(toLower, 0), 2928);
    }

    private int utf_toupper(int a) {
        if (a < 128 && (cmp_flags[0] & CMP_KEEPASCII) != 0) {
            return a < 'a' || a > 'z' ? a : a - ('a' - 'A');
        }
        if ((cmp_flags[0] & CMP_INTERNAL) == 0) {
            return musl_towupper(a);
        }
        if (a < 128) {
            return musl_toupper((byte) a & 0xff);
        }
        return utf_convert(a, new Ptr<T_convertStruct>(toUpper, 0), 3184);
    }

    private boolean utf_islower(int a) {
        return utf_toupper(a) != a || a == 223;
    }

    private int utf_tolower(int a) {
        if (a < 128 && (cmp_flags[0] & CMP_KEEPASCII) != 0) {
            return a < 'A' || a > 'Z' ? a : a + ('a' - 'A');
        }
        if ((cmp_flags[0] & CMP_INTERNAL) == 0) {
            return musl_towlower(a);
        }
        if (a < 128) {
            return musl_tolower((byte) a & 0xff);
        }
        return utf_convert(a, new Ptr<T_convertStruct>(toLower, 0), 2928);
    }

    private boolean utf_isupper(int a) {
        return utf_tolower(a) != a;
    }

    private int utf_strnicmp(BytePtr s1, BytePtr s2, long n1, long n2) {
        T_utf_safe_read_char_adv__out_T utf_safe_read_char_adv__o = new T_utf_safe_read_char_adv__out_T();
        int c1 = 0;
        int c2 = 0;
        int cdiff = 0;
        byte[] buffer = new byte[6];
        for (;;) {
            utf_safe_read_char_adv__o = utf_safe_read_char_adv(s1, n1);
            s1 = utf_safe_read_char_adv__o.s;
            n1 = utf_safe_read_char_adv__o.n;
            c1 = utf_safe_read_char_adv__o.r__;
            utf_safe_read_char_adv__o = utf_safe_read_char_adv(s2, n2);
            s2 = utf_safe_read_char_adv__o.s;
            n2 = utf_safe_read_char_adv__o.n;
            c2 = utf_safe_read_char_adv__o.r__;
            if (c1 <= 0 || c2 <= 0) {
                break;
            }
            if (c1 == c2) {
                continue;
            }
            cdiff = utf_fold(c1) - utf_fold(c2);
            if (cdiff != 0) {
                return cdiff;
            }
        }
        if (c1 == 0 || c2 == 0) {
            if (c1 == 0 && c2 == 0) {
                return 0;
            }
            return c1 == 0 ? -1 : 1;
        }
        if (c1 != -1 && c2 == -1) {
            n1 = (long) utf_char2bytes(utf_fold(c1), new BytePtr(buffer, 0));
            s1 = new BytePtr(buffer, 0);
        } else if (c2 != -1 && c1 == -1) {
            n2 = (long) utf_char2bytes(utf_fold(c2), new BytePtr(buffer, 0));
            s2 = new BytePtr(buffer, 0);
        }
        while (Long.compareUnsigned(n1, 0L) > 0 && Long.compareUnsigned(n2, 0L) > 0 && s1.get() != NUL
                && s2.get() != NUL) {
            cdiff = s1.u() - s2.u();
            if (cdiff != 0) {
                return cdiff;
            }
            s1 = s1.add(1);
            s2 = s2.add(1);
            n1--;
            n2--;
        }
        if (Long.compareUnsigned(n1, 0L) > 0 && s1.get() == NUL) {
            n1 = 0L;
        }
        if (Long.compareUnsigned(n2, 0L) > 0 && s2.get() == NUL) {
            n2 = 0L;
        }
        if (n1 == 0L && n2 == 0L) {
            return 0;
        }
        return n1 == 0L ? -1 : 1;
    }

    private int mb_strnicmp2(BytePtr s1, BytePtr s2, long n1, long n2) {
        if (n1 == n2) {
            return mb_strnicmp(s1, s2, n1);
        } else {
            return utf_strnicmp(s1, s2, n1, n2);
        }
    }

    private int mb_strnicmp(BytePtr s1, BytePtr s2, long nn) {
        return utf_strnicmp(s1, s2, nn, nn);
    }

    private void show_utf8() {
        int rlen = 0;
        int clen;
        int i = 0;
        BytePtr line = ml_get_cursor();
        int len = utfc_ptr2len(line);
        if (len == 0) {
            msg(BytePtr.lit("NUL"));
            return;
        }
        clen = 0;
        for (i = 0; i < len; i++) {
            if (clen == 0) {
                if (i > 0) {
                    musl_strcpy(IObuff.add(rlen), BytePtr.lit("+ "));
                    rlen += 2;
                }
                clen = utf_ptr2len(line.add(i));
            }
            vim_snprintf(IObuff.add(rlen), (long) (1025 - rlen), BytePtr.lit("%02x "),
                    line.at(i) == NL ? NUL : line.u(i));
            clen--;
            rlen += (int) musl_strlen(IObuff.add(rlen));
            if (rlen > 1005) {
                break;
            }
        }
        msg(IObuff);
    }

    private int utf_head_off(BytePtr base, BytePtr p) {
        BytePtr q = null;
        BytePtr s = null;
        int c = 0;
        int len = 0;
        if (p.u() < 128) {
            return 0;
        }
        for (q = p; ; q = q.add(-1)) {
            for (s = q; (s.u(1) & 192) == 128; s = s.add(1)) {
            }
            while (q.gt(base) && (q.u() & 192) == 128) {
                q = q.add(-1);
            }
            len = (int) utf8len_tab[q.u()];
            if (len != (int) (s.sub(q) + 1L) && len != (int) (p.sub(q) + 1L)) {
                return 0;
            }
            if (q.le(base)) {
                break;
            }
            c = utf_ptr2char(q);
            if (utf_iscomposing(c)) {
                continue;
            }
            break;
        }
        return (int) p.sub(q);
    }

    private T_mb_copy_char__out_T mb_copy_char(BytePtr fp, BytePtr tp) {
        T_mb_copy_char__out_T out__ = new T_mb_copy_char__out_T();
        int l = utfc_ptr2len(fp);
        Rt.memmove(tp, fp, (long) l);
        tp = tp.add(l);
        fp = fp.add(l);
        out__.fp = fp;
        out__.tp = tp;
        return out__;
    }

    private int mb_off_next(BytePtr base, BytePtr p) {
        int head_off = utf_head_off(base, p);
        if (head_off == 0) {
            return 0;
        }
        return utfc_ptr2len(p.add(-head_off)) - head_off;
    }

    private void utf_find_illegal() {
        long pos_lnum = curwin.w_cursor.lnum;
        int pos_col_ = curwin.w_cursor.col;
        int pos_coladd = curwin.w_cursor.coladd;
        BytePtr p = null;
        int len = 0;
        curwin.w_cursor.coladd = 0;
        for (;;) {
            p = ml_get_cursor();
            while (p.get() != NUL) {
                len = utf_ptr2len(p);
                if (p.u() >= 128 && (len == 1 || utf_char2len(utf_ptr2char(p)) != len)) {
                    curwin.w_cursor.col += (int) p.sub(ml_get_cursor());
                    curwin.w_set_curswant = true;
                    return;
                }
                p = p.add(len);
            }
            if (curwin.w_cursor.lnum == curbuf.b_ml.ml_line_count) {
                break;
            }
            curwin.w_cursor.lnum++;
            curwin.w_cursor.col = 0;
        }
        curwin.w_cursor.lnum = pos_lnum;
        curwin.w_cursor.col = pos_col_;
        curwin.w_cursor.coladd = pos_coladd;
        beep_flush();
    }

    private void mb_adjust_cursor() {
        mb_adjustpos(curbuf, curwin.w_cursor);
    }

    private void mb_adjustpos(S_file_buffer buf, T_pos_T lp) {
        BytePtr p;
        if (lp.col > 0 || lp.coladd > 1) {
            p = ml_get_buf(buf, lp.lnum, false);
            if (p.get() == NUL || ml_get_buf_len(buf, lp.lnum) < lp.col) {
                lp.col = 0;
            } else {
                lp.col -= utf_head_off(p, p.add(lp.col));
            }
            if (lp.coladd == 1 && p.at(lp.col) != TAB && vim_isprintc(utf_ptr2char(p.add(lp.col)))
                    && ptr2cells(p.add(lp.col)) > 1) {
                lp.coladd = 0;
            }
        }
    }

    private BytePtr mb_prevptr(BytePtr line, BytePtr p) {
        if (p.gt(line)) {
            p = p.add(-(utf_head_off(line, p.add(-1)) + 1));
        }
        return p;
    }

    private int mb_charlen(BytePtr str) {
        BytePtr p = str;
        int count = 0;
        if (p == null) {
            return 0;
        }
        for (count = 0; p.get() != NUL; count++) {
            p = p.add(utfc_ptr2len(p));
        }
        return count;
    }

    private BytePtr mb_unescape(Ptr<BytePtr> pp) {
        int n = 0;
        int m = 0;
        BytePtr str = pp.get();
        for (n = 0; str.at(n) != NUL && m < 4; n++) {
            if (str.u(n) == 128 && str.u(n + 1) == KS_SPECIAL && str.at(n + 2) == 'X') {
                mb_unescape_buf[m++] = -128;
                n += 2;
            } else if (str.u(n) == 128 && str.u(n + 1) == KS_EXTRA && str.at(n + 2) == KE_CSI) {
                mb_unescape_buf[m++] = (byte) CSI;
                n += 2;
            } else if (str.u(n) == 128) {
                break;
            } else {
                mb_unescape_buf[m++] = str.at(n);
            }
            mb_unescape_buf[m] = NUL;
            if (utfc_ptr2len(new BytePtr(mb_unescape_buf, 0)) > 1) {
                pp.put(str.add(n).add(1));
                return new BytePtr(mb_unescape_buf, 0);
            }
            if ((mb_unescape_buf[0] & 0xff) < 128) {
                break;
            }
        }
        return null;
    }

    private boolean mb_lefthalve(int row, int col) {
        return utf_off2cells(LineOffset.at(row) + col, LineOffset.at(row) + screen_Columns) > 1;
    }

    private int mb_fix_col(int col, int row) {
        int off;
        col = check_col(col);
        row = check_row(row);
        off = LineOffset.at(row) + col;
        if (ScreenLines != null && col > 0 && (ScreenLines.at(off) == 0 && ScreenLinesUC.at(off) == 0)) {
            return col - 1;
        }
        return col;
    }

    private static void ml_free_tree(S_block_hdr hp) {
        S_pointer_block pp;
        int i = 0;
        if (hp == null) {
            return;
        }
        if (hp.bh_id == ('p' << 8) + 't') {
            pp = hp.bh_ptr;
            for (i = 0; i < (pp.pb_count & 0xffff); i++) {
                ml_free_tree(pp.pb_pointer[i].pe_block);
            }
        }
    }

    private static BytePtr ml_alloc_line(BytePtr line, int len) {
        BytePtr text = BytePtr.alloc((long) len);
        Rt.memmove(text, line, (long) len);
        return text;
    }

    private static boolean ml_open(S_file_buffer buf) {
        S_block_hdr hp = null;
        S_pointer_block pp;
        S_data_block dp;
        buf.b_ml.ml_stack_size = 0;
        buf.b_ml.ml_root = null;
        buf.b_ml.ml_stack = null;
        buf.b_ml.ml_stack_top = 0;
        buf.b_ml.ml_locked = null;
        buf.b_ml.ml_line_lnum = 0L;
        buf.b_ml.ml_flags = ML_EMPTY;
        buf.b_ml.ml_line_count = 1L;
        hp = ml_new_ptr();
        buf.b_ml.ml_root = hp;
        pp = hp.bh_ptr;
        pp.pb_count = 1;
        pp.pb_pointer[0].pe_line_count = 1L;
        hp = ml_new_data();
        buf.b_ml.ml_root.bh_ptr.pb_pointer[0].pe_block = hp;
        dp = hp.bh_data;
        dp.db_line[0].dl_text = ml_alloc_line(BytePtr.lit(""), 1);
        dp.db_line[0].dl_len = 1;
        dp.db_line_count = 1L;
        return true;
    }

    private static void ml_close(S_file_buffer buf, boolean del_file) {
        if (buf.b_ml.ml_root == null) {
            return;
        }
        ml_free_tree(buf.b_ml.ml_root);
        buf.b_ml.ml_root = null;
        buf.b_flags &= ~BF_RECOVERED;
    }

    private void ml_close_all(boolean del_file) {
        S_file_buffer buf = curbuf;
        ml_close(buf, del_file && ((buf.b_flags & BF_PRESERVED) == 0 || vim_strchr(p_cpo[0], CPO_PRESERVE) == null));
    }

    private void ml_close_notmod() {
        S_file_buffer buf = curbuf;
        if (bufIsChanged(buf) == 0) {
            ml_close(buf, true);
        }
    }

    private BytePtr ml_get(long lnum) {
        return ml_get_buf(curbuf, lnum, false);
    }

    private BytePtr ml_get_pos(T_pos_T pos) {
        return ml_get_buf(curbuf, pos.lnum, false).add(pos.col);
    }

    private BytePtr ml_get_curline() {
        return ml_get_buf(curbuf, curwin.w_cursor.lnum, false);
    }

    private BytePtr ml_get_cursor() {
        return ml_get_buf(curbuf, curwin.w_cursor.lnum, false).add(curwin.w_cursor.col);
    }

    private int ml_get_len(long lnum) {
        return ml_get_buf_len(curbuf, lnum);
    }

    private int ml_get_pos_len(T_pos_T pos) {
        return ml_get_buf_len(curbuf, pos.lnum) - pos.col;
    }

    private int ml_get_curline_len() {
        return ml_get_buf_len(curbuf, curwin.w_cursor.lnum);
    }

    private int ml_get_cursor_len() {
        return ml_get_buf_len(curbuf, curwin.w_cursor.lnum) - curwin.w_cursor.col;
    }

    private int ml_get_buf_len(S_file_buffer buf, long lnum) {
        BytePtr line = null;
        if ((line = ml_get_buf(buf, lnum, false)).get() == NUL) {
            return 0;
        }
        if (buf.b_ml.ml_line_textlen <= 0) {
            buf.b_ml.ml_line_textlen = (int) musl_strlen(line) + 1;
        }
        return buf.b_ml.ml_line_textlen - 1;
    }

    private BytePtr ml_get_invalid(S_file_buffer buf, long lnum) {
        musl_strcpy(new BytePtr(ml_get_invalid_questions, 0), BytePtr.lit("???"));
        buf.b_ml.ml_line_len = 4;
        buf.b_ml.ml_line_textlen = buf.b_ml.ml_line_len;
        buf.b_ml.ml_line_lnum = lnum;
        return new BytePtr(ml_get_invalid_questions, 0);
    }

    private BytePtr ml_get_buf(S_file_buffer buf, long lnum, boolean will_change) {
        S_block_hdr hp = null;
        S_data_block dp;
        if (lnum > buf.b_ml.ml_line_count) {
            if (ml_get_buf_recursive == 0) {
                ml_get_buf_recursive++;
                vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_ml_get_invalid_lnum_nr, 0), lnum);
                iemsg(iobuff_or(new BytePtr(e_ml_get_invalid_lnum_nr, 0)));
                ml_get_buf_recursive--;
            }
            ml_flush_line(buf);
            return ml_get_invalid(buf, lnum);
        }
        if (lnum <= 0L) {
            lnum = 1L;
        }
        if (buf.b_ml.ml_root == null) {
            buf.b_ml.ml_line_len = 1;
            buf.b_ml.ml_line_textlen = buf.b_ml.ml_line_len;
            return BytePtr.lit("");
        }
        if (buf.b_ml.ml_line_lnum != lnum) {
            int idx;
            ml_flush_line(buf);
            if ((hp = ml_find_line(buf, lnum, ML_FIND)) == null) {
                if (ml_get_buf_recursive == 0) {
                    ml_get_buf_recursive++;
                    get_trans_bufname(buf);
                    shorten_dir(NameBuff);
                    vim_snprintf(IObuff, emsg_iobuff_room(),
                            new BytePtr(e_ml_get_cannot_find_line_nr_in_buffer_nr_str, 0), lnum, buf.b_fnum, NameBuff);
                    iemsg(iobuff_or(new BytePtr(e_ml_get_cannot_find_line_nr_in_buffer_nr_str, 0)));
                    ml_get_buf_recursive--;
                }
                return ml_get_invalid(buf, lnum);
            }
            dp = hp.bh_data;
            idx = (int) (lnum - buf.b_ml.ml_locked_low);
            buf.b_ml.ml_line_ptr = dp.db_line[idx].dl_text;
            buf.b_ml.ml_line_len = dp.db_line[idx].dl_len;
            buf.b_ml.ml_line_textlen = buf.b_ml.ml_line_len;
            buf.b_ml.ml_line_lnum = lnum;
            buf.b_ml.ml_flags &= ~(ML_LINE_DIRTY | ML_ALLOCATED);
        }
        return buf.b_ml.ml_line_ptr;
    }

    private int ml_line_alloced() {
        return curbuf.b_ml.ml_flags & ML_LINE_DIRTY;
    }

    private boolean ml_append_int(S_file_buffer buf, long lnum, BytePtr line_arg, int len_arg, int flags) {
        BytePtr line = line_arg;
        int len = len_arg;
        int i = 0;
        int line_count;
        BytePtr text;
        int db_idx;
        S_block_hdr hp = null;
        S_data_block dp;
        S_pointer_block pp = null;
        S_info_pointer ip = null;
        boolean ret = false;
        if (lnum > buf.b_ml.ml_line_count || buf.b_ml.ml_root == null) {
            return false;
        }
        if (lowest_marked != 0 && lowest_marked > lnum) {
            lowest_marked = lnum + 1L;
        }
        if (len == 0) {
            len = (int) musl_strlen(line) + 1;
        }
        text = ml_alloc_line(line, len);
        if ((hp = ml_find_line(buf, lnum == 0L ? 1L : lnum, ML_INSERT)) == null) {
            return ret;
        }
        buf.b_ml.ml_flags &= ~ML_EMPTY;
        if (lnum == 0L) {
            db_idx = -1;
        } else {
            db_idx = (int) (lnum - buf.b_ml.ml_locked_low);
        }
        line_count = (int) (buf.b_ml.ml_locked_high - buf.b_ml.ml_locked_low);
        dp = hp.bh_data;
        if (dp.db_line_count >= DB_LINE_MAX && db_idx == line_count - 1 && lnum < buf.b_ml.ml_line_count) {
            buf.b_ml.ml_locked_lineadd--;
            buf.b_ml.ml_locked_high--;
            if ((hp = ml_find_line(buf, lnum + 1L, ML_INSERT)) == null) {
                return ret;
            }
            db_idx = -1;
            line_count = (int) (buf.b_ml.ml_locked_high - buf.b_ml.ml_locked_low);
            dp = hp.bh_data;
        }
        buf.b_ml.ml_line_count++;
        if (dp.db_line_count < DB_LINE_MAX) {
            if (line_count > (db_idx + 1)) {
                Rt.moveStructs(new Ptr<S_data_line>(dp.db_line, db_idx + 2),
                        new Ptr<S_data_line>(dp.db_line, db_idx + 1), (int) (long) (line_count - db_idx - 1));
            }
            dp.db_line[db_idx + 1].dl_text = text;
            dp.db_line[db_idx + 1].dl_len = len;
            dp.db_line[db_idx + 1].dl_marked = FALSE;
            dp.db_line_count++;
        } else {
            long line_count_left;
            long line_count_right;
            S_block_hdr hp_left;
            S_block_hdr hp_right;
            S_block_hdr hp_new;
            int lines_moved;
            int total_moved = 0;
            S_data_block dp_right;
            S_data_block dp_left;
            int stack_idx = 0;
            boolean in_left;
            int lineadd;
            S_block_hdr bp_left;
            S_block_hdr bp_right;
            int pb_idx = 0;
            S_pointer_block pp_new = null;
            if (db_idx < 0) {
                lines_moved = 0;
                in_left = true;
            } else {
                lines_moved = line_count - db_idx - 1;
                in_left = lines_moved != 0;
            }
            hp_new = ml_new_data();
            if (db_idx < 0) {
                hp_left = hp_new;
                hp_right = hp;
                line_count_left = 0L;
                line_count_right = (long) line_count;
            } else {
                hp_left = hp;
                hp_right = hp_new;
                line_count_left = (long) line_count;
                line_count_right = 0L;
            }
            dp_right = hp_right.bh_data;
            dp_left = hp_left.bh_data;
            bp_left = hp_left;
            bp_right = hp_right;
            if (!in_left) {
                dp_right.db_line[0].dl_text = text;
                dp_right.db_line[0].dl_len = len;
                dp_right.db_line[0].dl_marked = FALSE;
                line_count_right++;
            }
            if (lines_moved != 0) {
                Rt.moveStructs(new Ptr<S_data_line>(dp_right.db_line, (int) line_count_right),
                        new Ptr<S_data_line>(dp.db_line, db_idx + 1), (int) (long) lines_moved);
                line_count_right += (long) lines_moved;
                line_count_left -= (long) lines_moved;
            }
            if (in_left) {
                dp_left.db_line[(int) line_count_left].dl_text = text;
                dp_left.db_line[(int) line_count_left].dl_len = len;
                dp_left.db_line[(int) line_count_left].dl_marked = FALSE;
                line_count_left++;
            }
            dp_left.db_line_count = line_count_left;
            dp_right.db_line_count = line_count_right;
            lineadd = buf.b_ml.ml_locked_lineadd;
            buf.b_ml.ml_locked_lineadd = 0;
            ml_find_line(buf, 0L, ML_FLUSH);
            for (stack_idx = buf.b_ml.ml_stack_top - 1; stack_idx >= 0; stack_idx--) {
                ip = buf.b_ml.ml_stack.at(stack_idx);
                pb_idx = ip.ip_index;
                hp = ip.ip_block;
                pp = hp.bh_ptr;
                if (hp.bh_id != ('p' << 8) + 't') {
                    iemsg(new BytePtr(e_pointer_block_id_wrong_three, 0));
                    return ret;
                }
                if ((pp.pb_count & 0xffff) < PB_COUNT_MAX) {
                    if (pb_idx + 1 < (pp.pb_count & 0xffff)) {
                        Rt.moveStructs(new Ptr<S_pointer_entry>(pp.pb_pointer, pb_idx + 2),
                                new Ptr<S_pointer_entry>(pp.pb_pointer, pb_idx + 1),
                                (int) (long) ((pp.pb_count & 0xffff) - pb_idx - 1));
                    }
                    pp.pb_count++;
                    pp.pb_pointer[pb_idx].pe_line_count = line_count_left;
                    pp.pb_pointer[pb_idx].pe_block = bp_left;
                    pp.pb_pointer[pb_idx + 1].pe_line_count = line_count_right;
                    pp.pb_pointer[pb_idx + 1].pe_block = bp_right;
                    buf.b_ml.ml_stack_top = stack_idx + 1;
                    if (lineadd != 0) {
                        buf.b_ml.ml_stack_top--;
                        ml_lineadd(buf, lineadd);
                        buf.b_ml.ml_stack.at(buf.b_ml.ml_stack_top).ip_high += (long) lineadd;
                        buf.b_ml.ml_stack_top++;
                    }
                    break;
                }
                for (;;) {
                    hp_new = ml_new_ptr();
                    pp_new = hp_new.bh_ptr;
                    if (hp != buf.b_ml.ml_root) {
                        break;
                    }
                    pp_new.pb_count = pp.pb_count;
                    Rt.moveStructs(new Ptr<S_pointer_entry>(pp_new.pb_pointer, 0),
                            new Ptr<S_pointer_entry>(pp.pb_pointer, 0), (int) (pp.pb_count & 0xffffL));
                    pp.pb_count = 1;
                    pp.pb_pointer[0].pe_block = hp_new;
                    pp.pb_pointer[0].pe_line_count = buf.b_ml.ml_line_count;
                    hp = hp_new;
                    pp = pp_new;
                    ip.ip_index = 0;
                    stack_idx++;
                }
                total_moved = (pp.pb_count & 0xffff) - pb_idx - 1;
                if (total_moved != 0) {
                    Rt.moveStructs(new Ptr<S_pointer_entry>(pp_new.pb_pointer, 0),
                            new Ptr<S_pointer_entry>(pp.pb_pointer, pb_idx + 1), (int) (long) total_moved);
                    pp_new.pb_count = (short) total_moved;
                    pp.pb_count -= (short) (total_moved - 1);
                    pp.pb_pointer[pb_idx + 1].pe_block = bp_right;
                    pp.pb_pointer[pb_idx + 1].pe_line_count = line_count_right;
                } else {
                    pp_new.pb_count = 1;
                    pp_new.pb_pointer[0].pe_block = bp_right;
                    pp_new.pb_pointer[0].pe_line_count = line_count_right;
                }
                pp.pb_pointer[pb_idx].pe_block = bp_left;
                pp.pb_pointer[pb_idx].pe_line_count = line_count_left;
                line_count_right = 0L;
                for (i = 0; i < (pp_new.pb_count & 0xffff); i++) {
                    line_count_right += pp_new.pb_pointer[i].pe_line_count;
                }
                line_count_left = 0L;
                for (i = 0; i < (pp.pb_count & 0xffff); i++) {
                    line_count_left += pp.pb_pointer[i].pe_line_count;
                }
                bp_left = hp;
                bp_right = hp_new;
            }
            if (stack_idx < 0) {
                iemsg(new BytePtr(e_updated_too_many_blocks, 0));
                buf.b_ml.ml_stack_top = 0;
            }
        }
        ret = true;
        return ret;
    }

    private boolean ml_append_flush(S_file_buffer buf, long lnum, BytePtr line, int len, int flags) {
        if (lnum > buf.b_ml.ml_line_count) {
            return false;
        }
        if (buf.b_ml.ml_line_lnum != 0L) {
            ml_flush_line(buf);
        }
        return ml_append_int(buf, lnum, line, len, flags);
    }

    private boolean ml_append(long lnum, BytePtr line, int len) {
        return ml_append_flags(lnum, line, len, 0);
    }

    private boolean ml_append_flags(long lnum, BytePtr line, int len, int flags) {
        if (curbuf.b_ml.ml_root == null && !open_buffer()) {
            return false;
        }
        return ml_append_flush(curbuf, lnum, line, len, flags);
    }

    private boolean ml_replace(long lnum, BytePtr line, boolean copy) {
        int len = -1;
        if (line != null) {
            len = (int) musl_strlen(line);
        }
        return ml_replace_len(lnum, line, len, false, copy);
    }

    private boolean ml_replace_len(long lnum, BytePtr line_arg, int len_arg, boolean has_props, boolean copy) {
        BytePtr line = line_arg;
        int len = len_arg;
        if (line == null) {
            return false;
        }
        if (curbuf.b_ml.ml_root == null && !open_buffer()) {
            return false;
        }
        if (!has_props) {
            len++;
        }
        if (copy) {
            line = vim_strnsave(line, (long) (len - 1));
        }
        if (curbuf.b_ml.ml_line_lnum != lnum) {
            ml_flush_line(curbuf);
        }
        curbuf.b_ml.ml_line_ptr = line;
        curbuf.b_ml.ml_line_len = len;
        curbuf.b_ml.ml_line_textlen = !has_props ? len_arg + 1 : 0;
        curbuf.b_ml.ml_line_lnum = lnum;
        curbuf.b_ml.ml_flags = (curbuf.b_ml.ml_flags | ML_LINE_DIRTY) & ~ML_EMPTY;
        return true;
    }

    private boolean ml_delete_int(S_file_buffer buf, long lnum, int flags) {
        S_block_hdr hp = null;
        S_data_block dp;
        S_pointer_block pp = null;
        S_info_pointer ip = null;
        int count;
        int idx;
        int stack_idx = 0;
        boolean i;
        boolean ret = false;
        if (lowest_marked != 0 && lowest_marked > lnum) {
            lowest_marked--;
        }
        if (buf.b_ml.ml_line_count == 1L) {
            if ((flags & ML_DEL_MESSAGE) != 0) {
                set_keep_msg(new BytePtr(no_lines_msg, 0), 0);
            }
            i = ml_replace(1L, BytePtr.lit(""), true);
            buf.b_ml.ml_flags |= ML_EMPTY;
            return i;
        }
        if (buf.b_ml.ml_root == null) {
            return false;
        }
        if ((hp = ml_find_line(buf, lnum, ML_DELETE)) == null) {
            return false;
        }
        dp = hp.bh_data;
        count = (int) (buf.b_ml.ml_locked_high - buf.b_ml.ml_locked_low + 2L);
        idx = (int) (lnum - buf.b_ml.ml_locked_low);
        buf.b_ml.ml_line_count--;
        if (count == 1) {
            buf.b_ml.ml_locked = null;
            for (stack_idx = buf.b_ml.ml_stack_top - 1; stack_idx >= 0; stack_idx--) {
                buf.b_ml.ml_stack_top = 0;
                ip = buf.b_ml.ml_stack.at(stack_idx);
                idx = ip.ip_index;
                hp = ip.ip_block;
                pp = hp.bh_ptr;
                if (hp.bh_id != ('p' << 8) + 't') {
                    iemsg(new BytePtr(e_pointer_block_id_wrong_four, 0));
                    return ret;
                }
                pp.pb_count--;
                count = pp.pb_count & 0xffff;
                if (count == 0) {
                } else {
                    if (count != idx) {
                        Rt.moveStructs(new Ptr<S_pointer_entry>(pp.pb_pointer, idx),
                                new Ptr<S_pointer_entry>(pp.pb_pointer, idx + 1), (int) (long) (count - idx));
                    }
                    buf.b_ml.ml_stack_top = stack_idx;
                    if (buf.b_ml.ml_locked_lineadd != 0) {
                        ml_lineadd(buf, buf.b_ml.ml_locked_lineadd);
                        buf.b_ml.ml_stack.at(buf.b_ml.ml_stack_top).ip_high += (long) buf.b_ml.ml_locked_lineadd;
                    }
                    buf.b_ml.ml_stack_top++;
                    break;
                }
            }
        } else {
            if (idx < count - 1) {
                Rt.moveStructs(new Ptr<S_data_line>(dp.db_line, idx), new Ptr<S_data_line>(dp.db_line, idx + 1),
                        (int) (long) (count - idx - 1));
            }
            dp.db_line_count--;
        }
        ret = true;
        return ret;
    }

    private boolean ml_delete(long lnum) {
        return ml_delete_flags(lnum, 0);
    }

    private boolean ml_delete_flags(long lnum, int flags) {
        ml_flush_line(curbuf);
        if (lnum < 1L || lnum > curbuf.b_ml.ml_line_count) {
            return false;
        }
        return ml_delete_int(curbuf, lnum, flags);
    }

    private void ml_setmarked(long lnum) {
        S_block_hdr hp = null;
        S_data_block dp;
        if (lnum < 1L || lnum > curbuf.b_ml.ml_line_count || curbuf.b_ml.ml_root == null) {
            return;
        }
        if (lowest_marked == 0L || lowest_marked > lnum) {
            lowest_marked = lnum;
        }
        if ((hp = ml_find_line(curbuf, lnum, ML_FIND)) == null) {
            return;
        }
        dp = hp.bh_data;
        dp.db_line[(int) (lnum - curbuf.b_ml.ml_locked_low)].dl_marked = TRUE;
    }

    private long ml_firstmarked() {
        S_block_hdr hp = null;
        S_data_block dp = null;
        long lnum = 0;
        int i = 0;
        if (curbuf.b_ml.ml_root == null) {
            return 0L;
        }
        for (lnum = lowest_marked; lnum <= curbuf.b_ml.ml_line_count; ) {
            if ((hp = ml_find_line(curbuf, lnum, ML_FIND)) == null) {
                return 0L;
            }
            dp = hp.bh_data;
            for (i = (int) (lnum - curbuf.b_ml.ml_locked_low); lnum <= curbuf.b_ml.ml_locked_high; i++, lnum++) {
                if (dp.db_line[i].dl_marked != 0) {
                    dp.db_line[i].dl_marked = FALSE;
                    lowest_marked = lnum + 1L;
                    return lnum;
                }
            }
        }
        return 0L;
    }

    private void ml_clearmarked() {
        S_block_hdr hp = null;
        S_data_block dp = null;
        long lnum = 0;
        int i = 0;
        if (curbuf.b_ml.ml_root == null || lowest_marked == 0L) {
            return;
        }
        for (lnum = lowest_marked; lnum <= curbuf.b_ml.ml_line_count; ) {
            if ((hp = ml_find_line(curbuf, lnum, ML_FIND)) == null) {
                return;
            }
            dp = hp.bh_data;
            for (i = (int) (lnum - curbuf.b_ml.ml_locked_low); lnum <= curbuf.b_ml.ml_locked_high; i++, lnum++) {
                if (dp.db_line[i].dl_marked != 0) {
                    dp.db_line[i].dl_marked = FALSE;
                }
            }
        }
        lowest_marked = 0L;
    }

    private void ml_flush_line(S_file_buffer buf) {
        S_block_hdr hp;
        S_data_block dp;
        long lnum;
        BytePtr new_line;
        int idx;
        if (buf.b_ml.ml_line_lnum == 0L || buf.b_ml.ml_root == null) {
            return;
        }
        if ((buf.b_ml.ml_flags & ML_LINE_DIRTY) != 0) {
            if (ml_flush_line_entered) {
                return;
            }
            ml_flush_line_entered = true;
            lnum = buf.b_ml.ml_line_lnum;
            new_line = buf.b_ml.ml_line_ptr;
            hp = ml_find_line(buf, lnum, ML_FIND);
            if (hp == null) {
                vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_cannot_find_line_nr, 0), lnum);
                iemsg(iobuff_or(new BytePtr(e_cannot_find_line_nr, 0)));
            } else {
                dp = hp.bh_data;
                idx = (int) (lnum - buf.b_ml.ml_locked_low);
                dp.db_line[idx].dl_text = new_line;
                dp.db_line[idx].dl_len = buf.b_ml.ml_line_len;
            }
            ml_flush_line_entered = false;
        }
        buf.b_ml.ml_flags &= ~(ML_LINE_DIRTY | ML_ALLOCATED);
        buf.b_ml.ml_line_lnum = 0L;
    }

    private static S_block_hdr ml_new_data() {
        S_data_block dp = new S_data_block();
        S_block_hdr hp = new S_block_hdr();
        hp.bh_id = ('d' << 8) + 'a';
        hp.bh_data = dp;
        dp.db_line_count = 0L;
        return hp;
    }

    private static S_block_hdr ml_new_ptr() {
        S_pointer_block pp = new S_pointer_block();
        S_block_hdr hp = new S_block_hdr();
        hp.bh_id = ('p' << 8) + 't';
        hp.bh_ptr = pp;
        pp.pb_count = 0;
        return hp;
    }

    private S_block_hdr ml_find_line(S_file_buffer buf, long lnum, int action) {
        S_pointer_block pp = null;
        S_info_pointer ip = null;
        S_block_hdr hp = null;
        long t = 0;
        S_block_hdr bp;
        long low;
        long high;
        int top = 0;
        int idx = 0;
        if (buf.b_ml.ml_locked != null) {
            if ((action & 16) != 0 && buf.b_ml.ml_locked_low <= lnum && buf.b_ml.ml_locked_high >= lnum) {
                if (action == ML_INSERT) {
                    buf.b_ml.ml_locked_lineadd++;
                    buf.b_ml.ml_locked_high++;
                } else if (action == ML_DELETE) {
                    buf.b_ml.ml_locked_lineadd--;
                    buf.b_ml.ml_locked_high--;
                }
                return buf.b_ml.ml_locked;
            }
            buf.b_ml.ml_locked = null;
            if (buf.b_ml.ml_locked_lineadd != 0) {
                ml_lineadd(buf, buf.b_ml.ml_locked_lineadd);
            }
        }
        if (action == ML_FLUSH) {
            return null;
        }
        bp = buf.b_ml.ml_root;
        low = 1L;
        high = buf.b_ml.ml_line_count;
        if (action == ML_FIND) {
            for (top = buf.b_ml.ml_stack_top - 1; top >= 0; top--) {
                ip = buf.b_ml.ml_stack.at(top);
                if (ip.ip_low <= lnum && ip.ip_high >= lnum) {
                    bp = ip.ip_block;
                    low = ip.ip_low;
                    high = ip.ip_high;
                    buf.b_ml.ml_stack_top = top;
                    break;
                }
            }
            if (top < 0) {
                buf.b_ml.ml_stack_top = 0;
            }
        } else {
            buf.b_ml.ml_stack_top = 0;
        }
        for (;;) {
            hp = bp;
            if (action == ML_INSERT) {
                high++;
            } else if (action == ML_DELETE) {
                high--;
            }
            if (hp.bh_id == ('d' << 8) + 'a') {
                buf.b_ml.ml_locked = hp;
                buf.b_ml.ml_locked_low = low;
                buf.b_ml.ml_locked_high = high;
                buf.b_ml.ml_locked_lineadd = 0;
                return hp;
            }
            pp = hp.bh_ptr;
            if (hp.bh_id != ('p' << 8) + 't') {
                iemsg(new BytePtr(e_pointer_block_id_wrong, 0));
                break;
            }
            if ((top = ml_add_stack(buf)) < 0) {
                break;
            }
            ip = buf.b_ml.ml_stack.at(top);
            ip.ip_block = bp;
            ip.ip_low = low;
            ip.ip_high = high;
            ip.ip_index = -1;
            for (idx = 0; idx < (pp.pb_count & 0xffff); idx++) {
                t = pp.pb_pointer[idx].pe_line_count;
                low += t;
                if (low > lnum) {
                    ip.ip_index = idx;
                    bp = pp.pb_pointer[idx].pe_block;
                    high = low - 1L;
                    low -= t;
                    break;
                }
            }
            if (idx >= (pp.pb_count & 0xffff)) {
                if (lnum > buf.b_ml.ml_line_count) {
                    vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_line_number_out_of_range_nr_past_the_end, 0),
                            lnum - buf.b_ml.ml_line_count);
                    iemsg(iobuff_or(new BytePtr(e_line_number_out_of_range_nr_past_the_end, 0)));
                } else {
                    iemsg(new BytePtr(e_line_count_wrong_in_block, 0));
                }
                break;
            }
            if (action == ML_DELETE) {
                pp.pb_pointer[idx].pe_line_count--;
            } else if (action == ML_INSERT) {
                pp.pb_pointer[idx].pe_line_count++;
            }
        }
        if (action == ML_DELETE) {
            ml_lineadd(buf, 1);
        } else if (action == ML_INSERT) {
            ml_lineadd(buf, -1);
        }
        buf.b_ml.ml_stack_top = 0;
        return null;
    }

    private static int ml_add_stack(S_file_buffer buf) {
        Ptr<S_info_pointer> newstack;
        int top = buf.b_ml.ml_stack_top;
        if (top == buf.b_ml.ml_stack_size) {
            newstack = new Ptr<S_info_pointer>(S_info_pointer.array(buf.b_ml.ml_stack_size + STACK_INCR), 0);
            if (top > 0) {
                Rt.moveStructs(newstack, buf.b_ml.ml_stack, (int) (long) top);
            }
            buf.b_ml.ml_stack = newstack;
            buf.b_ml.ml_stack_size += STACK_INCR;
        }
        buf.b_ml.ml_stack_top++;
        return top;
    }

    private void ml_lineadd(S_file_buffer buf, int count) {
        int idx = 0;
        S_info_pointer ip = null;
        S_pointer_block pp = null;
        S_block_hdr hp = null;
        for (idx = buf.b_ml.ml_stack_top - 1; idx >= 0; idx--) {
            ip = buf.b_ml.ml_stack.at(idx);
            hp = ip.ip_block;
            pp = hp.bh_ptr;
            if (hp.bh_id != ('p' << 8) + 't') {
                iemsg(new BytePtr(e_pointer_block_id_wrong_two, 0));
                break;
            }
            pp.pb_pointer[ip.ip_index].pe_line_count += (long) count;
            ip.ip_high += (long) count;
        }
    }

    private int msg(BytePtr s) {
        return msg_attr_keep(s, 0, false) ? 1 : 0;
    }

    private int msg_attr(BytePtr s, int attr) {
        return msg_attr_keep(s, attr, false) ? 1 : 0;
    }

    private boolean msg_attr_keep(BytePtr s, int attr, boolean keep) {
        boolean retval;
        BytePtr buf = null;
        if (!emsg_on_display && message_filtered(s)) {
            return true;
        }
        if (msg_attr_keep_entered >= 3) {
            return true;
        }
        msg_attr_keep_entered++;
        if (!BytePtr.eq(s, keep_msg)
                || ((int) s.get() != '<' && last_msg_hist != null && last_msg_hist.msg != null
                && musl_strcmp(s, last_msg_hist.msg) != 0)) {
            add_msg_hist(s, -1, attr);
        }
        msg_start();
        buf = msg_strtrunc(s, false);
        if (buf != null) {
            s = buf;
        }
        msg_outtrans_attr(s, attr);
        msg_clr_eos();
        retval = msg_end();
        if (keep && retval && vim_strsize(s) < (int) (Rows[0] - (long) cmdline_row - 1L) * cmdline_width + sc_col) {
            set_keep_msg(s, 0);
        }
        need_fileinfo = false;
        msg_attr_keep_entered--;
        return retval;
    }

    private BytePtr msg_strtrunc(BytePtr s, boolean force) {
        BytePtr buf = null;
        int len;
        int room;
        if ((msg_scroll == 0 && need_wait_return == 0 && shortmess(SHM_TRUNCALL) && msg_silent == 0) || force) {
            len = vim_strsize(s);
            if (msg_scrolled != 0) {
                room = (int) (Rows[0] - (long) msg_row) * cmdline_width - 1;
            } else {
                room = (int) (Rows[0] - (long) msg_row - 1L) * cmdline_width + sc_col - 1;
            }
            if (len > room && room > 0) {
                len = (room + 2) * 18;
                buf = BytePtr.alloc((long) len);
                trunc_string(s, buf, room, len);
            }
        }
        return buf;
    }

    private void trunc_string(BytePtr s, BytePtr buf, int room_in, int buflen) {
        long room = (long) (room_in - 3);
        long half;
        long len = 0L;
        int e = 0;
        int i;
        int n = 0;
        if (s.get() == NUL) {
            if (buflen > 0) {
                buf.put((byte) NUL);
            }
            return;
        }
        if (room_in < 3) {
            room = 0L;
        }
        half = Long.divideUnsigned(room, 2L);
        for (e = 0; Long.compareUnsigned(len, half) < 0 && e < buflen; e++) {
            if (s.at(e) == NUL) {
                buf.set(e, (byte) NUL);
                return;
            }
            n = ptr2cells(s.add(e));
            if (Long.compareUnsigned(len + (long) n, half) > 0) {
                break;
            }
            len += (long) n;
            buf.set(e, s.at(e));
            for (n = utfc_ptr2len(s.add(e)); --n > 0; ) {
                if (++e == buflen) {
                    break;
                }
                buf.set(e, s.at(e));
            }
        }
        i = e;
        half = (long) (i = (int) musl_strlen(s));
        for (;;) {
            do {
                half = half - (long) utf_head_off(s, s.add((int) half).add(-1)) - 1L;
            } while (Long.compareUnsigned(half, 0L) > 0 && utf_iscomposing(utf_ptr2char(s.add((int) half))));
            n = ptr2cells(s.add((int) half));
            if (Long.compareUnsigned(len + (long) n, room) > 0 || half == 0L) {
                break;
            }
            len += (long) n;
            i = (int) half;
        }
        if (i <= e + 3) {
            if (!BytePtr.eq(s, buf)) {
                len = musl_strlen(s);
                if (Long.compareUnsigned(len, (long) buflen) >= 0) {
                    len = (long) (buflen - 1);
                }
                len = len - (long) e + 1L;
                if (Long.compareUnsigned(len, 1L) < 0) {
                    buf.set(e - 1, (byte) NUL);
                } else {
                    Rt.memmove(buf.add(e), s.add(e), len);
                }
            }
        } else if (e + 3 < buflen) {
            Rt.memmove(buf.add(e), BytePtr.lit("..."), 3L);
            len = musl_strlen(s.add(i)) + 1L;
            if (Long.compareUnsigned(len, (long) buflen - (long) e - 3L) >= 0) {
                len = (long) (buflen - e - 3 - 1);
            }
            Rt.memmove(buf.add(e).add(3), s.add(i), len);
            buf.set((int) ((long) (e + 3) + len - 1L), (byte) NUL);
        } else {
            buf.set(buflen - 1, (byte) NUL);
        }
    }

    private long iobuff_room() {
        if (IObuff == null) {
            return 0L;
        }
        return 1025L;
    }

    long emsg_iobuff_room() {
        if (IObuff == null || emsg_not_now()) {
            return 0L;
        }
        return 1025L;
    }

    BytePtr iobuff_or(BytePtr s) {
        if (IObuff == null) {
            return s;
        }
        return IObuff;
    }

    private static long safelen_result(BytePtr str, long str_m, int str_l) {
        if (str_m == 0L) {
            return 0L;
        }
        if (str_l < 0) {
            str.put((byte) NUL);
            return 0L;
        }
        return Long.compareUnsigned((long) str_l, str_m) >= 0 ? str_m - 1L : (long) str_l;
    }

    private long append_room(BytePtr str, long str_m) {
        long len = musl_strlen(str);
        if (Long.compareUnsigned(str_m, len) <= 0) {
            return 0L;
        }
        return str_m - len;
    }

    private void reset_last_sourcing() {
        last_sourcing_name = null;
        last_sourcing_lnum = 0;
    }

    private boolean other_sourcing_name() {
        if (exestack.ga_data != null && exestack.ga_len > 0
                && GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_name != null) {
            if (last_sourcing_name != null) {
                return musl_strcmp(GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_name,
                        last_sourcing_name) != 0;
            }
            return true;
        }
        return false;
    }

    private BytePtr get_emsg_source() {
        BytePtr Buf;
        BytePtr p;
        if (exestack.ga_data != null && exestack.ga_len > 0
                && GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_name != null && other_sourcing_name()) {
            BytePtr sname = estack_sfile(ESTACK_NONE);
            if (sname == null) {
                sname = GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_name;
            }
            p = BytePtr.lit("Error detected while processing %s:");
            Buf = BytePtr.alloc(musl_strlen(sname) + musl_strlen(p));
            vim_snprintf(Buf, musl_strlen(sname) + musl_strlen(p), p, sname);
            return Buf;
        }
        return null;
    }

    private BytePtr get_emsg_lnum() {
        BytePtr Buf;
        BytePtr p;
        if (GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_name != null
                && (other_sourcing_name()
                || GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_lnum != (long) last_sourcing_lnum)
                && GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_lnum != 0L) {
            p = BytePtr.lit("line %4ld:");
            Buf = BytePtr.alloc(musl_strlen(p) + 20L);
            vim_snprintf(Buf, musl_strlen(p) + 20L, p, GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_lnum);
            return Buf;
        }
        return null;
    }

    private void msg_source(int attr) {
        BytePtr p;
        if (msg_source_recursive) {
            return;
        }
        msg_source_recursive = true;
        no_wait_return++;
        p = get_emsg_source();
        if (p != null) {
            msg_scroll = TRUE;
            msg_attr(p, attr);
        }
        p = get_emsg_lnum();
        if (p != null) {
            msg_attr(p, highlight_attr[HLF_N]);
            last_sourcing_lnum = (int) GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_lnum;
        }
        if (GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_name == null || other_sourcing_name()) {
            last_sourcing_name = null;
            if (GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_name != null) {
                last_sourcing_name = vim_strsave(GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_name);
            }
        }
        no_wait_return--;
        msg_source_recursive = false;
    }

    private boolean emsg_not_now() {
        if (emsg_off > 0) {
            return true;
        }
        return false;
    }

    private int emsg_core(BytePtr s) {
        int attr;
        BytePtr p;
        int r;
        called_emsg++;
        if (emsg_off == 0) {
            if (emsg_silent != 0) {
                if (emsg_noredir == 0) {
                    msg_start();
                    p = get_emsg_source();
                    if (p != null) {
                        musl_strcat(p, BytePtr.lit("\n"));
                    }
                    p = get_emsg_lnum();
                    if (p != null) {
                        musl_strcat(p, BytePtr.lit("\n"));
                    }
                }
                return TRUE;
            }
            msg_silent = 0;
            cmd_silent = false;
            if (global_busy != 0) {
                global_busy++;
            }
            if (p_eb[0] != 0) {
                beep_flush();
            } else {
                flush_buffers(FLUSH_MINIMAL);
            }
            did_emsg++;
        }
        emsg_on_display = true;
        attr = highlight_attr[HLF_E];
        if (msg_scrolled != 0) {
            need_wait_return = TRUE;
        }
        msg_scroll = TRUE;
        msg_source(attr);
        msg_nowait = false;
        r = msg_attr(s, attr);
        return r;
    }

    int emsg(BytePtr s) {
        if (emsg_not_now()) {
            return TRUE;
        }
        return emsg_core(s);
    }

    void iemsg(BytePtr s) {
        if (emsg_not_now()) {
            return;
        }
        emsg_core(new BytePtr(e_internal_error_please_report_a_bug, 0));
        emsg_core(s);
    }

    private void internal_error(BytePtr where) {
        emsg_core(new BytePtr(e_internal_error_please_report_a_bug, 0));
        vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_internal_error_str, 0), where);
        iemsg(iobuff_or(new BytePtr(e_internal_error_str, 0)));
    }

    private void emsg_invreg(int name) {
        vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_invalid_register_name_str, 0),
                transchar_buf(null, name));
        emsg(iobuff_or(new BytePtr(e_invalid_register_name_str, 0)));
    }

    private BytePtr msg_trunc_attr(BytePtr s, boolean force, int attr) {
        int n;
        BytePtr ts;
        add_msg_hist(s, -1, attr);
        ts = msg_may_trunc(force, s);
        msg_hist_off = true;
        n = msg_attr(ts, attr);
        msg_hist_off = false;
        if (n != 0) {
            return ts;
        }
        return null;
    }

    private BytePtr msg_may_trunc(boolean force, BytePtr s) {
        int n = 0;
        int room = (int) (Rows[0] - (long) cmdline_row - 1L) * cmdline_width + sc_col - 1;
        if (room > 0 && (force || shortmess(SHM_TRUNC)) && (n = (int) musl_strlen(s) - room) > 0) {
            int size = vim_strsize(s);
            if (size <= room) {
                return s;
            }
            for (n = 0; size >= room; ) {
                size -= utf_ptr2cells(s.add(n));
                n += utfc_ptr2len(s.add(n));
            }
            n--;
            s = s.add(n);
            s.put((byte) '<');
        }
        return s;
    }

    private void add_msg_hist(BytePtr s, int len, int attr) {
        S_msg_hist p;
        if (msg_hist_off || msg_silent != 0) {
            return;
        }
        p = new S_msg_hist();
        if (len < 0) {
            len = (int) musl_strlen(s);
        }
        while (len > 0 && s.get() == '\n') {
            s = s.add(1);
            len--;
        }
        while (len > 0 && s.at(len - 1) == '\n') {
            len--;
        }
        p.msg = vim_strnsave(s, (long) len);
        p.next = null;
        p.attr = attr;
        if (last_msg_hist != null) {
            last_msg_hist.next = p;
        }
        last_msg_hist = p;
        if (first_msg_hist == null) {
            first_msg_hist = last_msg_hist;
        }
        msg_hist_len++;
        check_msg_hist();
    }

    private boolean delete_first_msg() {
        S_msg_hist p;
        if (msg_hist_len <= 0) {
            return false;
        }
        p = first_msg_hist;
        first_msg_hist = p.next;
        if (first_msg_hist == null) {
            last_msg_hist = null;
        }
        msg_hist_len--;
        return true;
    }

    private void check_msg_hist() {
        while (msg_hist_len > 0 && msg_hist_len > msg_hist_max) {
            delete_first_msg();
        }
    }

    private boolean messagesopt_changed() {
        BytePtr[] p = new BytePtr[1];
        int messages_flags_new = 0;
        int messages_wait_new = 0;
        int messages_history_new = 0;
        p[0] = p_mopt[0];
        while (p[0].get() != NUL) {
            if (musl_strncmp(p[0], BytePtr.lit("hit-enter"), 9L) == 0) {
                p[0] = p[0].add(9);
                messages_flags_new |= MESSAGES_HIT_ENTER;
            } else if (musl_strncmp(p[0], BytePtr.lit("wait:"), 5L) == 0 && ascii_isdigit(p[0].u(5))) {
                p[0] = p[0].add(5);
                messages_wait_new = (int) getdigits(new Ptr<BytePtr>(p, 0));
                messages_flags_new |= MESSAGES_WAIT;
            } else if (musl_strncmp(p[0], BytePtr.lit("history:"), 8L) == 0 && ascii_isdigit(p[0].u(8))) {
                p[0] = p[0].add(8);
                messages_history_new = (int) getdigits(new Ptr<BytePtr>(p, 0));
                messages_flags_new |= MESSAGES_HISTORY;
            }
            if (p[0].get() != ',' && p[0].get() != NUL) {
                return false;
            }
            if (p[0].get() == ',') {
                p[0] = p[0].add(1);
            }
        }
        if ((messages_flags_new & (MESSAGES_HIT_ENTER | MESSAGES_WAIT)) == 0) {
            return false;
        }
        if ((messages_flags_new & MESSAGES_HISTORY) == 0) {
            return false;
        }
        if (messages_history_new < 0 || messages_history_new > 10000) {
            return false;
        }
        if (messages_wait_new < 0 || messages_wait_new > 10000) {
            return false;
        }
        msg_flags = messages_flags_new;
        msg_wait = messages_wait_new;
        msg_hist_max = messages_history_new;
        check_msg_hist();
        return true;
    }

    private void ex_messages(S_exarg eap) {
        S_msg_hist p;
        int c = 0;
        if (musl_strcmp(eap.arg[0], BytePtr.lit("clear")) == 0) {
            int keep = (int) (eap.addr_count == 0 ? 0L : eap.line2);
            while (msg_hist_len > keep) {
                delete_first_msg();
            }
            return;
        }
        if (eap.arg[0].get() != NUL) {
            emsg(new BytePtr(e_invalid_argument, 0));
            return;
        }
        msg_hist_off = true;
        p = first_msg_hist;
        if (eap.addr_count != 0) {
            for (; p != null && got_int == 0; p = p.next) {
                c++;
            }
            c -= (int) eap.line2;
            for (p = first_msg_hist; p != null && got_int == 0 && c > 0; p = p.next, c--) {
            }
        }
        for (; p != null && got_int == 0; p = p.next) {
            if (p.msg != null) {
                msg_attr(p.msg, p.attr);
            }
        }
        msg_hist_off = false;
    }

    private void wait_return(int redraw) {
        int c = 0;
        int oldState;
        int tmpState;
        int had_got_int = 0;
        int save_reg_recording = 0;
        if (redraw == TRUE) {
            set_must_redraw(UPD_CLEAR);
        }
        if (msg_silent != 0) {
            return;
        }
        if (vgetc_busy > 0) {
            return;
        }
        need_wait_return = TRUE;
        if (no_wait_return != 0) {
            cmdline_row = msg_row;
            return;
        }
        oldState = State;
        if (quit_more) {
            c = CAR;
            quit_more = false;
            got_int = FALSE;
        } else if (!stuff_empty()) {
            c = CAR;
        } else {
            screenalloc(false);
            State = 8192 | MODE_NORMAL;
            cmdline_row = msg_row;
            if ((msg_flags & MESSAGES_HIT_ENTER) != 0) {
                hit_return_msg();
                do {
                    had_got_int = got_int;
                    no_mapping++;
                    allow_keys++;
                    save_reg_recording = reg_recording;
                    reg_recording = 0;
                    c = safe_vgetc();
                    if (had_got_int != 0 && global_busy == 0) {
                        got_int = FALSE;
                    }
                    no_mapping--;
                    allow_keys--;
                    reg_recording = save_reg_recording;
                    if (KeyTyped && p_more[0] != 0 && p_cp[0] == 0) {
                        if (c == 'b' || c == Ctrl_B || c == 'k' || c == 'u' || c == 'g' || c == K_UP || c == K_PAGEUP) {
                            if ((long) msg_scrolled > Rows[0]) {
                                do_more_prompt(c);
                            } else {
                                msg_didout = FALSE;
                                c = K_IGNORE;
                                msg_col = 0;
                            }
                            if (quit_more) {
                                c = CAR;
                                quit_more = false;
                                got_int = FALSE;
                            } else if (c != K_IGNORE) {
                                c = K_IGNORE;
                                hit_return_msg();
                            }
                        } else if ((long) msg_scrolled > (Rows[0] - 2L)
                                && (c == 'j' || c == 'd' || c == 'f' || c == Ctrl_F || c == K_DOWN
                                || c == K_PAGEDOWN)) {
                            c = K_IGNORE;
                        }
                    }
                } while ((had_got_int != 0 && c == Ctrl_C) || c == K_IGNORE || c == K_LEFTDRAG || c == K_LEFTRELEASE
                        || c == K_MIDDLEDRAG || c == K_MIDDLERELEASE || c == K_RIGHTDRAG || c == K_RIGHTRELEASE
                        || c == K_MOUSELEFT || c == K_MOUSERIGHT || c == K_MOUSEDOWN || c == K_MOUSEUP
                        || c == K_MOUSEMOVE);
                ui_breakcheck();
                if (c == K_LEFTMOUSE || c == K_MIDDLEMOUSE || c == K_RIGHTMOUSE || c == K_X1MOUSE || c == K_X2MOUSE) {
                } else if (!KeyTyped || (vim_strchr(BytePtr.lit("\015\n "), c) == null && c != Ctrl_C && c != 'q')) {
                    ins_char_typebuf(vgetc_char, vgetc_mod_mask);
                    do_redraw = true;
                }
            } else {
                c = CAR;
                do_sleep((long) msg_wait, true);
            }
        }
        if (c == ':' || c == '?' || c == '/') {
            cmdline_row = msg_row;
            skip_redraw = true;
            do_redraw = false;
        }
        tmpState = State;
        State = oldState;
        msg_check();
        if (swapping_screen() && !termcap_active) {
            newline_on_exit = true;
        }
        need_wait_return = FALSE;
        did_wait_return = true;
        emsg_on_display = false;
        lines_left = -1;
        reset_last_sourcing();
        if (keep_msg != null
                && (long) vim_strsize(keep_msg) >= (Rows[0] - (long) cmdline_row - 1L) * (long) cmdline_width + (long) sc_col) {
            keep_msg = null;
        }
        if (tmpState == MODE_SETWSIZE) {
            starttermcap();
            shell_resized();
        } else if (!skip_redraw && (redraw == TRUE || (msg_scrolled != 0 && redraw != -1))) {
            starttermcap();
            redraw_later(UPD_VALID);
        }
    }

    private void hit_return_msg() {
        int save_p_more = p_more[0];
        p_more[0] = FALSE;
        if (msg_didout != 0) {
            msg_putchar('\n');
        }
        if (got_int != 0) {
            msg_puts(BytePtr.lit("Interrupt: "));
        }
        msg_puts_attr(BytePtr.lit("Press ENTER or type command to continue"), highlight_attr[HLF_R]);
        if (!msg_use_printf()) {
            msg_clr_eos();
        }
        p_more[0] = save_p_more;
    }

    private void set_keep_msg(BytePtr s, int attr) {
        if (s != null && msg_silent == 0) {
            keep_msg = vim_strsave(s);
        } else {
            keep_msg = null;
        }
        keep_msg_more = false;
        keep_msg_attr = attr;
    }

    private void set_keep_msg_from_hist() {
        if (keep_msg == null && last_msg_hist != null && msg_scrolled == 0 && (State & MODE_NORMAL) != 0) {
            set_keep_msg(last_msg_hist.msg, last_msg_hist.attr);
        }
    }

    private void msg_start() {
        if (msg_row < cmdline_row) {
            msg_row = cmdline_row;
        }
        if (msg_silent == 0) {
            keep_msg = null;
            need_fileinfo = false;
        }
        if (msg_scroll == 0 && full_screen != 0) {
            msg_row = cmdline_row;
            msg_col = 0;
        } else if (msg_didout != 0 || in_echowindow != 0) {
            msg_putchar('\n');
            cmdline_row = msg_row;
        }
        if (!msg_didany || lines_left < 0) {
            msg_starthere();
        }
        if (msg_silent == 0) {
            msg_didout = FALSE;
            cursor_off();
        }
    }

    private void msg_starthere() {
        lines_left = cmdline_row;
        msg_didany = false;
    }

    private void msg_putchar(int c) {
        msg_putchar_attr(c, 0);
    }

    private void msg_putchar_attr(int c, int attr) {
        int t1 = 0;
        byte[] buf = new byte[22];
        if (c < 0) {
            buf[0] = -128;
            buf[1] = (byte) (c == 128 ? KS_SPECIAL : (c == NUL ? KS_ZERO : -c & 255));
            buf[2] = (byte) (c == 128 || c == NUL ? 'X' : (-c >>> 8) & 255);
            buf[3] = NUL;
        } else {
            t1 = utf_char2bytes(c, new BytePtr(buf, 0));
            buf[t1] = NUL;
        }
        msg_puts_attr(new BytePtr(buf, 0), attr);
    }

    private int msg_outtrans(BytePtr str) {
        return msg_outtrans_attr(str, 0);
    }

    private int msg_outtrans_attr(BytePtr str, int attr) {
        return msg_outtrans_len_attr(str, (int) musl_strlen(str), attr);
    }

    private int msg_outtrans_len(BytePtr str, int len) {
        return msg_outtrans_len_attr(str, len, 0);
    }

    private int msg_outtrans_len_attr(BytePtr msgstr, int len, int attr) {
        int retval = 0;
        BytePtr str = msgstr;
        BytePtr plain_start = msgstr;
        BytePtr s = null;
        int mb_l = 0;
        int c = 0;
        int save_got_int = got_int;
        got_int = FALSE;
        if (attr == 0) {
            attr = highlight_attr[HLF_MSG];
        }
        if ((attr & MSG_HIST) != 0) {
            add_msg_hist(str, len, attr);
            attr &= ~MSG_HIST;
        }
        if (msg_silent == 0 && len > 0 && msg_row >= cmdline_row && msg_col == 0) {
            clear_cmdline = false;
            mode_displayed = false;
        }
        if (utf_iscomposing(utf_ptr2char(msgstr))) {
            msg_puts_attr(BytePtr.lit(" "), attr);
        }
        while (--len >= 0 && got_int == 0) {
            mb_l = utfc_ptr2len_len(str, len + 1);
            if (mb_l > 1) {
                c = utf_ptr2char(str);
                if (vim_isprintc(c)) {
                    retval += utf_ptr2cells(str);
                } else {
                    if (str.gt(plain_start)) {
                        msg_puts_attr_len(plain_start, (int) str.sub(plain_start), attr);
                    }
                    plain_start = str.add(mb_l);
                    msg_puts_attr(transchar_buf(null, c), attr == 0 ? highlight_attr[HLF_8] : attr);
                    retval += char2cells(c);
                }
                len -= mb_l - 1;
                str = str.add(mb_l);
            } else {
                s = transchar_byte_buf(null, str.u());
                if (s.at(1) != NUL) {
                    if (str.gt(plain_start)) {
                        msg_puts_attr_len(plain_start, (int) str.sub(plain_start), attr);
                    }
                    plain_start = str.add(1);
                    msg_puts_attr(s, attr == 0 ? highlight_attr[HLF_8] : attr);
                    retval += (int) musl_strlen(s);
                } else {
                    retval++;
                }
                str = str.add(1);
            }
        }
        if (str.gt(plain_start) && got_int == 0) {
            msg_puts_attr_len(plain_start, (int) str.sub(plain_start), attr);
        }
        got_int |= save_got_int;
        return retval;
    }

    private int msg_outtrans_special(BytePtr strstart, boolean from, int maxlen) {
        BytePtr[] str = new BytePtr[1];
        str[0] = strstart;
        int retval = 0;
        BytePtr text = null;
        int len = 0;
        int attr = highlight_attr[HLF_8];
        while (str[0].get() != NUL) {
            if ((BytePtr.eq(str[0], strstart) || str[0].at(1) == NUL) && str[0].get() == ' ') {
                text = BytePtr.lit("<Space>");
                str[0] = str[0].add(1);
            } else {
                text = str2special(new Ptr<BytePtr>(str, 0), from, false);
            }
            if ((int) text.at(0) != NUL && (int) text.at(1) == NUL) {
                text = transchar_byte_buf(null, text.u(0));
            }
            len = vim_strsize(text);
            if (maxlen > 0 && retval + len >= maxlen) {
                break;
            }
            msg_puts_attr(text, len > 1 && utfc_ptr2len(text) <= 1 ? attr : 0);
            retval += len;
        }
        return retval;
    }

    private BytePtr str2special(Ptr<BytePtr> sp, boolean replace_spaces, boolean replace_others) {
        int c;
        BytePtr str = sp.get();
        int modifiers = 0;
        boolean special = false;
        BytePtr p = mb_unescape(sp);
        if (p != null) {
            return p;
        }
        c = str.u();
        if (c == 128 && str.at(1) != NUL && str.at(2) != NUL) {
            if (str.u(1) == KS_MODIFIER) {
                modifiers = str.u(2);
                str = str.add(3);
                c = str.u();
            }
            if (c == 128 && str.at(1) != NUL && str.at(2) != NUL) {
                c = str.u(1) == KS_SPECIAL ? 128 : (str.u(1) == KS_ZERO ? -(KS_ZERO + ('X' << 8)) : -(str.u(1) + (str.u(2) << 8)));
                str = str.add(2);
            }
            if (c < 0 || modifiers != 0) {
                special = true;
            }
        }
        if (!(c < 0) && (int) mb_bytelen_tab[c] > 1) {
            BytePtr p_2;
            sp.put(str);
            p_2 = mb_unescape(sp);
            if (p_2 != null) {
                c = utf_ptr2char(p_2);
            } else {
                sp.put(str.add(1));
            }
        } else {
            sp.put(str.add(str.get() == NUL ? 0 : 1));
        }
        if (special || c < ' ' || (replace_spaces && c == ' ')
                || (replace_others && (c == '<' || c == '|' || c == '\\'))) {
            return get_special_key_name(c, modifiers);
        }
        str2special_buf[0] = (byte) c;
        str2special_buf[1] = NUL;
        return new BytePtr(str2special_buf, 0);
    }

    private void str2specialbuf(BytePtr sp_arg, BytePtr buf, int len) {
        BytePtr[] sp = new BytePtr[] {sp_arg};
        BytePtr s = null;
        long buf_len = 0L;
        long s_len = 0;
        buf.put((byte) NUL);
        while (sp[0].get() != 0) {
            s = str2special(new Ptr<BytePtr>(sp, 0), false, false);
            s_len = musl_strlen(s);
            if (Long.compareUnsigned(buf_len + s_len, (long) len) < 0) {
                musl_strcpy(buf.add((int) buf_len), s);
                buf_len += s_len;
            } else {
                break;
            }
        }
    }

    private void msg_prt_line(BytePtr s, int list) {
        BytePtr t1 = null;
        BytePtr t2 = null;
        BytePtr t3 = null;
        int c = 0;
        int col = 0;
        int n_extra = 0;
        int c_extra = 0;
        int c_final = 0;
        BytePtr p_extra = null;
        int n = 0;
        int attr = 0;
        BytePtr trail = null;
        BytePtr lead = null;
        boolean in_multispace = false;
        int multispace_pos = 0;
        int l = 0;
        byte[] buf = new byte[22];
        if (curwin.w_onebuf_opt.wo_list[0] != 0) {
            list = TRUE;
        }
        if (list != 0) {
            if (curwin.w_lcs_chars.trail[0] != 0) {
                trail = s.add((int) musl_strlen(s));
                while (trail.gt(s) && (trail.at(-1) == ' ' || trail.at(-1) == '\t')) {
                    trail = trail.add(-1);
                }
            }
            if (curwin.w_lcs_chars.lead[0] != 0 || curwin.w_lcs_chars.leadmultispace != null
                    || curwin.w_lcs_chars.leadtab1 != NUL) {
                lead = s;
                while (lead.at(0) == ' ' || lead.at(0) == '\t') {
                    lead = lead.add(1);
                }
                if (lead.get() == NUL) {
                    lead = null;
                }
            }
        }
        if (s.get() == NUL && !(list != 0 && curwin.w_lcs_chars.eol[0] != NUL)) {
            msg_putchar(' ');
        }
        while (got_int == 0) {
            if (n_extra > 0) {
                n_extra--;
                if (n_extra == 0 && c_final != 0) {
                    c = c_final;
                } else if (c_extra != 0) {
                    c = c_extra;
                } else {
                    t1 = p_extra;
                    p_extra = p_extra.add(1);
                    c = t1.u();
                }
            } else if ((l = utfc_ptr2len(s)) > 1) {
                col += utf_ptr2cells(s);
                if (l >= MB_MAXBYTES) {
                    musl_strcpy(new BytePtr(buf, 0), BytePtr.lit("?"));
                } else if (curwin.w_lcs_chars.nbsp[0] != NUL && list != 0
                        && (utf_ptr2char(s) == 160 || utf_ptr2char(s) == 8239)) {
                    int len = utf_char2bytes(curwin.w_lcs_chars.nbsp[0], new BytePtr(buf, 0));
                    buf[len] = NUL;
                } else {
                    Rt.memmove(new BytePtr(buf, 0), s, (long) l);
                    buf[l] = NUL;
                }
                msg_puts(new BytePtr(buf, 0));
                s = s.add(l);
                continue;
            } else {
                attr = 0;
                t2 = s;
                s = s.add(1);
                c = t2.u();
                if (list != 0) {
                    in_multispace = c == ' ' && (s.get() == ' ' || (col > 0 && s.at(-2) == ' '));
                    if (!in_multispace) {
                        multispace_pos = 0;
                    }
                }
                if (c == TAB && (list == 0 || curwin.w_lcs_chars.tab1 != 0)) {
                    n_extra = (int) (curbuf.b_p_ts[0] - (long) col % curbuf.b_p_ts[0] - 1L);
                    if (list == 0) {
                        c = ' ';
                        c_extra = ' ';
                        c_final = NUL;
                    } else {
                        int lcs_tab1 = curwin.w_lcs_chars.tab1;
                        int lcs_tab2 = curwin.w_lcs_chars.tab2[0];
                        int lcs_tab3 = curwin.w_lcs_chars.tab3;
                        if (lead != null && s.le(lead) && curwin.w_lcs_chars.leadtab1 != NUL) {
                            lcs_tab1 = curwin.w_lcs_chars.leadtab1;
                            lcs_tab2 = curwin.w_lcs_chars.leadtab2[0];
                            lcs_tab3 = curwin.w_lcs_chars.leadtab3;
                        }
                        c = n_extra == 0 && lcs_tab3 != 0 ? lcs_tab3 : lcs_tab1;
                        c_extra = lcs_tab2;
                        c_final = lcs_tab3;
                        attr = highlight_attr[HLF_8];
                    }
                } else if (c == 160 && list != 0 && curwin.w_lcs_chars.nbsp[0] != NUL) {
                    c = curwin.w_lcs_chars.nbsp[0];
                    attr = highlight_attr[HLF_8];
                } else if (c == NUL && list != 0 && curwin.w_lcs_chars.eol[0] != NUL) {
                    p_extra = BytePtr.lit("");
                    c_extra = NUL;
                    c_final = NUL;
                    n_extra = 1;
                    c = curwin.w_lcs_chars.eol[0];
                    attr = highlight_attr[HLF_AT];
                    s = s.add(-1);
                } else if (c != NUL && (n = byte2cells(c)) > 1) {
                    n_extra = n - 1;
                    p_extra = transchar_byte_buf(null, c);
                    c_extra = NUL;
                    c_final = NUL;
                    t3 = p_extra;
                    p_extra = p_extra.add(1);
                    c = t3.u();
                    attr = highlight_attr[HLF_8];
                } else if (c == ' ') {
                    if (lead != null && s.le(lead) && in_multispace && curwin.w_lcs_chars.leadmultispace != null) {
                        c = curwin.w_lcs_chars.leadmultispace.at(multispace_pos++);
                        if (curwin.w_lcs_chars.leadmultispace.at(multispace_pos) == NUL) {
                            multispace_pos = 0;
                        }
                        attr = highlight_attr[HLF_8];
                    } else if (lead != null && s.le(lead) && curwin.w_lcs_chars.lead[0] != NUL) {
                        c = curwin.w_lcs_chars.lead[0];
                        attr = highlight_attr[HLF_8];
                    } else if (trail != null && s.gt(trail)) {
                        c = curwin.w_lcs_chars.trail[0];
                        attr = highlight_attr[HLF_8];
                    } else if (in_multispace && curwin.w_lcs_chars.multispace != null) {
                        c = curwin.w_lcs_chars.multispace.at(multispace_pos++);
                        if (curwin.w_lcs_chars.multispace.at(multispace_pos) == NUL) {
                            multispace_pos = 0;
                        }
                        attr = highlight_attr[HLF_8];
                    } else if (list != 0 && curwin.w_lcs_chars.space[0] != NUL) {
                        c = curwin.w_lcs_chars.space[0];
                        attr = highlight_attr[HLF_8];
                    }
                }
            }
            if (c == NUL) {
                break;
            }
            msg_putchar_attr(c, attr);
            col++;
        }
        msg_clr_eos();
    }

    private BytePtr screen_puts_mbyte(BytePtr s, int l, int attr) {
        int cw;
        msg_didout = TRUE;
        cw = utf_ptr2cells(s);
        if (cw > 1 && msg_col == cmdline_width - 1) {
            msg_screen_putchar('>', highlight_attr[HLF_AT]);
            return s;
        }
        screen_puts_len(s, l, msg_row, cmdline_col_off + msg_col, attr);
        msg_col += cw;
        if (msg_col >= cmdline_width) {
            msg_col = 0;
            msg_row++;
        }
        return s.add(l);
    }

    private void msg_puts(BytePtr s) {
        msg_puts_attr(s, 0);
    }

    private void msg_puts_title(BytePtr s) {
        msg_puts_attr(s, highlight_attr[HLF_T]);
    }

    private void msg_puts_attr(BytePtr s, int attr) {
        msg_puts_attr_len(s, -1, attr);
    }

    private void msg_puts_attr_len(BytePtr str, int maxlen, int attr) {
        if (msg_silent != 0) {
            return;
        }
        if (attr == 0) {
            attr = highlight_attr[HLF_MSG];
        }
        if ((attr & MSG_HIST) != 0 && maxlen < 0) {
            add_msg_hist(str, -1, attr);
            attr &= ~MSG_HIST;
        }
        if (msg_scrolled != 0 && !msg_scrolled_ign && musl_strcmp(str, BytePtr.lit("\015")) != 0) {
            need_wait_return = TRUE;
        }
        msg_didany = true;
        if (msg_use_printf()) {
            host_message(str, maxlen, !info_message ? 1 : 0);
            msg_didout = TRUE;
        } else {
            msg_puts_display(str, maxlen, attr, false);
        }
        need_fileinfo = false;
    }

    private void msg_puts_display(BytePtr str, int maxlen, int attr, boolean recurse) {
        T_store_sb_text__out_T store_sb_text__o = new T_store_sb_text__out_T();
        BytePtr s = str;
        BytePtr t_s = str;
        int t_col = 0;
        int l = 0;
        int cw = 0;
        BytePtr sb_str = str;
        int sb_col = msg_col;
        boolean wrap = false;
        boolean did_last_char = false;
        did_wait_return = false;
        while ((maxlen < 0 || (int) s.sub(str) < maxlen) && s.get() != NUL) {
            int wrap_col = cmdline_width - 1;
            if (!recurse && (long) msg_row >= Rows[0] - 1L
                    && (s.get() == '\n'
                    || ((s.get() != '\r' && msg_col + t_col >= wrap_col)
                    || (s.get() == TAB && msg_col + t_col >= (wrap_col & -8))
                    || (utf_ptr2cells(s) > 1 && msg_col + t_col >= wrap_col - 1)))) {
                if (t_col > 0) {
                    t_col = t_puts(t_col, t_s, s, attr);
                }
                if (msg_no_more && lines_left == 0) {
                    break;
                }
                msg_scroll_up();
                msg_row = (int) (Rows[0] - 2L);
                if (msg_col >= cmdline_width) {
                    msg_col = cmdline_width - 1;
                }
                if (s.u() >= ' ') {
                    if (maxlen >= 0) {
                        l = utfc_ptr2len_len(s, (int) str.add(maxlen).sub(s));
                    } else {
                        l = utfc_ptr2len(s);
                    }
                    s = screen_puts_mbyte(s, l, attr);
                    did_last_char = true;
                } else {
                    did_last_char = false;
                }
                if (p_more[0] != 0) {
                    store_sb_text__o = store_sb_text(sb_str, s, attr, sb_col, true);
                    sb_str = store_sb_text__o.sb_str;
                    sb_col = store_sb_text__o.sb_col;
                }
                inc_msg_scrolled();
                need_wait_return = TRUE;
                redraw_cmdline = TRUE;
                if (cmdline_row > 0) {
                    cmdline_row--;
                }
                if (lines_left > 0) {
                    lines_left--;
                }
                if (p_more[0] != 0 && lines_left == 0 && State != (8192 | MODE_NORMAL) && !msg_no_more) {
                    do_more_prompt(NUL);
                    if (quit_more) {
                        return;
                    }
                }
                if (did_last_char) {
                    continue;
                }
            }
            wrap = s.get() == '\n' || msg_col + t_col >= wrap_col
                    || (utf_ptr2cells(s) > 1 && msg_col + t_col >= wrap_col - 1);
            if (t_col > 0 && (wrap || s.get() == '\r' || s.get() == '\b' || s.get() == '\t' || s.get() == BELL)) {
                t_col = t_puts(t_col, t_s, s, attr);
            }
            if (wrap && p_more[0] != 0 && !recurse) {
                store_sb_text__o = store_sb_text(sb_str, s, attr, sb_col, true);
                sb_str = store_sb_text__o.sb_str;
                sb_col = store_sb_text__o.sb_col;
            }
            if (s.get() == '\n') {
                msg_didout = FALSE;
                msg_col = 0;
                if ((long) ++msg_row >= Rows[0]) {
                    msg_row = (int) (Rows[0] - 1L);
                }
            } else if (s.get() == '\r') {
                msg_col = 0;
            } else if (s.get() == '\b') {
                if (msg_col != 0) {
                    msg_col--;
                }
            } else if (s.get() == TAB) {
                do {
                    msg_screen_putchar(' ', attr);
                } while ((msg_col & 7) != 0);
            } else if (s.get() == BELL) {
                vim_beep(BO_SH);
            } else {
                cw = utf_ptr2cells(s);
                if (maxlen >= 0) {
                    l = utfc_ptr2len_len(s, (int) str.add(maxlen).sub(s));
                } else {
                    l = utfc_ptr2len(s);
                }
                if (cw > 1 && msg_col + t_col >= wrap_col) {
                    if (l > 1) {
                        s = screen_puts_mbyte(s, l, attr).add(-1);
                    } else {
                        msg_screen_putchar(s.u(), attr);
                    }
                } else {
                    if (t_col == 0) {
                        t_s = s;
                    }
                    t_col += cw;
                    s = s.add(l - 1);
                }
            }
            s = s.add(1);
        }
        if (t_col > 0) {
            t_puts(t_col, t_s, s, attr);
        }
        if (p_more[0] != 0 && !recurse && !(BytePtr.eq(s, sb_str.add(1)) && sb_str.get() == '\n')) {
            store_sb_text(sb_str, s, attr, sb_col, false);
        }
        msg_check();
    }

    private boolean message_filtered(BytePtr msg) {
        boolean match;
        if (cmdmod.cmod_filter_regmatch.regprog == null) {
            return false;
        }
        match = vim_regexec(cmdmod.cmod_filter_regmatch, msg, 0);
        return cmdmod.cmod_filter_force ? match : !match;
    }

    private void msg_scroll_up() {
        screen_del_lines(0, 0, 1, (int) Rows[0], true, 0, null);
        if (!can_clear(BytePtr.lit(" "))) {
            screen_fill((int) Rows[0] - 1, (int) Rows[0], cmdline_col_off, cmdline_col_off + cmdline_width, ' ', ' ',
                    highlight_attr[HLF_MSG]);
            if ((ScreenAttrs.at((int) (Integer.toUnsignedLong(LineOffset.at((int) (Rows[0] - 2L))) + Columns[0] - 1L)) & 0xffff) == 65535) {
                screen_fill((int) Rows[0] - 2, (int) Rows[0] - 1, (int) Columns[0] - 1, (int) Columns[0], ' ', ' ',
                        highlight_attr[HLF_MSG]);
            }
        }
    }

    private void inc_msg_scrolled() {
        msg_scrolled++;
        set_must_redraw(UPD_VALID);
    }

    private T_store_sb_text__out_T store_sb_text(BytePtr sb_str, BytePtr s, int attr, int sb_col, boolean finish) {
        T_store_sb_text__out_T out__ = new T_store_sb_text__out_T();
        S_msgchunk_S mp;
        if (do_clear_sb_text == SB_CLEAR_ALL || do_clear_sb_text == SB_CLEAR_CMDLINE_DONE) {
            clear_sb_text(do_clear_sb_text == SB_CLEAR_ALL);
            msg_sb_eol();
            do_clear_sb_text = SB_CLEAR_NONE;
        }
        if (s.gt(sb_str)) {
            mp = new S_msgchunk_S();
            mp.sb_text = BytePtr.alloc(s.sub(sb_str) + 1L);
            mp.sb_eol = (byte) (finish ? 1 : 0);
            mp.sb_msg_col = sb_col;
            mp.sb_attr = attr;
            vim_strncpy(mp.sb_text, sb_str, s.sub(sb_str));
            if (last_msgchunk[0] == null) {
                last_msgchunk[0] = mp;
                mp.sb_prev[0] = null;
            } else {
                mp.sb_prev[0] = last_msgchunk[0];
                last_msgchunk[0].sb_next = mp;
                last_msgchunk[0] = mp;
            }
            mp.sb_next = null;
        } else if (finish && last_msgchunk[0] != null) {
            last_msgchunk[0].sb_eol = TRUE;
        }
        sb_str = s;
        sb_col = 0;
        out__.sb_str = sb_str;
        out__.sb_col = sb_col;
        return out__;
    }

    private void may_clear_sb_text() {
        do_clear_sb_text = SB_CLEAR_ALL;
    }

    private void sb_text_start_cmdline() {
        if (do_clear_sb_text == SB_CLEAR_CMDLINE_BUSY) {
            sb_text_restart_cmdline();
        } else {
            msg_sb_eol();
            do_clear_sb_text = SB_CLEAR_CMDLINE_BUSY;
        }
    }

    private void sb_text_restart_cmdline() {
        S_msgchunk_S tofree;
        do_clear_sb_text = SB_CLEAR_CMDLINE_BUSY;
        if (last_msgchunk[0] == null || last_msgchunk[0].sb_eol != 0) {
            return;
        }
        tofree = msg_sb_start(last_msgchunk[0]);
        last_msgchunk[0] = tofree.sb_prev[0];
        if (last_msgchunk[0] != null) {
            last_msgchunk[0].sb_next = null;
        }
        while (tofree != null) {
            S_msgchunk_S tofree_next = tofree.sb_next;
            tofree = tofree_next;
        }
    }

    private void sb_text_end_cmdline() {
        do_clear_sb_text = SB_CLEAR_CMDLINE_DONE;
    }

    private void clear_sb_text(boolean all) {
        S_msgchunk_S mp = null;
        Ptr<S_msgchunk_S> lastp;
        if (all) {
            lastp = new Ptr<S_msgchunk_S>(last_msgchunk, 0);
        } else {
            if (last_msgchunk[0] == null) {
                return;
            }
            lastp = new Ptr<S_msgchunk_S>(msg_sb_start(last_msgchunk[0]).sb_prev, 0);
        }
        while (lastp.get() != null) {
            mp = lastp.get().sb_prev[0];
            lastp.put(mp);
        }
    }

    private void show_sb_text() {
        S_msgchunk_S mp = msg_sb_start(last_msgchunk[0]);
        if (mp == null || mp.sb_prev[0] == null) {
            vim_beep(BO_MESS);
        } else {
            do_more_prompt('G');
            wait_return(FALSE);
        }
    }

    private static S_msgchunk_S msg_sb_start(S_msgchunk_S mps) {
        S_msgchunk_S mp = mps;
        while (mp != null && mp.sb_prev[0] != null && mp.sb_prev[0].sb_eol == 0) {
            mp = mp.sb_prev[0];
        }
        return mp;
    }

    private void msg_sb_eol() {
        if (last_msgchunk[0] != null) {
            last_msgchunk[0].sb_eol = TRUE;
        }
    }

    private S_msgchunk_S disp_sb_line(int row, S_msgchunk_S smp, boolean clear_to_eol) {
        S_msgchunk_S mp = smp;
        BytePtr p = null;
        for (;;) {
            msg_row = row;
            msg_col = mp.sb_msg_col;
            p = mp.sb_text;
            if (p.get() == '\n') {
                p = p.add(1);
            }
            msg_puts_display(p, -1, mp.sb_attr, true);
            if (clear_to_eol) {
                screen_fill(row, row + 1, cmdline_col_off + msg_col, cmdline_col_off + cmdline_width, ' ', ' ',
                        highlight_attr[HLF_MSG]);
            }
            if (mp.sb_eol != 0 || mp.sb_next == null) {
                break;
            }
            mp = mp.sb_next;
        }
        return mp.sb_next;
    }

    private int t_puts(int t_col, BytePtr t_s, BytePtr s, int attr) {
        msg_didout = TRUE;
        screen_puts_len(t_s, (int) s.sub(t_s), msg_row, cmdline_col_off + msg_col, attr);
        msg_col += t_col;
        t_col = 0;
        if (utf_iscomposing(utf_ptr2char(t_s))) {
            msg_col--;
        }
        if (msg_col >= cmdline_width) {
            msg_col = 0;
            msg_row++;
        }
        return t_col;
    }

    private boolean msg_use_printf() {
        return !msg_check_screen() || (swapping_screen() && !termcap_active);
    }

    @SuppressWarnings("fallthrough")
    private boolean do_more_prompt(int typed_char) {
        int used_typed_char = typed_char;
        int oldState = State;
        int c = 0;
        int toscroll = 0;
        S_msgchunk_S mp_last = null;
        S_msgchunk_S mp = null;
        int i = 0;
        int msg_attr = highlight_attr[HLF_MSG];
        if (do_more_prompt_entered || (State == (8192 | MODE_NORMAL) && typed_char == 0)) {
            return false;
        }
        do_more_prompt_entered = true;
        if (typed_char == 'G') {
            mp_last = msg_sb_start(last_msgchunk[0]);
            for (i = 0; (long) i < Rows[0] - 2L && mp_last != null && mp_last.sb_prev[0] != null; i++) {
                mp_last = msg_sb_start(mp_last.sb_prev[0]);
            }
        }
        State = MODE_ASKMORE;
        if (typed_char == NUL) {
            msg_moremsg(false);
        }
        for (;;) {
            if (used_typed_char != NUL) {
                c = used_typed_char;
                used_typed_char = NUL;
            } else {
                c = get_keystroke();
            }
            toscroll = 0;
            switch (c) {
                case BS:
                case K_BS:
                case 'k':
                case K_UP:
                    toscroll = -1;
                    break;
                case CAR:
                case NL:
                case 'j':
                case K_DOWN:
                    toscroll = 1;
                    break;
                case 'u':
                    toscroll = (int) -(Rows[0] / 2L);
                    break;
                case 'd':
                    toscroll = (int) (Rows[0] / 2L);
                    break;
                case 'b':
                case Ctrl_B:
                case K_PAGEUP:
                    toscroll = (int) -(Rows[0] - 1L);
                    break;
                case ' ':
                case 'f':
                case Ctrl_F:
                case K_PAGEDOWN:
                case K_LEFTMOUSE:
                    toscroll = (int) (Rows[0] - 1L);
                    break;
                case 'g':
                    toscroll = -999999;
                    break;
                case 'G':
                    toscroll = 999999;
                    lines_left = 999999;
                    break;
                case ':':
                    typeahead_noflush(':');
                    cmdline_row = (int) (Rows[0] - 1L);
                    skip_redraw = true;
                    need_wait_return = FALSE;
                // fall through
                case 'q':
                case Ctrl_C:
                case ESC:
                    got_int = TRUE;
                    quit_more = true;
                    lines_left = (int) (Rows[0] - 1L);
                    break;
                default:
                    msg_moremsg(true);
                    continue;
            }
            if (toscroll != 0) {
                if (toscroll < 0) {
                    if (mp_last == null) {
                        mp = msg_sb_start(last_msgchunk[0]);
                    } else if (mp_last.sb_prev[0] != null) {
                        mp = msg_sb_start(mp_last.sb_prev[0]);
                    } else {
                        mp = null;
                    }
                    for (i = 0; (long) i < Rows[0] - 2L && mp != null && mp.sb_prev[0] != null; i++) {
                        mp = msg_sb_start(mp.sb_prev[0]);
                    }
                    if (mp != null && mp.sb_prev[0] != null) {
                        for (i = 0; i > toscroll; i--) {
                            if (mp == null || mp.sb_prev[0] == null) {
                                break;
                            }
                            mp = msg_sb_start(mp.sb_prev[0]);
                            if (mp_last == null) {
                                mp_last = msg_sb_start(last_msgchunk[0]);
                            } else {
                                mp_last = msg_sb_start(mp_last.sb_prev[0]);
                            }
                        }
                        if (toscroll == -1 && screen_ins_lines(0, 0, 1, (int) Rows[0], 0, null)) {
                            disp_sb_line(0, mp, false);
                        } else {
                            boolean did_clear = screenclear();
                            for (i = 0; mp != null && (long) i < Rows[0] - 1L; i++) {
                                mp = disp_sb_line(i, mp, !did_clear);
                                msg_scrolled++;
                            }
                        }
                        toscroll = 0;
                    }
                } else {
                    while (toscroll > 0 && mp_last != null) {
                        msg_scroll_up();
                        inc_msg_scrolled();
                        screen_fill((int) Rows[0] - 2, (int) Rows[0] - 1, cmdline_col_off,
                                cmdline_col_off + cmdline_width, ' ', ' ', msg_attr);
                        mp_last = disp_sb_line((int) Rows[0] - 2, mp_last, false);
                        toscroll--;
                    }
                }
                if (toscroll <= 0) {
                    screen_fill((int) Rows[0] - 1, (int) Rows[0], cmdline_col_off, cmdline_col_off + cmdline_width, ' ',
                            ' ', msg_attr);
                    msg_moremsg(false);
                    continue;
                }
                lines_left = toscroll;
            }
            break;
        }
        screen_fill((int) Rows[0] - 1, (int) Rows[0], cmdline_col_off, cmdline_col_off + cmdline_width, ' ', ' ',
                msg_attr);
        State = oldState;
        if (quit_more) {
            msg_row = (int) (Rows[0] - 1L);
            msg_col = 0;
        }
        do_more_prompt_entered = false;
        return false;
    }

    private void msg_screen_putchar(int c, int attr) {
        msg_didout = TRUE;
        screen_putchar(c, msg_row, cmdline_col_off + msg_col, attr);
        if (++msg_col >= cmdline_width) {
            msg_col = 0;
            msg_row++;
        }
    }

    private void msg_moremsg(boolean full) {
        BytePtr s = BytePtr.lit("-- More --");
        int attr = highlight_attr[HLF_M];
        screen_puts(s, (int) Rows[0] - 1, cmdline_col_off, attr);
        if (full) {
            screen_puts(BytePtr.lit(" SPACE/d/j: screen/page/line down, b/u/k: up, q: quit "), (int) Rows[0] - 1,
                    cmdline_col_off + vim_strsize(s), attr);
        }
    }

    private void repeat_message() {
        if (State == MODE_ASKMORE) {
            msg_moremsg(true);
            msg_row = (int) (Rows[0] - 1L);
        } else if (State == MODE_EXTERNCMD) {
            windgoto(msg_row, cmdline_col_off + msg_col);
        } else if (State == (8192 | MODE_NORMAL) || State == MODE_SETWSIZE) {
            if ((long) msg_row == Rows[0] - 1L) {
                msg_didout = FALSE;
                msg_col = 0;
                msg_clr_eos();
            }
            hit_return_msg();
            msg_row = (int) (Rows[0] - 1L);
        }
    }

    private boolean msg_check_screen() {
        if (full_screen == 0 || !screen_valid(false)) {
            return false;
        }
        if ((long) msg_row >= Rows[0]) {
            msg_row = (int) (Rows[0] - 1L);
        }
        if (msg_col >= cmdline_width) {
            msg_col = cmdline_width - 1;
        }
        return true;
    }

    private void msg_clr_eos() {
        if (msg_silent == 0) {
            msg_clr_eos_force();
        }
    }

    private void msg_clr_eos_force() {
        if (msg_use_printf()) {
            if (full_screen != 0) {
                if (term_strings[KS_CD].get() != 0) {
                    out_str(term_strings[KS_CD]);
                } else if (term_strings[KS_CE].get() != 0) {
                    out_str(term_strings[KS_CE]);
                }
            }
        } else {
            int msg_attr = highlight_attr[HLF_MSG];
            screen_fill(msg_row, msg_row + 1, cmdline_col_off + msg_col, cmdline_col_off + cmdline_width, ' ', ' ',
                    msg_attr);
            screen_fill(msg_row + 1, (int) Rows[0], cmdline_col_off, cmdline_col_off + cmdline_width, ' ', ' ',
                    msg_attr);
        }
    }

    private void msg_clr_cmdline() {
        msg_row = cmdline_row;
        msg_col = 0;
        msg_clr_eos_force();
    }

    private boolean msg_end() {
        if (!exiting && need_wait_return != 0 && (State & MODE_CMDLINE) == 0) {
            wait_return(FALSE);
            return false;
        }
        out_flush();
        return true;
    }

    private void msg_check() {
        if ((long) msg_row == Rows[0] - 1L && msg_col >= sc_col) {
            need_wait_return = TRUE;
            redraw_cmdline = TRUE;
        }
    }

    private void verbose_enter_scroll() {
        msg_scroll = TRUE;
    }

    private void verbose_leave_scroll() {
        cmdline_row = msg_row;
    }

    private void give_warning(BytePtr message, boolean hl) {
        give_warning_with_source(message, hl, false);
    }

    private void give_warning_with_source(BytePtr message, boolean hl, boolean with_source) {
        if (msg_silent != 0) {
            return;
        }
        no_wait_return++;
        keep_msg = null;
        if (hl) {
            keep_msg_attr = highlight_attr[HLF_W];
        } else {
            keep_msg_attr = 0;
        }
        if (with_source) {
            msg_start();
            msg_source(highlight_attr[HLF_W]);
            msg_puts(BytePtr.lit(" "));
            msg_puts_attr(message, highlight_attr[HLF_W] | MSG_HIST);
            msg_clr_eos();
            msg_end();
        } else if (msg_attr(message, keep_msg_attr) != 0 && msg_scrolled == 0) {
            set_keep_msg(message, keep_msg_attr);
        }
        msg_didout = FALSE;
        msg_nowait = true;
        msg_col = 0;
        no_wait_return--;
    }

    private void msg_advance(int col) {
        if (msg_silent != 0) {
            msg_col = col;
            return;
        }
        if (col >= cmdline_width) {
            col = cmdline_width - 1;
        }
        while (msg_col < col) {
            msg_putchar(' ');
        }
    }

    private void msg_warn_missing_clipboard() {
        if (global_busy == 0 && !did_warn_clipboard && silence_w23_w24_msg == 0) {
            msg(BytePtr.lit("W24: Clipboard register not available. See :h W24"));
            did_warn_clipboard = true;
        }
    }

    private int plines(long lnum) {
        return plines_win(curwin, lnum, true);
    }

    private int plines_win(S_window_S wp, long lnum, boolean limit_winheight) {
        int lines;
        if (wp.w_width == 0) {
            return 1;
        }
        if (wp.w_onebuf_opt.wo_wrap[0] == 0) {
            lines = 1;
        } else {
            lines = plines_win_nofold(wp, lnum);
        }
        if (limit_winheight && lines > wp.w_height) {
            return wp.w_height;
        }
        return lines;
    }

    private int plines_win_nofold(S_window_S wp, long lnum) {
        long col;
        int width;
        T_chartabsize_T cts = new T_chartabsize_T();
        BytePtr s = ml_get_buf(wp.w_buffer, lnum, false);
        init_chartabsize_arg(cts, wp, lnum, 0, s, s);
        if (s.get() == NUL) {
            return 1;
        }
        win_linetabsize_cts(cts, MAXCOL);
        col = (long) cts.cts_vcol;
        if (wp.w_onebuf_opt.wo_list[0] != 0 && wp.w_lcs_chars.eol[0] != NUL) {
            col += 1L;
        }
        width = wp.w_width - win_col_off(wp);
        if (width <= 0) {
            return 32000;
        }
        if (col <= (long) width) {
            return 1;
        }
        col -= (long) width;
        width += win_col_off2(wp);
        return (int) ((col + (long) (width - 1)) / (long) width + 1L);
    }

    private int plines_win_col(S_window_S wp, long lnum, long column) {
        long col;
        int lines = 0;
        int width;
        BytePtr line;
        T_chartabsize_T cts = new T_chartabsize_T();
        if (wp.w_onebuf_opt.wo_wrap[0] == 0) {
            return lines + 1;
        }
        if (wp.w_width == 0) {
            return lines + 1;
        }
        line = ml_get_buf(wp.w_buffer, lnum, false);
        init_chartabsize_arg(cts, wp, lnum, 0, line, line);
        while (cts.cts_ptr.get() != NUL && cts.cts_ptr.lt(line.add((int) column))) {
            cts.cts_vcol += win_lbr_chartabsize(cts, null, null);
            cts.cts_ptr = cts.cts_ptr.add(utfc_ptr2len(cts.cts_ptr));
        }
        col = (long) cts.cts_vcol;
        if (cts.cts_ptr.get() == TAB && (State & MODE_NORMAL) != 0
                && (wp.w_onebuf_opt.wo_list[0] == 0 || wp.w_lcs_chars.tab1 != 0)) {
            col += (long) (win_lbr_chartabsize(cts, null, null) - 1);
        }
        width = wp.w_width - win_col_off(wp);
        if (width <= 0) {
            return 9999;
        }
        lines += 1;
        if (col > ((long) width)) {
            lines += (int) ((col - (long) width) / (long) (width + win_col_off2(wp)) + 1L);
        }
        return lines;
    }

    private int plines_m_win(S_window_S wp, long first, long last, int max) {
        int count = 0;
        while (first <= last && count < max) {
            count += plines_win(wp, first, false);
            first++;
        }
        return max < count ? max : count;
    }

    private int gchar_pos(T_pos_T pos) {
        BytePtr ptr;
        int ptrlen;
        if (pos.col == MAXCOL) {
            return NUL;
        }
        ptrlen = ml_get_len(pos.lnum);
        ptr = ml_get_pos(pos);
        if (pos.col > ptrlen) {
            return NUL;
        }
        return utf_ptr2char(ptr);
    }

    private int gchar_cursor() {
        return utf_ptr2char(ml_get_cursor());
    }

    private void pchar_cursor(int c) {
        BytePtr t1 = null;
        t1 = ml_get_buf(curbuf, curwin.w_cursor.lnum, true).add(curwin.w_cursor.col);
        t1.put((byte) c);
    }

    private static BytePtr skip_to_option_part(BytePtr p) {
        if (p.get() == ',') {
            p = p.add(1);
        }
        while (p.get() == ' ') {
            p = p.add(1);
        }
        return p;
    }

    private void check_status(S_file_buffer buf) {
        S_window_S wp = curwin;
        if (wp.w_buffer == buf && wp.w_status_height != 0) {
            wp.w_redr_status = true;
            set_must_redraw(UPD_VALID);
        }
    }

    private int ask_yesno(BytePtr str, boolean direct) {
        int r = ' ';
        int save_State = State;
        if (exiting) {
            term_enter();
        }
        no_wait_return++;
        State = MODE_CONFIRM;
        no_mapping++;
        allow_keys++;
        while (r != 'y' && r != 'n') {
            vim_snprintf(IObuff, iobuff_room(), BytePtr.lit("%s (y/n)?"), str);
            msg_attr(iobuff_or(BytePtr.lit("%s (y/n)?")), highlight_attr[HLF_R]);
            if (direct) {
                r = get_keystroke();
            } else {
                r = plain_vgetc();
            }
            if (r == Ctrl_C || r == ESC) {
                r = 'n';
            }
            msg_putchar(r);
            out_flush();
        }
        no_wait_return--;
        State = save_State;
        no_mapping--;
        allow_keys--;
        return r;
    }

    private int get_keystroke() {
        BytePtr buf = null;
        int buflen = 150;
        int maxlen = 0;
        int[] len = new int[1];
        len[0] = 0;
        int n = 0;
        int save_mapped_ctrl_c = mapped_ctrl_c;
        int waited = 0;
        mod_mask[0] = 0;
        mapped_ctrl_c = FALSE;
        for (;;) {
            cursor_on();
            out_flush();
            maxlen = (buflen - 6 - len[0]) / 3;
            if (buf == null) {
                buf = BytePtr.alloc((long) buflen);
            } else if (maxlen < 10) {
                BytePtr t_buf = buf;
                int t_buflen = buflen;
                buflen += 100;
                buf = (BytePtr) host_alloc((long) buflen);
                Rt.memmove(buf, t_buf, (long) t_buflen);
                maxlen = (buflen - 6 - len[0]) / 3;
            }
            if (buf == null) {
                do_outofmem_msg((long) buflen);
                return ESC;
            }
            n = ui_inchar(buf.add(len[0]), maxlen, len[0] == 0 ? -1L : 100L, 0);
            if (n > 0) {
                n = fix_input_buffer(buf.add(len[0]), n);
                len[0] += n;
                waited = 0;
            } else if (len[0] > 0) {
                waited++;
            }
            if ((n = check_termcode(1, buf, buflen, new IntPtr(len, 0))) < 0
                    && (p_ttimeout[0] == 0 || (long) waited * 100L < (p_ttm[0] < 0L ? p_tm[0] : p_ttm[0]))) {
                continue;
            }
            if (n == KEYLEN_REMOVED) {
                if (must_redraw != 0 && need_wait_return == 0
                        && (State & (MODE_CMDLINE | (8192 | MODE_NORMAL) | MODE_ASKMORE)) == 0) {
                    update_screen(0);
                    setcursor();
                }
                continue;
            }
            if (n > 0) {
                len[0] = n;
            }
            if (len[0] == 0) {
                continue;
            }
            n = buf.u(0);
            if (n == 128) {
                n = buf.u(1) == KS_SPECIAL ? 128 : (buf.u(1) == KS_ZERO ? -(KS_ZERO + ('X' << 8)) : -(buf.u(1) + (buf.u(2) << 8)));
                if (buf.u(1) == KS_MODIFIER || n == K_IGNORE) {
                    if (buf.u(1) == KS_MODIFIER) {
                        mod_mask[0] = buf.u(2);
                    }
                    len[0] -= 3;
                    if (len[0] > 0) {
                        Rt.memmove(buf, buf.add(3), (long) len[0]);
                    }
                    continue;
                }
                break;
            }
            if ((int) mb_bytelen_tab[n] > len[0]) {
                continue;
            }
            buf.set(len[0] >= buflen ? buflen - 1 : len[0], (byte) NUL);
            n = utf_ptr2char(buf);
            if (n == intr_char) {
                n = ESC;
            }
            break;
        }
        mapped_ctrl_c = save_mapped_ctrl_c;
        return merge_modifyOtherKeys(n, new IntPtr(mod_mask, 0));
    }

    private void msgmore(long n) {
        long pn;
        if (global_busy != 0 || !messaging()) {
            return;
        }
        if (keep_msg != null && !keep_msg_more) {
            return;
        }
        if (n > 0L) {
            pn = n;
        } else {
            pn = -n;
        }
        if (pn > p_report[0]) {
            if (n > 0L) {
                vim_snprintf(new BytePtr(msg_buf, 0), MSG_BUF_LEN,
                        NGETTEXT(BytePtr.lit("%ld more line"), BytePtr.lit("%ld more lines"), pn), pn);
            } else {
                vim_snprintf(new BytePtr(msg_buf, 0), MSG_BUF_LEN,
                        NGETTEXT(BytePtr.lit("%ld line less"), BytePtr.lit("%ld fewer lines"), pn), pn);
            }
            if (got_int != 0) {
                vim_strcat(new BytePtr(msg_buf, 0), BytePtr.lit(" (Interrupted)"), MSG_BUF_LEN);
            }
            if (msg(new BytePtr(msg_buf, 0)) != 0) {
                set_keep_msg(new BytePtr(msg_buf, 0), 0);
                keep_msg_more = true;
            }
        }
    }

    private void beep_flush() {
        if (emsg_silent == 0) {
            flush_buffers(FLUSH_MINIMAL);
            vim_beep(BO_ERROR);
        }
    }

    private void vim_beep(int val) {
        if (emsg_silent != 0 || in_assert_fails) {
            return;
        }
        if (!((bo_flags[0] & val) != 0 || (bo_flags[0] & BO_ALL) != 0)) {
            if (!vim_beep_did_init || musl_now_ms() - vim_beep_start_tv > 500L) {
                vim_beep_did_init = true;
                vim_beep_start_tv = musl_now_ms();
                if (p_vb[0] != 0) {
                    out_str_cf(term_strings[KS_VB]);
                } else {
                    out_char(BELL);
                }
            }
        }
    }

    private static long expand_env_esc(BytePtr srcp, BytePtr dst, int dstlen, BytePtr esc_chars, boolean one,
            BytePtr startstr) {
        BytePtr t1 = null;
        BytePtr t2 = null;
        BytePtr t3 = null;
        BytePtr t4 = null;
        BytePtr dst_start = dst;
        BytePtr src = skipwhite(srcp);
        dstlen--;
        while (src.get() != 0 && dstlen > 0) {
            if (src.at(0) == '\\' && src.at(1) != NUL) {
                t1 = dst;
                dst = dst.add(1);
                t2 = src;
                src = src.add(1);
                t1.put(t2.get());
                dstlen--;
            }
            if (dstlen > 0) {
                t3 = dst;
                dst = dst.add(1);
                t4 = src;
                src = src.add(1);
                t3.put(t4.get());
                dstlen--;
            }
        }
        dst.put((byte) NUL);
        return dst.sub(dst_start);
    }

    private void prepare_to_exit() {
        windgoto((int) Rows[0] - 1, cmdline_col_off);
        int was_full_screen = full_screen;
        full_screen = TRUE;
        term_leave();
        full_screen = was_full_screen;
        stoptermcap();
        out_flush();
    }

    private void preserve_exit() {
        prepare_to_exit();
        really_exiting = true;
        out_str(IObuff);
        screen_start();
        out_flush();
        ml_close_notmod();
        ml_close_all(false);
        out_str(BytePtr.lit("Vim: Finished.\015\n"));
        getout(1);
    }

