    private int path_is_url(BytePtr p) {
        if (musl_strncmp(p, BytePtr.lit("://"), 3L) == 0) {
            return URL_SLASH;
        } else if (musl_strncmp(p, BytePtr.lit(":\\\\"), 3L) == 0) {
            return URL_BACKSLASH;
        }
        return 0;
    }

    private static T_vim_append_digit_long__out_T vim_append_digit_long(long value, int digit) {
        T_vim_append_digit_long__out_T out__ = new T_vim_append_digit_long__out_T();
        long x = value;
        if (x > ((LONG_MAX - (long) digit) / 10L)) {
            out__.r__ = false;
            out__.value = value;
            return out__;
        }
        value = x * 10L + (long) digit;
        out__.r__ = true;
        out__.value = value;
        return out__;
    }

    private static int trim_to_int(long x) {
        return (int) (x > INT_MAX ? INT_MAX : (x < INT_MIN ? INT_MIN : x));
    }

    private int virtual_active() {
        int cur_ve_flags = get_ve_flags();
        if (cur_ve_flags == VE_ALL || ((cur_ve_flags & VE_INSERT) != 0 && (State & MODE_INSERT) != 0)) {
            return TRUE;
        }
        if (virtual_op != MAYBE) {
            return virtual_op;
        }
        return (cur_ve_flags & VE_BLOCK) != 0 && VIsual_active && VIsual_mode == Ctrl_V ? 1 : 0;
    }

    private int getviscol() {
        int[] x = new int[1];
        getvvcol(curwin, curwin.w_cursor, new IntPtr(x, 0), null, null, 0);
        return x[0];
    }

    private boolean coladvance_force(int wcol) {
        boolean rc = coladvance2(curwin.w_cursor, true, FALSE, wcol);
        if (wcol == MAXCOL) {
            curwin.w_valid &= ~VALID_VIRTCOL;
        } else {
            set_valid_virtcol(curwin, wcol);
        }
        return rc;
    }

    private int getviscol2(int col, int coladd) {
        int[] x = new int[1];
        T_pos_T pos = new T_pos_T();
        pos.lnum = curwin.w_cursor.lnum;
        pos.col = col;
        pos.coladd = coladd;
        getvvcol(curwin, pos, new IntPtr(x, 0), null, null, 0);
        return x[0];
    }

    private boolean coladvance(int wantcol) {
        boolean rc = getvpos(curwin.w_cursor, wantcol);
        if (wantcol == MAXCOL || (rc ? 1 : 0) == FAIL) {
            curwin.w_valid &= ~VALID_VIRTCOL;
        } else if (ml_get_cursor().get() != TAB) {
            set_valid_virtcol(curwin, wantcol);
        }
        return rc;
    }

    private boolean getvpos(T_pos_T pos, int wantcol) {
        return coladvance2(pos, false, virtual_active(), wantcol);
    }

    private boolean coladvance2(T_pos_T pos, boolean addspaces, int finetune, int wcol_arg) {
        int wcol = wcol_arg;
        int idx;
        int col = 0;
        int csize = 0;
        boolean one_more = (State & MODE_INSERT) != 0 || restart_edit != NUL
                || (VIsual_active && p_sel[0].get() != 'o') || ((get_ve_flags() & VE_ONEMORE) != 0 && wcol < MAXCOL);
        BytePtr line = ml_get_buf(curbuf, pos.lnum, false);
        int linelen = ml_get_buf_len(curbuf, pos.lnum);
        if (wcol >= MAXCOL) {
            idx = linelen - 1 + (one_more ? 1 : 0);
            col = wcol;
            if ((addspaces || finetune != 0) && !VIsual_active) {
                curwin.w_curswant = linetabsize(curwin, pos.lnum) + (one_more ? 1 : 0);
                if (curwin.w_curswant > 0) {
                    curwin.w_curswant--;
                }
            }
        } else {
            int width = curwin.w_width - win_col_off(curwin);
            T_chartabsize_T cts = new T_chartabsize_T();
            if (finetune != 0 && curwin.w_onebuf_opt.wo_wrap[0] != 0 && curwin.w_width != 0 && wcol >= width
                    && width > 0) {
                csize = linetabsize_eol(curwin, pos.lnum);
                if (csize > 0) {
                    csize--;
                }
                if (wcol / width > (csize / width) && ((State & MODE_INSERT) == 0 || wcol > (csize + 1))) {
                    wcol = (csize / width + 1) * width - 1;
                }
            }
            init_chartabsize_arg(cts, curwin, pos.lnum, 0, line, line);
            while (cts.cts_vcol <= wcol && cts.cts_ptr.get() != NUL) {
                csize = lbr_chartabsize_adv(cts);
                cts.cts_vcol += csize;
            }
            col = cts.cts_vcol;
            idx = (int) cts.cts_ptr.sub(line);
            if (col > wcol || (virtual_active() == 0 && (one_more ? 1 : 0) == 0)) {
                idx -= 1;
                col -= csize;
            }
            if (virtual_active() != 0 && addspaces && wcol >= 0 && ((col != wcol && col != wcol + 1) || csize > 1)) {
                if (line.at(idx) == NUL) {
                    int correct = wcol - col;
                    BytePtr newline = BytePtr.alloc((long) (idx + correct + 1));
                    int t = 0;
                    if (newline == null) {
                        return false;
                    }
                    for (t = 0; t < idx; t++) {
                        newline.set(t, line.at(t));
                    }
                    for (t = 0; t < correct; t++) {
                        newline.set(t + idx, (byte) ' ');
                    }
                    newline.set(idx + correct, (byte) NUL);
                    ml_replace(pos.lnum, newline, false);
                    changed_bytes(pos.lnum, idx);
                    idx += correct;
                    col = wcol;
                } else {
                    int correct_2 = wcol - col - csize + 1;
                    BytePtr newline_2;
                    int t_2 = 0;
                    int s = 0;
                    int v = 0;
                    if (-correct_2 > csize) {
                        return false;
                    }
                    newline_2 = BytePtr.alloc((long) (linelen + csize));
                    for (t_2 = 0; t_2 < linelen; t_2++) {
                        if (t_2 != idx) {
                            newline_2.set(s++, line.at(t_2));
                        } else {
                            for (v = 0; v < csize; v++) {
                                newline_2.set(s++, (byte) ' ');
                            }
                        }
                    }
                    newline_2.set(linelen + csize - 1, (byte) NUL);
                    ml_replace(pos.lnum, newline_2, false);
                    changed_bytes(pos.lnum, idx);
                    idx += csize - 1 + correct_2;
                    col += correct_2;
                }
            }
        }
        if (idx < 0) {
            pos.col = 0;
        } else {
            pos.col = idx;
        }
        pos.coladd = 0;
        if (finetune != 0) {
            if (wcol == MAXCOL) {
                if (!one_more) {
                    int[] scol = new int[1];
                    int[] ecol = new int[1];
                    getvcol(curwin, pos, new IntPtr(scol, 0), null, new IntPtr(ecol, 0), 0);
                    pos.coladd = ecol[0] - scol[0];
                }
            } else {
                int b = wcol - col;
                if (b > 0 && b < MAXCOL - 2 * curwin.w_width) {
                    pos.coladd = b;
                }
                col += b;
            }
        }
        mb_adjustpos(curbuf, pos);
        if (wcol < 0 || col < wcol) {
            return false;
        }
        return true;
    }

    private int inc_cursor() {
        return inc(curwin.w_cursor);
    }

    private int inc(T_pos_T lp) {
        BytePtr p;
        if (lp.col != MAXCOL) {
            p = ml_get_pos(lp);
            if (p.get() != NUL) {
                int l = utfc_ptr2len(p);
                lp.col += l;
                return p.at(l) != NUL ? 0 : 2;
            }
        }
        if (lp.lnum != curbuf.b_ml.ml_line_count) {
            lp.col = 0;
            lp.lnum++;
            lp.coladd = 0;
            return 1;
        }
        return -1;
    }

    private int incl(T_pos_T lp) {
        int r = 0;
        if ((r = inc(lp)) >= 1 && lp.col != 0) {
            r = inc(lp);
        }
        return r;
    }

    private int dec_cursor() {
        return dec(curwin.w_cursor);
    }

    private int dec(T_pos_T lp) {
        BytePtr p;
        lp.coladd = 0;
        if (lp.col == MAXCOL) {
            p = ml_get(lp.lnum);
            lp.col = ml_get_len(lp.lnum);
            lp.col -= utf_head_off(p, p.add(lp.col));
            return 0;
        }
        if (lp.col > 0) {
            lp.col--;
            p = ml_get(lp.lnum);
            lp.col -= utf_head_off(p, p.add(lp.col));
            return 0;
        }
        if (lp.lnum > 1L) {
            lp.lnum--;
            p = ml_get(lp.lnum);
            lp.col = ml_get_len(lp.lnum);
            lp.col -= utf_head_off(p, p.add(lp.col));
            return 1;
        }
        return -1;
    }

    private int decl(T_pos_T lp) {
        int r = 0;
        if ((r = dec(lp)) == 1 && lp.col != 0) {
            r = dec(lp);
        }
        return r;
    }

    private static long get_cursor_rel_lnum(S_window_S wp, long lnum) {
        long cursor = wp.w_cursor.lnum;
        long retval = 0L;
        retval = lnum - cursor;
        return retval;
    }

    private void check_pos(S_file_buffer buf, T_pos_T pos) {
        int len;
        if (pos.lnum > buf.b_ml.ml_line_count) {
            pos.lnum = buf.b_ml.ml_line_count;
        }
        if (pos.col > 0) {
            len = ml_get_buf_len(buf, pos.lnum);
            if (pos.col > len) {
                pos.col = len;
            }
        }
    }

    private void check_cursor_lnum() {
        if (curwin.w_cursor.lnum > curbuf.b_ml.ml_line_count) {
            curwin.w_cursor.lnum = curbuf.b_ml.ml_line_count;
        }
        if (curwin.w_cursor.lnum <= 0L) {
            curwin.w_cursor.lnum = 1L;
        }
    }

    private void check_cursor_col() {
        check_cursor_col_win(curwin);
    }

    private void check_cursor_col_win(S_window_S win) {
        int oldcol = win.w_cursor.col;
        int oldcoladd = win.w_cursor.col + win.w_cursor.coladd;
        int cur_ve_flags = get_ve_flags();
        int len = ml_get_buf_len(win.w_buffer, win.w_cursor.lnum);
        if (len == 0) {
            win.w_cursor.col = 0;
        } else if (win.w_cursor.col >= len) {
            if ((State & MODE_INSERT) != 0 || restart_edit != 0 || (VIsual_active && p_sel[0].get() != 'o')
                    || (cur_ve_flags & VE_ONEMORE) != 0 || virtual_active() != 0) {
                win.w_cursor.col = len;
            } else {
                win.w_cursor.col = len - 1;
                mb_adjustpos(win.w_buffer, win.w_cursor);
            }
        } else if (win.w_cursor.col < 0) {
            win.w_cursor.col = 0;
        }
        if (oldcol == MAXCOL) {
            win.w_cursor.coladd = 0;
        } else if (cur_ve_flags == VE_ALL) {
            if (oldcoladd > win.w_cursor.col) {
                win.w_cursor.coladd = oldcoladd - win.w_cursor.col;
                if (win.w_cursor.col + 1 < len) {
                    int[] cs = new int[1];
                    int[] ce = new int[1];
                    getvcol(win, win.w_cursor, new IntPtr(cs, 0), null, new IntPtr(ce, 0), 0);
                    if (win.w_cursor.coladd > (ce[0] - cs[0])) {
                        win.w_cursor.coladd = ce[0] - cs[0];
                    }
                }
            } else {
                win.w_cursor.coladd = 0;
            }
        }
    }

    private void check_cursor() {
        check_cursor_lnum();
        check_cursor_col();
    }

    private void check_visual_pos() {
        if (VIsual.lnum > curbuf.b_ml.ml_line_count) {
            VIsual.lnum = curbuf.b_ml.ml_line_count;
            VIsual.col = 0;
            VIsual.coladd = 0;
        } else {
            int len = ml_get_len(VIsual.lnum);
            if (VIsual.col > len) {
                VIsual.col = len;
                VIsual.coladd = 0;
            }
        }
    }

    private void adjust_cursor_col() {
        if (curwin.w_cursor.col > 0 && (!VIsual_active || p_sel[0].get() == 'o') && gchar_cursor() == NUL) {
            curwin.w_cursor.col--;
        }
    }

    private boolean set_leftcol(int leftcol) {
        boolean retval = false;
        if (curwin.w_leftcol == leftcol) {
            return false;
        }
        curwin.w_leftcol = leftcol;
        changed_cline_bef_curs();
        long lastcol = (long) (curwin.w_leftcol + curwin.w_width - curwin_col_off() - 1);
        validate_virtcol();
        long siso = get_sidescrolloff_value();
        if (curwin.w_virtcol[0] > ((int) (lastcol - siso))) {
            retval = true;
            coladvance((int) (lastcol - siso));
        } else if ((long) curwin.w_virtcol[0] < (long) curwin.w_leftcol + siso) {
            retval = true;
            coladvance((int) ((long) curwin.w_leftcol + siso));
        }
        int[] s = new int[1];
        int[] e = new int[1];
        getvvcol(curwin, curwin.w_cursor, new IntPtr(s, 0), null, new IntPtr(e, 0), 0);
        if (e[0] > ((int) lastcol)) {
            retval = true;
            coladvance(s[0] - 1);
        } else if (s[0] < curwin.w_leftcol) {
            retval = true;
            if (!coladvance(e[0] + 1)) {
                curwin.w_leftcol = s[0];
                changed_cline_bef_curs();
            }
        }
        if (retval) {
            curwin.w_set_curswant = true;
        }
        redraw_later(UPD_NOT_VALID);
        return retval;
    }

    private T_copy_option_part__out_T copy_option_part(BytePtr option, BytePtr buf, int maxlen, BytePtr sep_chars) {
        BytePtr t1 = null;
        T_copy_option_part__out_T out__ = new T_copy_option_part__out_T();
        int len = 0;
        BytePtr p = option;
        if (p.get() == '.') {
            t1 = p;
            p = p.add(1);
            buf.set(len++, t1.get());
        }
        while (p.get() != NUL && vim_strchr(sep_chars, p.u()) == null) {
            if (p.at(0) == '\\' && vim_strchr(sep_chars, p.u(1)) != null) {
                p = p.add(1);
            }
            if (len < maxlen - 1) {
                buf.set(len++, p.get());
            }
            p = p.add(1);
        }
        buf.set(len, (byte) NUL);
        if (p.get() != NUL && p.get() != ',') {
            p = p.add(1);
        }
        p = skip_to_option_part(p);
        option = p;
        out__.r__ = len;
        out__.option = option;
        return out__;
    }

    private static boolean vim_isspace(int x) {
        return (x >= 9 && x <= 13) || x == ' ';
    }

    private int name_to_mod_mask(int c) {
        int i = 0;
        c = c < 'a' || c > 'z' ? c : c - ('a' - 'A');
        for (i = 0; (int) mod_mask_table[i].mod_mask != 0; i++) {
            if (c == (mod_mask_table[i].name & 0xff)) {
                return (int) mod_mask_table[i].mod_flag;
            }
        }
        return 0;
    }

    private int simplify_key(int key, IntPtr modifiers) {
        int i = 0;
        int key0;
        int key1;
        if ((modifiers.get() & (MOD_MASK_SHIFT | MOD_MASK_CTRL)) == 0) {
            return key;
        }
        if (key == TAB && (modifiers.get() & MOD_MASK_SHIFT) != 0) {
            modifiers.put(modifiers.get() & ~MOD_MASK_SHIFT);
            return K_TC_k_B;
        }
        key0 = -key & 255;
        key1 = (-key >>> 8) & 255;
        for (i = 0; modifier_keys_table[i] != NUL; i += MOD_KEYS_ENTRY_SIZE) {
            if (key0 == (modifier_keys_table[i + 3] & 0xff) && key1 == (modifier_keys_table[i + 4] & 0xff)
                    && (modifiers.get() & (modifier_keys_table[i] & 0xff)) != 0) {
                modifiers.put(modifiers.get() & ~(modifier_keys_table[i] & 0xff));
                return -((modifier_keys_table[i + 1] & 0xff) + ((modifier_keys_table[i + 2] & 0xff) << 8));
            }
        }
        return key;
    }

