    private void curs_rows(S_window_S wp) {
        long lnum = 0;
        boolean valid = false;
        boolean all_invalid = !redrawing() || wp.w_lines_valid == 0 || wp.w_lines.at(0).wl_lnum > wp.w_topline;
        int i = 0;
        wp.w_cline_row = 0;
        for (lnum = wp.w_topline; lnum < wp.w_cursor.lnum; i++) {
            valid = false;
            if (!all_invalid && i < wp.w_lines_valid) {
                if (wp.w_lines.at(i).wl_lnum < lnum || wp.w_lines.at(i).wl_valid == 0) {
                    continue;
                }
                if (wp.w_lines.at(i).wl_lnum == lnum) {
                    valid = true;
                } else if (wp.w_lines.at(i).wl_lnum > lnum) {
                    i--;
                }
            }
            if (valid && (lnum != wp.w_topline || wp.w_skipcol == 0)) {
                lnum++;
                wp.w_cline_row += wp.w_lines.at(i).wl_size & 0xffff;
            } else {
                wp.w_cline_row += plines_correct_topline(wp, lnum, true);
                lnum++;
            }
        }
        check_cursor_moved(wp);
        if ((wp.w_valid & VALID_CHEIGHT) == 0) {
            if (all_invalid || i == wp.w_lines_valid
                    || (i < wp.w_lines_valid
                    && (wp.w_lines.at(i).wl_valid == 0 || wp.w_lines.at(i).wl_lnum != wp.w_cursor.lnum))) {
                wp.w_cline_height = plines_win(wp, wp.w_cursor.lnum, true);
            } else if (i > wp.w_lines_valid) {
                wp.w_cline_height = 0;
            } else {
                wp.w_cline_height = wp.w_lines.at(i).wl_size & 0xffff;
            }
        }
        redraw_for_cursorline(curwin);
        wp.w_valid |= VALID_CROW | VALID_CHEIGHT;
    }

