    private int win_col_off2(S_window_S wp) {
        if ((wp.w_onebuf_opt.wo_nu[0] != 0 || wp.w_onebuf_opt.wo_rnu[0] != 0)
                && vim_strchr(p_cpo[0], CPO_NUMCOL) != null) {
            return 8;
        }
        return 0;
    }

    private int curwin_col_off2() {
        return win_col_off2(curwin);
    }

    private void curs_columns(boolean may_scroll) {
        long diff;
        int extra;
        long off_left;
        long off_right;
        int n;
        int p_lines;
        int width1;
        int width2 = 0;
        int new_leftcol;
        int[] startcol = new int[1];
        int[] endcol = new int[1];
        int prev_skipcol;
        long so = get_scrolloff_value();
        long siso = get_sidescrolloff_value();
        boolean did_sub_skipcol = false;
        update_topline();
        if ((curwin.w_valid & VALID_CROW) == 0) {
            curs_rows(curwin);
        }
        getvvcol(curwin, curwin.w_cursor, new IntPtr(startcol, 0), new IntPtr(curwin.w_virtcol, 0),
                new IntPtr(endcol, 0), 0);
        if (startcol[0] > dollar_vcol) {
            dollar_vcol = -1;
        }
        extra = curwin_col_off();
        curwin.w_wcol = curwin.w_virtcol[0] + extra;
        endcol[0] += extra;
        curwin.w_wrow = curwin.w_cline_row;
        width1 = curwin.w_width - extra;
        if (width1 <= 0) {
            curwin.w_wcol = curwin.w_width - 1;
            if (curwin.w_onebuf_opt.wo_wrap[0] != 0) {
                curwin.w_wrow = curwin.w_height - 1;
            } else {
                curwin.w_wrow = curwin.w_height - 1 - curwin.w_empty_rows;
            }
        } else if (curwin.w_onebuf_opt.wo_wrap[0] != 0 && curwin.w_width != 0) {
            width2 = width1 + curwin_col_off2();
            if (curwin.w_cursor.lnum == curwin.w_topline && curwin.w_skipcol > 0 && curwin.w_wcol >= curwin.w_skipcol) {
                if (curwin.w_skipcol <= width1) {
                    curwin.w_wcol -= width2;
                } else {
                    curwin.w_wcol -= width2 * ((curwin.w_skipcol - width1) / width2 + 1);
                }
                did_sub_skipcol = true;
            }
            if (curwin.w_wcol >= curwin.w_width) {
                n = (curwin.w_wcol - curwin.w_width) / width2 + 1;
                curwin.w_wcol -= n * width2;
                curwin.w_wrow += n;
            }
        } else if (may_scroll) {
            off_left = (long) (startcol[0] - curwin.w_leftcol) - siso;
            off_right = (long) (endcol[0] - curwin.w_leftcol) - ((long) curwin.w_width - siso) + 1L;
            if (off_left < 0L || off_right > 0L) {
                if (off_left < 0L) {
                    diff = -off_left;
                } else {
                    diff = off_right;
                }
                if (p_ss[0] == 0L || diff >= (long) (width1 / 2) || off_right >= off_left) {
                    new_leftcol = curwin.w_wcol - extra - width1 / 2;
                } else {
                    if (diff < p_ss[0]) {
                        diff = p_ss[0];
                    }
                    if (off_left < 0L) {
                        new_leftcol = curwin.w_leftcol - (int) diff;
                    } else {
                        new_leftcol = curwin.w_leftcol + (int) diff;
                    }
                }
                if (new_leftcol < 0) {
                    new_leftcol = 0;
                }
                if (new_leftcol != curwin.w_leftcol) {
                    curwin.w_leftcol = new_leftcol;
                    redraw_later(UPD_NOT_VALID);
                }
            }
            curwin.w_wcol -= curwin.w_leftcol;
        } else if (curwin.w_wcol > curwin.w_leftcol) {
            curwin.w_wcol -= curwin.w_leftcol;
        } else {
            curwin.w_wcol = 0;
        }
        prev_skipcol = curwin.w_skipcol;
        p_lines = 0;
        if ((curwin.w_wrow >= curwin.w_height
                || ((prev_skipcol > 0 || (long) curwin.w_wrow + so >= (long) curwin.w_height)
                && (p_lines = plines_win(curwin, curwin.w_cursor.lnum, false)) - 1 >= curwin.w_height))
                && curwin.w_height != 0 && curwin.w_cursor.lnum == curwin.w_topline && width2 > 0
                && curwin.w_width != 0) {
            extra = 0;
            if ((long) curwin.w_skipcol + so * (long) width2 > ((long) curwin.w_virtcol[0])) {
                extra = 1;
            }
            if (p_lines == 0) {
                p_lines = plines_win(curwin, curwin.w_cursor.lnum, false);
            }
            p_lines--;
            if ((long) p_lines > ((long) curwin.w_wrow + so)) {
                n = (int) ((long) curwin.w_wrow + so);
            } else {
                n = p_lines;
            }
            if ((long) n >= (long) (curwin.w_height + curwin.w_skipcol / width2) - so) {
                extra += 2;
            }
            if (extra == 3 || (long) curwin.w_height <= so * 2L) {
                n = curwin.w_virtcol[0] / width2;
                if (n > (curwin.w_height / 2)) {
                    n -= curwin.w_height / 2;
                } else {
                    n = 0;
                }
                if (n > (p_lines - curwin.w_height + 1)) {
                    n = p_lines - curwin.w_height + 1;
                }
                if (n > 0) {
                    curwin.w_skipcol = width1 + (n - 1) * width2;
                } else {
                    curwin.w_skipcol = 0;
                }
            } else if (extra == 1) {
                extra = (int) (((long) curwin.w_skipcol + so * (long) width2 - (long) curwin.w_virtcol[0] + (long) width2 - 1L) / (long) width2);
                if (extra > 0) {
                    if (extra * width2 > curwin.w_skipcol) {
                        extra = curwin.w_skipcol / width2;
                    }
                    curwin.w_skipcol -= extra * width2;
                }
            } else if (extra == 2) {
                endcol[0] = (n - curwin.w_height + 1) * width2;
                while (endcol[0] > curwin.w_virtcol[0]) {
                    endcol[0] -= width2;
                }
                if (endcol[0] > curwin.w_skipcol) {
                    curwin.w_skipcol = endcol[0];
                }
            }
            if (did_sub_skipcol) {
                curwin.w_wrow -= (curwin.w_skipcol - prev_skipcol) / width2;
            } else {
                curwin.w_wrow -= curwin.w_skipcol / width2;
            }
            if (curwin.w_wrow >= curwin.w_height) {
                extra = curwin.w_wrow - curwin.w_height + 1;
                curwin.w_skipcol += extra * width2;
                curwin.w_wrow -= extra;
            }
            extra = (prev_skipcol - curwin.w_skipcol) / width2;
            if (extra > 0) {
                win_ins_lines(curwin, 0, extra, false, false);
            } else if (extra < 0) {
                win_del_lines(curwin, 0, -extra, false, false, 0);
            }
        } else if (curwin.w_onebuf_opt.wo_sms[0] == 0) {
            curwin.w_skipcol = 0;
        }
        if (prev_skipcol != curwin.w_skipcol) {
            redraw_later(UPD_SOME_VALID);
        }
        curwin.w_valid_leftcol = curwin.w_leftcol;
        curwin.w_valid_skipcol = curwin.w_skipcol;
        curwin.w_valid |= VALID_WCOL | VALID_WROW | VALID_VIRTCOL;
    }

    private void cursor_correct_sms() {
        if (curwin.w_onebuf_opt.wo_sms[0] == 0 || curwin.w_onebuf_opt.wo_wrap[0] == 0
                || curwin.w_cursor.lnum != curwin.w_topline) {
            return;
        }
        long so = get_scrolloff_value();
        int width1 = curwin.w_width - curwin_col_off();
        int width2 = width1 + curwin_col_off2();
        int so_cols = (int) (so == 0L ? 0L : (long) width1 + (so - 1L) * (long) width2);
        int space_cols = (curwin.w_height - 1) * width2;
        int overlap;
        int top;
        int bot;
        int size = so == 0L ? 0 : linetabsize_eol(curwin, curwin.w_topline);
        if (curwin.w_topline == 1L && curwin.w_skipcol == 0) {
            so_cols = 0;
        } else if (so_cols > (space_cols / 2)) {
            so_cols = space_cols / 2;
        }
        while (so_cols > size && so_cols - width2 >= width1 && width1 > 0) {
            so_cols -= width2;
        }
        if (so_cols >= width1 && so_cols > size) {
            so_cols -= width1;
        }
        overlap = curwin.w_skipcol == 0 ? 0 : sms_marker_overlap(curwin, curwin.w_width - width2);
        top = curwin.w_skipcol + (so_cols != 0 ? so_cols : overlap);
        bot = curwin.w_skipcol + width1 + (curwin.w_height - 1) * width2 - so_cols;
        validate_virtcol();
        int col = curwin.w_virtcol[0];
        if (col < top) {
            if (col < width1) {
                col += width1;
            }
            while (width2 > 0 && col < top) {
                col += width2;
            }
        } else {
            while (width2 > 0 && col >= bot) {
                col -= width2;
            }
        }
        if (col != curwin.w_virtcol[0]) {
            boolean rc;
            curwin.w_curswant = col;
            rc = coladvance(curwin.w_curswant);
            curwin.w_valid &= ~(VALID_WROW | VALID_WCOL | VALID_CHEIGHT | VALID_CROW | VALID_VIRTCOL);
            if ((rc ? 1 : 0) == FAIL && curwin.w_skipcol > 0 && curwin.w_cursor.lnum < curbuf.b_ml.ml_line_count) {
                validate_virtcol();
                if (curwin.w_virtcol[0] < curwin.w_skipcol + overlap) {
                    curwin.w_cursor.lnum++;
                    curwin.w_cursor.col = 0;
                    curwin.w_cursor.coladd = 0;
                    curwin.w_curswant = 0;
                    curwin.w_valid &= ~VALID_VIRTCOL;
                }
            }
        }
    }

    private void scroll_redraw(int up, long count) {
        long prev_topline = curwin.w_topline;
        int prev_skipcol = curwin.w_skipcol;
        long prev_lnum = curwin.w_cursor.lnum;
        if (up != 0) {
            scrollup(count, true);
        } else {
            scrolldown(count, true);
        }
        if (get_scrolloff_value() > 0L) {
            cursor_correct();
            check_cursor_moved(curwin);
            curwin.w_valid |= VALID_TOPLINE;
            while (curwin.w_topline == prev_topline && curwin.w_skipcol == prev_skipcol) {
                if (up != 0) {
                    if (curwin.w_cursor.lnum > prev_lnum || !cursor_down(1L, false)) {
                        break;
                    }
                } else {
                    if (curwin.w_cursor.lnum < prev_lnum || prev_topline == 1L || !cursor_up(1L, false)) {
                        break;
                    }
                }
                check_cursor_moved(curwin);
                curwin.w_valid |= VALID_TOPLINE;
            }
        }
        cursor_correct_sms();
        if (curwin.w_cursor.lnum != prev_lnum) {
            coladvance(curwin.w_curswant);
        }
        redraw_later(UPD_VALID);
    }

    private void scrolldown(long line_count, boolean byfold) {
        long t1 = 0;
        long done = 0L;
        int wrow;
        boolean moved = false;
        boolean do_sms = curwin.w_onebuf_opt.wo_wrap[0] != 0 && curwin.w_onebuf_opt.wo_sms[0] != 0;
        int width1 = 0;
        int width2 = 0;
        if (do_sms) {
            width1 = curwin.w_width - curwin_col_off();
            width2 = width1 + curwin_col_off2();
        }
        validate_cursor();
        for (int todo = (int) line_count; todo > 0; todo--) {
            if (curwin.w_topline == 1L && (!do_sms || curwin.w_skipcol < width1)) {
                break;
            }
            if (do_sms && curwin.w_skipcol >= width1) {
                if (curwin.w_skipcol >= width1 + width2) {
                    curwin.w_skipcol -= width2;
                } else {
                    curwin.w_skipcol -= width1;
                }
                redraw_later(UPD_NOT_VALID);
                done++;
            } else {
                curwin.w_topline--;
                curwin.w_skipcol = 0;
                if (do_sms) {
                    int size = linetabsize_eol(curwin, curwin.w_topline);
                    if (size > width1) {
                        curwin.w_skipcol = width1;
                        size -= width1;
                        redraw_later(UPD_NOT_VALID);
                    }
                    while (size > width2) {
                        curwin.w_skipcol += width2;
                        size -= width2;
                    }
                    done++;
                } else {
                    done += (long) plines(curwin.w_topline);
                }
            }
            curwin.w_botline--;
            invalidate_botline();
        }
        curwin.w_wrow += (int) done;
        curwin.w_cline_row += (int) done;
        wrow = curwin.w_wrow;
        if (curwin.w_onebuf_opt.wo_wrap[0] != 0 && curwin.w_width != 0) {
            validate_virtcol();
            validate_cheight();
            wrow += curwin.w_cline_height - 1 - curwin.w_virtcol[0] / curwin.w_width;
        }
        while (wrow >= curwin.w_height && curwin.w_cursor.lnum > 1L) {
            t1 = curwin.w_cursor.lnum;
            curwin.w_cursor.lnum--;
            wrow -= plines(t1);
            curwin.w_valid &= ~(VALID_WROW | VALID_WCOL | VALID_CHEIGHT | VALID_CROW | VALID_VIRTCOL);
            moved = true;
        }
        if (moved) {
            coladvance(curwin.w_curswant);
        }
        if (curwin.w_cursor.lnum < curwin.w_topline) {
            curwin.w_cursor.lnum = curwin.w_topline;
        }
    }

    private void scrollup(long line_count, boolean byfold) {
        boolean do_sms = curwin.w_onebuf_opt.wo_wrap[0] != 0 && curwin.w_onebuf_opt.wo_sms[0] != 0;
        if (do_sms) {
            int width1 = curwin.w_width - curwin_col_off();
            int width2 = width1 + curwin_col_off2();
            int size = 0;
            int prev_skipcol = curwin.w_skipcol;
            if (do_sms) {
                size = linetabsize_eol(curwin, curwin.w_topline);
            }
            for (int todo = (int) line_count; todo > 0; todo--) {
                long lnum = curwin.w_topline;
                if (lnum == curwin.w_topline && do_sms) {
                    int add = curwin.w_skipcol > 0 ? width2 : width1;
                    curwin.w_skipcol += add;
                    if (curwin.w_skipcol >= size) {
                        if (lnum == curbuf.b_ml.ml_line_count) {
                            curwin.w_skipcol -= add;
                            break;
                        }
                        lnum++;
                    }
                } else {
                    if (lnum >= curbuf.b_ml.ml_line_count) {
                        break;
                    }
                    lnum++;
                }
                if (lnum > curwin.w_topline) {
                    curwin.w_botline += lnum - curwin.w_topline;
                    curwin.w_topline = lnum;
                    curwin.w_skipcol = 0;
                    if (todo > 1 && do_sms) {
                        size = linetabsize_eol(curwin, curwin.w_topline);
                    }
                }
            }
            if (prev_skipcol > 0 || curwin.w_skipcol > 0) {
                redraw_later(UPD_NOT_VALID);
            }
        } else {
            curwin.w_topline += line_count;
            curwin.w_botline += line_count;
        }
        if (curwin.w_topline > curbuf.b_ml.ml_line_count) {
            curwin.w_topline = curbuf.b_ml.ml_line_count;
        }
        if (curwin.w_botline > (curbuf.b_ml.ml_line_count + 1L)) {
            curwin.w_botline = curbuf.b_ml.ml_line_count + 1L;
        }
        curwin.w_valid &= ~(VALID_WROW | VALID_CROW | VALID_BOTLINE);
        if (curwin.w_cursor.lnum < curwin.w_topline) {
            curwin.w_cursor.lnum = curwin.w_topline;
            curwin.w_valid &= ~(VALID_WROW | VALID_WCOL | VALID_CHEIGHT | VALID_CROW | VALID_VIRTCOL);
            coladvance(curwin.w_curswant);
        }
    }

    private void adjust_skipcol() {
        if (curwin.w_onebuf_opt.wo_wrap[0] == 0 || curwin.w_onebuf_opt.wo_sms[0] == 0
                || curwin.w_cursor.lnum != curwin.w_topline) {
            return;
        }
        int width1 = curwin.w_width - curwin_col_off();
        if (width1 <= 0) {
            return;
        }
        int width2 = width1 + curwin_col_off2();
        long so = get_scrolloff_value();
        int scrolloff_cols = (int) (so == 0L ? 0L : (long) width1 + (so - 1L) * (long) width2);
        boolean scrolled = false;
        int row = 0;
        int overlap;
        int col;
        validate_cheight();
        if (curwin.w_cline_height == curwin.w_height
                && plines_win(curwin, curwin.w_cursor.lnum, false) <= curwin.w_height) {
            reset_skipcol();
            return;
        }
        validate_virtcol();
        overlap = sms_marker_overlap(curwin, curwin.w_width - width2);
        while (curwin.w_skipcol > 0 && curwin.w_virtcol[0] < curwin.w_skipcol + overlap + scrolloff_cols) {
            if (curwin.w_skipcol >= width1 + width2) {
                curwin.w_skipcol -= width2;
            } else {
                curwin.w_skipcol -= width1;
            }
            scrolled = true;
        }
        if (scrolled) {
            validate_virtcol();
            redraw_later(UPD_NOT_VALID);
            return;
        }
        col = curwin.w_virtcol[0] + scrolloff_cols;
        if (scrolloff_cols > 0) {
            int size = linetabsize_eol(curwin, curwin.w_topline);
            size = width1 + width2 * ((size - width1 + width2 - 1) / width2);
            while (col > size) {
                col -= width2;
            }
        }
        col -= curwin.w_skipcol;
        if (col >= width1) {
            col -= width1;
            row++;
        }
        if (col > width2) {
            row += col / width2;
        }
        if (row >= curwin.w_height) {
            if (curwin.w_skipcol == 0) {
                curwin.w_skipcol += width1;
                row--;
            }
            if (row >= curwin.w_height) {
                curwin.w_skipcol += (row - curwin.w_height) * width2;
            }
            redraw_later(UPD_NOT_VALID);
        }
    }

    private void scrolldown_clamp() {
        int end_row;
        if (curwin.w_topline <= 1L) {
            return;
        }
        validate_cursor();
        end_row = curwin.w_wrow;
        end_row += plines(curwin.w_topline - 1L);
        if (curwin.w_onebuf_opt.wo_wrap[0] != 0 && curwin.w_width != 0) {
            validate_cheight();
            validate_virtcol();
            end_row += curwin.w_cline_height - 1 - curwin.w_virtcol[0] / curwin.w_width;
        }
        if ((long) end_row < (long) curwin.w_height - get_scrolloff_value()) {
            curwin.w_topline--;
            curwin.w_botline--;
            curwin.w_valid &= ~(VALID_WROW | VALID_CROW | VALID_BOTLINE);
        }
    }

    private void scrollup_clamp() {
        int start_row;
        if (curwin.w_topline == curbuf.b_ml.ml_line_count) {
            return;
        }
        validate_cursor();
        start_row = curwin.w_wrow - plines(curwin.w_topline);
        if (curwin.w_onebuf_opt.wo_wrap[0] != 0 && curwin.w_width != 0) {
            validate_virtcol();
            start_row -= curwin.w_virtcol[0] / curwin.w_width;
        }
        if ((long) start_row >= get_scrolloff_value()) {
            curwin.w_topline++;
            curwin.w_botline++;
            curwin.w_valid &= ~(VALID_WROW | VALID_CROW | VALID_BOTLINE);
        }
    }

    private void topline_back_winheight(T_lineoff_T lp, boolean winheight) {
        lp.lnum--;
        if (lp.lnum < 1L) {
            lp.height = MAXCOL;
        } else {
            lp.height = plines_win(curwin, lp.lnum, winheight);
        }
    }

    private void topline_back(T_lineoff_T lp) {
        topline_back_winheight(lp, true);
    }

    private void botline_forw(T_lineoff_T lp) {
        lp.lnum++;
        if (lp.lnum > curbuf.b_ml.ml_line_count) {
            lp.height = MAXCOL;
        } else {
            lp.height = plines(lp.lnum);
        }
    }

    private void scroll_cursor_top(int min_scroll, boolean always) {
        int scrolled = 0;
        int extra = 0;
        int used;
        int i = 0;
        long top;
        long bot;
        long old_topline = curwin.w_topline;
        int old_skipcol = curwin.w_skipcol;
        long new_topline;
        int off = (int) get_scrolloff_value();
        if (mouse_dragging > 0) {
            off = mouse_dragging - 1;
        }
        validate_cheight();
        used = curwin.w_cline_height;
        if (curwin.w_cursor.lnum < curwin.w_topline) {
            scrolled = used;
        }
        top = curwin.w_cursor.lnum - 1L;
        bot = curwin.w_cursor.lnum + 1L;
        new_topline = top + 1L;
        while (top > 0L) {
            i = plines(top);
            if (top < curwin.w_topline) {
                scrolled += i;
            }
            if ((new_topline >= curwin.w_topline || scrolled > min_scroll) && extra >= off) {
                break;
            }
            used += i;
            if (extra + i <= off && bot < curbuf.b_ml.ml_line_count) {
                used += plines(bot);
            }
            if (used > curwin.w_height) {
                break;
            }
            extra += i;
            new_topline = top;
            top--;
            bot++;
        }
        if (used > curwin.w_height) {
            scroll_cursor_halfway(FALSE, FALSE);
        } else {
            if (new_topline < curwin.w_topline || always) {
                curwin.w_topline = new_topline;
            }
            if (curwin.w_topline > curwin.w_cursor.lnum) {
                curwin.w_topline = curwin.w_cursor.lnum;
            }
            if (curwin.w_topline != old_topline) {
                reset_skipcol();
            } else if (curwin.w_topline == curwin.w_cursor.lnum) {
                validate_virtcol();
                if (curwin.w_skipcol >= curwin.w_virtcol[0]) {
                    int width1 = curwin.w_width - curwin_col_off();
                    int width2 = width1 + curwin_col_off2();
                    int plines_off = 0;
                    int skipcol;
                    if (width2 > 0 && curwin.w_virtcol[0] >= width1) {
                        plines_off = (curwin.w_virtcol[0] - width1) / width2 + 1;
                    }
                    skipcol = skipcol_from_plines(curwin, plines_off);
                    if (skipcol != curwin.w_skipcol) {
                        curwin.w_skipcol = skipcol;
                        redraw_later(UPD_SOME_VALID);
                    }
                }
            }
            if (curwin.w_topline != old_topline || curwin.w_skipcol != old_skipcol) {
                curwin.w_valid &= ~(VALID_WROW | VALID_CROW | VALID_BOTLINE | VALID_BOTLINE_AP);
            }
            curwin.w_valid |= VALID_TOPLINE;
        }
    }

    private static void set_empty_rows(S_window_S wp, int used) {
        if (used == 0) {
            wp.w_empty_rows = 0;
        } else {
            wp.w_empty_rows = wp.w_height - used;
        }
    }

    private void scroll_cursor_bot(int min_scroll, boolean set_topbot) {
        int used;
        int scrolled = 0;
        int extra = 0;
        int i = 0;
        long line_count;
        long old_topline = curwin.w_topline;
        int old_skipcol = curwin.w_skipcol;
        T_lineoff_T loff = new T_lineoff_T();
        T_lineoff_T boff = new T_lineoff_T();
        long old_botline = curwin.w_botline;
        long old_valid = (long) curwin.w_valid;
        int old_empty_rows = curwin.w_empty_rows;
        long so = get_scrolloff_value();
        boolean do_sms = curwin.w_onebuf_opt.wo_wrap[0] != 0 && curwin.w_onebuf_opt.wo_sms[0] != 0;
        long cln = curwin.w_cursor.lnum;
        if (set_topbot) {
            used = 0;
            long cln_last = cln;
            curwin.w_botline = cln_last + 1L;
            loff.lnum = cln_last + 1L;
            while (true) {
                topline_back_winheight(loff, false);
                if (loff.height == MAXCOL) {
                    break;
                }
                if (used + loff.height > curwin.w_height) {
                    if (do_sms) {
                        if (used < curwin.w_height) {
                            int plines_offset = used + loff.height - curwin.w_height;
                            used = curwin.w_height;
                            curwin.w_topline = loff.lnum;
                            curwin.w_skipcol = skipcol_from_plines(curwin, plines_offset);
                        }
                    }
                    break;
                }
                curwin.w_topline = loff.lnum;
                used += loff.height;
            }
            set_empty_rows(curwin, used);
            curwin.w_valid |= VALID_BOTLINE | VALID_BOTLINE_AP;
            if (curwin.w_topline != old_topline || curwin.w_skipcol != old_skipcol || curwin.w_skipcol != 0) {
                curwin.w_valid &= ~(VALID_WROW | VALID_CROW);
                if (curwin.w_skipcol != old_skipcol) {
                    redraw_later(UPD_NOT_VALID);
                } else {
                    reset_skipcol();
                }
            }
        } else {
            validate_botline();
        }
        validate_cheight();
        used = curwin.w_cline_height;
        if (do_sms && (dy_flags[0] & DY_LASTLINE) != 0) {
            int upto_cursor = plines_win_col(curwin, cln, (long) curwin.w_cursor.col);
            if (upto_cursor < used) {
                used = upto_cursor;
            }
        }
        if (cln >= curwin.w_botline) {
            scrolled = used;
            if (cln == curwin.w_botline) {
                scrolled -= curwin.w_empty_rows;
            }
            if (do_sms) {
                int top_plines = plines_win(curwin, curwin.w_topline, false);
                int width1 = curwin.w_width - curwin_col_off();
                if (width1 > 0) {
                    int width2 = width1 + curwin_col_off2();
                    int skip_lines = 0;
                    if (curwin.w_skipcol > width1) {
                        skip_lines += (curwin.w_skipcol - width1) / width2 + 1;
                    } else if (curwin.w_skipcol > 0) {
                        skip_lines = 1;
                    }
                    top_plines -= skip_lines;
                    if (top_plines > curwin.w_height) {
                        scrolled += top_plines - curwin.w_height;
                    }
                }
            }
        }
        loff.lnum = cln;
        boff.lnum = cln;
        while (loff.lnum > 1L) {
            if ((((scrolled <= 0 || scrolled >= min_scroll)
                    && (long) extra >= (mouse_dragging > 0 ? (long) (mouse_dragging - 1) : so))
                    || boff.lnum + 1L > curbuf.b_ml.ml_line_count) && loff.lnum <= curwin.w_botline) {
                break;
            }
            long loff_lnum_before = loff.lnum;
            topline_back(loff);
            if (loff.height == MAXCOL) {
                used = MAXCOL;
            } else {
                used += loff.height;
            }
            if (used > curwin.w_height) {
                break;
            }
            if (loff.lnum >= curwin.w_botline) {
                scrolled += loff.height;
                if (loff.lnum == curwin.w_botline && loff_lnum_before > curwin.w_botline) {
                    scrolled -= curwin.w_empty_rows;
                }
            }
            if (boff.lnum < curbuf.b_ml.ml_line_count) {
                long boff_lnum_before = boff.lnum;
                botline_forw(boff);
                used += boff.height;
                if (used > curwin.w_height) {
                    break;
                }
                if ((long) extra < (mouse_dragging > 0 ? (long) (mouse_dragging - 1) : so) || scrolled < min_scroll) {
                    extra += boff.height;
                    if (boff.lnum >= curwin.w_botline) {
                        scrolled += boff.height;
                        if (boff.lnum >= curwin.w_botline && boff_lnum_before < curwin.w_botline) {
                            scrolled -= curwin.w_empty_rows;
                        }
                    }
                }
            }
        }
        if (scrolled <= 0) {
            line_count = 0L;
        } else if (used > curwin.w_height) {
            line_count = (long) used;
        } else {
            line_count = 0L;
            boff.lnum = curwin.w_topline - 1L;
            for (i = 0; i < scrolled && boff.lnum < curwin.w_botline; ) {
                botline_forw(boff);
                i += boff.height;
                line_count++;
            }
            if (i < scrolled) {
                line_count = 9999L;
            }
        }
        boolean eof_pressure = scrolloffpad_eof_pressure(cln, so);
        if (line_count >= (long) curwin.w_height && line_count > ((long) min_scroll)) {
            scroll_cursor_halfway(eof_pressure ? 1 : 0, TRUE);
        } else if (line_count > 0L) {
            if (do_sms) {
                scrollup((long) scrolled, true);
            } else {
                scrollup(line_count, true);
            }
        }
        if (curwin.w_topline == old_topline && curwin.w_skipcol == old_skipcol && set_topbot) {
            curwin.w_botline = old_botline;
            curwin.w_empty_rows = old_empty_rows;
            curwin.w_valid = (int) old_valid;
        }
        curwin.w_valid |= VALID_TOPLINE;
        if (set_topbot) {
            cursor_correct_sms();
        }
    }

    private void scroll_cursor_halfway(int atend, int prefer_above) {
        int above = 0;
        long topline;
        int skipcol = 0;
        int below = 0;
        int used;
        T_lineoff_T loff = new T_lineoff_T();
        T_lineoff_T boff = new T_lineoff_T();
        boff.lnum = curwin.w_cursor.lnum;
        loff.lnum = boff.lnum;
        used = plines(loff.lnum);
        topline = loff.lnum;
        int want_height = 0;
        boolean do_sms = curwin.w_onebuf_opt.wo_wrap[0] != 0 && curwin.w_onebuf_opt.wo_sms[0] != 0;
        if (do_sms) {
            if (atend != 0) {
                want_height = (curwin.w_height - used) / 2;
                used = 0;
            } else {
                want_height = curwin.w_height;
            }
        }
        while (topline > 1L) {
            if (do_sms) {
                topline_back_winheight(loff, false);
                if (loff.height == MAXCOL) {
                    break;
                }
                used += loff.height;
                if (atend == 0 && boff.lnum < curbuf.b_ml.ml_line_count) {
                    botline_forw(boff);
                    used += boff.height;
                }
                if (used > want_height) {
                    if (used - loff.height < want_height) {
                        topline = loff.lnum;
                        skipcol = skipcol_from_plines(curwin, used - want_height);
                    }
                    break;
                }
                topline = loff.lnum;
                continue;
            }
            boolean done = false;
            for (int round = 1; round <= 2; round++) {
                if (prefer_above != 0 ? round == 2 && below < above : round == 1 && below <= above) {
                    if (boff.lnum < curbuf.b_ml.ml_line_count) {
                        botline_forw(boff);
                        used += boff.height;
                        if (used > curwin.w_height) {
                            done = true;
                            break;
                        }
                        below += boff.height;
                    } else {
                        below++;
                        if (atend != 0) {
                            used++;
                        }
                    }
                }
                if (prefer_above != 0 ? round == 1 && below >= above : round == 1 && below > above) {
                    topline_back(loff);
                    if (loff.height == MAXCOL) {
                        used = MAXCOL;
                    } else {
                        used += loff.height;
                    }
                    if (used > curwin.w_height) {
                        done = true;
                        break;
                    }
                    above += loff.height;
                    topline = loff.lnum;
                }
            }
            if (done) {
                break;
            }
        }
        if (curwin.w_topline != topline || skipcol != 0 || curwin.w_skipcol != 0) {
            curwin.w_topline = topline;
            if (skipcol != 0) {
                curwin.w_skipcol = skipcol;
                redraw_later(UPD_NOT_VALID);
            } else if (do_sms) {
                reset_skipcol();
            }
        }
        curwin.w_valid &= ~(VALID_WROW | VALID_CROW | VALID_BOTLINE | VALID_BOTLINE_AP);
        curwin.w_valid |= VALID_TOPLINE;
    }

    private void cursor_correct() {
        int above = 0;
        long topline;
        int below = 0;
        long botline;
        long cln;
        int max_off;
        long so = get_scrolloff_value();
        int above_wanted = (int) so;
        int below_wanted = (int) so;
        if (mouse_dragging > 0) {
            above_wanted = mouse_dragging - 1;
            below_wanted = mouse_dragging - 1;
        }
        if (curwin.w_topline == 1L) {
            above_wanted = 0;
            max_off = curwin.w_height / 2;
            if (below_wanted > max_off) {
                below_wanted = max_off;
            }
        }
        validate_botline();
        if (curwin.w_botline == curbuf.b_ml.ml_line_count + 1L && mouse_dragging == 0) {
            below_wanted = 0;
            max_off = (curwin.w_height - 1) / 2;
            if (above_wanted > max_off) {
                above_wanted = max_off;
            }
        }
        cln = curwin.w_cursor.lnum;
        if (cln >= curwin.w_topline + (long) above_wanted && cln < curwin.w_botline - (long) below_wanted) {
            return;
        }
        topline = curwin.w_topline;
        botline = curwin.w_botline - 1L;
        while ((above < above_wanted || below < below_wanted) && topline < botline) {
            if (below < below_wanted && (below <= above || above >= above_wanted)) {
                below += plines(botline);
                botline--;
            }
            if (above < above_wanted && (above < below || below >= below_wanted)) {
                above += plines(topline);
                topline++;
            }
        }
        if (topline == botline || botline == 0L) {
            curwin.w_cursor.lnum = topline;
        } else if (topline > botline) {
            curwin.w_cursor.lnum = botline;
        } else {
            if (cln < topline && curwin.w_topline > 1L) {
                curwin.w_cursor.lnum = topline;
                curwin.w_valid &= ~(VALID_WROW | VALID_WCOL | VALID_CHEIGHT | VALID_CROW);
            }
            if (cln > botline && curwin.w_botline <= curbuf.b_ml.ml_line_count) {
                curwin.w_cursor.lnum = botline;
                curwin.w_valid &= ~(VALID_WROW | VALID_WCOL | VALID_CHEIGHT | VALID_CROW);
            }
        }
        check_cursor_moved(curwin);
        curwin.w_valid |= VALID_TOPLINE;
    }

    private int get_scroll_overlap(int dir) {
        T_lineoff_T loff = new T_lineoff_T();
        int min_height = curwin.w_height - 2;
        validate_botline();
        if ((dir == -1 && curwin.w_topline == 1L) || (dir == FORWARD && curwin.w_botline > curbuf.b_ml.ml_line_count)) {
            return min_height + 2;
        }
        loff.lnum = dir == FORWARD ? curwin.w_botline : curwin.w_topline - 1L;
        loff.height = plines(loff.lnum);
        int h1 = loff.height;
        if (h1 > min_height) {
            return min_height + 2;
        }
        if (dir == FORWARD) {
            topline_back(loff);
        } else {
            botline_forw(loff);
        }
        int h2 = loff.height;
        if (h2 == MAXCOL || h2 + h1 > min_height) {
            return min_height + 2;
        }
        if (dir == FORWARD) {
            topline_back(loff);
        } else {
            botline_forw(loff);
        }
        int h3 = loff.height;
        if (h3 == MAXCOL || h3 + h2 > min_height) {
            return min_height + 2;
        }
        if (dir == FORWARD) {
            topline_back(loff);
        } else {
            botline_forw(loff);
        }
        int h4 = loff.height;
        if (h4 == MAXCOL || h4 + h3 + h2 > min_height || h3 + h2 + h1 > min_height) {
            return min_height + 1;
        } else {
            return min_height;
        }
    }

    private boolean scroll_with_sms(int dir, long count, LongPtr curscount) {
        int prev_sms = curwin.w_onebuf_opt.wo_sms[0];
        int prev_skipcol = curwin.w_skipcol;
        long prev_topline = curwin.w_topline;
        curwin.w_onebuf_opt.wo_sms[0] = TRUE;
        scroll_redraw(dir == FORWARD ? 1 : 0, count);
        if (prev_sms == 0 && curwin.w_skipcol > 0) {
            int fixdir = dir;
            if (musl_labs(curwin.w_topline - prev_topline) > ((long) (dir == -1 ? 1 : 0))) {
                fixdir = dir * -1;
            }
            int width1 = curwin.w_width - curwin_col_off();
            int width2 = width1 + curwin_col_off2();
            count = (long) (1 + (curwin.w_skipcol - width1 - 1) / width2);
            if (fixdir == FORWARD) {
                count = (long) (1 + (linetabsize_eol(curwin,
                        curwin.w_topline) - curwin.w_skipcol - width1 + width2 - 1) / width2);
            }
            scroll_redraw(fixdir == FORWARD ? 1 : 0, count);
            curscount.put(curscount.get() + count * (long) (fixdir == dir ? 1 : -1));
        }
        curwin.w_onebuf_opt.wo_sms[0] = prev_sms;
        return curwin.w_topline != prev_topline || curwin.w_skipcol != prev_skipcol;
    }

    private boolean pagescroll(int dir, long count_arg, boolean half) {
        long[] count = new long[] {count_arg};
        boolean did_move = false;
        int buflen = (int) curbuf.b_ml.ml_line_count;
        int prev_col = curwin.w_cursor.col;
        int prev_curswant = curwin.w_curswant;
        long prev_lnum = curwin.w_cursor.lnum;
        S_oparg_S oa = new S_oparg_S();
        S_cmdarg_S ca = new S_cmdarg_S();
        ca.oap = oa;
        if (half) {
            if (count[0] != 0) {
                curwin.w_onebuf_opt.wo_scr[0] = (long) curwin.w_height < count[0] ? (long) curwin.w_height : count[0];
            }
            count[0] = (long) curwin.w_height < curwin.w_onebuf_opt.wo_scr[0] ? (long) curwin.w_height : curwin.w_onebuf_opt.wo_scr[0];
            long[] curscount = new long[1];
            curscount[0] = count[0];
            if (dir == FORWARD && curwin.w_topline + (long) curwin.w_height + count[0] > ((long) buflen)) {
                int n = plines_correct_topline(curwin, curwin.w_topline, false);
                if ((long) n - count[0] < (long) curwin.w_height && curwin.w_topline < (long) buflen) {
                    n += plines_m_win(curwin, curwin.w_topline + 1L, (long) buflen,
                            (int) ((long) curwin.w_height + count[0]));
                }
                if ((long) n < (long) curwin.w_height + count[0]) {
                    count[0] = (long) (n - curwin.w_height);
                }
            }
            if (count[0] > 0L) {
                did_move = scroll_with_sms(dir, count[0], new LongPtr(curscount, 0));
                curwin.w_cursor.lnum = prev_lnum;
                curwin.w_cursor.col = prev_col;
                curwin.w_curswant = prev_curswant;
            }
            if (curwin.w_onebuf_opt.wo_wrap[0] != 0) {
                nv_screengo(oa, dir, curscount[0]);
            } else if (dir == FORWARD) {
                cursor_down_inner(curwin, curscount[0]);
            } else {
                cursor_up_inner(curwin, curscount[0]);
            }
        } else {
            count[0] *= true && p_window[0] > 0L
                    && p_window[0] < Rows[0] - 1L ? (1L > (p_window[0] - 2L) ? 1L : p_window[0] - 2L) : (long) get_scroll_overlap(dir);
            did_move = scroll_with_sms(dir, count[0], new LongPtr(count, 0));
            if (did_move) {
                validate_botline();
                long lnum = dir == FORWARD ? curwin.w_topline : curwin.w_botline - 1L;
                curwin.w_cursor.lnum = lnum > 1L ? lnum : 1L;
            }
        }
        if (get_scrolloff_value() > 0L) {
            cursor_correct();
        }
        did_move = did_move || prev_col != curwin.w_cursor.col || prev_lnum != curwin.w_cursor.lnum;
        if (!did_move) {
            beep_flush();
        } else if (curwin.w_onebuf_opt.wo_sms[0] == 0) {
            beginline(BL_SOL | BL_FIX);
        } else if (p_sol[0] != 0) {
            nv_g_home_m_cmd(ca);
        }
        return (did_move ? OK : FAIL) != 0;
    }

    private int find_command(int cmdchar) {
        int i = 0;
        int idx;
        int top;
        int bot;
        int c = 0;
        if (cmdchar >= 256) {
            return -1;
        }
        if (cmdchar < 0) {
            cmdchar = -cmdchar;
        }
        if (cmdchar <= nv_max_linear) {
            return nv_cmd_idx[cmdchar] & 0xffff;
        }
        bot = nv_max_linear + 1;
        top = 193;
        idx = -1;
        while (bot <= top) {
            i = (top + bot) / 2;
            c = nv_cmds[nv_cmd_idx[i] & 0xffff].cmd_char;
            if (c < 0) {
                c = -c;
            }
            if (cmdchar == c) {
                idx = nv_cmd_idx[i] & 0xffff;
                break;
            }
            if (cmdchar > c) {
                bot = i + 1;
            } else {
                top = i - 1;
            }
        }
        return idx;
    }

    private boolean check_text_locked(S_oparg_S oap) {
        if (!text_locked()) {
            return false;
        }
        if (oap != null) {
            clearopbeep(oap);
        }
        text_locked_msg();
        return true;
    }

    private boolean check_text_or_curbuf_locked(S_oparg_S oap) {
        if (check_text_locked(oap)) {
            return true;
        }
        if (!curbuf_locked()) {
            return false;
        }
        if (oap != null) {
            clearop(oap);
        }
        return true;
    }

    private T_normal_cmd_get_count__out_T normal_cmd_get_count(S_cmdarg_S cap, int c, boolean toplevel,
            boolean set_prevcount, int ctrl_w, int need_flushbuf) {
        T_normal_cmd_get_count__out_T out__ = new T_normal_cmd_get_count__out_T();
        for (;;) {
            if (!(VIsual_active && VIsual_select != 0)) {
                while ((c >= '1' && c <= '9') || (cap.count0 != 0L && (c == K_DEL || c == K_KDEL || c == '0'))) {
                    if (c == K_DEL || c == K_KDEL) {
                        cap.count0 /= 10L;
                        del_from_showcmd(4);
                    } else if (cap.count0 > 99999999L) {
                        cap.count0 = 999999999L;
                    } else {
                        cap.count0 = cap.count0 * 10L + (long) (c - '0');
                    }
                    if (ctrl_w != 0) {
                        no_mapping++;
                        allow_keys++;
                    }
                    no_zero_mapping++;
                    c = plain_vgetc();
                    no_zero_mapping--;
                    if (ctrl_w != 0) {
                        no_mapping--;
                        allow_keys--;
                    }
                    need_flushbuf |= add_to_showcmd(c) ? 1 : 0;
                }
                if (c == Ctrl_W && ctrl_w == 0 && cap.oap.op_type == OP_NOP) {
                    ctrl_w = TRUE;
                    cap.opcount = cap.count0;
                    cap.count0 = 0L;
                    no_mapping++;
                    allow_keys++;
                    c = plain_vgetc();
                    no_mapping--;
                    allow_keys--;
                    need_flushbuf |= add_to_showcmd(c) ? 1 : 0;
                    continue;
                }
            }
            break;
        }
        if (c == K_CURSORHOLD) {
            cap.oap.prev_opcount = cap.opcount;
            cap.oap.prev_count0 = cap.count0;
        } else if (cap.opcount != 0L) {
            if (cap.count0 != 0) {
                if (cap.opcount >= 999999999L / cap.count0) {
                    cap.count0 = 999999999L;
                } else {
                    cap.count0 *= cap.opcount;
                }
            } else {
                cap.count0 = cap.opcount;
            }
        }
        cap.opcount = cap.count0;
        cap.count1 = cap.count0 == 0L ? 1L : cap.count0;
        out__.r__ = c;
        out__.ctrl_w = ctrl_w;
        out__.need_flushbuf = need_flushbuf;
        return out__;
    }

    private boolean normal_cmd_needs_more_chars(S_cmdarg_S cap, short cmd_flags) {
        return (cmd_flags & 0xffff & NV_NCH) != 0
                && (((cmd_flags & 0xffff & (2 | NV_NCH)) == (2 | NV_NCH) && cap.oap.op_type == OP_NOP)
                || (cmd_flags & 0xffff & (4 | NV_NCH)) == (4 | NV_NCH)
                || (cap.cmdchar == 'q' && cap.oap.op_type == OP_NOP && reg_recording == 0 && reg_executing == 0)
                || ((cap.cmdchar == 'a' || cap.cmdchar == 'i') && (cap.oap.op_type != OP_NOP || VIsual_active)));
    }

    private T_normal_cmd_get_more_chars__out_T normal_cmd_get_more_chars(int idx_arg, S_cmdarg_S cap,
            int need_flushbuf) {
        T_normal_cmd_get_more_chars__out_T out__ = new T_normal_cmd_get_more_chars__out_T();
        int idx = idx_arg;
        int c = 0;
        IntPtr cp;
        boolean repl = false;
        boolean lit = false;
        boolean lang;
        no_mapping++;
        allow_keys++;
        did_cursorhold = TRUE;
        if (cap.cmdchar == 'g') {
            cap.nchar[0] = plain_vgetc();
            need_flushbuf |= add_to_showcmd(cap.nchar[0]) ? 1 : 0;
            if (cap.nchar[0] == 'r' || cap.nchar[0] == '\'' || cap.nchar[0] == '`' || cap.nchar[0] == Ctrl_BSL) {
                cp = new IntPtr(cap.extra_char, 0);
                if (cap.nchar[0] != 'r') {
                    lit = true;
                } else {
                    repl = true;
                }
            } else {
                cp = null;
            }
        } else {
            if (cap.cmdchar == 'r') {
                repl = true;
            }
            cp = new IntPtr(cap.nchar, 0);
        }
        lang = repl || (nv_cmds[idx].cmd_flags & 0xffff & NV_LANG) != 0;
        if (cp != null) {
            if (repl) {
                State = REPLACE_FLAG | MODE_INSERT;
            }
            if ((State & MODE_INSERT) != 0 && p_ek[0] == 0) {
                out_str(term_strings[KS_CBD]);
                out_str_t_TE();
            }
            cp.put(plain_vgetc());
            if ((State & MODE_INSERT) != 0 && p_ek[0] == 0) {
                out_str_t_BE();
                out_str_t_TI();
            }
            State = 4096 | MODE_NORMAL;
            need_flushbuf |= add_to_showcmd(cp.get()) ? 1 : 0;
            if (!lit) {
            }
            if (IntPtr.eq(cp, new IntPtr(cap.extra_char, 0)) && cap.nchar[0] == Ctrl_BSL
                    && (cap.extra_char[0] == Ctrl_N || cap.extra_char[0] == Ctrl_G)) {
                cap.cmdchar = Ctrl_BSL;
                cap.nchar[0] = cap.extra_char[0];
                idx = find_command(cap.cmdchar);
            } else if ((cap.nchar[0] == 'n' || cap.nchar[0] == 'N') && cap.cmdchar == 'g') {
                cap.oap.op_type = get_op_type(cp.get(), NUL);
            } else if (cp.get() == Ctrl_BSL) {
                long towait = p_ttm[0] >= 0L ? p_ttm[0] : p_tm[0];
                while ((c = vpeekc()) <= 0 && towait > 0L) {
                    do_sleep(towait > 50L ? 50L : towait, false);
                    towait -= 50L;
                }
                if (c > 0) {
                    c = plain_vgetc();
                    if (c != Ctrl_N && c != Ctrl_G) {
                        vungetc(c);
                    } else {
                        cap.cmdchar = Ctrl_BSL;
                        cap.nchar[0] = c;
                        idx = find_command(cap.cmdchar);
                    }
                }
            }
            if (lang) {
                no_mapping--;
                while ((c = vpeekc()) > 0 && (c >= 256 || (int) mb_bytelen_tab[vpeekc()] > 1)) {
                    c = plain_vgetc();
                    if (!utf_iscomposing(c)) {
                        vungetc(c);
                        break;
                    } else if (cap.ncharC1 == 0) {
                        cap.ncharC1 = c;
                    } else {
                        cap.ncharC2 = c;
                    }
                }
                no_mapping++;
                no_u_sync++;
                gotchars_ignore();
                no_u_sync--;
            }
        }
        no_mapping--;
        allow_keys--;
        out__.r__ = idx;
        out__.need_flushbuf = need_flushbuf;
        return out__;
    }

    private boolean normal_cmd_need_to_wait_for_msg(S_cmdarg_S cap, T_pos_T old_pos) {
        return ((p_smd[0] != 0 && msg_silent == 0
                && (restart_edit != 0
                || (VIsual_active && old_pos.lnum == curwin.w_cursor.lnum && old_pos.col == curwin.w_cursor.col))
                && (clear_cmdline || redraw_cmdline != 0) && (msg_didout != 0 || (msg_didany && msg_scroll != 0))
                && !msg_nowait && KeyTyped)
                || (restart_edit != 0 && !VIsual_active && (msg_scroll != 0 || emsg_on_display)))
                && cap.oap.regname == 0 && (cap.retval & CA_COMMAND_BUSY) == 0 && stuff_empty() && typebuf_typed()
                && emsg_silent == 0 && !in_assert_fails && !did_wait_return && cap.oap.op_type == OP_NOP;
    }

    private void normal_cmd_wait_for_msg() {
        int save_State = State;
        if (restart_edit != 0) {
            State = MODE_INSERT;
        }
        if (must_redraw != 0 && keep_msg != null && !emsg_on_display) {
            BytePtr kmsg = keep_msg;
            keep_msg = null;
            setcursor();
            update_screen(0);
            keep_msg = kmsg;
            kmsg = vim_strsave(keep_msg);
            msg_attr(kmsg, keep_msg_attr);
        }
        setcursor();
        cursor_on();
        out_flush();
        if (msg_scroll != 0 || emsg_on_display) {
            ui_delay(1003L, true);
        }
        ui_delay(3003L, false);
        State = save_State;
        msg_scroll = FALSE;
        emsg_on_display = false;
    }

    private void normal_cmd(S_oparg_S oap, boolean toplevel) {
        T_normal_cmd_get_count__out_T normal_cmd_get_count__o = new T_normal_cmd_get_count__out_T();
        T_normal_cmd_get_more_chars__out_T normal_cmd_get_more_chars__o = new T_normal_cmd_get_more_chars__out_T();
        S_cmdarg_S ca = new S_cmdarg_S();
        int c;
        int ctrl_w = FALSE;
        int old_col = curwin.w_curswant;
        int need_flushbuf = FALSE;
        T_pos_T old_pos = new T_pos_T();
        int mapped_len;
        int idx;
        boolean set_prevcount = false;
        int save_did_cursorhold = did_cursorhold;
        ca.zero();
        ca.oap = oap;
        ca.opcount = opcount;
        finish_op = oap.op_type != OP_NOP ? 1 : 0;
        if (finish_op == 0 && oap.regname == 0) {
            ca.opcount = 0L;
        }
        if (oap.prev_opcount > 0L || oap.prev_count0 > 0L) {
            ca.opcount = oap.prev_opcount;
            ca.count0 = oap.prev_count0;
            oap.prev_opcount = 0L;
            oap.prev_count0 = 0L;
        }
        mapped_len = typebuf_maplen();
        State = 4096 | MODE_NORMAL;
        c = safe_vgetc();
        if (restart_edit == 0) {
            normal_cmd_old_mapped_len = 0;
        } else if (normal_cmd_old_mapped_len != 0 || (VIsual_active && mapped_len == 0 && typebuf_maplen() > 0)) {
            normal_cmd_old_mapped_len = typebuf_maplen();
        }
        if (c == NUL) {
            c = -(KS_ZERO + ('X' << 8));
        }
        if (VIsual_active && VIsual_select != 0 && (vim_isprintc(c) || c == NL || c == CAR || c == K_KENTER)) {
            int len = ins_char_typebuf(vgetc_char, vgetc_mod_mask);
            if (KeyTyped) {
                ungetchars(len);
            }
            if (restart_edit != 0) {
                c = 'd';
            } else {
                c = 'c';
            }
            msg_nowait = true;
            normal_cmd_old_mapped_len = 0;
        }
        if (KeyTyped && !KeyStuffed) {
            win_ensure_size();
        }
        need_flushbuf = add_to_showcmd(c) ? 1 : 0;
        normal_cmd_get_count__o = normal_cmd_get_count(ca, c, toplevel, set_prevcount, ctrl_w, need_flushbuf);
        ctrl_w = normal_cmd_get_count__o.ctrl_w;
        need_flushbuf = normal_cmd_get_count__o.need_flushbuf;
        c = normal_cmd_get_count__o.r__;
        if (ctrl_w != 0) {
            ca.nchar[0] = c;
            ca.cmdchar = Ctrl_W;
        } else {
            ca.cmdchar = c;
        }
        idx = find_command(ca.cmdchar);
        c1: {
            if (idx < 0) {
                clearopbeep(oap);
                break c1;
            }
            if ((nv_cmds[idx].cmd_flags & 0xffff & NV_NCW) != 0 && check_text_or_curbuf_locked(oap)) {
                break c1;
            }
            if (VIsual_active) {
                if (km_stopsel && (nv_cmds[idx].cmd_flags & 0xffff & NV_STS) != 0
                        && (mod_mask[0] & MOD_MASK_SHIFT) == 0) {
                    end_visual_mode();
                    redraw_curbuf_later(UPD_INVERTED);
                }
                if (km_startsel) {
                    if ((nv_cmds[idx].cmd_flags & 0xffff & NV_SS) != 0) {
                        unshift_special(ca);
                        idx = find_command(ca.cmdchar);
                        if (idx < 0) {
                            clearopbeep(oap);
                            break c1;
                        }
                    } else if ((nv_cmds[idx].cmd_flags & 0xffff & NV_SSS) != 0 && (mod_mask[0] & MOD_MASK_SHIFT) != 0) {
                        mod_mask[0] &= ~MOD_MASK_SHIFT;
                    }
                }
            }
            if (normal_cmd_needs_more_chars(ca, nv_cmds[idx].cmd_flags)) {
                normal_cmd_get_more_chars__o = normal_cmd_get_more_chars(idx, ca, need_flushbuf);
                need_flushbuf = normal_cmd_get_more_chars__o.need_flushbuf;
                idx = normal_cmd_get_more_chars__o.r__;
            }
            if (need_flushbuf != 0) {
                out_flush();
            }
            if (ca.cmdchar != K_IGNORE) {
                if (ex_normal_busy != 0) {
                    did_cursorhold = save_did_cursorhold;
                } else {
                    did_cursorhold = FALSE;
                }
            }
            State = MODE_NORMAL;
            if (ca.nchar[0] == ESC || ca.extra_char[0] == ESC) {
                clearop(oap);
                if (restart_edit == 0 && goto_im()) {
                    restart_edit = 'a';
                }
                break c1;
            }
            if (ca.cmdchar != K_IGNORE) {
                msg_didout = FALSE;
                msg_col = 0;
            }
            old_pos.set(curwin.w_cursor);
            if (!VIsual_active && km_startsel) {
                if ((nv_cmds[idx].cmd_flags & 0xffff & NV_SS) != 0) {
                    start_selection();
                    unshift_special(ca);
                    idx = find_command(ca.cmdchar);
                } else if ((nv_cmds[idx].cmd_flags & 0xffff & NV_SSS) != 0 && (mod_mask[0] & MOD_MASK_SHIFT) != 0) {
                    start_selection();
                    mod_mask[0] &= ~MOD_MASK_SHIFT;
                }
            }
            ca.arg = (int) nv_cmds[idx].cmd_arg;
            nv_cmds[idx].cmd_func.call(ca);
            if (finish_op == 0 && oap.op_type == 0
                    && (idx < 0 || (nv_cmds[idx].cmd_flags & 0xffff & NV_KEEPREG) == 0)) {
                clearop(oap);
            }
            if (normal_cmd_old_mapped_len > 0) {
                normal_cmd_old_mapped_len = typebuf_maplen();
            }
            if (ca.cmdchar != K_IGNORE && ca.cmdchar != K_MOUSEMOVE) {
                do_pending_operator(ca, old_col, false);
            }
            if (normal_cmd_need_to_wait_for_msg(ca, old_pos)) {
                normal_cmd_wait_for_msg();
            }
        }
        msg_nowait = false;
        if (oap.op_type == OP_NOP) {
            finish_op = FALSE;
        }
        if (oap.op_type == OP_NOP && oap.regname == 0 && ca.cmdchar != K_CURSORHOLD) {
            clear_showcmd();
        }
        checkpcmark();
        mb_adjust_cursor();
        if (oap.op_type == OP_NOP
                && ((restart_edit != 0 && !VIsual_active && normal_cmd_old_mapped_len == 0)
                || restart_VIsual_select == 1) && (ca.retval & CA_COMMAND_BUSY) == 0 && stuff_empty()
                && oap.regname == 0) {
            if (restart_VIsual_select == 1) {
                VIsual_select = TRUE;
                showmode();
                restart_VIsual_select = 0;
                VIsual_select_reg = 0;
            }
            if (restart_edit != 0 && !VIsual_active && normal_cmd_old_mapped_len == 0) {
                edit(restart_edit, false, 1L);
            }
        }
        if (restart_VIsual_select == 2) {
            restart_VIsual_select = 1;
        }
        opcount = ca.opcount;
    }

