    private void clear_showcmd() {
        if (p_sc[0] == 0) {
            return;
        }
        if (VIsual_active && stuff_empty() && typebuf.tb_len == 0) {
            boolean cursor_bot = VIsual.lnum != curwin.w_cursor.lnum ? VIsual.lnum < curwin.w_cursor.lnum : (VIsual.col != curwin.w_cursor.col ? VIsual.col < curwin.w_cursor.col : VIsual.coladd < curwin.w_cursor.coladd);
            long lines;
            int[] leftcol = new int[1];
            int[] rightcol = new int[1];
            long top;
            long bot;
            if (cursor_bot) {
                top = VIsual.lnum;
                bot = curwin.w_cursor.lnum;
            } else {
                top = curwin.w_cursor.lnum;
                bot = VIsual.lnum;
            }
            lines = bot - top + 1L;
            if (VIsual_mode == Ctrl_V) {
                getvcols(curwin, curwin.w_cursor, VIsual, new IntPtr(leftcol, 0), new IntPtr(rightcol, 0),
                        GETVCOL_END_EXCL_LBR);
                vim_snprintf(new BytePtr(showcmd_buf, 0), SHOWCMD_COLS + 1 + 30, BytePtr.lit("%ldx%ld"), lines,
                        (long) (rightcol[0] - leftcol[0] + 1));
            } else if (VIsual_mode == 'V' || VIsual.lnum != curwin.w_cursor.lnum) {
                vim_snprintf(new BytePtr(showcmd_buf, 0), SHOWCMD_COLS + 1 + 30, BytePtr.lit("%ld"), lines);
            } else {
                BytePtr s;
                BytePtr e;
                int l = 0;
                int bytes = 0;
                int chars = 0;
                if (cursor_bot) {
                    s = ml_get_pos(VIsual);
                    e = ml_get_cursor();
                } else {
                    s = ml_get_cursor();
                    e = ml_get_pos(VIsual);
                }
                while (p_sel[0].get() != 'e' ? s.le(e) : s.lt(e)) {
                    l = utfc_ptr2len(s);
                    if (l == 0) {
                        bytes++;
                        chars++;
                        break;
                    }
                    bytes += l;
                    chars++;
                    s = s.add(l);
                }
                if (bytes == chars) {
                    vim_snprintf(new BytePtr(showcmd_buf, 0), SHOWCMD_COLS + 1 + 30, BytePtr.lit("%d"), chars);
                } else {
                    vim_snprintf(new BytePtr(showcmd_buf, 0), SHOWCMD_COLS + 1 + 30, BytePtr.lit("%d-%d"), chars,
                            bytes);
                }
            }
            showcmd_buf[SHOWCMD_COLS] = NUL;
            showcmd_visual = true;
        } else {
            showcmd_buf[0] = NUL;
            showcmd_visual = false;
            if (showcmd_is_clear) {
                return;
            }
        }
        display_showcmd();
    }

    private boolean add_to_showcmd(int c) {
        int t1 = 0;
        BytePtr p;
        int old_len;
        int extra_len;
        int overflow;
        int i = 0;
        byte[] mbyte_buf = new byte[21];
        if (p_sc[0] == 0 || msg_silent != 0) {
            return false;
        }
        if (showcmd_visual) {
            showcmd_buf[0] = NUL;
            showcmd_visual = false;
        }
        if (c < 0) {
            for (i = 0; add_to_showcmd_ignore[i] != 0; i++) {
                if (add_to_showcmd_ignore[i] == c) {
                    return false;
                }
            }
        }
        if (c <= 127 || !vim_isprintc(c)) {
            p = transchar(c);
            if (p.get() == ' ') {
                musl_strcpy(p, BytePtr.lit("<20>"));
            }
        } else {
            t1 = utf_char2bytes(c, new BytePtr(mbyte_buf, 0));
            mbyte_buf[t1] = NUL;
            p = new BytePtr(mbyte_buf, 0);
        }
        old_len = (int) musl_strlen(new BytePtr(showcmd_buf, 0));
        extra_len = (int) musl_strlen(p);
        overflow = old_len + extra_len - SHOWCMD_COLS;
        if (overflow > 0) {
            Rt.memmove(new BytePtr(showcmd_buf, 0), new BytePtr(showcmd_buf, 0).add(overflow),
                    (long) (old_len - overflow + 1));
        }
        musl_strcat(new BytePtr(showcmd_buf, 0), p);
        if (char_avail()) {
            return false;
        }
        display_showcmd();
        return true;
    }

    private void add_to_showcmd_c(int c) {
        if (!add_to_showcmd(c)) {
            setcursor();
        }
    }

    private void del_from_showcmd(int len) {
        int old_len;
        if (p_sc[0] == 0) {
            return;
        }
        old_len = (int) musl_strlen(new BytePtr(showcmd_buf, 0));
        if (len > old_len) {
            len = old_len;
        }
        showcmd_buf[old_len - len] = NUL;
        if (!char_avail()) {
            display_showcmd();
        }
    }

    private void push_showcmd() {
        if (p_sc[0] != 0) {
            musl_strcpy(new BytePtr(old_showcmd_buf, 0), new BytePtr(showcmd_buf, 0));
        }
    }

    private void pop_showcmd() {
        if (p_sc[0] == 0) {
            return;
        }
        musl_strcpy(new BytePtr(showcmd_buf, 0), new BytePtr(old_showcmd_buf, 0));
        display_showcmd();
    }

    private void showcmd_update_clear_state() {
        showcmd_is_clear = showcmd_buf[0] == NUL;
    }

    private void display_showcmd() {
        int len = vim_strsize(new BytePtr(showcmd_buf, 0));
        showcmd_update_clear_state();
        cursor_off();
        if (p_sloc[0].get() == 's') {
            if (showcmd_is_clear && vgetc_busy == 0) {
                curwin.w_redr_status = true;
            } else {
                win_redr_status(curwin, false);
            }
        } else if (p_sloc[0].get() == 't') {
            if (showcmd_is_clear && vgetc_busy == 0) {
                redraw_tabline = true;
            } else {
                draw_tabline();
            }
        } else {
            if (!showcmd_is_clear) {
                screen_puts(new BytePtr(showcmd_buf, 0), (int) Rows[0] - 1, cmdline_col_off + sc_col, 0);
            }
            screen_puts(BytePtr.lit("          ").add(len), (int) Rows[0] - 1, cmdline_col_off + sc_col + len, 0);
        }
        setcursor();
    }

