    private BytePtr set_bool_option(int opt_idx, T_optvar_T varp, int value, int opt_flags) {
        IntPtr t1 = null;
        int old_value = varp.ov_int.get();
        BytePtr errmsg = null;
        if (secure != 0 && (options[opt_idx].flags[0] & P_SECURE) != 0) {
            return new BytePtr(e_not_allowed_here, 0);
        }
        varp.ov_int.put(value);
        if ((opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0) {
            t1 = get_varp_scope(new Ptr<S_vimoption>(options, opt_idx), OPT_GLOBAL).ov_int;
            t1.put(value);
        }
        if (options[opt_idx].opt_did_set_cb != null) {
            T_optset_T args = new T_optset_T();
            args.zero();
            args.os_varp.set(varp);
            args.os_flags = opt_flags;
            args.os_oldval.boolean_ = old_value;
            args.os_newval.boolean_ = value;
            args.os_errbuf = null;
            errmsg = options[opt_idx].opt_did_set_cb.call(args);
            if (errmsg != null) {
                return errmsg;
            }
        }
        options[opt_idx].flags[0] |= P_WAS_SET;
        comp_col();
        if (curwin.w_curswant != MAXCOL && (options[opt_idx].flags[0] & (P_CURSWANT | P_RALL)) != 0L
                && (options[opt_idx].flags[0] & P_HLONLY) == 0L) {
            curwin.w_set_curswant = true;
        }
        if ((opt_flags & OPT_NO_REDRAW) == 0) {
            check_redraw(options[opt_idx].flags[0]);
        }
        return errmsg;
    }

    private BytePtr check_num_option_bounds(LongPtr pp, long old_value, long old_Rows, long old_Columns, BytePtr errbuf,
            long errbuflen, BytePtr errmsg) {
        if (Rows[0] < (long) min_rows_for_all_tabpages() && full_screen != 0) {
            if (errbuf != null) {
                vim_snprintf(errbuf, errbuflen, new BytePtr(e_need_at_least_nr_lines, 0), min_rows_for_all_tabpages());
                errmsg = errbuf;
            }
            Rows[0] = (long) min_rows_for_all_tabpages();
        }
        if (Columns[0] < MIN_COLUMNS && full_screen != 0) {
            if (errbuf != null) {
                vim_snprintf(errbuf, errbuflen, new BytePtr(e_need_at_least_nr_columns, 0), 12);
                errmsg = errbuf;
            }
            Columns[0] = MIN_COLUMNS;
        }
        limit_screen_size();
        if (old_Rows != Rows[0] || old_Columns != Columns[0]) {
            if (updating_screen != 0) {
                pp.put(old_value);
            } else if (full_screen != 0) {
                set_shellsize((int) Columns[0], (int) Rows[0], TRUE);
            } else {
                check_shellsize();
                if ((long) cmdline_row > (Rows[0] - p_ch[0]) && Rows[0] > p_ch[0]) {
                    cmdline_row = (int) (Rows[0] - p_ch[0]);
                }
            }
            if (p_window[0] >= Rows[0] || !option_was_set(BytePtr.lit("window"))) {
                p_window[0] = Rows[0] - 1L;
            }
        }
        if (p_tm[0] < 0L) {
            errmsg = new BytePtr(e_argument_must_be_positive, 0);
            p_tm[0] = 0L;
        }
        if ((curwin.w_onebuf_opt.wo_scr[0] <= 0L
                || (curwin.w_onebuf_opt.wo_scr[0] > ((long) curwin.w_height) && curwin.w_height > 0))
                && full_screen != 0) {
            if (LongPtr.eq(pp, new LongPtr(curwin.w_onebuf_opt.wo_scr, 0))) {
                if (curwin.w_onebuf_opt.wo_scr[0] != 0L) {
                    errmsg = new BytePtr(e_invalid_scroll_size, 0);
                }
                win_comp_scroll(curwin);
            } else if (curwin.w_onebuf_opt.wo_scr[0] <= 0L) {
                curwin.w_onebuf_opt.wo_scr[0] = 1L;
            } else {
                curwin.w_onebuf_opt.wo_scr[0] = (long) curwin.w_height;
            }
        }
        if (p_hi[0] < 0L) {
            errmsg = new BytePtr(e_argument_must_be_positive, 0);
            p_hi[0] = 0L;
        } else if (p_hi[0] > 10000L) {
            errmsg = new BytePtr(e_invalid_argument, 0);
            p_hi[0] = 10000L;
        }
        if (p_report[0] < 0L) {
            errmsg = new BytePtr(e_argument_must_be_positive, 0);
            p_report[0] = 1L;
        }
        if ((p_sj[0] < -100L || p_sj[0] >= Rows[0]) && full_screen != 0) {
            if (Rows[0] != old_Rows) {
                p_sj[0] = Rows[0] / 2L;
            } else {
                errmsg = new BytePtr(e_invalid_scroll_size, 0);
                p_sj[0] = 1L;
            }
        }
        if (p_so[0] < 0L && full_screen != 0) {
            errmsg = new BytePtr(e_argument_must_be_positive, 0);
            p_so[0] = 0L;
        }
        if (p_sop[0] < 0L && full_screen != 0) {
            errmsg = new BytePtr(e_invalid_argument, 0);
            p_sop[0] = 0L;
        }
        if (p_siso[0] < 0L && full_screen != 0) {
            errmsg = new BytePtr(e_argument_must_be_positive, 0);
            p_siso[0] = 0L;
        }
        if (p_ss[0] < 0L) {
            errmsg = new BytePtr(e_argument_must_be_positive, 0);
            p_ss[0] = 0L;
        }
        return errmsg;
    }

    private BytePtr set_num_option(int opt_idx, T_optvar_T varp, long value, BytePtr errbuf, long errbuflen,
            int opt_flags) {
        LongPtr t1 = null;
        BytePtr errmsg = null;
        long old_value = varp.ov_long.get();
        long old_Rows = Rows[0];
        long old_Columns = Columns[0];
        LongPtr pp = varp.ov_long;
        if (secure != 0 && (options[opt_idx].flags[0] & P_SECURE) != 0) {
            return new BytePtr(e_not_allowed_here, 0);
        }
        pp.put(value);
        if ((opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0) {
            t1 = get_varp_scope(new Ptr<S_vimoption>(options, opt_idx), OPT_GLOBAL).ov_long;
            t1.put(value);
        }
        if (options[opt_idx].opt_did_set_cb != null) {
            T_optset_T args = new T_optset_T();
            args.zero();
            args.os_varp.set(varp);
            args.os_flags = opt_flags;
            args.os_oldval.number = old_value;
            args.os_newval.number = value;
            args.os_errbuf = null;
            errmsg = options[opt_idx].opt_did_set_cb.call(args);
        }
        errmsg = check_num_option_bounds(pp, old_value, old_Rows, old_Columns, errbuf, errbuflen, errmsg);
        options[opt_idx].flags[0] |= P_WAS_SET;
        comp_col();
        if (curwin.w_curswant != MAXCOL && (options[opt_idx].flags[0] & (P_CURSWANT | P_RALL)) != 0L
                && (options[opt_idx].flags[0] & P_HLONLY) == 0L) {
            curwin.w_set_curswant = true;
        }
        if ((opt_flags & OPT_NO_REDRAW) == 0) {
            check_redraw(options[opt_idx].flags[0]);
        }
        return errmsg;
    }

    private void check_redraw(long flags) {
        boolean doclear = (flags & P_RCLR) == P_RCLR;
        boolean all = (flags & P_RALL) == P_RALL || doclear;
        if ((flags & P_RSTAT) != 0 || all) {
            status_redraw_all();
        }
        if ((flags & P_RBUF) != 0 || (flags & P_RWIN) != 0 || all) {
            if ((flags & P_HLONLY) != 0) {
                redraw_later(UPD_NOT_VALID);
            } else {
                changed_window_setting();
            }
        }
        if ((flags & P_RBUF) != 0) {
            redraw_curbuf_later(UPD_NOT_VALID);
        }
        if (doclear) {
            redraw_all_later(UPD_CLEAR);
        } else if (all) {
            redraw_all_later(UPD_NOT_VALID);
        }
    }

    private int findoption(BytePtr arg) {
        int opt_idx = 0;
        BytePtr s = null;
        BytePtr p;
        boolean is_term_opt;
        if ((int) findoption_quick_tab[1] == 0) {
            int last_opt_idx = 0;
            for (last_opt_idx = 0; options[last_opt_idx].fullname != null; last_opt_idx++) {
            }
            for (int tab_idx = 1; tab_idx < 27; tab_idx++) {
                findoption_quick_tab[tab_idx] = (short) last_opt_idx;
            }
            p = options[0].fullname;
            for (opt_idx = 1; opt_idx < last_opt_idx; opt_idx++) {
                s = options[opt_idx].fullname;
                if ((int) s.at(0) != (int) p.at(0)) {
                    if ((int) s.at(0) == 't' && (int) s.at(1) == '_') {
                        findoption_quick_tab[26] = (short) opt_idx;
                    } else {
                        findoption_quick_tab[(int) s.at(0) - 'a'] = (short) opt_idx;
                    }
                }
                p = s;
            }
        }
        if (arg.u(0) < 'a' || arg.u(0) > 'z') {
            return -1;
        }
        is_term_opt = arg.at(0) == 't' && arg.at(1) == '_';
        if (is_term_opt) {
            opt_idx = (int) findoption_quick_tab[26];
        } else {
            opt_idx = (int) findoption_quick_tab[arg.u(0) - 'a'];
        }
        for (; (s = options[opt_idx].fullname) != null && (int) s.at(0) == arg.u(0); opt_idx++) {
            if (musl_strcmp(arg, s) == 0) {
                break;
            }
        }
        if (s != null && (int) s.at(0) != arg.u(0)) {
            s = null;
        }
        if (s == null && !is_term_opt) {
            opt_idx = (int) findoption_quick_tab[arg.u(0) - 'a'];
            for (; options[opt_idx].fullname != null; opt_idx++) {
                s = options[opt_idx].shortname;
                if (s != null && musl_strcmp(arg, s) == 0) {
                    break;
                }
                s = null;
            }
        }
        if (s == null) {
            opt_idx = -1;
        }
        return opt_idx;
    }

    private long get_option_flags(int opt_idx) {
        return options[opt_idx].flags[0];
    }

    private void set_option_flag(int opt_idx, long flag) {
        options[opt_idx].flags[0] |= flag;
    }

    private boolean is_global_option(int opt_idx) {
        return options[opt_idx].indir == PV_NONE;
    }

    private int is_global_local_option(int opt_idx) {
        return options[opt_idx].indir & PV_BOTH;
    }

    private int is_window_local_option(int opt_idx) {
        return options[opt_idx].var_.ov_win;
    }

    private boolean is_hidden_option(int opt_idx) {
        return optvar_is_null(options[opt_idx].var_.copy());
    }

    private BytePtr set_option_value(BytePtr name, long number, BytePtr string, int opt_flags) {
        T_optvar_T varp = new T_optvar_T();
        long flags;
        int errbuflen = ERR_BUFLEN;
        int opt_idx = findoption(name);
        if (opt_idx < 0) {
            int key = 0;
            if (musl_strlen(name) == 4L && name.at(0) == 't' && name.at(1) == '_'
                    && (key = find_key_option(name, false)) != 0) {
                byte[] key_name = new byte[2];
                if (key < 0) {
                    key_name[0] = (byte) (-key & 255);
                    key_name[1] = (byte) ((-key >>> 8) & 255);
                } else {
                    key_name[0] = (byte) KS_KEY;
                    key_name[1] = (byte) (key & 255);
                }
                add_termcode(new BytePtr(key_name, 0), string, FALSE);
                if (full_screen != 0) {
                    ttest(false);
                }
                redraw_all_later(UPD_CLEAR);
                return null;
            }
            vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_unknown_option_str_2, 0), name);
            emsg(iobuff_or(new BytePtr(e_unknown_option_str_2, 0)));
        } else {
            flags = options[opt_idx].flags[0];
            if ((flags & P_STRING) != 0) {
                return set_string_option(opt_idx, string, opt_flags, new BytePtr(set_option_value_errbuf, 0),
                        (long) errbuflen);
            }
            varp = get_varp_scope(new Ptr<S_vimoption>(options, opt_idx), opt_flags);
            if (!optvar_is_null(varp.copy())) {
                if (number == 0L && string != null) {
                    int idx = 0;
                    for (idx = 0; string.at(idx) == '0'; idx++) {
                    }
                    if (string.at(idx) != NUL || idx == 0) {
                        vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_number_required_after_str_equal_str, 0),
                                name, string);
                        emsg(iobuff_or(new BytePtr(e_number_required_after_str_equal_str, 0)));
                        return null;
                    }
                }
                if ((flags & P_NUM) != 0) {
                    return set_num_option(opt_idx, varp.copy(), number, new BytePtr(set_option_value_errbuf, 0), 80L,
                            opt_flags);
                } else {
                    return set_bool_option(opt_idx, varp.copy(), (int) number, opt_flags);
                }
            }
        }
        return null;
    }

    private void set_option_value_give_err(BytePtr name, long number, BytePtr string, int opt_flags) {
        BytePtr errmsg = set_option_value(name, number, string, opt_flags);
        if (errmsg != null) {
            emsg(errmsg);
        }
    }

    private BytePtr get_term_code(BytePtr tname) {
        int opt_idx = 0;
        T_optvar_T varp = new T_optvar_T();
        if (tname.at(0) != 't' || tname.at(1) != '_' || tname.at(2) == NUL || tname.at(3) == NUL) {
            return null;
        }
        if ((opt_idx = findoption(tname)) >= 0) {
            varp = get_varp(new Ptr<S_vimoption>(options, opt_idx));
            if (!optvar_is_null(varp.copy())) {
                return varp.ov_str.get();
            }
            return null;
        }
        return find_termcode(tname.add(2));
    }

    private BytePtr get_highlight_default() {
        int i = findoption(BytePtr.lit("hl"));
        if (i >= 0) {
            return options[i].def_str[VI_DEFAULT];
        }
        return null;
    }

    private int find_key_option(BytePtr arg_arg, boolean has_lt) {
        T_find_special_key__out_T find_special_key__o = new T_find_special_key__out_T();
        int key = 0;
        int modifiers;
        BytePtr[] arg = new BytePtr[1];
        arg[0] = arg_arg;
        if (arg[0].at(0) == 't' && arg[0].at(1) == '_' && arg[0].at(2) != 0 && arg[0].at(3) != 0) {
            if (!has_lt || arg[0].at(4) == '>') {
                key = -(arg[0].u(2) + (arg[0].u(3) << 8));
            }
        } else if (has_lt) {
            arg[0] = arg[0].add(-1);
            modifiers = 0;
            find_special_key__o = find_special_key(new Ptr<BytePtr>(arg, 0), modifiers,
                    FSK_KEYCODE | FSK_KEEP_X_KEY | FSK_SIMPLIFY, null);
            modifiers = find_special_key__o.modp;
            key = find_special_key__o.r__;
            if (modifiers != 0) {
                key = 0;
            }
        }
        return key;
    }

    @SuppressWarnings({"rawtypes", "unchecked"})
    private void showoptions(int all, int opt_flags) {
        Ptr<S_vimoption> p = null;
        int col = 0;
        boolean isterm = false;
        T_optvar_T varp = new T_optvar_T();
        int item_count = 0;
        int run = 0;
        int row = 0;
        int rows = 0;
        int cols = 0;
        int i = 0;
        int len = 0;
        Ptr<Ptr<S_vimoption>> items = new Ptr<Ptr<S_vimoption>>(new Ptr[185], 0);
        if (all == 2) {
            msg_puts_title(BytePtr.lit("\n--- Terminal codes ---"));
        } else if ((opt_flags & OPT_GLOBAL) != 0) {
            msg_puts_title(BytePtr.lit("\n--- Global option values ---"));
        } else if ((opt_flags & OPT_LOCAL) != 0) {
            msg_puts_title(BytePtr.lit("\n--- Local option values ---"));
        } else {
            msg_puts_title(BytePtr.lit("\n--- Options ---"));
        }
        for (run = 1; run <= 2 && got_int == 0; run++) {
            item_count = 0;
            for (p = new Ptr<S_vimoption>(options, 0); p.get().fullname != null; p = p.add(1)) {
                if (message_filtered(p.get().fullname)) {
                    continue;
                }
                varp = optvar_none();
                isterm = istermoption(p);
                if ((opt_flags & (OPT_LOCAL | OPT_GLOBAL)) != 0) {
                    if (p.get().indir != PV_NONE && !isterm) {
                        varp = get_varp_scope(p, opt_flags);
                    }
                } else {
                    varp = get_varp(p);
                }
                if (!optvar_is_null(varp.copy())
                        && ((all == 2 && isterm) || (all == 1 && !isterm)
                        || (all == 0 && !optval_default(p, varp.copy(), p_cp[0])))) {
                    if ((opt_flags & OPT_ONECOLUMN) != 0) {
                        len = (int) Columns[0];
                    } else if ((p.get().flags[0] & P_BOOL) != 0) {
                        len = 1;
                    } else {
                        option_value2string(p, opt_flags);
                        len = (int) musl_strlen(p.get().fullname) + vim_strsize(NameBuff) + 1;
                    }
                    if ((len <= INC - GAP && run == 1) || (len > (INC - GAP) && run == 2)) {
                        items.set(item_count++, p);
                    }
                }
            }
            if (run == 1) {
                cols = (int) ((Columns[0] + GAP - 3L) / INC);
                if (cols == 0) {
                    cols = 1;
                }
                rows = (item_count + cols - 1) / cols;
            } else {
                rows = item_count;
            }
            for (row = 0; row < rows && got_int == 0; row++) {
                msg_putchar('\n');
                if (got_int != 0) {
                    break;
                }
                col = 0;
                for (i = row; i < item_count; i += rows) {
                    msg_col = col;
                    showoneopt(items.at(i), opt_flags);
                    col += INC;
                }
                out_flush();
                ui_breakcheck();
            }
        }
    }

    private boolean optval_default(Ptr<S_vimoption> p, T_optvar_T varp, int compatible) {
        int dvi;
        if (optvar_is_null(varp.copy())) {
            return true;
        }
        dvi = (p.get().flags[0] & P_VI_DEF) != 0 || compatible != 0 ? VI_DEFAULT : VIM_DEFAULT;
        if ((p.get().flags[0] & P_NUM) != 0) {
            return varp.ov_long.get() == p.get().def_num[dvi];
        }
        if ((p.get().flags[0] & P_BOOL) != 0) {
            return varp.ov_int.get() == (int) p.get().def_num[dvi];
        }
        return musl_strcmp(varp.ov_str.get(), p.get().def_str[dvi]) == 0;
    }

    private void showoneopt(Ptr<S_vimoption> p, int opt_flags) {
        T_optvar_T varp = new T_optvar_T();
        info_message = true;
        varp = get_varp_scope(p, opt_flags);
        if ((p.get().flags[0] & P_BOOL) != 0
                && (IntPtr.eq(varp.ov_int,
                new IntPtr(curbuf.b_changed, 0)) ? curbufIsChanged() == 0 : varp.ov_int.get() == 0)) {
            msg_puts(BytePtr.lit("no"));
        } else if ((p.get().flags[0] & P_BOOL) != 0 && varp.ov_int.get() < 0) {
            msg_puts(BytePtr.lit("--"));
        } else {
            msg_puts(BytePtr.lit("  "));
        }
        msg_puts(p.get().fullname);
        if ((p.get().flags[0] & P_BOOL) == 0) {
            msg_putchar('=');
            option_value2string(p, opt_flags);
            msg_outtrans(NameBuff);
        }
        info_message = false;
    }

    private void clear_termoptions() {
        stoptermcap();
        free_termoptions();
    }

    private void free_termoptions() {
        Ptr<S_vimoption> p = null;
        for (p = new Ptr<S_vimoption>(options, 0); p.get().fullname != null; p = p.add(1)) {
            if (istermoption(p)) {
                if ((p.get().flags[0] & P_ALLOCED) != 0) {
                    free_string_option(p.get().var_.ov_str.get());
                }
                if ((p.get().flags[0] & P_DEF_ALLOCED) != 0) {
                    free_string_option(p.get().def_str[VI_DEFAULT]);
                }
                p.get().var_.ov_str.put(empty_option);
                p.get().def_str[VI_DEFAULT] = empty_option;
                p.get().flags[0] &= ~(P_ALLOCED | P_DEF_ALLOCED);
            }
        }
        clear_termcodes();
    }

    private void set_term_defaults() {
        Ptr<S_vimoption> p = null;
        for (p = new Ptr<S_vimoption>(options, 0); p.get().fullname != null; p = p.add(1)) {
            if (istermoption(p) && !BytePtr.eq(p.get().def_str[VI_DEFAULT], p.get().var_.ov_str.get())) {
                if ((p.get().flags[0] & P_DEF_ALLOCED) != 0) {
                    free_string_option(p.get().def_str[VI_DEFAULT]);
                    p.get().flags[0] &= ~P_DEF_ALLOCED;
                }
                p.get().def_str[VI_DEFAULT] = p.get().var_.ov_str.get();
                if ((p.get().flags[0] & P_ALLOCED) != 0) {
                    p.get().flags[0] |= P_DEF_ALLOCED;
                    p.get().flags[0] &= ~P_ALLOCED;
                }
            }
        }
    }

    private static boolean istermoption(Ptr<S_vimoption> p) {
        return (int) p.get().fullname.at(0) == 't' && (int) p.get().fullname.at(1) == '_';
    }

    private boolean istermoption_idx(int opt_idx) {
        return istermoption(new Ptr<S_vimoption>(options, opt_idx));
    }

    private T_optvar_T get_varp_allbuf(Ptr<S_vimoption> p) {
        switch (p.get().indir) {
            case (PV_WIN + WV_LIST) -> {
                return optvar_int(new IntPtr(curwin.w_allbuf_opt.wo_list, 0)).copy();
            }
            case (PV_WIN + WV_NU) -> {
                return optvar_int(new IntPtr(curwin.w_allbuf_opt.wo_nu, 0)).copy();
            }
            case (PV_WIN + WV_RNU) -> {
                return optvar_int(new IntPtr(curwin.w_allbuf_opt.wo_rnu, 0)).copy();
            }
            case (PV_WIN + WV_SCROLL) -> {
                return optvar_long(new LongPtr(curwin.w_allbuf_opt.wo_scr, 0)).copy();
            }
            case (PV_WIN + WV_SMS) -> {
                return optvar_int(new IntPtr(curwin.w_allbuf_opt.wo_sms, 0)).copy();
            }
            case (PV_WIN + WV_WRAP) -> {
                return optvar_int(new IntPtr(curwin.w_allbuf_opt.wo_wrap, 0)).copy();
            }
            case (PV_WIN + WV_WCR) -> {
                return optvar_str(new Ptr<BytePtr>(curwin.w_allbuf_opt.wo_wcr, 0)).copy();
            }
            case (PV_WIN + WV_WHL) -> {
                return optvar_str(new Ptr<BytePtr>(curwin.w_allbuf_opt.wo_whl, 0)).copy();
            }
        }
        return optvar_none().copy();
    }

    private T_optvar_T get_varp_scope(Ptr<S_vimoption> p, int scope) {
        if ((scope & OPT_GLOBAL) != 0 && p.get().indir != PV_NONE) {
            if (p.get().var_.ov_win != 0) {
                return get_varp_allbuf(p).copy();
            }
            return p.get().var_.copy();
        }
        if ((scope & OPT_LOCAL) != 0 && (p.get().indir & PV_BOTH) != 0) {
            switch (p.get().indir) {
                case (PV_BOTH + (PV_WIN + WV_SISO)) -> {
                    return optvar_long(new LongPtr(curwin.w_onebuf_opt.wo_siso, 0)).copy();
                }
                case (PV_BOTH + (PV_WIN + WV_SO)) -> {
                    return optvar_long(new LongPtr(curwin.w_onebuf_opt.wo_so, 0)).copy();
                }
                case (PV_BOTH + (PV_WIN + WV_SOP)) -> {
                    return optvar_long(new LongPtr(curwin.w_onebuf_opt.wo_sop, 0)).copy();
                }
                case (PV_BOTH + (PV_BUF + BV_UL)) -> {
                    return optvar_long(new LongPtr(curbuf.b_p_ul, 0)).copy();
                }
                case (PV_BOTH + (PV_WIN + WV_LCS)) -> {
                    return optvar_str(new Ptr<BytePtr>(curwin.w_onebuf_opt.wo_lcs, 0)).copy();
                }
                case (PV_BOTH + (PV_WIN + WV_FCS)) -> {
                    return optvar_str(new Ptr<BytePtr>(curwin.w_onebuf_opt.wo_fcs, 0)).copy();
                }
                case (PV_BOTH + (PV_WIN + WV_VE)) -> {
                    return optvar_str(new Ptr<BytePtr>(curwin.w_onebuf_opt.wo_ve, 0)).copy();
                }
            }
            return optvar_none().copy();
        }
        return get_varp(p).copy();
    }

    private T_optvar_T get_option_varp_scope(int opt_idx, int scope) {
        return get_varp_scope(new Ptr<S_vimoption>(options, opt_idx), scope).copy();
    }

    private T_optvar_T get_varp(Ptr<S_vimoption> p) {
        if (optvar_is_null(p.get().var_.copy())) {
            return optvar_none().copy();
        }
        switch (p.get().indir) {
            case PV_NONE -> {
                return p.get().var_.copy();
            }
            case (PV_BOTH + (PV_WIN + WV_SISO)) -> {
                return (curwin.w_onebuf_opt.wo_siso[0] >= 0L ? optvar_long(new LongPtr(curwin.w_onebuf_opt.wo_siso,
                        0)) : p.get().var_).copy();
            }
            case (PV_BOTH + (PV_WIN + WV_SO)) -> {
                return (curwin.w_onebuf_opt.wo_so[0] >= 0L ? optvar_long(new LongPtr(curwin.w_onebuf_opt.wo_so,
                        0)) : p.get().var_).copy();
            }
            case (PV_BOTH + (PV_WIN + WV_SOP)) -> {
                return (curwin.w_onebuf_opt.wo_sop[0] != -1L ? optvar_long(new LongPtr(curwin.w_onebuf_opt.wo_sop,
                        0)) : p.get().var_).copy();
            }
            case (PV_BOTH + (PV_BUF + BV_UL)) -> {
                return (curbuf.b_p_ul[0] != -123456L ? optvar_long(new LongPtr(curbuf.b_p_ul,
                        0)) : p.get().var_).copy();
            }
            case (PV_WIN + WV_LIST) -> {
                return optvar_int(new IntPtr(curwin.w_onebuf_opt.wo_list, 0)).copy();
            }
            case (PV_BOTH + (PV_WIN + WV_LCS)) -> {
                return (curwin.w_onebuf_opt.wo_lcs[0].get() != NUL ? optvar_str(new Ptr<BytePtr>(curwin.w_onebuf_opt.wo_lcs, 0)) : p.get().var_).copy();
            }
            case (PV_BOTH + (PV_WIN + WV_FCS)) -> {
                return (curwin.w_onebuf_opt.wo_fcs[0].get() != NUL ? optvar_str(new Ptr<BytePtr>(curwin.w_onebuf_opt.wo_fcs, 0)) : p.get().var_).copy();
            }
            case (PV_BOTH + (PV_WIN + WV_VE)) -> {
                return (curwin.w_onebuf_opt.wo_ve[0].get() != NUL ? optvar_str(new Ptr<BytePtr>(curwin.w_onebuf_opt.wo_ve, 0)) : p.get().var_).copy();
            }
            case (PV_WIN + WV_NU) -> {
                return optvar_int(new IntPtr(curwin.w_onebuf_opt.wo_nu, 0)).copy();
            }
            case (PV_WIN + WV_RNU) -> {
                return optvar_int(new IntPtr(curwin.w_onebuf_opt.wo_rnu, 0)).copy();
            }
            case (PV_WIN + WV_SCROLL) -> {
                return optvar_long(new LongPtr(curwin.w_onebuf_opt.wo_scr, 0)).copy();
            }
            case (PV_WIN + WV_SMS) -> {
                return optvar_int(new IntPtr(curwin.w_onebuf_opt.wo_sms, 0)).copy();
            }
            case (PV_WIN + WV_WRAP) -> {
                return optvar_int(new IntPtr(curwin.w_onebuf_opt.wo_wrap, 0)).copy();
            }
            case (PV_WIN + WV_WCR) -> {
                return optvar_str(new Ptr<BytePtr>(curwin.w_onebuf_opt.wo_wcr, 0)).copy();
            }
            case (PV_WIN + WV_WHL) -> {
                return optvar_str(new Ptr<BytePtr>(curwin.w_onebuf_opt.wo_whl, 0)).copy();
            }
            case (PV_BUF + BV_AI) -> {
                return optvar_int(new IntPtr(curbuf.b_p_ai, 0)).copy();
            }
            case (PV_BUF + BV_CI) -> {
                return optvar_int(new IntPtr(curbuf.b_p_ci, 0)).copy();
            }
            case (PV_BUF + BV_ET) -> {
                return optvar_int(new IntPtr(curbuf.b_p_et, 0)).copy();
            }
            case (PV_BUF + BV_ISK) -> {
                return optvar_str(new Ptr<BytePtr>(curbuf.b_p_isk, 0)).copy();
            }
            case (PV_BUF + BV_MPS) -> {
                return optvar_str(new Ptr<BytePtr>(curbuf.b_p_mps, 0)).copy();
            }
            case (PV_BUF + BV_MA) -> {
                return optvar_int(new IntPtr(curbuf.b_p_ma, 0)).copy();
            }
            case (PV_BUF + BV_MOD) -> {
                return optvar_int(new IntPtr(curbuf.b_changed, 0)).copy();
            }
            case (PV_BUF + BV_NF) -> {
                return optvar_str(new Ptr<BytePtr>(curbuf.b_p_nf, 0)).copy();
            }
            case (PV_BUF + BV_PI) -> {
                return optvar_int(new IntPtr(curbuf.b_p_pi, 0)).copy();
            }
            case (PV_BUF + BV_QE) -> {
                return optvar_str(new Ptr<BytePtr>(curbuf.b_p_qe, 0)).copy();
            }
            case (PV_BUF + BV_SI) -> {
                return optvar_int(new IntPtr(curbuf.b_p_si, 0)).copy();
            }
            case (PV_BUF + BV_STS) -> {
                return optvar_long(new LongPtr(curbuf.b_p_sts, 0)).copy();
            }
            case (PV_BUF + BV_SW) -> {
                return optvar_long(new LongPtr(curbuf.b_p_sw, 0)).copy();
            }
            case (PV_BUF + BV_TS) -> {
                return optvar_long(new LongPtr(curbuf.b_p_ts, 0)).copy();
            }
            case (PV_BUF + BV_TW) -> {
                return optvar_long(new LongPtr(curbuf.b_p_tw, 0)).copy();
            }
            case (PV_BUF + BV_WM) -> {
                return optvar_long(new LongPtr(curbuf.b_p_wm, 0)).copy();
            }
            default -> iemsg(new BytePtr(e_get_varp_error, 0));
        }
        return optvar_long(new LongPtr(curbuf.b_p_wm, 0)).copy();
    }

    private Ptr<BytePtr> get_option_var(int opt_idx) {
        return options[opt_idx].var_.ov_str;
    }

