    private void after_copy_winopt(S_window_S wp) {
        BytePtr errmsg = update_winhighlight(wp, wp.w_onebuf_opt.wo_whl[0]);
        if (errmsg != null) {
            emsg(errmsg);
        }
        if (wp.w_onebuf_opt.wo_wrap[0] != 0) {
            wp.w_leftcol = 0;
        } else {
            wp.w_skipcol = 0;
        }
        set_listchars_option(wp, wp.w_onebuf_opt.wo_lcs[0], true, null, 0L);
        set_fillchars_option(wp, wp.w_onebuf_opt.wo_fcs[0], true, null, 0L);
    }

    private BytePtr copy_option_val(BytePtr val) {
        if (BytePtr.eq(val, empty_option)) {
            return empty_option;
        }
        return vim_strsave(val);
    }

    private void copy_winopt(T_winopt_T from, T_winopt_T to_) {
        to_.wo_list[0] = from.wo_list[0];
        to_.wo_lcs[0] = copy_option_val(from.wo_lcs[0]);
        to_.wo_fcs[0] = copy_option_val(from.wo_fcs[0]);
        to_.wo_nu[0] = from.wo_nu[0];
        to_.wo_rnu[0] = from.wo_rnu[0];
        to_.wo_ve[0] = copy_option_val(from.wo_ve[0]);
        to_.wo_ve_flags[0] = from.wo_ve_flags[0];
        to_.wo_wrap[0] = from.wo_wrap[0];
        to_.wo_wcr[0] = copy_option_val(from.wo_wcr[0]);
        to_.wo_sms[0] = from.wo_sms[0];
        to_.wo_siso[0] = from.wo_siso[0];
        to_.wo_so[0] = from.wo_so[0];
        to_.wo_sop[0] = from.wo_sop[0];
        to_.wo_wrap_flags = from.wo_wrap_flags;
        to_.wo_whl[0] = copy_option_val(from.wo_whl[0]);
        check_winopt(to_);
    }

    private void check_win_options(S_window_S win) {
        check_winopt(win.w_onebuf_opt);
        check_winopt(win.w_allbuf_opt);
    }

    private void check_winopt(T_winopt_T wop) {
        check_string_option(new Ptr<BytePtr>(wop.wo_wcr, 0));
        check_string_option(new Ptr<BytePtr>(wop.wo_lcs, 0));
        check_string_option(new Ptr<BytePtr>(wop.wo_fcs, 0));
        check_string_option(new Ptr<BytePtr>(wop.wo_ve, 0));
        check_string_option(new Ptr<BytePtr>(wop.wo_whl, 0));
    }

    private void clear_winopt(T_winopt_T wop) {
        clear_string_option(new Ptr<BytePtr>(wop.wo_wcr, 0));
        clear_string_option(new Ptr<BytePtr>(wop.wo_lcs, 0));
        clear_string_option(new Ptr<BytePtr>(wop.wo_fcs, 0));
        clear_string_option(new Ptr<BytePtr>(wop.wo_ve, 0));
        clear_string_option(new Ptr<BytePtr>(wop.wo_whl, 0));
    }

    private void buf_copy_options(S_file_buffer buf, int flags) {
        boolean should_copy = true;
        BytePtr save_p_isk = null;
        boolean dont_do_help;
        boolean did_isk = false;
        if (p_cpo[0] != null) {
            if ((vim_strchr(p_cpo[0], CPO_BUFOPTGLOB) == null || (flags & BCO_ENTER) == 0)
                    && (buf.b_p_initialized
                    || ((flags & BCO_ENTER) == 0 && vim_strchr(p_cpo[0], CPO_BUFOPT) != null))) {
                should_copy = false;
            }
            if (should_copy || (flags & BCO_ALWAYS) != 0) {
                dont_do_help = ((flags & BCO_NOHELP) != 0 && buf.b_help) || buf.b_p_initialized;
                if (dont_do_help) {
                    save_p_isk = buf.b_p_isk[0];
                    buf.b_p_isk[0] = null;
                }
                if (!buf.b_p_initialized) {
                    free_buf_options(buf, true);
                } else {
                    free_buf_options(buf, false);
                }
                buf.b_p_ai[0] = p_ai[0];
                buf.b_p_ai_nopaste = p_ai_nopaste;
                buf.b_p_sw[0] = p_sw[0];
                buf.b_p_tw[0] = p_tw[0];
                buf.b_p_tw_nopaste = p_tw_nopaste;
                buf.b_p_wm[0] = p_wm[0];
                buf.b_p_wm_nopaste = p_wm_nopaste;
                buf.b_p_et[0] = p_et[0];
                buf.b_p_et_nopaste = p_et_nopaste;
                buf.b_p_sts[0] = p_sts[0];
                buf.b_p_sts_nopaste = p_sts_nopaste;
                buf.b_p_nf[0] = vim_strsave(p_nf[0]);
                buf.b_p_mps[0] = vim_strsave(p_mps[0]);
                buf.b_p_si[0] = p_si[0];
                buf.b_p_ci[0] = p_ci[0];
                buf.b_p_pi[0] = p_pi[0];
                buf.b_p_ul[0] = -123456L;
                buf.b_bkc_flags = 0;
                buf.b_tc_flags = 0;
                buf.b_cot_flags = 0;
                buf.b_p_qe[0] = vim_strsave(p_qe[0]);
                if (dont_do_help) {
                    buf.b_p_isk[0] = save_p_isk;
                } else {
                    buf.b_p_isk[0] = vim_strsave(p_isk[0]);
                    did_isk = true;
                    buf.b_p_ts[0] = p_ts[0];
                    buf.b_help = false;
                    buf.b_p_ma[0] = p_ma[0];
                }
            }
            if (should_copy) {
                buf.b_p_initialized = true;
            }
        }
        check_buf_options(buf);
        if (did_isk) {
            buf_init_chartab(buf, false);
        }
    }

    private void option_value2string(Ptr<S_vimoption> opp, int scope) {
        T_optvar_T varp = new T_optvar_T();
        varp = get_varp_scope(opp, scope);
        if ((opp.get().flags[0] & P_NUM) != 0) {
            vim_snprintf(NameBuff, PATH_MAX, BytePtr.lit("%ld"), varp.ov_long.get());
        } else {
            BytePtr s = varp.ov_str.get();
            if (s == null) {
                NameBuff.set(0, (byte) NUL);
            } else if ((opp.get().flags[0] & P_EXPAND) != 0) {
                home_replace(null, s, NameBuff, PATH_MAX, false);
            } else if (Ptr.eq(opp.get().var_.ov_str, new Ptr<BytePtr>(p_pt, 0))) {
                str2specialbuf(p_pt[0], NameBuff, PATH_MAX);
            } else {
                vim_strncpy(NameBuff, s, PATH_MAX - 1);
            }
        }
    }

    private boolean shortmess(int x) {
        return p_shm[0] != null
                && (vim_strchr(p_shm[0], x) != null
                || (vim_strchr(p_shm[0], 'a') != null && vim_strchr(BytePtr.lit("rmfixlnw"), x) != null));
    }

    private boolean option_was_set(BytePtr name) {
        int idx = findoption(name);
        if (idx < 0) {
            return false;
        }
        if ((options[idx].flags[0] & P_WAS_SET) != 0) {
            return true;
        }
        return false;
    }

    private boolean reset_option_was_set(BytePtr name) {
        int idx = findoption(name);
        if (idx < 0) {
            return false;
        }
        options[idx].flags[0] &= ~P_WAS_SET;
        return true;
    }

    private void compatible_set() {
        int opt_idx = 0;
        for (opt_idx = 0; !istermoption_idx(opt_idx); opt_idx++) {
            if (((options[opt_idx].flags[0] & P_VIM) != 0 && p_cp[0] != 0)
                    || ((options[opt_idx].flags[0] & P_VI_DEF) == 0 && p_cp[0] == 0)) {
                set_option_default(opt_idx, OPT_FREE, p_cp[0]);
            }
        }
        didset_options();
        didset_options2();
    }

    private boolean can_bs(int what) {
        switch (p_bs[0].u()) {
            case '3' -> {
                return true;
            }
            case '2' -> {
                return what != BS_NOSTOP;
            }
            case '1' -> {
                return what != BS_START;
            }
            case '0' -> {
                return false;
            }
        }
        return vim_strchr(p_bs[0], what) != null;
    }

    private long get_scrolloff_value() {
        return curwin.w_onebuf_opt.wo_so[0] < 0L ? p_so[0] : curwin.w_onebuf_opt.wo_so[0];
    }

    private long get_scrolloffpad_value() {
        return curwin.w_onebuf_opt.wo_sop[0] == -1L ? p_sop[0] : curwin.w_onebuf_opt.wo_sop[0];
    }

    private long get_sidescrolloff_value() {
        return curwin.w_onebuf_opt.wo_siso[0] < 0L ? p_siso[0] : curwin.w_onebuf_opt.wo_siso[0];
    }

    private int get_ve_flags() {
        return (curwin.w_onebuf_opt.wo_ve_flags[0] != 0 ? curwin.w_onebuf_opt.wo_ve_flags[0] : ve_flags[0]) & ~(VE_NONE | VE_NONEU);
    }

    private int magic_isset() {
        switch (magic_overruled) {
            case OPTION_MAGIC_ON -> {
                return TRUE;
            }
            case OPTION_MAGIC_OFF -> {
                return FALSE;
            }
            case OPTION_MAGIC_NOT_SET -> {
            }
        }
        return p_magic[0];
    }

    private void didset_string_options() {
        opt_strings_flags(p_cmp[0], new Ptr<BytePtr>(p_cmp_values, 0), new IntPtr(cmp_flags, 0), true);
        opt_strings_flags(p_bo[0], new Ptr<BytePtr>(p_bo_values, 0), new IntPtr(bo_flags, 0), true);
        opt_strings_flags(p_dy[0], new Ptr<BytePtr>(p_dy_values, 0), new IntPtr(dy_flags, 0), true);
        opt_strings_flags(p_ve[0], new Ptr<BytePtr>(p_ve_values, 0), new IntPtr(ve_flags, 0), true);
    }

    private BytePtr illegal_char(BytePtr errbuf, long errbuflen, int c) {
        if (errbuf == null) {
            return BytePtr.lit("");
        }
        vim_snprintf(errbuf, errbuflen, new BytePtr(e_illegal_character_str, 0), transchar(c));
        return errbuf;
    }

    private void check_buf_options(S_file_buffer buf) {
        check_string_option(new Ptr<BytePtr>(buf.b_p_mps, 0));
        check_string_option(new Ptr<BytePtr>(buf.b_p_isk, 0));
        check_string_option(new Ptr<BytePtr>(buf.b_p_nf, 0));
        check_string_option(new Ptr<BytePtr>(buf.b_p_qe, 0));
    }

    private static void free_string_option(BytePtr p) {
    }

    private void clear_string_option(Ptr<BytePtr> pp) {
        pp.put(empty_option);
    }

    private void check_string_option(Ptr<BytePtr> pp) {
        if (pp.get() == null) {
            pp.put(empty_option);
        }
    }

    private void set_string_option_global(int opt_idx, Ptr<BytePtr> varp) {
        Ptr<BytePtr> p;
        BytePtr s = null;
        if (is_window_local_option(opt_idx) != 0) {
            p = get_varp_allbuf(new Ptr<S_vimoption>(options, opt_idx)).ov_str;
        } else {
            p = get_option_var(opt_idx);
        }
        if (!is_global_option(opt_idx) && !Ptr.eq(p, varp) && (s = vim_strsave(varp.get())) != null) {
            free_string_option(p.get());
            p.put(s);
        }
    }

    private void set_string_option_direct(BytePtr name, int opt_idx, BytePtr val, int opt_flags, int set_sid) {
        BytePtr s;
        Ptr<BytePtr> varp;
        boolean both = (opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0;
        int idx = opt_idx;
        if (idx == -1) {
            idx = findoption(name);
            if (idx < 0) {
                vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_internal_error_str, 0),
                        BytePtr.lit("set_string_option_direct()"));
                emsg(iobuff_or(new BytePtr(e_internal_error_str, 0)));
                vim_snprintf(IObuff, emsg_iobuff_room(), BytePtr.lit("For option %s"), name);
                iemsg(iobuff_or(BytePtr.lit("For option %s")));
                return;
            }
        }
        if (is_hidden_option(idx)) {
            return;
        }
        s = vim_strsave(val);
        varp = get_option_varp_scope(idx, both ? OPT_LOCAL : opt_flags).ov_str;
        if ((opt_flags & OPT_FREE) != 0 && (get_option_flags(idx) & P_ALLOCED) != 0) {
            free_string_option(varp.get());
        }
        varp.put(s);
        if (both) {
            set_string_option_global(idx, varp);
        }
        set_option_flag(idx, P_ALLOCED);
        if (is_global_local_option(idx) != 0 && both) {
            free_string_option(varp.get());
            varp.put(empty_option);
        }
    }

    private void set_string_option_direct_in_win(S_window_S wp, BytePtr name, int opt_idx, BytePtr val, int opt_flags,
            int set_sid) {
        S_window_S save_curwin = curwin;
        block_autocmds();
        curwin = wp;
        curbuf = curwin.w_buffer;
        set_string_option_direct(name, opt_idx, val, opt_flags, set_sid);
        curwin = save_curwin;
        curbuf = curwin.w_buffer;
        unblock_autocmds();
    }

    private BytePtr set_string_option(int opt_idx, BytePtr value, int opt_flags, BytePtr errbuf, long errbuflen) {
        BytePtr s;
        Ptr<BytePtr> varp;
        BytePtr oldval;
        BytePtr errmsg = null;
        int[] value_checked = new int[1];
        value_checked[0] = FALSE;
        if (is_hidden_option(opt_idx)) {
            return null;
        }
        s = vim_strsave(value == null ? BytePtr.lit("") : value);
        varp = get_option_varp_scope(opt_idx,
                (opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0 ? (is_global_local_option(opt_idx) != 0 ? OPT_GLOBAL : OPT_LOCAL) : opt_flags).ov_str;
        oldval = varp.get();
        varp.put(s);
        if ((errmsg = did_set_string_option(opt_idx, varp, oldval, value, errbuf, errbuflen, opt_flags, OP_NONE,
                new IntPtr(value_checked, 0))) == null) {
            did_set_option(opt_idx, opt_flags, true, value_checked[0]);
        }
        return errmsg;
    }

    private boolean check_illegal_path_names(int opt_idx, Ptr<BytePtr> varp) {
        return ((get_option_flags(opt_idx) & P_NFNAME) != 0
                && musl_strpbrk(varp.get(),
                secure != 0 ? BytePtr.lit("/\\*?[|;&<>\015\n") : BytePtr.lit("/\\*?[<>\015\n")) != null)
                || ((get_option_flags(opt_idx) & P_NDNAME) != 0
                && musl_strpbrk(varp.get(), BytePtr.lit("*?[|;&<>\015\n")) != null);
    }

