    private BytePtr did_set_term_option(T_optset_T args) {
        Ptr<BytePtr> varp = args.os_varp.ov_str;
        if (full_screen == 0) {
            return null;
        }
        if (Ptr.eq(varp, new Ptr<BytePtr>(term_strings, KS_CCO))) {
            int colors = musl_atoi(term_strings[KS_CCO]);
            if (colors != t_colors) {
                t_colors = colors;
                if (t_colors <= 1) {
                    term_strings[KS_CCO] = empty_option;
                }
                init_highlight(true, false);
            }
        }
        ttest(false);
        if (Ptr.eq(varp, new Ptr<BytePtr>(term_strings, KS_ME))) {
            out_str(term_strings[KS_ME]);
            redraw_later(UPD_CLEAR);
        }
        if (Ptr.eq(varp, new Ptr<BytePtr>(term_strings, KS_CBE)) && termcap_active) {
            if (term_strings[KS_CBE].get() == NUL) {
                out_str(term_strings[KS_CBD]);
            } else {
                out_str(term_strings[KS_CBE]);
            }
        }
        if (Ptr.eq(varp, new Ptr<BytePtr>(term_strings, KS_BSU))
                || Ptr.eq(varp, new Ptr<BytePtr>(term_strings, KS_ESU))) {
            term_set_sync_output(TERM_SYNC_OUTPUT_OFF);
        }
        return null;
    }

