    private BytePtr did_set_string_option(int opt_idx, Ptr<BytePtr> varp, BytePtr oldval, BytePtr value, BytePtr errbuf,
            long errbuflen, int opt_flags, int op, IntPtr value_checked) {
        BytePtr errmsg = null;
        long free_oldval = get_option_flags(opt_idx) & P_ALLOCED;
        Fn6 did_set_cb = get_option_did_set_cb(opt_idx);
        T_optset_T args = new T_optset_T();
        if (Ptr.eq(varp, new Ptr<BytePtr>(term_strings, KS_NAME))) {
            opt_idx = findoption(BytePtr.lit("term"));
            if (opt_idx >= 0) {
                free_oldval = get_option_flags(opt_idx) & P_ALLOCED;
                did_set_cb = get_option_did_set_cb(opt_idx);
            }
        }
        args.zero();
        if (secure != 0 && (get_option_flags(opt_idx) & P_SECURE) != 0) {
            errmsg = new BytePtr(e_not_allowed_here, 0);
        } else if (check_illegal_path_names(opt_idx, varp)) {
            errmsg = new BytePtr(e_invalid_argument, 0);
        } else if (did_set_cb != null) {
            args.os_varp.set(optvar_str(varp));
            args.os_idx = opt_idx;
            args.os_flags = opt_flags;
            args.os_op = op;
            args.os_oldval.string = oldval;
            args.os_newval.string = value;
            args.os_errbuf = errbuf;
            args.os_errbuflen = errbuflen;
            errmsg = did_set_cb.call(args);
            value_checked.put(args.os_value_checked);
        }
        if (errmsg != null) {
            free_string_option(varp.get());
            varp.put(oldval);
            if (args.os_restore_chartab) {
                init_chartab();
            }
            if (Ptr.eq(varp, new Ptr<BytePtr>(p_hl, 0))) {
                highlight_changed();
            }
        } else {
            if (free_oldval != 0) {
                free_string_option(oldval);
            }
            set_option_flag(opt_idx, P_ALLOCED);
            if ((opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0 && is_global_local_option(opt_idx) != 0) {
                Ptr<BytePtr> p = get_option_varp_scope(opt_idx, OPT_LOCAL).ov_str;
                free_string_option(p.get());
                p.put(empty_option);
            } else if ((opt_flags & OPT_LOCAL) == 0 && opt_flags != OPT_GLOBAL) {
                set_string_option_global(opt_idx, varp);
            }
        }
        if (curwin.w_curswant != MAXCOL && (get_option_flags(opt_idx) & (P_CURSWANT | P_RALL)) != 0L
                && (get_option_flags(opt_idx) & P_HLONLY) == 0L) {
            curwin.w_set_curswant = true;
        }
        if ((opt_flags & OPT_NO_REDRAW) == 0) {
            check_redraw(get_option_flags(opt_idx));
        }
        return errmsg;
    }

    private boolean check_opt_strings(BytePtr val, Ptr<BytePtr> values, boolean list) {
        return opt_strings_flags(val, values, null, list);
    }

    private boolean opt_strings_flags(BytePtr val, Ptr<BytePtr> values, IntPtr flagp, boolean list) {
        int i = 0;
        int len = 0;
        int new_flags = 0;
        while (val.get() != 0) {
            for (i = 0; ; i++) {
                if (values.at(i) == null) {
                    return false;
                }
                len = (int) musl_strlen(values.at(i));
                if (musl_strncmp(values.at(i), val, (long) len) == 0
                        && ((list && val.at(len) == ',') || val.at(len) == NUL)) {
                    val = val.add(len + (val.at(len) == ',' ? 1 : 0));
                    new_flags |= 1 << i;
                    break;
                }
            }
        }
        if (flagp != null) {
            flagp.put(new_flags);
        }
        return true;
    }

    private void mch_write(BytePtr s, int len) {
        vim_ignored = host_write(s, len);
        if (p_wd[0] != 0) {
            RealWaitForChar(read_cmd_fd, p_wd[0], null, null);
        }
    }

    private int mch_inchar(BytePtr buf, int maxlen, long wtime, int tb_change_cnt) {
        return inchar_loop(buf, maxlen, wtime, tb_change_cnt, fp_WaitForChar, null);
    }

    private void mch_delay(long msec, int flags) {
        if ((flags & MCH_DELAY_IGNOREINPUT) != 0) {
            out_flush();
            musl_delay(msec, TRUE);
        } else {
            WaitForChar(msec, null, FALSE);
        }
    }

    void deathtrap(int sigarg) {
        int i = 0;
        if (deathtrap_entered == 0 && (sigarg == SIGHUP || sigarg == SIGTERM) && !vim_handle_signal(sigarg)) {
            return;
        }
        deathtrap_entered++;
        block_autocmds();
        v_dying = deathtrap_entered;
        for (i = 0; signal_info[i].sig != -1; i++) {
            if (sigarg == signal_info[i].sig) {
                break;
            }
        }
        full_screen = FALSE;
        if (deathtrap_entered == 2) {
            out_str(BytePtr.lit("Vim: Double signal, exiting\n"));
            out_flush();
            getout(1);
        }
        vim_snprintf(IObuff, 1025L, BytePtr.lit("Vim: Caught deadly signal %s\015\n"), signal_info[i].name);
        preserve_exit();
    }

    private void mch_suspend() {
        out_flush();
        term_leave();
        out_flush();
        musl_suspend();
        term_enter();
    }

    private void mch_init() {
        Columns[0] = 80L;
        Rows[0] = 24L;
        out_flush();
        musl_host_init();
    }

    private boolean vim_handle_signal(int sig) {
        switch (sig) {
            case -1 -> vim_handle_signal_blocked = true;
            case -2 -> {
                vim_handle_signal_blocked = false;
                if (vim_handle_signal_got_signal != 0) {
                    host_raise(vim_handle_signal_got_signal);
                    vim_handle_signal_got_signal = 0;
                }
            }
            default -> {
                if (!vim_handle_signal_blocked) {
                    return true;
                }
                vim_handle_signal_got_signal = sig;
                got_int = TRUE;
            }
        }
        return false;
    }

    private boolean vim_is_xterm(BytePtr name) {
        if (name == null) {
            return false;
        }
        return (musl_strncasecmp(name, BytePtr.lit("xterm"), 5L) == 0
                && musl_strncasecmp(name, BytePtr.lit("xterm-kitty"), 11L) != 0)
                || musl_strncasecmp(name, BytePtr.lit("nxterm"), 6L) == 0
                || musl_strncasecmp(name, BytePtr.lit("kterm"), 5L) == 0
                || musl_strncasecmp(name, BytePtr.lit("mlterm"), 6L) == 0
                || musl_strncasecmp(name, BytePtr.lit("rxvt"), 4L) == 0
                || musl_strncasecmp(name, BytePtr.lit("screen.xterm"), 12L) == 0
                || musl_strcmp(name, BytePtr.lit("builtin_xterm")) == 0;
    }

    private void exit_scroll() {
        if (newline_on_exit || msg_didout != 0) {
            if (msg_use_printf()) {
                if (info_message) {
                    host_message(BytePtr.lit("\n"), -1, FALSE);
                } else {
                    host_message(BytePtr.lit("\015\n"), -1, TRUE);
                }
            } else {
                out_char('\n');
            }
        } else {
            restore_cterm_colors();
            msg_clr_eos_force();
            windgoto((int) Rows[0] - 1, cmdline_col_off);
        }
    }

    private void mch_exit(int r) {
        exiting = true;
        term_leave();
        if (swapping_screen() && !newline_on_exit) {
            exit_scroll();
        }
        stoptermcap();
        if (!swapping_screen() || newline_on_exit) {
            exit_scroll();
        }
        if (full_screen != 0) {
            cursor_on();
        }
        out_flush();
        ml_close_all(true);
        host_exit(r);
    }

    private void get_stty() {
        T_ttyinfo_T info = new T_ttyinfo_T();
        byte[] buf = new byte[2];
        BytePtr p;
        if (!get_tty_info(read_cmd_fd, info)) {
            return;
        }
        intr_char = info.interrupt;
        buf[0] = (byte) info.backspace;
        buf[1] = NUL;
        add_termcode(BytePtr.lit("kb"), new BytePtr(buf, 0), FALSE);
        p = find_termcode(BytePtr.lit("kD"));
        if (p != null && p.u(0) == (buf[0] & 0xff) && p.u(1) == (buf[1] & 0xff)) {
            do_fixdel(null);
        }
    }

    private boolean get_tty_info(int fd, T_ttyinfo_T info) {
        int[] bs = new int[1];
        bs[0] = 0;
        int[] intr = new int[1];
        intr[0] = 0;
        int[] cr = new int[1];
        cr[0] = 0;
        int[] nlcr = new int[1];
        nlcr[0] = 0;
        if (musl_tty_keys(fd, new IntPtr(bs, 0), new IntPtr(intr, 0), new IntPtr(cr, 0), new IntPtr(nlcr, 0)) == OK) {
            info.backspace = (byte) bs[0] & 0xff;
            info.interrupt = (byte) intr[0] & 0xff;
            info.enter = cr[0] != 0 ? NL : CAR;
            info.nl_does_cr = (nlcr[0] != 0 ? TRUE : FALSE) != 0;
            return true;
        }
        return false;
    }

    private void mch_set_shellsize() {
        if (term_strings[KS_CWS].get() != 0) {
            term_set_winsize((int) Rows[0], (int) Columns[0]);
            out_flush();
            screen_start();
        }
    }

    private void mch_breakcheck(boolean force) {
        if ((term_entered || force) && RealWaitForChar(read_cmd_fd, 0L, null, null) != 0) {
            fill_input_buf(false);
        }
    }

    private int WaitForChar(long msec, IntPtr interrupted, int ignore_input) {
        int avail;
        if (ignore_input == 0 && input_available()) {
            return 1;
        }
        avail = RealWaitForChar(read_cmd_fd, msec, null, interrupted);
        return avail;
    }

    private int RealWaitForChar(int fd, long msec, IntPtr check_for_gpm, IntPtr interrupted) {
        return musl_wait_for_input(msec);
    }

    private static int no_Magic(int x) {
        if (x < 0) {
            return x + 256;
        }
        return x;
    }

    private static int toggle_Magic(int x) {
        if (x < 0) {
            return x + 256;
        }
        return x - 256;
    }

    private static int re_multi_type(int c) {
        if (c == '@' - 256 || c == '=' - 256 || c == '?' - 256) {
            return MULTI_ONE;
        }
        if (c == '*' - 256 || c == '+' - 256 || c == '{' - 256) {
            return MULTI_MULT;
        }
        return NOT_MULTI;
    }

    private static int backslash_trans(int c) {
        switch (c) {
            case 'r' -> {
                return CAR;
            }
            case 't' -> {
                return TAB;
            }
            case 'e' -> {
                return ESC;
            }
            case 'b' -> {
                return BS;
            }
        }
        return c;
    }

    private int get_char_class(Ptr<BytePtr> pp) {
        if (pp.get().at(1) == ':' && ascii_islower(pp.get().u(2)) && ascii_islower(pp.get().u(3))
                && ascii_islower(pp.get().u(4))) {
            T_keyvalue_T target = new T_keyvalue_T();
            Ptr<T_keyvalue_T> entry;
            target.key = 0;
            target.value.string[0] = pp.get().add(2);
            target.value.length = 0L;
            if (get_char_class_last_entry != null && cmp_keyvalue_value_n(target, get_char_class_last_entry) == 0) {
                entry = get_char_class_last_entry;
            } else {
                entry = keyvalue_bsearch(target, new Ptr<T_keyvalue_T>(get_char_class_char_class_tab, 0), 19L,
                        fp_cmp_keyvalue_value_n_Fn3);
            }
            if (entry != null) {
                get_char_class_last_entry = entry;
                pp.put(pp.get().add((int) (entry.get().value.length + 2L)));
                return entry.get().key;
            }
        }
        return CLASS_NONE;
    }

    private void init_class_tab() {
        int i = 0;
        if (init_class_tab_done) {
            return;
        }
        for (i = 0; i < 256; i++) {
            if (i >= '0' && i <= '7') {
                class_tab[i] = RI_DIGIT + RI_HEX + RI_OCTAL + RI_WORD;
            } else if (i >= '8' && i <= '9') {
                class_tab[i] = RI_DIGIT + RI_HEX + RI_WORD;
            } else if (i >= 'a' && i <= 'f') {
                class_tab[i] = RI_HEX + RI_WORD + RI_HEAD + RI_ALPHA + RI_LOWER;
            } else if (i >= 'g' && i <= 'z') {
                class_tab[i] = RI_WORD + RI_HEAD + RI_ALPHA + RI_LOWER;
            } else if (i >= 'A' && i <= 'F') {
                class_tab[i] = RI_HEX + RI_WORD + RI_HEAD + RI_ALPHA + RI_UPPER;
            } else if (i >= 'G' && i <= 'Z') {
                class_tab[i] = RI_WORD + RI_HEAD + RI_ALPHA + RI_UPPER;
            } else if (i == '_') {
                class_tab[i] = RI_WORD + RI_HEAD;
            } else {
                class_tab[i] = 0;
            }
        }
        class_tab[' '] |= (short) RI_WHITE;
        class_tab['\t'] |= (short) RI_WHITE;
        init_class_tab_done = true;
    }

    private static int re_multiline(S_regprog prog) {
        return prog.regflags & RF_HASNL;
    }

    private int get_coll_element(Ptr<BytePtr> pp) {
        int c;
        int l = 1;
        BytePtr p = pp.get();
        if (p.at(0) != NUL && p.at(1) == '.' && p.at(2) != NUL) {
            l = utfc_ptr2len(p.add(2));
            if (p.at(l + 2) == '.' && p.at(l + 3) == ']') {
                c = utf_ptr2char(p.add(2));
                pp.put(pp.get().add(l + 4));
                return c;
            }
        }
        return 0;
    }

    private void get_cpo_flags() {
        reg_cpo_lit = vim_strchr(p_cpo[0], CPO_LITERAL) != null;
        reg_cpo_bsl = vim_strchr(p_cpo[0], CPO_BACKSL) != null;
    }

    private BytePtr skip_anyof(BytePtr p_arg) {
        BytePtr[] p = new BytePtr[] {p_arg};
        int l = 0;
        if (p[0].get() == '^') {
            p[0] = p[0].add(1);
        }
        if (p[0].get() == ']' || p[0].get() == '-') {
            p[0] = p[0].add(1);
        }
        while (p[0].get() != NUL && p[0].get() != ']') {
            if ((l = utfc_ptr2len(p[0])) > 1) {
                p[0] = p[0].add(l);
            } else {
                if (p[0].get() == '-') {
                    p[0] = p[0].add(1);
                    if (p[0].get() != ']' && p[0].get() != NUL) {
                        p[0] = p[0].add(utfc_ptr2len(p[0]));
                    }
                } else if (p[0].get() == '\\' && !reg_cpo_bsl
                        && (vim_strchr(new BytePtr(REGEXP_INRANGE, 0), p[0].u(1)) != null
                        || (!reg_cpo_lit && vim_strchr(new BytePtr(REGEXP_ABBR, 0), p[0].u(1)) != null))) {
                    p[0] = p[0].add(2);
                } else if (p[0].get() == '[') {
                    if (get_char_class(new Ptr<BytePtr>(p, 0)) == CLASS_NONE
                            && get_coll_element(new Ptr<BytePtr>(p, 0)) == 0 && p[0].get() != NUL) {
                        p[0] = p[0].add(1);
                    }
                } else {
                    p[0] = p[0].add(1);
                }
            }
        }
        return p[0];
    }

    private BytePtr skip_regexp(BytePtr startp, int delim, int magic) {
        return skip_regexp_ex(startp, delim, magic, null, null, null);
    }

    private BytePtr skip_regexp_ex(BytePtr startp, int dirc, int magic, Ptr<BytePtr> newp, IntPtr dropped,
            IntPtr magic_val) {
        int mymagic;
        BytePtr p = startp;
        long startplen = 0L;
        if (magic != 0) {
            mymagic = MAGIC_ON;
        } else {
            mymagic = MAGIC_OFF;
        }
        get_cpo_flags();
        for (; p.at(0) != NUL; p = p.add(utfc_ptr2len(p))) {
            if (p.u(0) == dirc) {
                break;
            }
            if ((p.at(0) == '[' && mymagic >= MAGIC_ON)
                    || (p.at(0) == '\\' && p.at(1) == '[' && mymagic <= MAGIC_OFF)) {
                p = skip_anyof(p.add(1));
                if (p.at(0) == NUL) {
                    break;
                }
            } else if (p.at(0) == '\\' && p.at(1) != NUL) {
                if (dirc == '?' && newp != null && p.at(1) == '?') {
                    if (startplen == 0L) {
                        startplen = musl_strlen(startp);
                    }
                    if (newp.get() == null) {
                        newp.put(vim_strnsave(startp, startplen));
                        if (newp.get() != null) {
                            p = newp.get().add((int) p.sub(startp));
                            startp = newp.get();
                        }
                    }
                    if (dropped != null) {
                        dropped.put(dropped.get() + 1);
                    }
                    if (newp.get() != null) {
                        Rt.memmove(p, p.add(1), startplen - p.add(1).sub(startp) + 1L);
                    } else {
                        p = p.add(1);
                    }
                } else {
                    p = p.add(1);
                }
                if (p.get() == 'v') {
                    mymagic = MAGIC_ALL;
                } else if (p.get() == 'V') {
                    mymagic = MAGIC_NONE;
                }
            }
        }
        if (magic_val != null) {
            magic_val.put(mymagic);
        }
        return p;
    }

    private void initchr(BytePtr str) {
        regparse[0] = str;
        prevchr_len = 0;
        curchr = prevprevchr = prevchr = nextchr = -1;
        at_start = TRUE;
        prev_at_start = FALSE;
    }

    private int peekchr() {
        if (curchr != -1) {
            return curchr;
        }
        switch (curchr = regparse[0].u(0)) {
            case '.', '[', '~' -> {
                if (reg_magic >= MAGIC_ON) {
                    curchr = curchr - 256;
                }
            }
            case '(', ')', '{', '%', '+', '=', '?', '@', '!', '&', '|', '<', '>', '#', '"', '\'', ',', '-', ':', ';', '`', '/' -> {
                if (reg_magic == MAGIC_ALL) {
                    curchr = curchr - 256;
                }
            }
            case '*' -> {
                if (reg_magic >= MAGIC_ON && at_start == 0 && !(prev_at_start != 0 && prevchr == '^' - 256)
                        && (peekchr_after_slash != 0
                        || (prevchr != '(' - 256 && prevchr != '&' - 256 && prevchr != '|' - 256))) {
                    curchr = '*' - 256;
                }
            }
            case '^' -> {
                if (reg_magic >= MAGIC_OFF
                        && (at_start != 0 || reg_magic == MAGIC_ALL || prevchr == '(' - 256 || prevchr == '|' - 256
                        || prevchr == '&' - 256 || prevchr == 'n' - 256
                        || (no_Magic(prevchr) == '(' && prevprevchr == '%' - 256))) {
                    curchr = '^' - 256;
                    at_start = TRUE;
                    prev_at_start = FALSE;
                }
            }
            case '$' -> {
                if (reg_magic >= MAGIC_OFF) {
                    BytePtr p = regparse[0].add(1);
                    boolean is_magic_all = reg_magic == MAGIC_ALL;
                    while (p.at(0) == '\\'
                            && (p.at(1) == 'c' || p.at(1) == 'C' || p.at(1) == 'm' || p.at(1) == 'M' || p.at(1) == 'v'
                            || p.at(1) == 'V' || p.at(1) == 'Z')) {
                        if (p.at(1) == 'v') {
                            is_magic_all = true;
                        } else if (p.at(1) == 'm' || p.at(1) == 'M' || p.at(1) == 'V') {
                            is_magic_all = false;
                        }
                        p = p.add(2);
                    }
                    if (p.at(0) == NUL
                            || (p.at(0) == '\\'
                            && (p.at(1) == '|' || p.at(1) == '&' || p.at(1) == ')' || p.at(1) == 'n'))
                            || (is_magic_all && (p.at(0) == '|' || p.at(0) == '&' || p.at(0) == ')'))
                            || reg_magic == MAGIC_ALL) {
                        curchr = '$' - 256;
                    }
                }
            }
            case '\\' -> {
                int c = regparse[0].u(1);
                if (c == NUL) {
                    curchr = '\\';
                } else if (c <= '~' && META_flags[c] != 0) {
                    curchr = -1;
                    prev_at_start = at_start;
                    at_start = FALSE;
                    regparse[0] = regparse[0].add(1);
                    peekchr_after_slash++;
                    peekchr();
                    regparse[0] = regparse[0].add(-1);
                    peekchr_after_slash--;
                    curchr = toggle_Magic(curchr);
                } else if (vim_strchr(new BytePtr(REGEXP_ABBR, 0), c) != null) {
                    curchr = backslash_trans(c);
                } else if (reg_magic == MAGIC_NONE && (c == '$' || c == '^')) {
                    curchr = toggle_Magic(c);
                } else {
                    if (c >= 128) {
                        curchr = utf_ptr2char(regparse[0].add(1));
                    } else {
                        curchr = c;
                    }
                }
                break;
            }
            default -> {
                if (curchr >= 128) {
                    curchr = utf_ptr2char(regparse[0]);
                }
            }
        }
        return curchr;
    }

    private void skipchr() {
        if (regparse[0].get() == '\\') {
            prevchr_len = 1;
        } else {
            prevchr_len = 0;
        }
        if (regparse[0].at(prevchr_len) != NUL) {
            if (regparse[0].u(prevchr_len) < 128) {
                prevchr_len++;
            } else {
                prevchr_len += utf_ptr2len(regparse[0].add(prevchr_len));
            }
        }
        regparse[0] = regparse[0].add(prevchr_len);
        prev_at_start = at_start;
        at_start = FALSE;
        prevprevchr = prevchr;
        prevchr = curchr;
        curchr = nextchr;
        nextchr = -1;
    }

    private void skipchr_keepstart() {
        int as = prev_at_start;
        int pr = prevchr;
        int prpr = prevprevchr;
        skipchr();
        at_start = as;
        prevchr = pr;
        prevprevchr = prpr;
    }

    private int getchr() {
        int chr = peekchr();
        skipchr();
        return chr;
    }

    private void ungetchr() {
        nextchr = curchr;
        curchr = prevchr;
        prevchr = prevprevchr;
        at_start = prev_at_start;
        prev_at_start = FALSE;
        regparse[0] = regparse[0].add(-prevchr_len);
    }

    private long gethexchrs(int maxinputlen) {
        long nr = 0L;
        int c = 0;
        int i = 0;
        for (i = 0; i < maxinputlen; i++) {
            c = regparse[0].u(0);
            if (!vim_isxdigit(c)) {
                break;
            }
            nr <<= 4;
            nr |= (long) hex2nr(c);
            regparse[0] = regparse[0].add(1);
        }
        if (i == 0) {
            return -1L;
        }
        return nr;
    }

    private long getdecchrs() {
        long nr = 0L;
        int c = 0;
        int i = 0;
        for (i = 0; ; i++) {
            c = regparse[0].u(0);
            if (c < '0' || c > '9') {
                break;
            }
            nr *= 10L;
            nr += (long) (c - '0');
            regparse[0] = regparse[0].add(1);
            curchr = -1;
        }
        if (i == 0) {
            return -1L;
        }
        return nr;
    }

    private long getoctchrs() {
        long nr = 0L;
        int c = 0;
        int i = 0;
        for (i = 0; i < 3 && Long.compareUnsigned(nr, 32L) < 0; i++) {
            c = regparse[0].u(0);
            if (c < '0' || c > '7') {
                break;
            }
            nr <<= 3;
            nr |= (long) hex2nr(c);
            regparse[0] = regparse[0].add(1);
        }
        if (i == 0) {
            return -1L;
        }
        return nr;
    }

    private T_read_limits__out_T read_limits() {
        long minval;
        long maxval;
        T_read_limits__out_T out__ = new T_read_limits__out_T();
        boolean reverse = false;
        BytePtr first_char;
        long tmp;
        if (regparse[0].get() == '-') {
            regparse[0] = regparse[0].add(1);
            reverse = true;
        }
        first_char = regparse[0];
        minval = getdigits(new Ptr<BytePtr>(regparse, 0));
        if (regparse[0].get() == ',') {
            regparse[0] = regparse[0].add(1);
            if (vim_isdigit(regparse[0].u())) {
                maxval = getdigits(new Ptr<BytePtr>(regparse, 0));
            } else {
                maxval = 2147418112L;
            }
        } else if (ascii_isdigit(first_char.u())) {
            maxval = minval;
        } else {
            maxval = 2147418112L;
        }
        if (regparse[0].get() == '\\') {
            regparse[0] = regparse[0].add(1);
        }
        if (regparse[0].get() != '}') {
            vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_syntax_error_in_str_curlies, 0),
                    reg_magic == MAGIC_ALL ? BytePtr.lit("") : BytePtr.lit("\\"));
            emsg(iobuff_or(new BytePtr(e_syntax_error_in_str_curlies, 0)));
            rc_did_emsg = true;
            out__.r__ = FAIL;
            out__.minval = minval;
            out__.maxval = maxval;
            return out__;
        }
        if ((!reverse && minval > maxval) || (reverse && minval < maxval)) {
            tmp = minval;
            minval = maxval;
            maxval = tmp;
        }
        skipchr();
        out__.r__ = OK;
        out__.minval = minval;
        out__.maxval = maxval;
        return out__;
    }

    private boolean reg_iswordc(S_regengine_S re, int c) {
        return vim_iswordc_buf(c, re.rex.reg_buf);
    }

    private void reg_getline_common(S_regengine_S re, long lnum, int flags, Ptr<BytePtr> line, IntPtr length) {
        int get_line = flags & RGLF_LINE;
        int get_length = flags & RGLF_LENGTH;
        if (re.alone.string[0] != null && lnum != 0L) {
            re.failed = true;
        }
        long firstlnum;
        long maxline;
        firstlnum = re.rex.reg_firstlnum + lnum;
        maxline = re.rex.reg_maxline;
        if (firstlnum < 1L) {
            if (get_line != 0) {
                line.put(null);
            }
            if (get_length != 0) {
                length.put(0);
            }
            return;
        }
        if (lnum > maxline) {
            if (get_line != 0) {
                line.put(BytePtr.lit(""));
            }
            if (get_length != 0) {
                length.put(0);
            }
            return;
        }
        if (re.alone.string[0] != null) {
            if (get_line != 0) {
                line.put(lnum == 0L ? re.alone.string[0] : BytePtr.lit(""));
            }
            if (get_length != 0) {
                length.put(lnum == 0L ? (int) re.alone.length : 0);
            }
            return;
        }
        if (get_line != 0) {
            line.put(ml_get_buf(re.rex.reg_buf, firstlnum, false));
        }
        if (get_length != 0) {
            length.put(ml_get_buf_len(re.rex.reg_buf, firstlnum));
        }
    }

    private BytePtr reg_getline(S_regengine_S re, long lnum) {
        BytePtr[] line = new BytePtr[1];
        reg_getline_common(re, lnum, RGLF_LINE, new Ptr<BytePtr>(line, 0), null);
        return line[0];
    }

    private int reg_getline_len(S_regengine_S re, long lnum) {
        int[] length = new int[1];
        reg_getline_common(re, lnum, RGLF_LENGTH, null, new IntPtr(length, 0));
        return length[0];
    }

    private int reg_prev_class(S_regengine_S re) {
        if (re.rex.input.gt(re.rex.line)) {
            return mb_get_class_buf(re.rex.input.add(-1).add(-utf_head_off(re.rex.line, re.rex.input.add(-1))),
                    re.rex.reg_buf);
        }
        return -1;
    }

    private boolean reg_match_visual(S_regengine_S re) {
        T_pos_T top = new T_pos_T();
        T_pos_T bot = new T_pos_T();
        long lnum;
        int col;
        S_window_S wp = re.rex.reg_win == null ? curwin : re.rex.reg_win;
        int mode;
        int[] start = new int[1];
        int[] end = new int[1];
        int[] start2 = new int[1];
        int[] end2 = new int[1];
        int cols;
        int curswant;
        if (re.rex.reg_buf != curbuf || VIsual.lnum == 0L || !(re.rex.reg_match == null)) {
            return false;
        }
        if (VIsual_active) {
            if (VIsual.lnum != wp.w_cursor.lnum ? VIsual.lnum < wp.w_cursor.lnum : (VIsual.col != wp.w_cursor.col ? VIsual.col < wp.w_cursor.col : VIsual.coladd < wp.w_cursor.coladd)) {
                top.set(VIsual);
                bot.set(wp.w_cursor);
            } else {
                top.set(wp.w_cursor);
                bot.set(VIsual);
            }
            mode = VIsual_mode;
            curswant = wp.w_curswant;
        } else {
            if (curbuf.b_visual.vi_start.lnum != curbuf.b_visual.vi_end.lnum ? curbuf.b_visual.vi_start.lnum < curbuf.b_visual.vi_end.lnum : (curbuf.b_visual.vi_start.col != curbuf.b_visual.vi_end.col ? curbuf.b_visual.vi_start.col < curbuf.b_visual.vi_end.col : curbuf.b_visual.vi_start.coladd < curbuf.b_visual.vi_end.coladd)) {
                top.set(curbuf.b_visual.vi_start);
                bot.set(curbuf.b_visual.vi_end);
            } else {
                top.set(curbuf.b_visual.vi_end);
                bot.set(curbuf.b_visual.vi_start);
            }
            if (bot.lnum > curbuf.b_ml.ml_line_count) {
                bot.lnum = curbuf.b_ml.ml_line_count;
            }
            mode = curbuf.b_visual.vi_mode;
            curswant = curbuf.b_visual.vi_curswant;
        }
        lnum = re.rex.lnum + re.rex.reg_firstlnum;
        if (lnum < top.lnum || lnum > bot.lnum) {
            return false;
        }
        col = (int) re.rex.input.sub(re.rex.line);
        if (mode == 'v') {
            if ((lnum == top.lnum && col < top.col)
                    || (lnum == bot.lnum && col >= bot.col + (p_sel[0].get() != 'e' ? 1 : 0))) {
                return false;
            }
        } else if (mode == Ctrl_V) {
            getvvcol(wp, top, new IntPtr(start, 0), null, new IntPtr(end, 0), 0);
            getvvcol(wp, bot, new IntPtr(start2, 0), null, new IntPtr(end2, 0), 0);
            if (start2[0] < start[0]) {
                start[0] = start2[0];
            }
            if (end2[0] > end[0]) {
                end[0] = end2[0];
            }
            if (top.col == MAXCOL || bot.col == MAXCOL || curswant == MAXCOL) {
                end[0] = MAXCOL;
            }
            re.rex.line = reg_getline(re, re.rex.lnum);
            re.rex.input = re.rex.line.add(col);
            cols = win_linetabsize(wp, re.rex.reg_firstlnum + re.rex.lnum, re.rex.line, col);
            if (cols < start[0] || cols > (end[0] - (p_sel[0].get() == 'e' ? 1 : 0))) {
                return false;
            }
        }
        return true;
    }

