    private BytePtr regtilde(BytePtr source, int magic) {
        long postfixlen = 0;
        long tmpsublen = 0;
        BytePtr tmpsub = null;
        BytePtr newsub = source;
        BytePtr p = null;
        long newsublen = 0L;
        byte[] tilde = new byte[3];
        tilde[0] = '~';
        long tildelen = 1L;
        boolean error = false;
        if (magic == 0) {
            tilde[0] = '\\';
            tilde[1] = '~';
            tilde[2] = NUL;
            tildelen = 2L;
        }
        for (p = newsub; p.get() != 0; p = p.add(1)) {
            if (musl_strncmp(p, new BytePtr(tilde, 0), tildelen) == 0) {
                long prefixlen = p.sub(newsub);
                BytePtr postfix = p.add((int) tildelen);
                if (newsublen == 0L) {
                    newsublen = musl_strlen(newsub);
                }
                newsublen -= tildelen;
                postfixlen = newsublen - prefixlen;
                tmpsublen = prefixlen + reg_prev_sublen + postfixlen;
                if (Long.compareUnsigned(tmpsublen, 0L) > 0 && reg_prev_sub != null) {
                    if (Long.compareUnsigned(tmpsublen, MAXCOL) > 0) {
                        emsg(new BytePtr(e_resulting_text_too_long, 0));
                        error = true;
                        break;
                    }
                    tmpsub = BytePtr.alloc(tmpsublen + 1L);
                    Rt.memmove(tmpsub, newsub, prefixlen);
                    Rt.memmove(tmpsub.add((int) prefixlen), reg_prev_sub, reg_prev_sublen);
                    musl_strcpy(tmpsub.add((int) prefixlen).add((int) reg_prev_sublen), postfix);
                    newsub = tmpsub;
                    newsublen = tmpsublen;
                    p = newsub.add((int) prefixlen).add((int) reg_prev_sublen);
                } else {
                    Rt.memmove(p, postfix, postfixlen + 1L);
                }
                p = p.add(-1);
            } else {
                if (p.get() == '\\' && p.at(1) != 0) {
                    p = p.add(1);
                }
                p = p.add(utfc_ptr2len(p) - 1);
            }
        }
        if (error) {
            return source;
        }
        newsublen = p.sub(newsub);
        if (newsublen == 0L) {
            reg_prev_sub = null;
        } else {
            reg_prev_sub = vim_strnsave(newsub, newsublen);
        }
        if (reg_prev_sub == null) {
            reg_prev_sublen = 0L;
        } else {
            reg_prev_sublen = newsublen;
        }
        return newsub;
    }

