    private void match_chunk(S_regengine_S re, T_regmmatch_T rmp, boolean do_all, S_file_buffer buf,
            Ptr<T_string_T> lines, long line1, long from, long to_, Ptr<T_linefound_T> found) {
        int t1 = 0;
        int t2 = 0;
        T_regmmatch_T m = new T_regmmatch_T();
        m.set(rmp);
        S_growarray searches = new S_growarray();
        S_growarray pos = new S_growarray();
        ga_init2(searches, 32L, 64);
        ga_init2(pos, 16L, 64);
        for (long i = from; i < to_ && !re.failed; i++) {
            BytePtr line = lines.at((int) i).string[0];
            int col = 0;
            int matchcol = 0;
            int prev_matchcol = MAXCOL;
            int first = searches.ga_len;
            re.alone.set(lines.at((int) i));
            for (;;) {
                long r = bt_regexec_multi(re, m, curwin, buf, line1 + i, col, null);
                if (re.failed || !ga_grow(searches, 1) || !ga_grow(pos, 2 * NSUBEXP)) {
                    re.failed = true;
                    break;
                }
                T_regsearch_T s = GA_Ptr_T_regsearch_T(searches).at(searches.ga_len);
                searches.ga_len++;
                s.col = col;
                s.nmatch = r <= 0L ? 0L : r;
                s.matchcol = m.rmm_matchcol;
                s.nsub = 0;
                s.pos = pos.ga_len;
                if (s.nmatch == 0L) {
                    break;
                }
                for (int k = 0; k < NSUBEXP; k++) {
                    if (m.startpos[k].lnum != -1L || m.startpos[k].col != -1 || m.endpos[k].lnum != -1L
                            || m.endpos[k].col != -1) {
                        s.nsub = k + 1;
                    }
                }
                for (int k_2 = 0; k_2 < s.nsub; k_2++) {
                    t1 = pos.ga_len;
                    pos.ga_len++;
                    GA_Ptr_T_lpos_T(pos).at(t1).set(m.startpos[k_2]);
                    t2 = pos.ga_len;
                    pos.ga_len++;
                    GA_Ptr_T_lpos_T(pos).at(t2).set(m.endpos[k_2]);
                }
                if (!do_all) {
                    break;
                }
                if (matchcol == prev_matchcol && m.endpos[0].col == matchcol) {
                    if (line.at(matchcol) == NUL) {
                        break;
                    }
                    matchcol += utfc_ptr2len(line.add(matchcol));
                } else {
                    matchcol = m.endpos[0].col;
                    prev_matchcol = matchcol;
                }
                if (line.at(matchcol) == NUL) {
                    break;
                }
                col = matchcol;
            }
            found.at((int) i).n = searches.ga_len - first;
            found.at((int) i).next = first;
        }
        for (long i_2 = from; i_2 < to_; i_2++) {
            found.at((int) i_2).searches = GA_Ptr_T_regsearch_T(searches).add(found.at((int) i_2).next);
            found.at((int) i_2).pos = GA_Ptr_T_lpos_T(pos);
            found.at((int) i_2).next = 0;
        }
    }

    private boolean match_lines(T_regmmatch_T rmp, boolean do_all, S_file_buffer buf, Ptr<T_string_T> lines, long line1,
            long n, Ptr<T_linefound_T> found) {
        return Rt.chunks(n, (from, to) -> {
            S_regengine_S re = new S_regengine_S();
            match_chunk(re, rmp, do_all, buf, lines, line1, from, to, found);
            return !re.failed;
        });
    }

