            re.rex.reg_endpos = rex_save_reg_endpos;
            re.rex.reg_win = rex_save_reg_win;
            re.rex.reg_buf = rex_save_reg_buf;
            re.rex.reg_firstlnum = rex_save_reg_firstlnum;
