    private void term_font(int n) {
        if (term_strings[KS_CF].get() != 0) {
            byte[] buf = new byte[20];
            vim_snprintf(new BytePtr(buf, 0), 20L, term_strings[KS_CF], 9 + n);
            out_str(new BytePtr(buf, 0));
        }
    }

    private void term_color(BytePtr s, int n) {
        byte[] buf = new byte[20];
        int i = s.u() == CSI ? 1 : 2;
        if (n >= 8 && t_colors >= 16 && ((s.at(0) == ESC && s.at(1) == '[') || (s.u(0) == CSI && (i = 1) == 1))
                && s.at(i) != NUL
                && (musl_strcmp(s.add(i).add(1), BytePtr.lit("%p1%dm")) == 0
                || musl_strcmp(s.add(i).add(1), BytePtr.lit("%dm")) == 0) && (s.at(i) == '3' || s.at(i) == '4')) {
            BytePtr format = BytePtr.lit("%s%s%%dm");
            BytePtr lead = i == 2 ? BytePtr.lit("\033[") : BytePtr.lit("\233");
            BytePtr tail = s.at(i) == '3' ? (n >= 16 ? BytePtr.lit("38;5;") : BytePtr.lit("9")) : (n >= 16 ? BytePtr.lit("48;5;") : BytePtr.lit("10"));
            vim_snprintf(new BytePtr(buf, 0), 20L, format, lead, tail);
            out_str(tgoto(new BytePtr(buf, 0), 0, n >= 16 ? n : n - 8));
        } else {
            out_str(tgoto(s, 0, n));
        }
    }

    private void term_fg_color(int n) {
        if (term_strings[KS_CAF].get() != 0) {
            term_color(term_strings[KS_CAF], n);
        } else if (term_strings[KS_CSF].get() != 0) {
            term_color(term_strings[KS_CSF], n);
        }
    }

    private void term_bg_color(int n) {
        if (term_strings[KS_CAB].get() != 0) {
            term_color(term_strings[KS_CAB], n);
        } else if (term_strings[KS_CSB].get() != 0) {
            term_color(term_strings[KS_CSB], n);
        }
    }

    private void term_ul_color(int n) {
        if (term_strings[KS_CAU].get() != 0) {
            term_color(term_strings[KS_CAU], n);
        }
    }

    private BytePtr term_bg_default() {
        if (musl_strcmp(term_strings[KS_NAME], BytePtr.lit("linux")) == 0
                || musl_strcmp(term_strings[KS_NAME], BytePtr.lit("screen.linux")) == 0
                || musl_strncmp(term_strings[KS_NAME], BytePtr.lit("cygwin"), 6L) == 0
                || musl_strncmp(term_strings[KS_NAME], BytePtr.lit("putty"), 5L) == 0) {
            return BytePtr.lit("dark");
        }
        return BytePtr.lit("light");
    }

    private void ttest(boolean pairs) {
        check_options();
        if (term_strings[KS_CM].get() == NUL) {
            emsg(new BytePtr(e_terminal_capability_cm_required, 0));
        }
        if (term_strings[KS_CS].get() != NUL) {
            scroll_region = true;
        } else {
            scroll_region = false;
        }
        if (pairs) {
            if (term_strings[KS_ME].get() == NUL) {
                term_strings[KS_MB] = empty_option;
                term_strings[KS_MD] = term_strings[KS_MB];
                term_strings[KS_MR] = term_strings[KS_MD];
                term_strings[KS_ME] = term_strings[KS_MR];
            }
            if (term_strings[KS_SO].get() == NUL || term_strings[KS_SE].get() == NUL) {
                term_strings[KS_SE] = empty_option;
                term_strings[KS_SO] = term_strings[KS_SE];
            }
            if (term_strings[KS_US].get() == NUL || term_strings[KS_UE].get() == NUL) {
                term_strings[KS_UE] = empty_option;
                term_strings[KS_US] = term_strings[KS_UE];
            }
            if (term_strings[KS_CZH].get() == NUL || term_strings[KS_CZR].get() == NUL) {
                term_strings[KS_CZR] = empty_option;
                term_strings[KS_CZH] = term_strings[KS_CZR];
            }
            if (term_strings[KS_VE].get() == NUL) {
                term_strings[KS_VI] = empty_option;
            }
            if (term_strings[KS_ME].get() == NUL) {
                term_strings[KS_ME] = term_strings[KS_SE];
                term_strings[KS_MR] = term_strings[KS_SO];
                term_strings[KS_MD] = term_strings[KS_SO];
            }
            if (term_strings[KS_SO].get() == NUL) {
                term_strings[KS_SE] = term_strings[KS_ME];
                if (term_strings[KS_MR].get() == NUL) {
                    term_strings[KS_SO] = term_strings[KS_MD];
                } else {
                    term_strings[KS_SO] = term_strings[KS_MR];
                }
            }
            if (term_strings[KS_CZH].get() == NUL) {
                term_strings[KS_CZR] = term_strings[KS_ME];
                if (term_strings[KS_MR].get() == NUL) {
                    term_strings[KS_CZH] = term_strings[KS_MD];
                } else {
                    term_strings[KS_CZH] = term_strings[KS_MR];
                }
            }
            if (term_strings[KS_CSB].get() == NUL || term_strings[KS_CSF].get() == NUL) {
                term_strings[KS_CSB] = empty_option;
                term_strings[KS_CSF] = empty_option;
            }
            if (term_strings[KS_CAB].get() == NUL || term_strings[KS_CAF].get() == NUL) {
                term_strings[KS_CAB] = empty_option;
                term_strings[KS_CAF] = empty_option;
            }
            p_wiv[0] = term_strings[KS_XS].get() != NUL ? 1 : 0;
        }
        need_gather = true;
        t_colors = musl_atoi(term_strings[KS_CCO]);
        set_rgb_term_prop();
    }

    private void check_shellsize() {
        if (Rows[0] < (long) min_rows_for_all_tabpages()) {
            Rows[0] = (long) min_rows_for_all_tabpages();
        }
        limit_screen_size();
        if ((long) cmdline_row >= Rows[0]) {
            cmdline_row = (int) (Rows[0] - 1L);
        }
        if ((long) msg_row >= Rows[0]) {
            msg_row = (int) (Rows[0] - 1L);
        }
    }

    private void limit_screen_size() {
        if (Columns[0] < MIN_COLUMNS) {
            Columns[0] = MIN_COLUMNS;
        } else if (Columns[0] > 10000L) {
            Columns[0] = 10000L;
        }
        if (Rows[0] > 1000L) {
            Rows[0] = 1000L;
        }
    }

    private void win_new_shellsize() {
        if ((long) win_new_shellsize_old_Rows != Rows[0] || (long) win_new_shellsize_old_Columns != Columns[0]
                || win_new_shellsize_old_coloff != 0) {
            ui_new_shellsize();
        }
        if ((long) win_new_shellsize_old_Columns != Columns[0] || win_new_shellsize_old_coloff != 0) {
            win_new_shellsize_old_Columns = (int) Columns[0];
            win_new_shellsize_old_coloff = 0;
            shell_new_columns();
        }
        if ((long) win_new_shellsize_old_Rows != Rows[0]) {
            if (p_window[0] == (long) (win_new_shellsize_old_Rows - 1)
                    || (win_new_shellsize_old_Rows == 0 && !option_was_set(BytePtr.lit("window")))) {
                p_window[0] = Rows[0] - 1L;
            }
            win_new_shellsize_old_Rows = (int) Rows[0];
            shell_new_rows();
        }
    }

    private void shell_resized() {
        set_shellsize(0, 0, FALSE);
    }

    private void set_shellsize_inner(int width, int height, int mustset) {
        if (updating_screen != 0) {
            return;
        }
        if (curwin.w_buffer == null || curwin.w_lines == null) {
            return;
        }
        if (mustset != 0 || (!ui_get_shellsize() && height != 0)) {
            Rows[0] = (long) height;
            Columns[0] = (long) width;
            check_shellsize();
            ui_set_shellsize(mustset);
        } else {
            check_shellsize();
        }
        if (State != MODE_ASKMORE && State != MODE_EXTERNCMD && State != MODE_CONFIRM) {
            screenclear();
        } else {
            screen_start();
        }
        if (starting != NO_SCREEN) {
            changed_line_abv_curs();
            invalidate_botline();
            if (State == MODE_ASKMORE || State == MODE_EXTERNCMD || State == MODE_CONFIRM) {
                screenalloc(false);
                repeat_message();
            } else {
                if ((State & MODE_CMDLINE) != 0) {
                    update_screen(UPD_NOT_VALID);
                    redrawcmdline();
                } else {
                    update_topline();
                    update_screen(UPD_NOT_VALID);
                    if (redrawing()) {
                        setcursor();
                    }
                }
            }
            cursor_on();
        }
        out_flush();
    }

    private void set_shellsize(int width, int height, int mustset) {
        if (width < 0 || height < 0) {
            return;
        }
        if (State == (8192 | MODE_NORMAL) || State == MODE_SETWSIZE) {
            State = MODE_SETWSIZE;
            return;
        }
        set_shellsize_do_run = true;
        if (set_shellsize_busy) {
            return;
        }
        while (set_shellsize_do_run) {
            set_shellsize_do_run = false;
            set_shellsize_busy = true;
            set_shellsize_inner(width, height, mustset);
            set_shellsize_busy = false;
        }
    }

    private void out_str_t_TE() {
        out_str(term_strings[KS_CTE]);
        if (modify_otherkeys_state == MOKS_ENABLED || modify_otherkeys_state == MOKS_DISABLED) {
            modify_otherkeys_state = MOKS_DISABLED;
        } else if (modify_otherkeys_state != MOKS_INITIAL) {
            modify_otherkeys_state = MOKS_AFTER_T_TE;
        }
        if (kitty_protocol_state == KKPS_ENABLED || kitty_protocol_state == KKPS_DISABLED) {
            kitty_protocol_state = KKPS_DISABLED;
        } else {
            kitty_protocol_state = KKPS_AFTER_T_TE;
        }
    }

    private void out_str_t_TI() {
        out_str(term_strings[KS_CTI]);
        send_t_RK = true;
    }

    private void out_str_t_BE() {
        BytePtr p = null;
        if (term_strings[KS_CBE] == null || term_strings[KS_CBE].get() == NUL
                || (p = find_termcode(BytePtr.lit("PS"))) == null || p.get() == NUL
                || (p = find_termcode(BytePtr.lit("PE"))) == null || p.get() == NUL) {
            return;
        }
        out_str(term_strings[KS_CBE]);
    }

    private void may_send_t_RK() {
        if (send_t_RK && !work_pending() && ex_normal_busy == 0 && !exiting) {
            send_t_RK = false;
            out_str(term_strings[KS_CRK]);
            out_flush();
        }
    }

    private void term_enter() {
        if (full_screen == 0 || term_entered) {
            return;
        }
        if (termcap_active) {
            out_str_t_BE();
            out_str_t_TI();
        }
        out_flush();
        musl_term_start();
        term_entered = true;
        out_flush();
    }

    private void term_leave() {
        if (full_screen == 0 || !term_entered) {
            return;
        }
        if (termcap_active) {
            out_str(term_strings[KS_CBD]);
            out_str_t_TE();
        }
        out_flush();
        musl_term_stop();
        term_entered = false;
        out_flush();
    }

    private void starttermcap() {
        if (full_screen == 0 || termcap_active) {
            return;
        }
        out_str(term_strings[KS_TI]);
        out_str_t_TI();
        out_str(term_strings[KS_KS]);
        out_str_t_BE();
        if (p_ek[0] != 0 && term_strings[KS_FE].get() != NUL) {
            out_str(term_strings[KS_FE]);
        }
        out_flush();
        termcap_active = true;
        screen_start();
    }

    private void stoptermcap() {
        screen_stop_highlight();
        reset_cterm_colors();
        if (!termcap_active) {
            return;
        }
        if (p_ek[0] != 0 && term_strings[KS_FD].get() != NUL) {
            out_str(term_strings[KS_FD]);
        }
        out_str(term_strings[KS_CBD]);
        out_str(term_strings[KS_KE]);
        out_flush();
        termcap_active = false;
        if (term_strings[KS_TE].get() != NUL
                && (kitty_protocol_state == KKPS_ENABLED || kitty_protocol_state == KKPS_DISABLED)) {
            out_str_t_TE();
        }
        out_str(term_strings[KS_TE]);
        cursor_on();
        out_str_t_TE();
        screen_start();
        out_flush();
    }

    private boolean swapping_screen() {
        return full_screen != 0 && term_strings[KS_TI].get() != NUL;
    }

    private void scroll_start() {
        if (term_strings[KS_VS].get() == NUL || term_strings[KS_CVS].get() == NUL) {
            return;
        }
        out_str(term_strings[KS_VS]);
        out_str(term_strings[KS_CVS]);
        screen_start();
    }

    private void cursor_on_force() {
        out_str(term_strings[KS_VE]);
        cursor_is_off = false;
        cursor_is_asleep = false;
    }

    private void cursor_on() {
        if (cursor_is_off && !cursor_is_asleep) {
            cursor_on_force();
        }
    }

    private void cursor_off() {
        if (full_screen != 0 && !cursor_is_off) {
            out_str(term_strings[KS_VI]);
            cursor_is_off = true;
        }
    }

    private void cursor_sleep() {
        cursor_is_asleep = true;
        cursor_off();
    }

    private void cursor_unsleep() {
        cursor_is_asleep = false;
        cursor_on();
    }

    private void scroll_region_set(S_window_S wp, int off) {
        out_str(tgoto(term_strings[KS_CS], wp.w_winrow + wp.w_height - 1, wp.w_winrow + off));
        if (term_strings[KS_CSV].get() != NUL && (long) wp.w_width != Columns[0]) {
            out_str(tgoto(term_strings[KS_CSV], wp.w_wincol + wp.w_width - 1, wp.w_wincol));
        }
        screen_start();
    }

    private void scroll_region_reset() {
        out_str(tgoto(term_strings[KS_CS], (int) Rows[0] - 1, 0));
        if (term_strings[KS_CSV].get() != NUL) {
            out_str(tgoto(term_strings[KS_CSV], (int) Columns[0] - 1, 0));
        }
        screen_start();
    }

    private void clear_termcodes() {
        while (tc_len > 0) {
            tc_len--;
        }
        termcodes = null;
        tc_max_len = 0;
        need_gather = true;
    }

    private void adjust_modlen(int idx) {
        termcodes.at(idx).modlen = 0;
        int j = termcode_star(termcodes.at(idx).code, termcodes.at(idx).len);
        if (j <= 0) {
            return;
        }
        termcodes.at(idx).modlen = termcodes.at(idx).len - 1 - j;
        if (termcodes.at(idx).code.at(termcodes.at(idx).modlen - 1) == '@') {
            termcodes.at(idx).modlen--;
        }
    }

    private void add_termcode(BytePtr name, BytePtr string, int flags) {
        Ptr<S_termcode> new_tc;
        int i = 0;
        int j = 0;
        BytePtr s;
        int len;
        if (string == null || string.get() == NUL) {
            del_termcode(name);
            return;
        }
        s = vim_strsave(string);
        if (flags != 0 && flags != ATC_FROM_TERM && term_7to8bit(string) != 0) {
            Rt.memmove(s, s.add(1), musl_strlen(s.add(1)) + 1L);
            s.set(0, (byte) term_7to8bit(string));
        }
        len = (int) musl_strlen(s);
        need_gather = true;
        if (tc_len == tc_max_len) {
            tc_max_len += 20;
            new_tc = new Ptr<S_termcode>(S_termcode.array(tc_max_len), 0);
            for (i = 0; i < tc_len; i++) {
                new_tc.at(i).set(termcodes.at(i));
            }
            termcodes = new_tc;
        }
        for (i = 0; i < tc_len; i++) {
            if ((termcodes.at(i).name[0] & 0xff) < name.u(0)) {
                continue;
            }
            if ((termcodes.at(i).name[0] & 0xff) == name.u(0)) {
                if ((termcodes.at(i).name[1] & 0xff) < name.u(1)) {
                    continue;
                }
                if ((termcodes.at(i).name[1] & 0xff) == name.u(1)) {
                    if (flags == ATC_FROM_TERM && (j = termcode_star(termcodes.at(i).code, termcodes.at(i).len)) > 0) {
                        if (len == termcodes.at(i).len - j
                                && musl_strncmp(s, termcodes.at(i).code, (long) (len - 1)) == 0
                                && s.u(len - 1) == termcodes.at(i).code.u(termcodes.at(i).len - 1)) {
                            return;
                        }
                    } else {
                        tc_len--;
                        break;
                    }
                }
            }
            for (j = tc_len; j > i; j--) {
                termcodes.at(j).set(termcodes.at(j - 1));
            }
            break;
        }
        termcodes.at(i).name[0] = name.at(0);
        termcodes.at(i).name[1] = name.at(1);
        termcodes.at(i).code = s;
        termcodes.at(i).len = len;
        adjust_modlen(i);
        tc_len++;
    }

    private void accept_modifiers_for_function_keys() {
        T_regmatch_T regmatch = new T_regmatch_T();
        regmatch.zero();
        regmatch.rm_ic = true;
        regmatch.regprog = vim_regcomp(BytePtr.lit("^\033[\\d\\+\\~$"), RE_MAGIC);
        for (int i = 0; i < tc_len; i++) {
            if (regmatch.regprog == null) {
                return;
            }
            if (termcodes.at(i).name[0] == 'P' && (termcodes.at(i).name[1] == 'S' || termcodes.at(i).name[1] == 'E')) {
                continue;
            }
            BytePtr s = termcodes.at(i).code;
            if (s != null && vim_regexec(regmatch, s, 0)) {
                long len = musl_strlen(s);
                BytePtr ns = BytePtr.alloc(len + 3L);
                Rt.memmove(ns, s, len - 1L);
                Rt.memmove(ns.add((int) len).add(-1), BytePtr.lit(";*~"), 4L);
                termcodes.at(i).code = ns;
                termcodes.at(i).len += 2;
                adjust_modlen(i);
            }
        }
        vim_regfree(regmatch.regprog);
    }

    private static int termcode_star(BytePtr code, int len) {
        if (len >= 3 && code.at(len - 2) == '*') {
            if (len >= 5 && code.at(len - 3) == ';') {
                return 2;
            } else {
                return 1;
            }
        }
        return 0;
    }

    private BytePtr find_termcode(BytePtr name) {
        int i = 0;
        for (i = 0; i < tc_len; i++) {
            if ((termcodes.at(i).name[0] & 0xff) == name.u(0) && (termcodes.at(i).name[1] & 0xff) == name.u(1)) {
                return termcodes.at(i).code;
            }
        }
        return null;
    }

    private void del_termcode(BytePtr name) {
        int i = 0;
        if (termcodes == null) {
            return;
        }
        need_gather = true;
        for (i = 0; i < tc_len; i++) {
            if ((termcodes.at(i).name[0] & 0xff) == name.u(0) && (termcodes.at(i).name[1] & 0xff) == name.u(1)) {
                del_termcode_idx(i);
                return;
            }
        }
    }

    private void del_termcode_idx(int idx) {
        int i = 0;
        tc_len--;
        for (i = idx; i < tc_len; i++) {
            termcodes.at(i).set(termcodes.at(i + 1));
        }
    }

    private void switch_to_8bit() {
        int i = 0;
        int c = 0;
        if (!term_is_8bit(term_strings[KS_NAME])) {
            for (i = 0; i < tc_len; i++) {
                c = term_7to8bit(termcodes.at(i).code);
                if (c != 0) {
                    Rt.memmove(termcodes.at(i).code.add(1), termcodes.at(i).code.add(2),
                            musl_strlen(termcodes.at(i).code.add(2)) + 1L);
                    termcodes.at(i).code.set(0, (byte) c);
                }
            }
            need_gather = true;
        }
        detected_8bit = true;
    }

    private boolean put_string_in_typebuf(int offset, int slen, BytePtr string, int new_slen, BytePtr buf, int bufsize,
            IntPtr buflen) {
        int extra = new_slen - slen;
        string.set(new_slen, (byte) NUL);
        if (buf == null) {
            if (extra < 0) {
                del_typebuf(-extra, offset);
            } else if (extra > 0) {
                if (!ins_typebuf(string.add(slen), REMAP_YES, offset, false, FALSE)) {
                    return false;
                }
            }
            Rt.memmove(typebuf.tb_buf.add(typebuf.tb_off).add(offset), string, (long) new_slen);
        } else {
            if (extra < 0) {
                Rt.memmove(buf.add(offset), buf.add(offset).add(-extra), (long) (buflen.get() + offset + extra));
            } else if (extra > 0) {
                if (buflen.get() + extra + new_slen >= bufsize) {
                    return false;
                }
                Rt.memmove(buf.add(offset).add(extra), buf.add(offset), (long) (buflen.get() - offset));
            }
            Rt.memmove(buf.add(offset), string, (long) new_slen);
            buflen.put(buflen.get() + extra + new_slen);
        }
        return true;
    }

    private static int decode_modifiers(int n) {
        int code = n - 1;
        int modifiers = 0;
        if ((code & 1) != 0) {
            modifiers |= MOD_MASK_SHIFT;
        }
        if ((code & 2) != 0) {
            modifiers |= MOD_MASK_ALT;
        }
        if ((code & 4) != 0) {
            modifiers |= MOD_MASK_CTRL;
        }
        if ((code & 8) != 0) {
            modifiers |= MOD_MASK_META;
        }
        return modifiers;
    }

    private T_modifiers2keycode__out_T modifiers2keycode(int modifiers_arg, int key, BytePtr string) {
        int[] modifiers = new int[] {modifiers_arg};
        T_modifiers2keycode__out_T out__ = new T_modifiers2keycode__out_T();
        int new_slen = 0;
        if (modifiers[0] == 0) {
            out__.r__ = 0;
            out__.key = key;
            return out__;
        }
        key = simplify_key(key, new IntPtr(modifiers, 0));
        if (modifiers[0] != 0) {
            string.set(new_slen++, (byte) -128);
            string.set(new_slen++, (byte) KS_MODIFIER);
            string.set(new_slen++, (byte) modifiers[0]);
        }
        out__.r__ = new_slen;
        out__.key = key;
        return out__;
    }

    private void handle_u7_response(IntPtr arg, BytePtr tp, int csi_len) {
        if (arg.at(0) == 2 && arg.at(1) >= 2) {
            BytePtr aw = null;
            u7_status.tr_progress = STATUS_GOT;
            did_cursorhold = TRUE;
            if (arg.at(1) == 2) {
                aw = BytePtr.lit("single");
            } else if (arg.at(1) == 3) {
                aw = BytePtr.lit("double");
            }
            if (aw != null && musl_strcmp(aw, p_ambw[0]) != 0) {
                set_option_value_give_err(BytePtr.lit("ambw"), 0L, aw, 0);
                redraw_asap(UPD_CLEAR);
            }
        } else if (arg.at(0) == 3) {
            int value;
            xcc_status.tr_progress = STATUS_GOT;
            value = arg.at(1) == 1 ? TPR_YES : TPR_NO;
            term_props[TPR_CURSOR_STYLE].tpr_status = value;
            term_props[TPR_CURSOR_BLINK].tpr_status = value;
        }
    }

    private void handle_version_response(int first, IntPtr arg, int argc, BytePtr tp) {
        int version = arg.at(1);
        crv_status.tr_progress = STATUS_GOT;
        did_cursorhold = TRUE;
        init_term_props(false);
        if (tp.u(0) == CSI) {
            switch_to_8bit();
        }
        if (version > 20000) {
            version = 0;
        }
        if (first == '>' && argc == 3) {
            if (arg.at(0) == 77) {
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
            }
            if ((version == 100 || version == 115) && arg.at(0) == 0 && arg.at(2) == 0) {
                may_adjust_color_count(256);
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
            }
            if (version == 95) {
                if (arg.at(0) == 1 && arg.at(2) == 0) {
                    term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                    term_props[TPR_DECRQM].tpr_status = TPR_NO;
                } else if (arg.at(0) == 0 && arg.at(2) == 0) {
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                    term_props[TPR_DECRQM].tpr_status = TPR_YES;
                } else if (arg.at(0) == 0 && arg.at(2) == -1) {
                    term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
                }
            }
            if (arg.at(0) == 83) {
                if (arg.at(1) >= 40700) {
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                } else {
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_XTERM;
                }
            }
            if (term_props[TPR_MOUSE].tpr_status == TPR_UNKNOWN) {
                if (version >= 277) {
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                } else if (version >= 95) {
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_XTERM2;
                }
            }
            if (arg.at(1) >= 2500) {
                term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
            } else if (version == 136 && arg.at(2) == 0) {
                term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
                if (arg.at(0) == 0) {
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                }
            }
            if (arg.at(0) == 1 && arg.at(1) >= 4000 && arg.at(1) <= 4009) {
                term_props[TPR_KITTY].tpr_status = TPR_YES;
                term_props[TPR_KITTY].tpr_set_by_termresponse = true;
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                term_props[TPR_DECRQM].tpr_status = TPR_YES;
            }
            if (arg.at(0) == 1 && version == 12700 && arg.at(2) == 0) {
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                term_props[TPR_DECRQM].tpr_status = TPR_YES;
            }
            if (arg.at(0) == 83 && arg.at(1) >= 30600) {
                term_props[TPR_CURSOR_STYLE].tpr_status = TPR_NO;
                term_props[TPR_CURSOR_BLINK].tpr_status = TPR_NO;
                term_props[TPR_DECRQM].tpr_status = TPR_NO;
            }
            if (version < 95) {
                term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
            }
            if (version < 279) {
                term_props[TPR_CURSOR_STYLE].tpr_status = TPR_NO;
            }
            if (term_props[TPR_UNDERLINE_RGB].tpr_status != TPR_YES && term_strings[KS_8U].get() != NUL
                    && !option_was_set(BytePtr.lit("t_8u"))) {
                set_string_option_direct(BytePtr.lit("t_8u"), -1, BytePtr.lit(""), OPT_FREE, 0);
            }
        }
    }

    private static int add_key_to_buf(int key, BytePtr buf) {
        int idx = 0;
        if (key < 0) {
            buf.set(idx++, (byte) -128);
            buf.set(idx++, (byte) (-key & 255));
            buf.set(idx++, (byte) ((-key >>> 8) & 255));
        } else {
            idx += utf_char2bytes(key, buf.add(idx));
        }
        return idx;
    }

    private int put_key_modifiers_in_typebuf(int key_arg, int modifiers_arg, int csi_len, int offset, BytePtr buf,
            int bufsize, IntPtr buflen) {
        T_modifiers2keycode__out_T modifiers2keycode__o = new T_modifiers2keycode__out_T();
        int key = key_arg;
        int modifiers = modifiers_arg;
        key = may_adjust_key_for_ctrl(modifiers, key);
        modifiers = may_remove_shift_modifier(modifiers, key);
        byte[] string = new byte[8];
        modifiers2keycode__o = modifiers2keycode(modifiers, key, new BytePtr(string, 0));
        key = modifiers2keycode__o.key;
        int new_slen = modifiers2keycode__o.r__;
        if (key > 1114111) {
            return -1;
        }
        new_slen += add_key_to_buf(key, new BytePtr(string, 0).add(new_slen));
        string[new_slen] = NUL;
        if (!put_string_in_typebuf(offset, csi_len, new BytePtr(string, 0), new_slen, buf, bufsize, buflen)) {
            return -1;
        }
        return new_slen - csi_len + offset;
    }

    private static int parse_csi_f_keys(int arg) {
        byte[] key_name = new byte[2];
        switch (arg) {
            case 11 -> {
                key_name[0] = 'k';
                key_name[1] = '1';
            }
            case 12 -> {
                key_name[0] = 'k';
                key_name[1] = '2';
            }
            case 13 -> {
                key_name[0] = 'k';
                key_name[1] = '3';
            }
            case 14 -> {
                key_name[0] = 'k';
                key_name[1] = '4';
            }
            case 15 -> {
                key_name[0] = 'k';
                key_name[1] = '5';
            }
            case 17 -> {
                key_name[0] = 'k';
                key_name[1] = '6';
            }
            case 18 -> {
                key_name[0] = 'k';
                key_name[1] = '7';
            }
            case 19 -> {
                key_name[0] = 'k';
                key_name[1] = '8';
            }
            case 20 -> {
                key_name[0] = 'k';
                key_name[1] = '9';
            }
            case 21 -> {
                key_name[0] = 'F';
                key_name[1] = ';';
            }
            case 23 -> {
                key_name[0] = 'F';
                key_name[1] = '1';
            }
            case 24 -> {
                key_name[0] = 'F';
                key_name[1] = '2';
            }
        }
        if (key_name[0] != 0) {
            return -((key_name[0] & 0xff) + ((key_name[1] & 0xff) << 8));
        }
        return arg;
    }

    private int handle_key_with_modifier(IntPtr arg, int csi_len, int offset, BytePtr buf, int bufsize, IntPtr buflen,
            boolean iskitty, int trail) {
        if (!iskitty
                && (kitty_protocol_state == KKPS_INITIAL || kitty_protocol_state == KKPS_OFF
                || kitty_protocol_state == KKPS_AFTER_T_TE) && term_props[TPR_KITTY].tpr_status != TPR_YES) {
            seenModifyOtherKeys = true;
        }
        int key = iskitty ? arg.at(0) : arg.at(2);
        int modifiers = decode_modifiers(arg.at(1));
        if ((modifiers & MOD_MASK_SHIFT) != 0 && key >= 'a' && key <= 'z') {
            key += 'A' - 'a';
        }
        if (key == ESC) {
            key = K_ESC;
        } else if (arg.at(0) >= 11 && arg.at(0) <= 24 && trail == '~') {
            key = parse_csi_f_keys(arg.at(0));
        }
        return put_key_modifiers_in_typebuf(key, modifiers, csi_len, offset, buf, bufsize, buflen);
    }

    private int handle_key_without_modifier(IntPtr arg, int csi_len, int offset, BytePtr buf, int bufsize,
            IntPtr buflen, int trail) {
        byte[] string = new byte[7];
        int new_slen;
        if (arg.at(0) == ESC) {
            string[0] = -128;
            string[1] = (byte) KS_EXTRA;
            string[2] = KE_ESC;
            new_slen = 3;
        } else if (arg.at(0) >= 11 && arg.at(0) <= 24 && trail == '~') {
            int key = parse_csi_f_keys(arg.at(0));
            string[0] = -128;
            string[1] = (byte) (-key & 255);
            string[2] = (byte) ((-key >>> 8) & 255);
            new_slen = 3;
        } else {
            new_slen = add_key_to_buf(arg.at(0), new BytePtr(string, 0));
        }
        if (!put_string_in_typebuf(offset, csi_len, new BytePtr(string, 0), new_slen, buf, bufsize, buflen)) {
            return -1;
        }
        return new_slen - csi_len + offset;
    }

    private int handle_csi_function_key(int argc, IntPtr arg, int trail, int csi_len, BytePtr key_name, int offset,
            BytePtr buf, int bufsize, IntPtr buflen) {
        key_name.set(0, (byte) 'k');
        switch (trail) {
            case 'A' -> key_name.set(1, (byte) 'u');
            case 'B' -> key_name.set(1, (byte) 'd');
            case 'C' -> key_name.set(1, (byte) 'r');
            case 'D' -> key_name.set(1, (byte) 'l');
            case 'F' -> {
                key_name.set(0, (byte) '@');
                key_name.set(1, (byte) '7');
            }
            case 'H' -> key_name.set(1, (byte) 'h');
            case 'P' -> key_name.set(1, (byte) '1');
            case 'Q' -> key_name.set(1, (byte) '2');
            case 'R' -> key_name.set(1, (byte) '3');
            case 'S' -> key_name.set(1, (byte) '4');
            default -> {
                return 0;
            }
        }
        int key = -(key_name.u(0) + (key_name.u(1) << 8));
        int modifiers = argc == 2 ? decode_modifiers(arg.at(1)) : 0;
        put_key_modifiers_in_typebuf(key, modifiers, csi_len, offset, buf, bufsize, buflen);
        return csi_len;
    }

    private T_handle_csi__out_T handle_csi(BytePtr tp, int len, BytePtr argp, int offset, BytePtr buf, int bufsize,
            IntPtr buflen, BytePtr key_name, int slen) {
        BytePtr t1 = null;
        T_handle_csi__out_T out__ = new T_handle_csi__out_T();
        int first = -1;
        int trail;
        int[] arg = new int[3];
        arg[0] = -1;
        arg[1] = -1;
        arg[2] = -1;
        int argc = 0;
        BytePtr ap = argp;
        int csi_len;
        if (!ascii_isdigit(ap.u())) {
            t1 = ap;
            ap = ap.add(1);
            first = t1.u();
        }
        if (first >= 'A' && first <= 'Z') {
            trail = first;
            first = -1;
            ap = ap.add(-1);
        } else {
            for (argc = 0; argc < 3; ) {
                if (ap.ge(tp.add(len))) {
                    out__.r__ = -1;
                    out__.slen = slen;
                    return out__;
                }
                if (ap.get() == ';') {
                    arg[argc++] = -1;
                } else if (ascii_isdigit(ap.u())) {
                    arg[argc] = 0;
                    for (;;) {
                        if (ap.ge(tp.add(len))) {
                            out__.r__ = -1;
                            out__.slen = slen;
                            return out__;
                        }
                        if (!ascii_isdigit(ap.u())) {
                            break;
                        }
                        if (arg[argc] <= (INT_MAX - 9) / 10) {
                            arg[argc] = arg[argc] * 10 + (ap.u() - '0');
                        }
                        ap = ap.add(1);
                    }
                    argc++;
                }
                if (ap.get() == ';') {
                    ap = ap.add(1);
                } else {
                    break;
                }
            }
            while (ap.lt(tp.add(len)) && !(ap.u() >= '{' && ap.u() <= '~')
                    && !(ascii_isupper(ap.u()) || ascii_islower(ap.u()))) {
                ap = ap.add(1);
            }
            if (ap.ge(tp.add(len))) {
                out__.r__ = -1;
                out__.slen = slen;
                return out__;
            }
            trail = ap.u();
        }
        csi_len = (int) ap.sub(tp) + 1;
        if (first == '>' && (argc == 1 || argc == 2) && trail == 'm') {
            if (arg[0] == 4 && argc == 2) {
                modify_otherkeys_state = arg[1] == 2 ? MOKS_ENABLED : MOKS_OFF;
            }
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
            slen = csi_len;
        } else if (first == -1 && ascii_isupper(trail) && (argc == 0 || (argc == 2 && arg[0] == 1))) {
            int res = handle_csi_function_key(argc, new IntPtr(arg, 0), trail, csi_len, key_name, offset, buf, bufsize,
                    buflen);
            out__.r__ = res <= 0 ? res : len + res;
            out__.slen = slen;
            return out__;
        } else if (first == -1 && argc == 2 && trail == 'R') {
            handle_u7_response(new IntPtr(arg, 0), tp, csi_len);
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
            slen = csi_len;
        } else if (first == '?' && trail == 'c') {
            slen = csi_len;
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
        } else if (first == '?' && trail == 'y' && argc == 2 && arg[0] == 2026) {
            int setting = arg[1];
            slen = csi_len;
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
            if (setting >= 0 && setting <= 4) {
                switch (arg[0]) {
                    case 2026 -> {
                        sync_output_setting = setting;
                        set_option_value_give_err(BytePtr.lit("termsync"),
                                (long) (setting == 1 || setting == 2 ? 1 : 0), null, 0);
                    }
                }
            }
        } else if (first == '?' && argc == 1 && arg[0] == 1 && trail == 'z') {
            slen = csi_len;
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
            do_cmdline_cmd(BytePtr.lit("stop"));
        } else if (argc >= 3 && arg[0] == 48) {
            int height = arg[1];
            int width = arg[2];
            slen = csi_len;
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
            set_shellsize(width, height, 1);
        } else if (term_strings[KS_CRV].get() != NUL && ap.gt(argp.add(1)) && trail == 'c') {
            handle_version_response(first, new IntPtr(arg, 0), argc, tp);
            slen = csi_len;
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
        } else if (first == '?' && argc == 1 && trail == 'u') {
            if (arg[0] == '0') {
                kitty_protocol_state = KKPS_OFF;
            } else {
                kitty_protocol_state = KKPS_ENABLED;
                seenModifyOtherKeys = false;
            }
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
            slen = csi_len;
        } else if ((arg[0] == 27 && argc == 3 && trail == '~') || (argc == 2 && (trail == 'u' || trail == '~'))) {
            boolean iskitty = argc == 2 && (trail == 'u' || trail == '~');
            out__.r__ = len + handle_key_with_modifier(new IntPtr(arg, 0), csi_len, offset, buf, bufsize, buflen,
                    iskitty, trail);
            out__.slen = slen;
            return out__;
        } else if (argc == 1 && (trail == 'u' || trail == '~')) {
            out__.r__ = len + handle_key_without_modifier(new IntPtr(arg, 0), csi_len, offset, buf, bufsize, buflen,
                    trail);
            out__.slen = slen;
            return out__;
        }
        out__.r__ = 0;
        out__.slen = slen;
        return out__;
    }

    private void check_for_color_response(BytePtr resp, int len) {
        int i = 0;
        int j = 1 + (resp.at(0) == ESC ? 1 : 0);
        BytePtr argp = resp.add(j);
        if (len >= j + 3 && (argp.at(0) != '1' || (argp.at(1) != '1' && argp.at(1) != '0') || argp.at(2) != ';')) {
            i = 0;
        } else {
            for (i = j; i < len; i++) {
                if (resp.at(i) == '\7'
                        || (resp.u(0) == OSC ? resp.u(i) == STERM : resp.at(i) == ESC && i + 1 < len
                        && resp.at(i + 1) == '\\')) {
                    boolean is_bg = argp.at(1) == '1';
                    boolean is_4digit = i - j >= 21 && resp.at(j + 11) == '/' && resp.at(j + 16) == '/';
                    if (i - j >= 15 && musl_strncmp(resp.add(j).add(3), BytePtr.lit("rgb:"), 4L) == 0
                            && (is_4digit || (resp.at(j + 9) == '/' && resp.at(j + 12) == '/'))) {
                        BytePtr tp_r = resp.add(j).add(7);
                        BytePtr tp_g = resp.add(j).add(is_4digit ? 12 : 10);
                        BytePtr tp_b = resp.add(j).add(is_4digit ? 17 : 13);
                        if (is_bg) {
                            BytePtr new_bg_val = 3 * '6' < tp_r.u() + tp_g.u() + tp_b.u() ? BytePtr.lit("light") : BytePtr.lit("dark");
                            if (!option_was_set(BytePtr.lit("bg")) && musl_strcmp(p_bg[0], new_bg_val) != 0) {
                                set_option_value_give_err(BytePtr.lit("bg"), 0L, new_bg_val, 0);
                                reset_option_was_set(BytePtr.lit("bg"));
                                redraw_asap(UPD_CLEAR);
                            }
                        }
                    }
                    break;
                }
            }
        }
    }

    private boolean in_osc_sequence() {
        return osc_state.processing;
    }

    private T_handle_osc__out_T handle_osc(BytePtr tp, int len, BytePtr key_name, int slen) {
        T_handle_osc__out_T out__ = new T_handle_osc__out_T();
        byte last_char;
        if (!osc_state.processing) {
            int cur = 1 + (tp.at(0) == ESC ? 1 : 0);
            if (len < cur + 1 + (tp.u(0) != OSC ? 1 : 0)) {
                out__.r__ = false;
                out__.slen = slen;
                return out__;
            }
            ga_init2(osc_state.buf, 1L, 1024);
            osc_state.start_tv = musl_now_ms();
            osc_state.processing = true;
            osc_state.start_char = tp.at(0);
            last_char = 0;
        } else {
            last_char = GA_BytePtr(osc_state.buf).at(osc_state.buf.ga_len - 1);
        }
        key_name.set(0, (byte) KS_EXTRA);
        for (int i = 0; i < len; i++) {
            if (tp.at(i) == '\7'
                    || ((osc_state.start_char & 0xff) == OSC ? tp.u(i) == STERM : (tp.at(i) == ESC && i + 1 < len
                    && tp.at(i + 1) == '\\') || (i == 0 && tp.at(i) == '\\' && last_char == ESC))) {
                osc_state.processing = false;
                key_name.set(1, (byte) KE_OSC);
                ga_concat_len(osc_state.buf, tp, (long) (i + 1 + (tp.at(i) == ESC ? 1 : 0)));
                ga_append(osc_state.buf, NUL);
                slen = i + 1 + (tp.at(i) == ESC ? 1 : 0);
                check_for_color_response(GA_BytePtr(osc_state.buf), osc_state.buf.ga_len - 1);
                byte savebg = p_bg[0].get();
                if (p_bg[0].u() != (savebg & 0xff)) {
                    redraw_asap(UPD_CLEAR);
                }
                out__.r__ = true;
                out__.slen = slen;
                return out__;
            }
        }
        key_name.set(1, (byte) KE_IGNORE);
        if (musl_now_ms() - osc_state.start_tv >= p_ost[0]) {
            vim_snprintf(IObuff, emsg_iobuff_room(), new BytePtr(e_osc_response_timed_out, 0), osc_state.buf.ga_len,
                    osc_state.buf.ga_data);
            emsg(iobuff_or(new BytePtr(e_osc_response_timed_out, 0)));
            ga_clear(osc_state.buf);
            osc_state.processing = false;
            out__.r__ = false;
            out__.slen = slen;
            return out__;
        }
        ga_concat(osc_state.buf, tp);
        slen = len;
        out__.r__ = true;
        out__.slen = slen;
        return out__;
    }

    private static T_handle_dcs__out_T handle_dcs(BytePtr tp, BytePtr argp, int len, BytePtr key_name, int slen) {
        T_handle_dcs__out_T out__ = new T_handle_dcs__out_T();
        int i = 0;
        int j = 1 + (tp.at(0) == ESC ? 1 : 0);
        if (len < j + 3) {
            i = len;
        } else if ((argp.at(1) != '+' && argp.at(1) != '$') || (argp.at(2) != 'r' && argp.at(2) != 'R')) {
            i = 0;
        } else if (argp.at(1) == '+') {
            for (i = j; i < len; i++) {
                if ((tp.at(i) == ESC && i + 1 < len && tp.at(i + 1) == '\\') || tp.u(i) == STERM) {
                    key_name.set(0, (byte) KS_EXTRA);
                    key_name.set(1, (byte) KE_IGNORE);
                    slen = i + 1 + (tp.at(i) == ESC ? 1 : 0);
                    break;
                }
            }
        } else {
            for (i = j + 3; i < len; i++) {
                if (i - j == 3 && !musl_isdigit(tp.u(i))) {
                    break;
                }
                if (i - j == 4 && tp.at(i) != ' ') {
                    break;
                }
                if (i - j == 5 && tp.at(i) != 'q') {
                    break;
                }
                if (i - j == 6 && tp.at(i) != ESC && tp.u(i) != STERM) {
                    break;
                }
                if ((i - j == 6 && tp.u(i) == STERM) || (i - j == 7 && tp.at(i) == '\\')) {
                    key_name.set(0, (byte) KS_EXTRA);
                    key_name.set(1, (byte) KE_IGNORE);
                    slen = i + 1;
                    break;
                }
            }
        }
        if (i == len) {
            out__.r__ = false;
            out__.slen = slen;
            return out__;
        }
        out__.r__ = true;
        out__.slen = slen;
        return out__;
    }

    private int check_termcode(int max_offset, BytePtr buf, int bufsize, IntPtr buflen) {
        int n = 0;
        T_handle_csi__out_T handle_csi__o = new T_handle_csi__out_T();
        T_handle_dcs__out_T handle_dcs__o = new T_handle_dcs__out_T();
        T_handle_osc__out_T handle_osc__o = new T_handle_osc__out_T();
        T_modifiers2keycode__out_T modifiers2keycode__o = new T_modifiers2keycode__out_T();
        BytePtr tp = null;
        BytePtr p = null;
        int slen = 0;
        int modslen = 0;
        int len = 0;
        int retval = 0;
        int offset = 0;
        byte[] key_name = new byte[2];
        int modifiers = 0;
        BytePtr modifiers_start = null;
        int key = 0;
        int new_slen = 0;
        byte[] string = new byte[7];
        int i = 0;
        int j = 0;
        int idx = 0;
        boolean cpo_koffset = vim_strchr(p_cpo[0], CPO_KOFFSET) != null;
        if (need_gather) {
            gather_termleader();
        }
        for (offset = 0; offset < max_offset; offset++) {
            if (buf == null) {
                if (offset >= typebuf.tb_len) {
                    break;
                }
                tp = typebuf.tb_buf.add(typebuf.tb_off).add(offset);
                len = typebuf.tb_len - offset;
            } else {
                if (offset >= buflen.get()) {
                    break;
                }
                tp = buf.add(offset);
                len = buflen.get() - offset;
            }
            if (tp.u() == 128) {
                offset += 2;
                continue;
            }
            if (osc_state.processing) {
                tp.set(len, (byte) NUL);
                key_name[0] = NUL;
                key_name[1] = NUL;
                modifiers = 0;
                handle_osc__o = handle_osc(tp, len, new BytePtr(key_name, 0), slen);
                slen = handle_osc__o.slen;
                if (!handle_osc__o.r__) {
                    return -1;
                }
            } else {
                i = tp.u();
                for (p = new BytePtr(termleader, 0); p.get() != 0 && p.u() != i; p = p.add(1)) {
                }
                if (p.get() == NUL) {
                    continue;
                }
                if (tp.get() == ESC && p_ek[0] == 0 && (State & MODE_INSERT) != 0) {
                    continue;
                }
                tp.set(len, (byte) NUL);
                key_name[0] = NUL;
                key_name[1] = NUL;
                modifiers = 0;
                int keypad_index_found = -1;
                int keypad_slen_found = 0;
                for (idx = 0; idx < tc_len; idx++) {
                    boolean is_keypad = false;
                    slen = termcodes.at(idx).len;
                    modifiers_start = null;
                    if (cpo_koffset && offset != 0 && len < slen) {
                        continue;
                    }
                    if (musl_strncmp(termcodes.at(idx).code, tp, (long) (slen > len ? len : slen)) == 0) {
                        if (len < slen) {
                            return -1;
                        }
                        if (termcodes.at(idx).name[0] == 'K'
                                && (ascii_isdigit(termcodes.at(idx).name[1] & 0xff)
                                || ascii_isupper(termcodes.at(idx).name[1] & 0xff))) {
                            is_keypad = true;
                            if (keypad_index_found < 0) {
                                keypad_index_found = idx;
                                keypad_slen_found = slen;
                            }
                        }
                        if (!is_keypad) {
                            key_name[0] = termcodes.at(idx).name[0];
                            key_name[1] = termcodes.at(idx).name[1];
                            break;
                        }
                    }
                    if (termcodes.at(idx).modlen > 0) {
                        modslen = termcodes.at(idx).modlen;
                        if (cpo_koffset && offset != 0 && len < modslen) {
                            continue;
                        }
                        if (musl_strncmp(termcodes.at(idx).code, tp, (long) (modslen > len ? len : modslen)) == 0) {
                            if (len <= modslen) {
                                return -1;
                            }
                            if (tp.u(modslen) == termcodes.at(idx).code.u(slen - 1)) {
                                slen = modslen + 1;
                            } else if (tp.at(modslen) != ';' && modslen == slen - 3) {
                                continue;
                            } else if (termcodes.at(idx).code.at(modslen) == '@'
                                    && (tp.at(modslen) != '1' || tp.at(modslen + 1) != ';')) {
                                continue;
                            } else {
                                for (j = slen - 2; j < len
                                        && (musl_isdigit(tp.u(j)) || tp.at(j) == '-' || tp.at(j) == ';'); j++) {
                                }
                                j++;
                                if (len < j) {
                                    return -1;
                                }
                                if (tp.u(j - 1) != termcodes.at(idx).code.u(slen - 1)) {
                                    continue;
                                }
                                modifiers_start = tp.add(slen).add(-2);
                                n = musl_atoi(modifiers_start);
                                modifiers |= decode_modifiers(n);
                                slen = j;
                            }
                            if (termcodes.at(idx).name[0] == 'K'
                                    && (ascii_isdigit(termcodes.at(idx).name[1] & 0xff)
                                    || ascii_isupper(termcodes.at(idx).name[1] & 0xff))) {
                                is_keypad = true;
                                if (keypad_index_found < 0) {
                                    keypad_index_found = idx;
                                    keypad_slen_found = slen;
                                }
                            }
                            if (!is_keypad) {
                                key_name[0] = termcodes.at(idx).name[0];
                                key_name[1] = termcodes.at(idx).name[1];
                                break;
                            }
                        }
                    }
                }
                if (idx == tc_len && keypad_index_found >= 0) {
                    key_name[0] = termcodes.at(keypad_index_found).name[0];
                    key_name[1] = termcodes.at(keypad_index_found).name[1];
                    slen = keypad_slen_found;
                }
                if (key_name[0] == NUL) {
                    BytePtr argp = tp.at(0) == ESC ? tp.add(2) : tp.add(1);
                    if (((tp.at(0) == ESC && len >= 3 && tp.at(1) == '[') || (tp.u(0) == CSI && len >= 2))
                            && vim_strchr(BytePtr.lit("0123456789>?ABCDEFHPQRS"), argp.u()) != null) {
                        handle_csi__o = handle_csi(tp, len, argp, offset, buf, bufsize, buflen,
                                new BytePtr(key_name, 0), slen);
                        slen = handle_csi__o.slen;
                        int resp = handle_csi__o.r__;
                        if (resp != 0) {
                            return resp;
                        }
                    } else if ((tp.at(0) == ESC && len >= 2 && tp.at(1) == ']') || tp.u(0) == OSC) {
                        handle_osc__o = handle_osc(tp, len, new BytePtr(key_name, 0), slen);
                        slen = handle_osc__o.slen;
                        if (!handle_osc__o.r__) {
                            return -1;
                        }
                    } else if ((tp.at(0) == ESC && len >= 2 && tp.at(1) == 'P') || tp.u(0) == DCS) {
                        handle_dcs__o = handle_dcs(tp, argp, len, new BytePtr(key_name, 0), slen);
                        slen = handle_dcs__o.slen;
                        if (!handle_dcs__o.r__) {
                            return -1;
                        }
                    }
                }
            }
            if (key_name[0] == NUL) {
                continue;
            }
            if ((key_name[0] & 0xff) == KS_EXTRA) {
                if (key_name[1] == KE_FOCUSGAINED) {
                    if (focus_state == 0) {
                        ui_focus_change(true);
                        did_cursorhold = TRUE;
                        focus_state = TRUE;
                    }
                    key_name[1] = KE_IGNORE;
                } else if (key_name[1] == KE_FOCUSLOST) {
                    if (focus_state != 0) {
                        ui_focus_change(false);
                        did_cursorhold = TRUE;
                        focus_state = FALSE;
                    }
                    key_name[1] = KE_IGNORE;
                }
            }
            key = handle_x_keys(-((key_name[0] & 0xff) + ((key_name[1] & 0xff) << 8)));
            modifiers2keycode__o = modifiers2keycode(modifiers, key, new BytePtr(string, 0));
            key = modifiers2keycode__o.key;
            new_slen = modifiers2keycode__o.r__;
            key_name[0] = (byte) (-key & 255);
            key_name[1] = (byte) ((-key >>> 8) & 255);
            if ((key_name[0] & 0xff) == KS_KEY) {
                new_slen += utf_char2bytes(key_name[1] & 0xff, new BytePtr(string, 0).add(new_slen));
            } else if (osc_state.processing
                    || (new_slen == 0 && (key_name[0] & 0xff) == KS_EXTRA && key_name[1] == KE_IGNORE)) {
                retval = KEYLEN_REMOVED;
            } else {
                string[new_slen++] = -128;
                string[new_slen++] = key_name[0];
                string[new_slen++] = key_name[1];
            }
            if (!put_string_in_typebuf(offset, slen, new BytePtr(string, 0), new_slen, buf, bufsize, buflen)) {
                return -1;
            }
            return retval == 0 ? len + new_slen - slen + offset : retval;
        }
        return 0;
    }

    private T_replace_termcodes__out_T replace_termcodes(BytePtr from, int sid_arg, int flags, IntPtr did_simplify) {
        int len = 0;
        BytePtr bufp = null;
        T_replace_termcodes__out_T out__ = new T_replace_termcodes__out_T();
        T_find_term_bykeys__out_T find_term_bykeys__o = new T_find_term_bykeys__out_T();
        int i = 0;
        int slen = 0;
        int key = 0;
        long dlen = 0L;
        BytePtr[] src = new BytePtr[1];
        BytePtr result;
        S_growarray ga = new S_growarray();
        boolean do_backslash = vim_strchr(p_cpo[0], CPO_BSLASH) == null;
        boolean do_special = vim_strchr(p_cpo[0], CPO_SPECI) == null || (flags & REPTERM_SPECIAL) != 0;
        boolean do_key_code = vim_strchr(p_cpo[0], CPO_KEYCODE) == null;
        src[0] = from;
        ga_init2(ga, 1L, 100);
        if (!ga_grow(ga, (int) (musl_strlen(src[0]) * 6L + 1L))) {
            bufp = null;
            out__.r__ = from;
            out__.bufp = bufp;
            return out__;
        }
        result = GA_BytePtr(ga);
        if ((flags & REPTERM_FROM_PART) != 0 && src[0].at(0) == '#' && ascii_isdigit(src[0].u(1))) {
            result.set((int) dlen++, (byte) -128);
            result.set((int) dlen++, (byte) 'k');
            if (src[0].at(1) == '0') {
                result.set((int) dlen++, (byte) ';');
            } else {
                result.set((int) dlen++, src[0].at(1));
            }
            src[0] = src[0].add(2);
        }
        while (src[0].get() != NUL) {
            if (do_special && ((flags & REPTERM_DO_LT) != 0 || musl_strncmp(src[0], BytePtr.lit("<lt>"), 4L) != 0)) {
                int fsk_flags = FSK_KEYCODE | ((flags & REPTERM_NO_SIMPLIFY) != 0 ? 0 : FSK_SIMPLIFY) | ((flags & REPTERM_FROM_PART) != 0 ? FSK_FROM_PART : 0);
                slen = trans_special(new Ptr<BytePtr>(src, 0), result.add((int) dlen), fsk_flags, true, did_simplify);
                if (slen > 0) {
                    dlen += (long) slen;
                    continue;
                }
            }
            if (do_key_code) {
                find_term_bykeys__o = find_term_bykeys(src[0], len);
                len = find_term_bykeys__o.matchlen;
                i = find_term_bykeys__o.r__;
                if (i >= 0) {
                    result.set((int) dlen++, (byte) -128);
                    result.set((int) dlen++, termcodes.at(i).name[0]);
                    result.set((int) dlen++, termcodes.at(i).name[1]);
                    src[0] = src[0].add(len);
                    continue;
                }
            }
            key = src[0].u();
            if (key == Ctrl_V || (do_backslash && key == '\\')) {
                src[0] = src[0].add(1);
                if (src[0].get() == NUL) {
                    if ((flags & REPTERM_FROM_PART) != 0) {
                        result.set((int) dlen++, (byte) key);
                    }
                    break;
                }
            }
            for (i = utfc_ptr2len(src[0]); i > 0; i--) {
                if (src[0].u() == 128) {
                    result.set((int) dlen++, (byte) -128);
                    result.set((int) dlen++, (byte) KS_SPECIAL);
                    result.set((int) dlen++, (byte) 'X');
                } else {
                    result.set((int) dlen++, src[0].get());
                }
                src[0] = src[0].add(1);
            }
        }
        result.set((int) dlen, (byte) NUL);
        if ((bufp = vim_strsave(result)) != null) {
            from = bufp;
        }
        out__.r__ = from;
        out__.bufp = bufp;
        return out__;
    }

    private T_find_term_bykeys__out_T find_term_bykeys(BytePtr src, int matchlen) {
        T_find_term_bykeys__out_T out__ = new T_find_term_bykeys__out_T();
        int i = 0;
        int j = 0;
        int len = (int) musl_strlen(src);
        int found = -1;
        int foundlen = 1;
        int slen = 0;
        int modslen = 0;
        int thislen = 0;
        if (need_gather) {
            gather_termleader();
        }
        if (src.get() == NUL || vim_strchr(new BytePtr(termleader, 0), src.u()) == null) {
            out__.r__ = -1;
            out__.matchlen = matchlen;
            return out__;
        }
        for (i = 0; i < tc_len; i++) {
            slen = termcodes.at(i).len;
            modslen = termcodes.at(i).modlen;
            if (modslen > 0) {
                if (len > modslen && musl_strncmp(termcodes.at(i).code, src, (long) modslen) == 0) {
                    thislen = 0;
                    if (src.u(modslen) == termcodes.at(i).code.u(slen - 1)) {
                        thislen = modslen + 1;
                    } else if (src.at(modslen) != ';' && modslen == slen - 3) {
                        continue;
                    } else if (termcodes.at(i).code.at(modslen) == '@'
                            && (src.at(modslen) != '1' || src.at(modslen + 1) != ';')) {
                        continue;
                    } else {
                        for (j = slen - 2; j < len
                                && (musl_isdigit(src.u(j)) || src.at(j) == '-' || src.at(j) == ';'); j++) {
                        }
                        j++;
                        if (len < j) {
                            continue;
                        }
                        if (src.u(j - 1) != termcodes.at(i).code.u(slen - 1)) {
                            continue;
                        }
                        thislen = j;
                    }
                    if (thislen > foundlen) {
                        found = i;
                        foundlen = thislen;
                    }
                }
            } else {
                if (slen > foundlen && len >= slen && musl_strncmp(termcodes.at(i).code, src, (long) slen) == 0) {
                    found = i;
                    foundlen = slen;
                }
            }
        }
        if (true && found >= 0) {
            matchlen = foundlen;
        }
        out__.r__ = found;
        out__.matchlen = matchlen;
        return out__;
    }

    private void gather_termleader() {
        int i = 0;
        int len = 0;
        termleader[len] = NUL;
        for (i = 0; i < tc_len; i++) {
            if (vim_strchr(new BytePtr(termleader, 0), termcodes.at(i).code.u(0)) == null) {
                termleader[len++] = termcodes.at(i).code.at(0);
                termleader[len] = NUL;
            }
        }
        need_gather = false;
    }

    private void show_termcodes(int flags) {
        int col = 0;
        IntPtr items;
        int item_count = 0;
        int run = 0;
        int row = 0;
        int rows = 0;
        int cols = 0;
        int i = 0;
        int len = 0;
        if (tc_len == 0) {
            return;
        }
        items = IntPtr.alloc(tc_len);
        msg_puts_title(BytePtr.lit("\n--- Terminal keys ---"));
        for (run = (flags & OPT_ONECOLUMN) != 0 ? 3 : 1; run <= 3 && got_int == 0; run++) {
            item_count = 0;
            for (i = 0; i < tc_len; i++) {
                len = show_one_termcode(new BytePtr(termcodes.at(i).name, 0), termcodes.at(i).code, false);
                if ((flags & OPT_ONECOLUMN) != 0
                        || (len <= INC3 - TERMCODE_GAP ? run == 1 : (len <= INC2 - TERMCODE_GAP ? run == 2 : run == 3))) {
                    items.set(item_count++, i);
                }
            }
            if (run <= 2) {
                cols = (int) ((Columns[0] + TERMCODE_GAP) / (long) (run == 1 ? INC3 : INC2));
                if (cols == 0) {
                    cols = 1;
                }
                rows = (item_count + cols - 1) / cols;
            } else {
                rows = item_count;
            }
            for (row = 0; row < rows && got_int == 0; row++) {
                msg_putchar('\n');
                if (got_int != 0) {
                    break;
                }
                col = 0;
                for (i = row; i < item_count; i += rows) {
                    msg_col = col;
                    show_one_termcode(new BytePtr(termcodes.at(items.at(i)).name, 0), termcodes.at(items.at(i)).code,
                            true);
                    if (run == 2) {
                        col += INC2;
                    } else {
                        col += INC3;
                    }
                }
                out_flush();
                ui_breakcheck();
            }
        }
    }

    private int show_one_termcode(BytePtr name, BytePtr code, boolean printit) {
        BytePtr p;
        int len;
        if (name.u(0) > '~') {
            IObuff.set(0, (byte) ' ');
            IObuff.set(1, (byte) ' ');
            IObuff.set(2, (byte) ' ');
            IObuff.set(3, (byte) ' ');
        } else {
            IObuff.set(0, (byte) 't');
            IObuff.set(1, (byte) '_');
            IObuff.set(2, name.at(0));
            IObuff.set(3, name.at(1));
        }
        IObuff.set(4, (byte) ' ');
        p = get_special_key_name(-(name.u(0) + (name.u(1) << 8)), 0);
        if (p.at(1) != 't') {
            musl_strcpy(IObuff.add(5), p);
        } else {
            IObuff.set(5, (byte) NUL);
        }
        len = (int) musl_strlen(IObuff);
        do {
            IObuff.set(len++, (byte) ' ');
        } while (len < 17);
        IObuff.set(len, (byte) NUL);
        if (code == null) {
            len += 4;
        } else {
            len += vim_strsize(code);
        }
        if (printit) {
            msg_puts(IObuff);
            if (code == null) {
                msg_puts(BytePtr.lit("NULL"));
            } else {
                msg_outtrans(code);
            }
        }
        return len;
    }

    private void term_disable_dec() {
        term_set_sync_output(TERM_SYNC_OUTPUT_OFF);
        out_flush();
    }

    private boolean sync_output_active() {
        return p_tsy[0] != 0 && (sync_output_setting == 1 || sync_output_setting == 2)
                && term_strings[KS_BSU].get() != NUL && term_strings[KS_ESU].get() != NUL;
    }

    private void term_set_sync_output(int flags) {
        boolean in_gui = false;
        boolean allowed = p_tsy[0] != 0 && (sync_output_setting == 1 || sync_output_setting == 2);
        if ((flags & TERM_SYNC_OUTPUT_FLUSH) != 0) {
            if (allowed && !in_gui && sync_output_state > 0 && term_strings[KS_ESU].get() != NUL
                    && term_strings[KS_BSU].get() != NUL) {
                out_str_nf(term_strings[KS_ESU]);
                out_str_nf(term_strings[KS_BSU]);
                out_flush();
            }
            return;
        }
        if ((flags & TERM_SYNC_OUTPUT_OFF) != 0) {
            if (sync_output_state > 0 && term_strings[KS_ESU].get() != NUL) {
                out_str_nf(term_strings[KS_ESU]);
                out_flush();
                sync_output_state = 0;
            }
            return;
        }
        if (!allowed || in_gui || term_strings[KS_BSU].get() == NUL || term_strings[KS_ESU].get() == NUL) {
            return;
        }
        if ((flags & TERM_SYNC_OUTPUT_ENABLE) != 0) {
            if (sync_output_state++ > 0) {
                return;
            }
            out_str_nf(term_strings[KS_BSU]);
        } else if ((flags & TERM_SYNC_OUTPUT_DISABLE) != 0) {
            if (sync_output_state == 0 || --sync_output_state > 0) {
                return;
            }
            out_str_nf(term_strings[KS_ESU]);
            out_flush();
        } else {
            vim_snprintf(IObuff, emsg_iobuff_room(), BytePtr.lit("Unknown sync output value %d"), flags);
            iemsg(iobuff_or(BytePtr.lit("Unknown sync output value %d")));
            return;
        }
    }

    private void internal_format(int textwidth, int second_indent, int flags, boolean format_only, int c) {
        int startcol = 0;
        int wantcol = 0;
        int foundcol = 0;
        int len = 0;
        int virtcol = 0;
        int end_col = 0;
        boolean first_pass = false;
        int cc = 0;
        int save_char = NUL;
        boolean haveto_redraw = false;
        int safe_tw = trim_to_int(8L * (long) textwidth);
        if (curbuf.b_p_ai[0] == 0 && (State & VREPLACE_FLAG) == 0) {
            cc = gchar_cursor();
            if (cc == ' ' || cc == '\t') {
                save_char = cc;
                pchar_cursor('x');
            }
        }
        while (got_int == 0) {
            int end_foundcol = 0;
            int orig_col = 0;
            BytePtr saved_text = null;
            if (curwin.w_cursor.col < safe_tw) {
                virtcol = get_nolist_virtcol() + char2cells(c != NUL ? c : gchar_cursor());
                if (virtcol <= textwidth) {
                    break;
                }
            }
            if (p_paste[0] != 0) {
                break;
            }
            if ((startcol = curwin.w_cursor.col) == 0) {
                break;
            }
            coladvance(textwidth);
            wantcol = curwin.w_cursor.col;
            curwin.w_cursor.col = startcol < safe_tw ? startcol : safe_tw;
            foundcol = 0;
            first_pass = true;
            for (;;) {
                if (first_pass && c != NUL) {
                    cc = c;
                    first_pass = false;
                } else {
                    cc = gchar_cursor();
                }
                if ((cc == ' ' || cc == '\t') && !utf_iscomposing(utf_ptr2char(ml_get_cursor().add(1)))) {
                    end_col = curwin.w_cursor.col;
                    while (curwin.w_cursor.col > 0
                            && ((cc == ' ' || cc == '\t') && !utf_iscomposing(utf_ptr2char(ml_get_cursor().add(1))))) {
                        dec_cursor();
                        cc = gchar_cursor();
                    }
                    if (curwin.w_cursor.col == 0
                            && ((cc == ' ' || cc == '\t') && !utf_iscomposing(utf_ptr2char(ml_get_cursor().add(1))))) {
                        break;
                    }
                    inc_cursor();
                    end_foundcol = end_col + 1;
                    foundcol = curwin.w_cursor.col;
                    if (curwin.w_cursor.col <= wantcol) {
                        break;
                    }
                }
                if (curwin.w_cursor.col == 0) {
                    break;
                }
                dec_cursor();
            }
            if (foundcol == 0) {
                curwin.w_cursor.col = startcol;
                break;
            }
            undisplay_dollar();
            if ((State & VREPLACE_FLAG) != 0) {
                orig_col = startcol;
            } else {
                replace_offset = startcol - end_foundcol;
            }
            curwin.w_cursor.col = foundcol;
            while (true) {
                cc = gchar_cursor();
                if (!((cc == ' ' || cc == '\t') && !utf_iscomposing(utf_ptr2char(ml_get_cursor().add(1))))) {
                    break;
                }
                inc_cursor();
            }
            startcol -= curwin.w_cursor.col;
            if (startcol < 0) {
                startcol = 0;
            }
            if ((State & VREPLACE_FLAG) != 0) {
                int len_2 = ml_get_cursor_len();
                saved_text = vim_strnsave(ml_get_cursor(), (long) len_2);
                curwin.w_cursor.col = orig_col;
                if (saved_text == null) {
                    break;
                }
                saved_text.set(startcol, (byte) NUL);
                backspace_until_column(foundcol);
            } else {
                curwin.w_cursor.col = foundcol;
            }
            open_line(FORWARD, OPENLINE_DELSPACES + OPENLINE_MARKFIX, old_indent, null);
            old_indent = 0;
            replace_offset = 0;
            if ((State & VREPLACE_FLAG) != 0) {
                ins_bytes(saved_text);
            } else {
                curwin.w_cursor.col += startcol;
                len = ml_get_curline_len();
                if (curwin.w_cursor.col > len) {
                    curwin.w_cursor.col = len;
                }
            }
            haveto_redraw = true;
            did_ai = false;
            did_si = false;
            can_si = FALSE;
            can_si_back = false;
            line_breakcheck();
        }
        if (save_char != NUL) {
            pchar_cursor(save_char);
        }
        if (haveto_redraw) {
            update_topline();
            redraw_curbuf_later(UPD_VALID);
        }
    }

    private int comp_textwidth() {
        int textwidth = (int) curbuf.b_p_tw[0];
        if (textwidth == 0 && curbuf.b_p_wm[0] != 0) {
            textwidth = (int) ((long) curwin.w_width - curbuf.b_p_wm[0]);
            if (curwin.w_onebuf_opt.wo_nu[0] != 0 || curwin.w_onebuf_opt.wo_rnu[0] != 0) {
                textwidth -= 8;
            }
        }
        if (textwidth < 0) {
            textwidth = 0;
        }
        return textwidth;
    }

    private int cls() {
        int c = gchar_cursor();
        if (c == ' ' || c == '\t' || c == NUL) {
            return 0;
        }
        c = utf_class(c);
        if (c != 0 && cls_bigword != 0) {
            return 1;
        }
        return c;
    }

    private boolean fwd_word(long count, int bigword, int eol) {
        int sclass = 0;
        int i = 0;
        boolean last_line = false;
        curwin.w_cursor.coladd = 0;
        cls_bigword = bigword;
        while (--count >= 0L) {
            sclass = cls();
            last_line = curwin.w_cursor.lnum == curbuf.b_ml.ml_line_count;
            i = inc_cursor();
            if (i == -1 || (i >= 1 && last_line)) {
                return false;
            }
            if (i >= 1 && eol != 0 && count == 0L) {
                return true;
            }
            if (sclass != 0) {
                while (cls() == sclass) {
                    i = inc_cursor();
                    if (i == -1 || (i >= 1 && eol != 0 && count == 0L)) {
                        return true;
                    }
                }
            }
            while (cls() == 0) {
                if (curwin.w_cursor.col == 0 && ml_get_curline().get() == NUL) {
                    break;
                }
                i = inc_cursor();
                if (i == -1 || (i >= 1 && eol != 0 && count == 0L)) {
                    return true;
                }
            }
        }
        return true;
    }

    private boolean bck_word(long count, int bigword, boolean stop) {
        int sclass = 0;
        curwin.w_cursor.coladd = 0;
        cls_bigword = bigword;
        while (--count >= 0L) {
            sclass = cls();
            if (dec_cursor() == -1) {
                return false;
            }
            L_finished: {
                if (!stop || sclass == cls() || sclass == 0) {
                    while (cls() == 0) {
                        if (curwin.w_cursor.col == 0 && ml_get(curwin.w_cursor.lnum).get() == NUL) {
                            break L_finished;
                        }
                        if (dec_cursor() == -1) {
                            return true;
                        }
                    }
                    if (skip_chars(cls(), -1)) {
                        return true;
                    }
                }
                inc_cursor();
            }
            stop = false;
        }
        adjust_skipcol();
        return true;
    }

    private boolean end_word(long count, int bigword, boolean stop, boolean empty) {
        int sclass = 0;
        curwin.w_cursor.coladd = 0;
        cls_bigword = bigword;
        if (p_sel[0].get() == 'e' && VIsual_active && VIsual_mode == 'v' && VIsual_select_exclu_adj) {
            unadjust_for_sel();
        }
        while (--count >= 0L) {
            sclass = cls();
            if (inc_cursor() == -1) {
                return false;
            }
            L_finished: {
                if (cls() == sclass && sclass != 0) {
                    if (skip_chars(sclass, FORWARD)) {
                        return false;
                    }
                } else if (!stop || sclass == 0) {
                    while (cls() == 0) {
                        if (empty && curwin.w_cursor.col == 0 && ml_get(curwin.w_cursor.lnum).get() == NUL) {
                            break L_finished;
                        }
                        if (inc_cursor() == -1) {
                            return false;
                        }
                    }
                    if (skip_chars(cls(), FORWARD)) {
                        return false;
                    }
                }
                dec_cursor();
            }
            stop = false;
        }
        return true;
    }

    private boolean bckend_word(long count, boolean bigword, boolean eol) {
        int sclass = 0;
        int i = 0;
        curwin.w_cursor.coladd = 0;
        cls_bigword = bigword ? 1 : 0;
        while (--count >= 0L) {
            sclass = cls();
            if ((i = dec_cursor()) == -1) {
                return false;
            }
            if (eol && i == 1) {
                return true;
            }
            if (sclass != 0) {
                while (cls() == sclass) {
                    if ((i = dec_cursor()) == -1 || (eol && i == 1)) {
                        return true;
                    }
                }
            }
            while (cls() == 0) {
                if (curwin.w_cursor.col == 0 && ml_get(curwin.w_cursor.lnum).get() == NUL) {
                    break;
                }
                if ((i = dec_cursor()) == -1 || (eol && i == 1)) {
                    return true;
                }
            }
        }
        adjust_skipcol();
        return true;
    }

    private boolean skip_chars(int cclass, int dir) {
        while (cls() == cclass) {
            if ((dir == FORWARD ? inc_cursor() : dec_cursor()) == -1) {
                return true;
            }
        }
        return false;
    }

    private void back_in_line() {
        int sclass = cls();
        for (;;) {
            if (curwin.w_cursor.col == 0) {
                break;
            }
            dec_cursor();
            if (cls() != sclass) {
                inc_cursor();
                break;
            }
        }
    }

    private boolean current_word(S_oparg_S oap, long count, boolean include, boolean bigword) {
        T_pos_T start_pos = new T_pos_T();
        long pos_lnum;
        int pos_col_;
        int pos_coladd;
        boolean inclusive = true;
        boolean include_white = false;
        cls_bigword = bigword ? 1 : 0;
        start_pos.lnum = 0L;
        start_pos.col = 0;
        start_pos.coladd = 0;
        if (VIsual_active && p_sel[0].get() == 'e'
                && (VIsual.lnum != curwin.w_cursor.lnum ? VIsual.lnum < curwin.w_cursor.lnum : (VIsual.col != curwin.w_cursor.col ? VIsual.col < curwin.w_cursor.col : VIsual.coladd < curwin.w_cursor.coladd))) {
            dec_cursor();
        }
        if (!VIsual_active
                || (curwin.w_cursor.lnum == VIsual.lnum && curwin.w_cursor.col == VIsual.col
                && curwin.w_cursor.coladd == VIsual.coladd)) {
            back_in_line();
            start_pos.set(curwin.w_cursor);
            if ((cls() == 0 ? 1 : 0) == (include ? 1 : 0)) {
                if (!end_word(1L, bigword ? 1 : 0, true, true)) {
                    return false;
                }
            } else {
                fwd_word(1L, bigword ? 1 : 0, TRUE);
                if (curwin.w_cursor.col == 0) {
                    decl(curwin.w_cursor);
                } else {
                    oneleft();
                }
                if (include) {
                    include_white = true;
                }
            }
            if (VIsual_active) {
                VIsual.set(start_pos);
                redraw_curbuf_later(UPD_INVERTED);
            } else {
                oap.start.set(start_pos);
                oap.motion_type = MCHAR;
            }
            count--;
        }
        while (count > 0L) {
            inclusive = true;
            if (VIsual_active
                    && (curwin.w_cursor.lnum != VIsual.lnum ? curwin.w_cursor.lnum < VIsual.lnum : (curwin.w_cursor.col != VIsual.col ? curwin.w_cursor.col < VIsual.col : curwin.w_cursor.coladd < VIsual.coladd))) {
                if (decl(curwin.w_cursor) == -1) {
                    return false;
                }
                if ((include ? 1 : 0) != (cls() != 0 ? 1 : 0)) {
                    if (!bck_word(1L, bigword ? 1 : 0, true)) {
                        return false;
                    }
                } else {
                    if (!bckend_word(1L, bigword, true)) {
                        return false;
                    }
                    incl(curwin.w_cursor);
                }
            } else {
                if (incl(curwin.w_cursor) == -1) {
                    return false;
                }
                if ((include ? 1 : 0) != (cls() == 0 ? 1 : 0)) {
                    if (!fwd_word(1L, bigword ? 1 : 0, TRUE) && count > 1L) {
                        return false;
                    }
                    if (!oneleft()) {
                        inclusive = false;
                    }
                } else {
                    if (!end_word(1L, bigword ? 1 : 0, true, true)) {
                        return false;
                    }
                }
            }
            count--;
        }
        if (include_white && (cls() != 0 || (curwin.w_cursor.col == 0 && !inclusive))) {
            pos_lnum = curwin.w_cursor.lnum;
            pos_col_ = curwin.w_cursor.col;
            pos_coladd = curwin.w_cursor.coladd;
            curwin.w_cursor.set(start_pos);
            if (oneleft()) {
                back_in_line();
                if (cls() == 0 && curwin.w_cursor.col > 0) {
                    if (VIsual_active) {
                        VIsual.set(curwin.w_cursor);
                    } else {
                        oap.start.set(curwin.w_cursor);
                    }
                }
            }
            curwin.w_cursor.lnum = pos_lnum;
            curwin.w_cursor.col = pos_col_;
            curwin.w_cursor.coladd = pos_coladd;
        }
        if (VIsual_active) {
            if (p_sel[0].get() == 'e' && inclusive
                    && ((VIsual.lnum != curwin.w_cursor.lnum ? VIsual.lnum < curwin.w_cursor.lnum : (VIsual.col != curwin.w_cursor.col ? VIsual.col < curwin.w_cursor.col : VIsual.coladd < curwin.w_cursor.coladd)) || (VIsual.lnum == curwin.w_cursor.lnum && VIsual.col == curwin.w_cursor.col && VIsual.coladd == curwin.w_cursor.coladd))) {
                inc_cursor();
            }
            if (VIsual_mode == 'V') {
                VIsual_mode = 'v';
                redraw_cmdline = TRUE;
            }
        } else {
            oap.inclusive = inclusive ? 1 : 0;
        }
        return true;
    }

    private boolean current_block(S_oparg_S oap, long count, boolean include, int what, int other) {
        long old_pos_lnum;
        int old_pos_col;
        int old_pos_coladd;
        T_pos_T pos = null;
        T_pos_T start_pos = new T_pos_T();
        T_pos_T end_pos = null;
        long old_start_lnum;
        int old_start_col;
        int old_start_coladd;
        long old_end_lnum;
        int old_end_col;
        int old_end_coladd;
        BytePtr save_cpo;
        boolean sol = false;
        old_pos_lnum = curwin.w_cursor.lnum;
        old_pos_col = curwin.w_cursor.col;
        old_pos_coladd = curwin.w_cursor.coladd;
        old_end_lnum = curwin.w_cursor.lnum;
        old_end_col = curwin.w_cursor.col;
        old_end_coladd = curwin.w_cursor.coladd;
        old_start_lnum = old_end_lnum;
        old_start_col = old_end_col;
        old_start_coladd = old_end_coladd;
        if (!VIsual_active
                || (VIsual.lnum == curwin.w_cursor.lnum && VIsual.col == curwin.w_cursor.col
                && VIsual.coladd == curwin.w_cursor.coladd)) {
            setpcmark();
            if (what == '{') {
                while (inindent(1)) {
                    if (inc_cursor() != 0) {
                        break;
                    }
                }
            }
            if (gchar_cursor() == what) {
                curwin.w_cursor.col++;
            }
        } else if (VIsual.lnum != curwin.w_cursor.lnum ? VIsual.lnum < curwin.w_cursor.lnum : (VIsual.col != curwin.w_cursor.col ? VIsual.col < curwin.w_cursor.col : VIsual.coladd < curwin.w_cursor.coladd)) {
            old_start_lnum = VIsual.lnum;
            old_start_col = VIsual.col;
            old_start_coladd = VIsual.coladd;
            curwin.w_cursor.set(VIsual);
        } else {
            old_end_lnum = VIsual.lnum;
            old_end_col = VIsual.col;
            old_end_coladd = VIsual.coladd;
        }
        save_cpo = p_cpo[0];
        p_cpo[0] = vim_strchr(p_cpo[0], CPO_MATCHBSL) != null ? BytePtr.lit("%M") : BytePtr.lit("%");
        if ((pos = findmatch(null, what)) != null) {
            while (count-- > 0L) {
                if ((pos = findmatch(null, what)) == null) {
                    break;
                }
                curwin.w_cursor.set(pos);
                start_pos.set(pos);
            }
        } else {
            while (count-- > 0L) {
                if ((pos = findmatchlimit(null, what, FM_FORWARD, 0)) == null) {
                    break;
                }
                curwin.w_cursor.set(pos);
                start_pos.set(pos);
            }
        }
        p_cpo[0] = save_cpo;
        if (pos == null || (end_pos = findmatch(null, other)) == null) {
            curwin.w_cursor.lnum = old_pos_lnum;
            curwin.w_cursor.col = old_pos_col;
            curwin.w_cursor.coladd = old_pos_coladd;
            return false;
        }
        curwin.w_cursor.set(end_pos);
        while (!include) {
            incl(start_pos);
            sol = curwin.w_cursor.col == 0;
            decl(curwin.w_cursor);
            while (inindent(1)) {
                sol = true;
                if (decl(curwin.w_cursor) != 0) {
                    break;
                }
            }
            if (start_pos.lnum == end_pos.lnum && start_pos.col == end_pos.col && start_pos.coladd == end_pos.coladd
                    && VIsual_active) {
                curwin.w_cursor.lnum = old_pos_lnum;
                curwin.w_cursor.col = old_pos_col;
                curwin.w_cursor.coladd = old_pos_coladd;
                return false;
            }
            if (!(start_pos.lnum != old_start_lnum ? start_pos.lnum < old_start_lnum : (start_pos.col != old_start_col ? start_pos.col < old_start_col : start_pos.coladd < old_start_coladd)) && !(old_end_lnum != curwin.w_cursor.lnum ? old_end_lnum < curwin.w_cursor.lnum : (old_end_col != curwin.w_cursor.col ? old_end_col < curwin.w_cursor.col : old_end_coladd < curwin.w_cursor.coladd)) && !(start_pos.lnum == curwin.w_cursor.lnum && start_pos.col == curwin.w_cursor.col && start_pos.coladd == curwin.w_cursor.coladd) && VIsual_active) {
                curwin.w_cursor.lnum = old_start_lnum;
                curwin.w_cursor.col = old_start_col;
                curwin.w_cursor.coladd = old_start_coladd;
                decl(curwin.w_cursor);
                if ((pos = findmatch(null, what)) == null) {
                    curwin.w_cursor.lnum = old_pos_lnum;
                    curwin.w_cursor.col = old_pos_col;
                    curwin.w_cursor.coladd = old_pos_coladd;
                    return false;
                }
                start_pos.set(pos);
                curwin.w_cursor.set(pos);
                if ((end_pos = findmatch(null, other)) == null) {
                    curwin.w_cursor.lnum = old_pos_lnum;
                    curwin.w_cursor.col = old_pos_col;
                    curwin.w_cursor.coladd = old_pos_coladd;
                    return false;
                }
                curwin.w_cursor.set(end_pos);
            } else {
                break;
            }
        }
        if (VIsual_active) {
            if (p_sel[0].get() == 'e') {
                inc(curwin.w_cursor);
            }
            if (sol && gchar_cursor() != NUL) {
                inc(curwin.w_cursor);
            }
            VIsual.set(start_pos);
            VIsual_mode = 'v';
            redraw_curbuf_later(UPD_INVERTED);
            showmode();
        } else {
            oap.start.set(start_pos);
            oap.motion_type = MCHAR;
            oap.inclusive = FALSE;
            if (sol) {
                incl(curwin.w_cursor);
            } else if ((start_pos.lnum != curwin.w_cursor.lnum ? start_pos.lnum < curwin.w_cursor.lnum : (start_pos.col != curwin.w_cursor.col ? start_pos.col < curwin.w_cursor.col : start_pos.coladd < curwin.w_cursor.coladd)) || (start_pos.lnum == curwin.w_cursor.lnum && start_pos.col == curwin.w_cursor.col && start_pos.coladd == curwin.w_cursor.coladd)) {
                oap.inclusive = TRUE;
            } else {
                curwin.w_cursor.set(start_pos);
            }
        }
        return true;
    }

    private int find_next_quote(BytePtr line, int col, int quotechar, BytePtr escape) {
        int c = 0;
        for (;;) {
            c = line.u(col);
            if (c == NUL) {
                return -1;
            } else if (escape != null && vim_strchr(escape, c) != null) {
                col++;
                if (line.at(col) == NUL) {
                    return -1;
                }
            } else if (c == quotechar) {
                break;
            }
            col += utfc_ptr2len(line.add(col));
        }
        return col;
    }

    private int find_prev_quote(BytePtr line, int col_start, int quotechar, BytePtr escape) {
        int n = 0;
        while (col_start > 0) {
            col_start--;
            col_start -= utf_head_off(line, line.add(col_start));
            n = 0;
            if (escape != null) {
                while (col_start - n > 0 && vim_strchr(escape, line.u(col_start - n - 1)) != null) {
                    n++;
                }
            }
            if ((n & 1) != 0) {
                col_start -= n;
            } else if (line.u(col_start) == quotechar) {
                break;
            }
        }
        return col_start;
    }

    private boolean current_quote(S_oparg_S oap, long count, boolean include, int quotechar) {
        BytePtr line = null;
        int col_end = 0;
        int col_start = 0;
        boolean inclusive = false;
        boolean vis_empty = false;
        boolean vis_bef_curs = false;
        boolean did_exclusive_adj = false;
        boolean inside_quotes = false;
        boolean selected_quote = false;
        int i = 0;
        boolean restore_vis_bef = false;
        long t_lnum = 0;
        int t_col_ = 0;
        int t_coladd = 0;
        int first_col = 0;
        long t_lnum_2 = 0;
        int t_col__2 = 0;
        int t_coladd_2 = 0;
        line = ml_get_curline();
        col_start = curwin.w_cursor.col;
        inclusive = false;
        vis_empty = true;
        vis_bef_curs = false;
        did_exclusive_adj = false;
        inside_quotes = false;
        selected_quote = false;
        restore_vis_bef = false;
        if (VIsual_active) {
            if (VIsual.lnum != curwin.w_cursor.lnum) {
                return false;
            }
            vis_bef_curs = VIsual.lnum != curwin.w_cursor.lnum ? VIsual.lnum < curwin.w_cursor.lnum : (VIsual.col != curwin.w_cursor.col ? VIsual.col < curwin.w_cursor.col : VIsual.coladd < curwin.w_cursor.coladd);
            vis_empty = VIsual.lnum == curwin.w_cursor.lnum && VIsual.col == curwin.w_cursor.col
                    && VIsual.coladd == curwin.w_cursor.coladd;
            if (p_sel[0].get() == 'e') {
                if (vis_bef_curs) {
                    dec_cursor();
                    did_exclusive_adj = true;
                } else if (!vis_empty) {
                    dec(VIsual);
                    did_exclusive_adj = true;
                }
                vis_empty = VIsual.lnum == curwin.w_cursor.lnum && VIsual.col == curwin.w_cursor.col
                        && VIsual.coladd == curwin.w_cursor.coladd;
                if (!vis_bef_curs && !vis_empty) {
                    t_lnum = curwin.w_cursor.lnum;
                    t_col_ = curwin.w_cursor.col;
                    t_coladd = curwin.w_cursor.coladd;
                    curwin.w_cursor.set(VIsual);
                    VIsual.lnum = t_lnum;
                    VIsual.col = t_col_;
                    VIsual.coladd = t_coladd;
                    vis_bef_curs = true;
                    restore_vis_bef = true;
                }
            }
        }
        if (!vis_empty) {
            if (vis_bef_curs) {
                inside_quotes = VIsual.col > 0 && line.u(VIsual.col - 1) == quotechar
                        && line.at(curwin.w_cursor.col) != NUL && line.u(curwin.w_cursor.col + 1) == quotechar;
                i = VIsual.col;
                col_end = curwin.w_cursor.col;
            } else {
                inside_quotes = curwin.w_cursor.col > 0 && line.u(curwin.w_cursor.col - 1) == quotechar
                        && line.at(VIsual.col) != NUL && line.u(VIsual.col + 1) == quotechar;
                i = curwin.w_cursor.col;
                col_end = VIsual.col;
            }
            while (i <= col_end) {
                if (line.at(i) == NUL) {
                    break;
                }
                if (line.u(i++) == quotechar) {
                    selected_quote = true;
                    break;
                }
            }
        }
        L_abort_search: {
            if (!vis_empty && line.u(col_start) == quotechar) {
                if (vis_bef_curs) {
                    col_start = find_next_quote(line, col_start + 1, quotechar, null);
                    if (col_start < 0) {
                        break L_abort_search;
                    }
                    col_end = find_next_quote(line, col_start + 1, quotechar, curbuf.b_p_qe[0]);
                    if (col_end < 0) {
                        col_end = col_start;
                        col_start = curwin.w_cursor.col;
                    }
                } else {
                    col_end = find_prev_quote(line, col_start, quotechar, null);
                    if (line.u(col_end) != quotechar) {
                        break L_abort_search;
                    }
                    col_start = find_prev_quote(line, col_end, quotechar, curbuf.b_p_qe[0]);
                    if (line.u(col_start) != quotechar) {
                        col_start = col_end;
                        col_end = curwin.w_cursor.col;
                    }
                }
            } else {
                if (line.u(col_start) == quotechar || !vis_empty) {
                    first_col = col_start;
                    if (!vis_empty) {
                        if (vis_bef_curs) {
                            first_col = find_next_quote(line, col_start, quotechar, null);
                        } else {
                            first_col = find_prev_quote(line, col_start, quotechar, null);
                        }
                    }
                    col_start = 0;
                    for (;;) {
                        col_start = find_next_quote(line, col_start, quotechar, null);
                        if (col_start < 0 || col_start > first_col) {
                            break L_abort_search;
                        }
                        col_end = find_next_quote(line, col_start + 1, quotechar, curbuf.b_p_qe[0]);
                        if (col_end < 0) {
                            break L_abort_search;
                        }
                        if (col_start <= first_col && first_col <= col_end) {
                            break;
                        }
                        col_start = col_end + 1;
                    }
                } else {
                    col_start = find_prev_quote(line, col_start, quotechar, curbuf.b_p_qe[0]);
                    if (line.u(col_start) != quotechar) {
                        col_start = find_next_quote(line, col_start, quotechar, null);
                        if (col_start < 0) {
                            break L_abort_search;
                        }
                    }
                    col_end = find_next_quote(line, col_start + 1, quotechar, curbuf.b_p_qe[0]);
                    if (col_end < 0) {
                        break L_abort_search;
                    }
                }
            }
            if (include) {
                if (line.at(col_end + 1) == ' ' || line.at(col_end + 1) == '\t') {
                    while (line.at(col_end + 1) == ' ' || line.at(col_end + 1) == '\t') {
                        col_end++;
                    }
                } else {
                    while (col_start > 0 && (line.at(col_start - 1) == ' ' || line.at(col_start - 1) == '\t')) {
                        col_start--;
                    }
                }
            }
            if (!include && count < 2L && (vis_empty || !inside_quotes)) {
                col_start++;
            }
            curwin.w_cursor.col = col_start;
            if (VIsual_active) {
                if (vis_empty
                        || (vis_bef_curs && !selected_quote
                        && (inside_quotes
                        || (line.u(VIsual.col) != quotechar
                        && (VIsual.col == 0 || line.u(VIsual.col - 1) != quotechar))))) {
                    VIsual.set(curwin.w_cursor);
                    redraw_curbuf_later(UPD_INVERTED);
                }
            } else {
                oap.start.set(curwin.w_cursor);
                oap.motion_type = MCHAR;
            }
            curwin.w_cursor.col = col_end;
            if ((include || count > 1L || (!vis_empty && inside_quotes)) && inc_cursor() == 2) {
                inclusive = true;
            }
            if (VIsual_active) {
                if (vis_empty || vis_bef_curs) {
                    if (p_sel[0].get() != 'e') {
                        dec_cursor();
                    }
                } else {
                    if (inside_quotes
                            || (!selected_quote && line.u(VIsual.col) != quotechar
                            && (line.at(VIsual.col) == NUL || line.u(VIsual.col + 1) != quotechar))) {
                        dec_cursor();
                        VIsual.set(curwin.w_cursor);
                    }
                    curwin.w_cursor.col = col_start;
                }
                if (VIsual_mode == 'V') {
                    VIsual_mode = 'v';
                    redraw_cmdline = TRUE;
                }
            } else {
                oap.inclusive = inclusive ? 1 : 0;
            }
            return true;
        }
        if (VIsual_active && p_sel[0].get() == 'e') {
            if (did_exclusive_adj) {
                inc_cursor();
            }
            if (restore_vis_bef) {
                t_lnum_2 = curwin.w_cursor.lnum;
                t_col__2 = curwin.w_cursor.col;
                t_coladd_2 = curwin.w_cursor.coladd;
                curwin.w_cursor.set(VIsual);
                VIsual.lnum = t_lnum_2;
                VIsual.col = t_col__2;
                VIsual.coladd = t_coladd_2;
            }
        }
        return false;
    }

