    private int ui_inchar(BytePtr buf, int maxlen, long wtime, int tb_change_cnt) {
        int retval = 0;
        if (wtime == -1L || wtime > 100L) {
            vim_handle_signal(-2);
            if (((mapped_ctrl_c | curbuf.b_mapped_ctrl_c) & get_real_state()) != 0) {
                ctrl_c_interrupts = false;
            }
        }
        retval = mch_inchar(buf, maxlen, wtime, tb_change_cnt);
        if (wtime == -1L || wtime > 100L) {
            vim_handle_signal(-1);
        }
        ctrl_c_interrupts = true;
        return retval;
    }

    private int inchar_loop(BytePtr buf, int maxlen, long wtime, int tb_change_cnt, Fn7 wait_func, Fn8 resize_func) {
        int len = 0;
        int[] interrupted = new int[1];
        interrupted[0] = FALSE;
        boolean did_call_wait_func = false;
        long wait_time = 0;
        long elapsed_time = 0L;
        long start_tv = musl_now_ms();
        for (;;) {
            if (resize_func != null) {
                resize_func.call(FALSE);
            }
            if (wtime < 0L) {
                wait_time = -1L;
            } else {
                elapsed_time = musl_now_ms() - start_tv;
                wait_time = wtime - elapsed_time;
                if (wait_time <= 0L && did_call_wait_func) {
                    return 0;
                }
            }
            did_call_wait_func = true;
            if (wait_func.call(wait_time, new IntPtr(interrupted, 0), FALSE) != 0) {
                if (typebuf_changed(tb_change_cnt)) {
                    return 0;
                }
                if (buf == null) {
                    return input_available() ? 1 : 0;
                }
                len = read_from_input_buf(buf, (long) maxlen);
                if (len > 0) {
                    return len;
                }
                continue;
            }
            if ((resize_func != null && resize_func.call(TRUE) != 0) || wait_time > 0L) {
                continue;
            }
            break;
        }
        return 0;
    }

